  [519041161016576] = "Hoo-hoo-",
  [519041161272576] = "EU...",
  [1143563228324608] = "Como ex-esquadrão mercenário, você realmente não está pensando em embarcar em uma aventura comigo?",
  [1130504917094400] = "Pete gradualmente se alienou completamente, transformando-se em um monstro homem-árvore.",
