  [813709740605696] = "Então qual é a sua intenção de pescar aqui?",
  [813709740640512] = "Se eu usasse essas roupas na festa do clube em Backlund, perderia toda a minha cara! Sem falar na participação na 'Temporada Social Backlund' com o presidente!",
