  [813709740434176] = "Olha, os moradores locais não estão todos ocupados comprando coisas?",
  [1130369088944896] = "Muitas vezes penso... não posso mais mudar o final, mas será que eles ainda se arrependem? Há mais alguma coisa que eu possa fazer por eles...",
  [813709740003328] = "Guerra.",
  [1169951775789568] = "Acompanhado de leite quente até tarde da noite",
