  [1130369089445376] = "Teste de opção circular flutuante",
  [813709740599040] = "Eu... nós também temos nossos próprios jogos, mas não exatamente iguais aos seus.",
  [1143563228340736] = "Talvez tenha algo a ver com a família real, ou talvez seja um admirador de Earl Lasting, o que você acha?",
