  [1139094851715328] = "Preparar ritual",
  [1139094851714816] = "Há meio ano...",
  [1139094851714560] = "Dívida enorme",
  [1139094851714048] = "Preocupe-se com Enid",
  [1139094851713792] = "Elogie a joalheria",
  [1139094851713280] = "Discuta negócios",
  [1139094851712768] = "Ajuda com entrega",
  [1139094851712512] = "Pergunte sobre Pete",
  [1139094851712256] = "Elogie os jovens",
  [1139094851712000] = "Pergunte sobre descontos",
  [1139094851709952] = "Pense em uma maneira",
  [1139094851709696] = "Retire 2.000 centavos",
  [1139094851709440] = "[Verificação de Combate] Ameaçar com força",
  [1139094851709184] = "Saia primeiro e procure por pistas",
  [1139094851708672] = "Ameaçar com força",
  [1139094851708416] = "Bom conforto",
  [813709740114432] = "Em um clube tão grande, você não consegue encontrar um Vidente confiável?",
  [1139094851707904] = "[Verificação de negociação] Comece a persuadir",
  [1139094851707648] = "Disfarçado de policial",
  [1139094851707392] = "Persuasão sincera",
  [1130369089052928] = "Suspeito que seja porque o Silver Nightingale Whistle estava inconscientemente protegendo Arnold anteriormente.",
  [1130369089703936] = "Sim, senhor.",
  [813709740727040] = "Capturado...",
  [813709740396288] = "Com certeza estudarei muito e sairei menos da próxima vez. Eu prometo!",
  [1130504917142528] = "Klein sai correndo do beco, com uma névoa negra saindo de trás dele, forçando-o a continuar fugindo (espaço reservado para o texto da cena).",
  [1130504917142272] = "Pós-atmosfera: O jornal Tingen publicou uma notícia: [Recentemente, a polícia descobriu uma jovem que morreu de causas desconhecidas num apartamento nos arredores de Tingen. Após investigação, a falecida chamava-se Daisy, que havia sido registrada como cidadã falecida nos arquivos de Tingen há meio ano. Dadas as circunstâncias complexas do ‘falecido ter regressado dos mortos’, a verdade do caso ainda está sob investigação profunda.]",
  [1130504917142016] = "Você perdeu a verdade. As cartas do Tarô murmuram, ainda abrigando muitas especulações sobre a morte de Daisy. Você expressa suas desculpas às cartas do Tarô por não ter conseguido salvá-lo. Ele expulsa você do espaço, indicando que continuará esperando pelo próximo questionador. As falas da conversa parecem estranhas e, depois de sair, você recebe um buff negativo de 1 minuto; você não consegue descobrir...",
  [1130504917141760] = "Pós-atmosfera: Um novo adivinho muito preciso chegou ao Adivinhação Clube, com uma notável semelhança com a ex-Miss Daisy.",
  [1130504917141504] = "O jogador luta contra o Espírito Maligno, mata-o e o missão é bem-sucedido.",
  [1130504917141248] = "O Espírito Maligno. agradece ao jogador por encontrar o destino que perdeu; agora, pretende encontrar Daisy, ainda viva, e matá-la.",
  [1130504917140992] = "Você pensou que a história terminava aí, mas inesperadamente, um Espírito Maligno. surgiu das cartas do Tarô - foi o próprio cliente que pediu um adivinhação a Daisy, uma pessoa paranóica que acreditava no destino acima de tudo. Mais tarde, ele descobriu através de adivinhação que havia sido enganado, orou a um deus maligno por uma chance de completar sua missão e, eventualmente, foi extraído com alma para as cartas do Tarô, esperando no Adivinhação Clube por alguém que pudesse desvendar a verdade.",
  [1130504917140736] = "Um dia, quando Daisy estava de plantão no clube, chegou um cliente paranóico com o destino. Daisy realizou um adivinhação para ela e descobriu que o destino previu que ela seria morta por este cliente um dia no futuro. Para sobreviver, ela trancou a porta no dia previsto e usou a Magia Ritual para fingir sua própria morte antecipadamente, enganando temporariamente o destino.",
  [1130504917140480] = "Vendo que você tocou na verdade, a carta do Tarô fica radiante – em um instante, todo o espaço muda e você vê a história de Daisy...",
  [1130504917140224] = "Não.",
  [1130504917139968] = "Sim.",
  [1130504917139712] = "[Teste] Legendas em tela preta podem ser configuradas durante o carregamento para reduzir a sensação de interrupção das missões durante o processo de tela preta.",
  [1130504917139456] = "Um novo Sequência está sendo refeito; atualmente, é o antigo Sequência , que pode ser ignorado diretamente, por ser informal.",
  [1130504917139200] = "Você contou ao Capitão Frye tudo o que aconteceu no seu sonho ontem, palavra por palavra.",
  [1130504917138944] = "Você matou completamente esse monstro na névoa negra, observando silenciosamente enquanto a luz em seus olhos se dissipava. Você espreme seu último pedaço de espiritualidade para invocar o espírito do monstro...",
  [1130504917138688] = "A Radiestesia Rod Navigation encontrou uma maneira de resolver a maldição, apontando para a atmosfera da siderúrgica, com um flash do incinerador (legendas substituídas).",
  [1130504917138432] = "A fábrica têxtil estava silenciosa como uma igreja, mas seu espiritualidade flutuava como teclas de piano. Você olhou na direção do Espiritualidade Aviso. \nVi vagamente uma mão lutando na névoa negra, esculpindo cinco manchas de sangue no chão,\n os gritos da trabalhadora louca vieram da névoa negra novamente. Ela foi arrastada para a névoa negra e não houve mais movimento...",
  [1130504917138176] = "Você ouve um grito vindo de fora da oficina. Virando-se para olhar, você vê o monstro rastejando em sua direção, morrendo, com os olhos cheios de súplica.",
  [1130504917137920] = "Cobras de fogo dançam dentro do incinerador, engolindo completamente os sinistros sapatos de dança, e um fio de fumaça preta se dissipa da fornalha.",
  [1130504917137664] = "Os espíritos da fábrica foram tocados pela aura sinistra e apareceram um após o outro agitados.",
  [1130504917137408] = "Uma lembrança passa pela sua mente: a jovem trabalhadora, calçando esses sapatos de dança, se joga na fornalha.",
  [1130504917137152] = "Uma aura sinistra correu em sua direção; você não conseguiu se esquivar e foi amaldiçoado.",
  [1130504917136896] = "A trabalhadora louca ouve a voz da jovem trabalhadora, com o rosto cheio de terror, e ela se vira para fugir para a neblina.",
  [1130504917136640] = "A sombra de uma jovem trabalhadora brilhou na frente da porta do dormitório. Ela bateu na porta, implorando à colega de quarto que abrisse para ela. Este parecia ser o segmento de memória de alguém.",
  [1130504917136384] = "No rugido, havia uma mistura inexplicável de algumas emoções dolorosas, e também parecia implorar por alguma coisa.",
  [1130504917136128] = "A névoa negra envolvia a fábrica, e o rugido das feras podia ser ouvido vagamente na névoa.",
  [1130504917135872] = "As luzes se apagam, a apresentação para novamente e a letra aparece abaixo do palco.",
  [1130504917135616] = "Uma performance de explosão, com efeitos sonoros de explosão, luz de fogo e efeitos de tremor de tela, e as cercas de ferro ao redor desabaram em resposta...",
  [1130504917135360] = "Você transmitiu a avaliação do público para Speer.",
  [1130504917135104] = "As luzes se apagam novamente e a apresentação é interrompida.",
  [1130504917134848] = "As luzes se apagaram repentinamente e os outros atores permaneceram imóveis.",
  [1130504917134592] = "Você acordou, foi apenas um pesadelo.",
  [1130504917134336] = "A rua em frente ao Portão Blackthorn desapareceu e tornou-se a Praça Central de Tingen. \nO jogador olhou para cima e o céu noturno de Tingen foi substituído por uma crescente Torrente de Conhecimento.\n A luz fluida do conhecimento derramou-se no cérebro de uma jovem, e a pessoa originalmente normal fez 'bang' - e se dissipou em uma torrente.",
  [1130504917134080] = "[Espaço reservado] Esta é uma bela animação",
  [1130504917133824] = "No final, ele não conseguiu escapar da guerra.",
  [1130504917133568] = "Junto com Rozanne, agora sóbria, você ajuda Ando, ​​que dorme, a se sentar no sofá próximo.",
  [1130504917133312] = "Você sorri enquanto toma o último gole de seu café e arruma as xícaras com todos os outros, e Blackthorn retorna ao seu estado habitual.",
  [1130504917133056] = "A carruagem parou depois de percorrer uma distância.",
  [1130504917132800] = "A partir de então, ele nunca mais temeria o frio do mar, \n ou o barulho dos canhões.",
  [1130504917132544] = "O segundo tiro se dissipou no ar, \n provocando uma despedida eterna.",
  [1130504917132288] = "As pessoas na rua ouviram o barulho e começaram a sussurrar, \n enquanto outras procuravam freneticamente um patrulheiro.",
  [1130504917132032] = "Um tiro soou, \n seguido por \n uma cacofonia de vozes humanas misturadas com lamentos dolorosos.",
  [1130504917131520] = "Um vento frio e misterioso soprou, acompanhado pelo som de uma estranha gaita...",
  [1130504917131264] = "Depois de esperar um pouco na fila, finalmente chegou a sua vez.",
  [1130504917131008] = "Cook pediu para você sair da cozinha...",
  [1130504917130752] = "Na sala silenciosa, um pouco de brilho espiritual começou a se acumular sobre eles...",
  [1130504917130496] = "Em um instante, os dois caíram no chão.",
  [1130504917130240] = "Jonar e Liana usaram suas últimas forças para lutar ao lado da pequena Daisy. Eles se entreolharam com conhecimento de causa, sorriram levemente e tocaram o pulso de Daisy...",
  [1130504917129984] = "Jede de repente aperta o abdômen, cuspindo um grão de trigo após o outro.",
  [1130504917129728] = "Você foi descoberto.",
  [1130504917129472] = "Um Aprendiz pode abrir todas as portas, mas nem todas as portas podem ser acessadas.",
  [1130504917129216] = "Correu até o moinho de vento com Jirel.",
  [1130504917128960] = "Após o término da sessão de cânticos, Potter e George permaneceram onde estavam e não foram embora.",
  [1130504917128704] = "Algum tempo depois, você queria saber o resultado, então veio para a Hoy University novamente...",
  [1130504917128448] = "O professor Hamer saiu pensando profundamente. \n Embora sua figura fosse solitária, ela permaneceu resoluta...",
  [1130504917128192] = "O professor Hamer seguiu você até o Gabinete de Integridade Acadêmica e confessou suas ações. \nAs pessoas do Escritório de Integridade Acadêmica ficaram chocadas, alegando que considerariam cuidadosamente como lidar com isso.",
  [1130504917127936] = "Duas horas depois...",
  [1130504917127680] = "Você explicou seus pensamentos a Leon e começou a trabalhar ativamente em frente à lápide de Doug.",
  [1130504917127424] = "Finnis segue você a alguns passos de distância.",
  [1130504917127168] = "“Uau, au au!”",
  [1130504917126912] = "“Dedicado ao meu leal amigo Watson, de seu mestre.”",
  [1130504917126656] = "“Em seus últimos anos, Lisa vagou entre os sonhos e a realidade, \n graças à Deusa, ela finalmente acabou com aquele pesadelo.”",
  [1130504917126400] = "\"Dendris (suas roupas) descansa aqui no Sono. \n Você é o presente que a Deusa me concedeu.\"",
  [1130504917126144] = "“Deitada aqui está a poetisa da vida selvagem Lillian, \n que adorava explorar a natureza e voltou a abraçá-la.”",
  [1130504917125888] = "“Triss: \n Estou pronto para receber a noite, então a noite está pronta para me receber?”",
  [1130504917125376] = "Verificou as credenciais apresentadas pelo oficial de justiça.",
  [1130504917125120] = "Estou ficando louco",
  [1130504917124864] = "O policial inspecionou a escritura de propriedade que Dennis apresentou.",
  [1130504917123584] = "Um momento depois...",
  [1130504917123328] = "Foi-se... acabou-se tudo... \n Já não há sequer uma direção para dar um passo em frente...",
  [1130504917123072] = "Este mundo... parece ter chegado ao fim.",
  [1130504917122560] = "Por que... por que Sua doutrinação está se tornando cada vez mais frequente?",
  [1130504917121536] = "Muito, muito tempo se passou...",
  [1130504917121024] = "Bernadete Gustavo",
  [1130504917120768] = "Antes que as palavras terminassem, a porta da frente foi aberta rudemente.",
  [1130504917120256] = "Estou constantemente ansioso pelo dia em que a música terminará. \n No entanto, antes que a música pudesse ser concluída, Aiden teve que deixar o asilo.",
  [1130504917120000] = "Naquele momento, Aiden era como uma luz, fazendo-me não temer mais a noite. \n É que a luz também tem seus momentos de penumbra...",
  [1143492898197504] = "Nada mais",
  [1130504917119488] = "Na noite seguinte...",
  [1130504917119232] = "Você explicou a situação ao Capitão Frye e fez com que Jade fosse purificada.",
  [1130504917118976] = "Depois de esperar muito tempo na fila, finalmente chegou a sua vez...",
  [1130504917118208] = "......Mais ao sul que o Continente Sul, mais ao norte que o Continente Norte, mais a leste que o Mar Sônia, mais a oeste que o Mar Nevoeiro......",
  [1130504917117952] = "No momento de conseguir o que queria, uma voz nos virou, que estávamos desabando, de volta para mim.",
  [1130504917117696] = "Uma explosão de luz estelar caiu, o Verme Misterioso soltou você e ficou inerte nesta jaula de sonho, como se tivesse perdido sua alma.",
  [1130504917117440] = "Até que os gritos diminuam, ela rasteja confusa no silêncio.",
  [1130504917117184] = "Ela grita, arrancando os próprios cabelos, rolando no chão como um verme.",
  [1130504917116928] = "A luz do conhecimento cai nas mãos de Bernadette. Ela observa a luz do conhecimento em silêncio até que ela diminua e se dissipe... Por um longo tempo, ela baixa os olhos.",
  [1130504917116672] = "(Como a ação ainda não chegou, usarei uma tela preta aqui como espaço reservado e preencherei mais tarde)",
  [1130504917116416] = "Eu... não, suportamos milhares de infusões de conhecimento, morrendo constantemente por essa resposta.",
  [1130504917116160] = "Lembrei-me daquela Flesh Magic, deixando o Verme Misterioso do Mundo Espiritual devorar meu corpo.",
  [1130504917115648] = "Um, dois, três... \nperninhas de inseto rastejam por baixo da saia e sobem em suas pernas e pés...",
  [1130504917115392] = "Um, dois, três... \nvocê julga a quantidade pelo movimento dos lábios e dos dentes dela.",
  [1130504917115136] = "A Sra. Skana respondeu com ação - \n ela ansiosamente enviou o Verme Misterioso em sua boca.",
  [1130504917114880] = "【Atuação】 Kena foge rapidamente.",
  [1130504917114368] = "【Desempenho】 A garota está com dor.",
  [1130504917114112] = "【Desempenho】 Uma sensação de distorção aparece, Phantom Thief se transforma em uma jovem garota.",
  [1130504917113856] = "【Desempenho】Phantom Thief perde o controle.",
  [1130504917113600] = "【Atuação】 Lady Bailey sai, o Ladrão Fantasma permanece imóvel, mas bolhas começam a aparecer em sua cabeça, muito confuso.",
  [1130504917113344] = "【Atuação】 A câmera focaliza os dois conversando sob o plátano e depois o “ladrão” caído no chão.",
  [1130504917113088] = "【Desempenho】 Todo mundo está discutindo isso.",
  [1130504917112832] = "Você e Kena tomaram algumas medidas. </n> \n No dia seguinte, você se preparou para ir ao Restaurante Coastline como o 'Ladrão Fantasma Imperador Negro'.",
  [1130504917112320] = "A hora chegou ao meio-dia do dia seguinte ...",
  [1130504917112064] = "Um quarto de hora depois...",
  [1130504917111808] = "Afundando em um sonho... A inspiração tem uma premonição",
  [1130504917111552] = "Você olhou fixamente para a sorridente Daisy e o buquê de margaridas. \nDe repente, a pequena Daisy e as margaridas desapareceram ao mesmo tempo.",
  [1130504917111296] = "Depois de colher um punhado de margaridas, a pequena Daisy salta até você. \nEla estende o buquê com as duas mãos, convidando você a sentir a fragrância, e revela uma expressão inocente.",
  [1130504917111040] = "Diante de seus olhos está um grande campo de margaridas, e Daisy está pulando nele, muito feliz. \nA pequena Margarida sorri e olha para cá, depois continua correndo para vários lugares para colher margaridas.",
  [1130504917110784] = "Você se voltou para a fonte do som, mas não viu ninguém. \nVoltando, a rua ficou vazia novamente, com apenas margaridas espalhadas pelo chão e pétalas de margaridas flutuando no ar.",
  [1130504917110528] = "De repente, uma carruagem passou em alta velocidade, a menina foi derrubada pela carruagem e as margaridas foram esmagadas. \nSenhora (narração): Oh, Daisy!",
  [1130504917110272] = "A menina desapareceu repentinamente, deixando apenas margaridas no chão.",
  [1130504917110016] = "Uma menina se espreme no meio da rua, agacha-se para pegar o buquê de margaridas e aproxima-o do nariz para cheirá-lo. \nEntão, a garotinha abraça as margaridas e sorri em sua direção.",
  [1130504917109760] = "Quando a carruagem passou bem na frente do jogador, houve um solavanco, Miss Daisy foi sacudida e as margaridas em sua mão caíram no chão. \nO homem aproveitou para abraçar e acalmar Miss Daisy, a carruagem voltou a se acalmar, e os dois se entreolharam e riram.\n Depois que a carruagem foi embora e desapareceu, os pedestres na rua desapareceram um por um, deixando apenas as margaridas no chão.",
  [1130504917109504] = "Não muito longe, um jovem dirigia uma carruagem, carregando Miss Daisy rapidamente em direção ao jogador. \nSenhorita Daisy segurava um buquê de margaridas. O homem dirigia enquanto provocava Miss Daisy, fazendo-a rir alto.",
  [1130504917109248] = "Você fica sozinho na beira da rua como um observador. \nO fluxo de pessoas na rua surge do nada, uma por uma, tornando-se gradualmente muito animado, mas ninguém percebe sua existência.",
  [1130504917108992] = "Um momento depois...",
  [1130504917108736] = "Parta para retornar ao Clube do Tarô ...",
  [1130504917108480] = "【CS-2.3】 Fragrância Daisy - Terceiro Ciclo",
  [1130504917108224] = "【CS-2.2】 Fragrância Daisy - Segundo Ciclo",
  [1130504917107968] = "【CS-2.1】 Fragrância Daisy - Primeiro Ciclo",
  [1130504917107712] = "【CS-1.3】 Daisy Falls - Terceiro Ciclo",
  [1130504917107456] = "【CS-1.2】 Daisy Falls - Segundo Ciclo",
  [1130504917107200] = "【CS-1.1】 Daisy Falls - Primeiro Ciclo",
  [1130504917106688] = "Rebecca limpou a cena rapidamente. Logo, só você ficou no corredor da escola.",
  [1130504917106176] = "Depois de seguir Susie pela longa escadaria, você chegou ao local do teste...",
  [1130504917105920] = "Dois anos depois... Quinta Época, 1354.",
  [1130504917105664] = "O Sr. Louco usou sua autoridade para criar um afluente do destino do mundo dentro do Rio do Destino.",
  [1130504917105408] = "Antes que o Sr. Louco caísse em um sono profundo, ele descobriu um casulo especial de luz. Para lutar por mais esperança para lutar contra o apocalipse......",
  [1130504917105152] = "Espaço reservado para animação",
  [1130504917104896] = "Animação",
  [1130504917104640] = "Depois de muita atividade, você finalmente enterrou Fula, deixando ela e Jewen descansarem em paz juntos...",
  [1130504917101312] = "Doce Sonho",
  [1130504917101056] = "“...... Leve-me daqui...”",
  [1130504917100800] = "“......Wuu wuu...... Mãe...... não me deixe para trás.......”",
  [1130504917100544] = "“Seu lixo inútil, tão inútil quanto sua mãe que morreu de doença!”",
  [1130504917100288] = "“Mãe, mãe, salve-me…”",
  [1130504917100032] = "“Pare de me bater, pai...... isso dói...... tão doloroso......”",
  [1130504917099776] = "“Você só roubou esse pouco de dinheiro de volta, está tentando me matar de fome!”",
  [1130504917099520] = "“Você é um monstro sem casa!”",
  [1130504917099264] = "“Mate-a!”",
  [1130504917099008] = "“Fique longe dela!”",
  [1130504917098752] = "\"Jogue-a fora!\"",
  [1130504917098496] = "“Ela é um demônio!”",
  [1130504917098240] = "“Ela é uma louca!”",
  [1130504917097984] = "“Ela é uma aberração!”",
  [1130504917097728] = "“Ela costuma dizer coisas estranhas, é muito assustador.”",
  [1130504917097472] = "“Seus pais biológicos também eram Loucos.”",
  [1130504917097216] = "“Os pais dela a deixaram no portão do orfanato.”",
  [1130504917096960] = "“Cara horrível, fique longe de mim!”",
  [1130504917096704] = "Dunn e Daly explicaram brevemente o caso de sequestro de crianças em Tingen e o caso de Arnold.",
  [1130504917096448] = "Não houve resposta de dentro da casa.",
  [1130504917096192] = "Expliquei tudo para Carol.",
  [813709740004608] = "O que você está fazendo aqui?",
  [813709740287744] = "Esta senhora, o que há de errado com você?",
  [813709740596480] = "Não! A roupa da mamãe ainda está pendurada lá fora!",
  [1130369088945664] = "Qual é a situação?! Por que está tão barulhento lá fora?",
  [1130369089517312] = "No Mundo Extraordinário, não existe sucesso garantido. Vamos começar!",
  [1130369090183424] = "Independentemente de estar correto ou não, posso verificar essa hipótese agora.",
  [813709740004352] = "Para nós, pessoas comuns, a guerra sempre foi cruel.",
  [813709740596224] = "Ah? Então eu oro com devoção a você... apresse-se e chova! Apresse-se e troveje!",
  [1130369088945408] = "Minha cabeça está tonta e pesada, como se eu tivesse esquecido alguma coisa...",
  [1130369089517056] = "Hmm, sem problemas, mas o maior perigo vem desses 7 quebra-cabeças desconhecidos...",
  [1130369090183168] = "As respostas às duas perguntas estavam uma vez na cadeira da mesa adivinhação, e uma vez no tampo da mesa... <P_Yellow> As pistas parecem ainda apontar para o ato de adivinhação </> ?",
  [1130369090197248] = "Eu sou Mary, moro ao lado. Há algo em que eu possa ajudar?",
  [1130369090196992] = "Desde que o pequeno Aen desapareceu, o casal Aen tem procurado lá fora todos os dias... Suspiro, pequeno Aen, que garotinha fofa.",
  [1130369090196736] = "Nossa, então são os policiais. Achei que vocês fossem alguns personagens suspeitos.",
  [1130369090196480] = "Somos policiais aqui para investigar o desaparecimento da pequena Aen. Posso perguntar onde está a família dele?",
  [1130369090196224] = "<P_Heart> (Névoa espessa se aproxima) </> Vá você... no dia em que eu sair daqui, você saberá.",
  [1130369090195968] = "<P_Heart> (Zombaria) </> Guarde sua eloquência e espere se surpreender comigo. Ficarei aqui aguardando perguntas até que a verdade guie meu caminho.",
  [1130369090195712] = "Considerando que você me ajudou a descartar uma resposta errada, não vou usar sua imprudência contra você desta vez.",
  [1130369090195456] = "<P_Heart> (Animado) </> Cumprir os arranjos do destino é o que nós, cordeiros, mais deveríamos fazer! Nunca irei contra os resultados de nenhum adivinhação !",
  [1130369090195200] = "Sair deste espaço terá alguns efeitos colaterais... Espero que o destino te proteja e te dê a chance de ser meu espectador.",
  [1130369090194944] = "Obrigado, você já me ajudou muito. Deixe que outros continuem a fazer perguntas. Acabamos de descartar outra opção errada, e a verdade parece estar bem diante de nós...",
  [1130369090194688] = "<P_Heart> (Satisfeito) </> Sim, cumprindo os resultados de cada adivinhação , sempre fiz isso.",
  [1130369090194432] = "Certa vez, <P_Yellow> obtive uma conclusão incorreta </> depois de um adivinhação e perdi meu destino - a verdade que estou esperando agora é <P_Yellow> a nova orientação que o destino me deu </> .",
  [1130369090194176] = "Missão?",
  [1130369090193920] = "Só sei que estou esperando um resultado, uma <P_Yellow> missão que deve ser cumprida </> .",
  [1130369090193664] = "<P_Heart> (Em branco) </> Isso envolve a história e não posso responder. Sem a resposta à questão-chave, não posso deduzir a aparência original da história.",
  [1130369090193408] = "Todas as perguntas parecem girar em torno do verdadeiro motivo da morte de Daisy... Estou curioso, por que você está tão obcecado em descobrir essa verdade?",
  [1130369090193152] = "É uma pena que não tenhamos encontrado a questão mais crítica e não possamos reconstruir a verdade.",
  [1130369090192896] = "Isso é tudo. Teve também o livro 'Morte e Renascimento' que não tive tempo de perguntar...",
  [1130369090192640] = "Ela não usou a adaga para “cometer suicídio” e trancar a porta não era uma pista importante. <P_Yellow> O fator direto que causou sua 'morte' foi o Ritual de Magia na sala </>...",
  [1130369090192384] = "De acordo com as cinco rodadas de questionamentos, sabe-se que <P_Yellow> Daisy é uma adivinhadora, e sua morte está intimamente relacionada às adivinhação atividades que ela exerceu, ao conteúdo do adivinhação e aos clientes do adivinhação </> .",
  [1130369090192128] = "Daisy <P_Yellow> não usou Ritual Magic para substituir a morte de outra pessoa </> ! A verdade da 'morte' ainda não foi descoberta, mas infelizmente não há mais chances de fazer perguntas...",
  [1130369090191872] = "Ignorante! Então vá e seja enterrado com aquele adivinho estúpido!",
  [1130369090191616] = "Eu descobri a verdade, mas não vou te dar a chance de machucar mais ninguém.",
  [1130369090191360] = "...... eu recuso.",
  [1130369090191104] = "Minha existência, sua aparência, tudo cai como gotas de água enfileiradas... Pobres ovelhas, quem pode recusar uma tempestade?",
  [1130369090190848] = "<P_Heart> (risada baixa) </> Não é minha obsessão... você ainda não entendeu? Foi o destino que providenciou isso.",
  [316868191881473] = "Funcionou!",
  [1130369090190592] = "Missão... você ainda está obcecado em completar o destino de 'matar Daisy'?",
  [1130369090190336] = "Cale-se! Em consideração por você me ajudar a encontrar a verdade, não vou perseguir seu desrespeito desta vez. <P_Heart> (Zombando) </> Desaparece, ainda tenho uma missão a cumprir.",
  [1130369090190080] = "Deuses? Deve ser um deus do mal!",
  [1130369090189824] = "<P_Heart> (Carinhosamente) </> O destino me favorece... e me deu uma nova dica. Também orei aos deuses e tive a oportunidade de reexplorar a verdade.",
  [1130369090189568] = "Mas você me disse claramente que estava <P_Yellow> preso em uma carta de Tarot </> , o que está acontecendo?",
  [1130369090189312] = "<P_Heart> (Rindo) </> Você é realmente muito inteligente. Eu não escolhi errado ao escolher você para fazer perguntas.",
  [1130369090189056] = "<P_Heart> (Chocado) </> Você é esse cliente?! Então como você pôde ficar preso nesta carta de Tarô...",
  [1130369090188800] = "Heh, pense bem... como eu poderia ser aquela mulher estúpida que se ilude enganando o destino?",
  [1130369090188288] = "Como você ousa mentir para mim! Não, como você ousa, ouse enganar o destino!",
  [1130369090188032] = "<P_Heart> (Acenando com a cabeça) </> Claro.",
  [1130369090187776] = "Heh, é melhor você ser preciso... caso contrário, o preço de ignorar o destino, sua esbelta— <P_Heart> (levantou a mão e gesticulou duas vezes) </> provavelmente não pode suportar isso.",
  [1130369090187520] = "<P_Heart> (Surpreso) </> Sério?! Na verdade, é uma instrução!",
  [1130369090187264] = "O destino lhe concederá uma fortuna e guiará suas ações subsequentes.",
  [1130369090187008] = "<P_Heart> (Forçando um sorriso) </> Senhor, por favor, vá para a corrida 'Dog Catches Mouse' no Evil Dragon Bar em 7 dias e aposte em um cão de caça vermelho-ferrugem com um entalhe na orelha esquerda.",
  [1130369090186752] = "<P_Heart> (Isso absolutamente não pode ser dito a ele! Mas o adivinhação já mostrou tal resultado, o que devo fazer...) </>",
  [1130369090186496] = "<P_Heart> (Chocado) </> Ah!!! <P_Heart> (Ele, ele vai me matar em uma semana...) </>",
  [1143563228324864] = "Senhor, já recusamos muitas vezes.",
  [1130369090185984] = "<P_Heart> (risada baixa) </> ... Não tenho perguntas a fazer. <P_Yellow> Não importa quais instruções o destino dê, responderei 'bom' </> . Isto é o que nós, cordeiros, deveríamos fazer.",
  [1130369090185728] = "<P_Heart> (Franzindo a testa) </> Hum... talvez uma pergunta específica? Se houver uma direção clara, há uma chance de obter uma resposta mais precisa.",
  [1130369090185472] = "Hehe... tudo está bem. Eu só quero um guia para o futuro.",
  [1130369090185216] = "Olá, senhor. O que você gostaria de adivinhar hoje?",
  [1130369090184960] = "<P_Heart> (Demente) </> Então é isso! Eu entendo tudo, tudo!",
  [1130369090184704] = "Graças a você, você me ajudou a descobrir a verdade da história...",
  [1130369090184448] = "<P_Heart> (Rindo) </> Hehe... eu sei porque...",
  [1130369090184192] = "Como esperado! Daisy <P_Yellow> usou a adaga para iniciar o Ritual de Magia </> , criando sua própria <P_Yellow> morte falsa </> . Mas para que serviu isso? Não há mais chances de fazer perguntas...",
  [1130504917094656] = "Enid correu até seu irmão Pete, bateu palmas gentilmente e entoou uma balada—\n 'A dor, a dor voa, o ursinho espanta a dor, o irmão dorme lindamente...'",
  [1130504917092608] = "Contou ao Mentor Derrick sobre o processo de batalha com os Wraith.",
  [1130369090182912] = "<P_Heart> (Esta carta está se esforçando para me revelar mais informações através de respostas limitadas, o que também parece estar alinhado com seu desejo de escapar daqui...) </>",
  [1130369090182656] = "A localização <P_Yellow> da resposta </> em si também é uma forma de resposta?!",
  [1130369090182400] = "Certo! Ambas as escolhas em relação a <P_Yellow> adivinhação </> apareceram em <P_Yellow> esta sala </> . Poderia ser—",
  [1130369090182144] = "Até agora foram feitas três rodadas de escolhas, e as respostas aparecem em lugares completamente diferentes após cada pergunta. Isso não parece aleatório...",
  [1130369090181888] = "<P_Heart> (Animado) </> Vá em frente, pegue essa história incompleta e vá em busca da única resposta!",
  [1130369090181632] = "Somente descobrindo a verdade da história você poderá sair deste espaço com segurança; esta é na verdade sua única escolha...",
  [1130369090181376] = "Lembre-se, você só tem <P_Yellow> 5 </> chances de fazer perguntas, e eu só posso responder com <P_Yellow> \"Sim\" ou \"Não\" </> .",
  [1130369090181120] = "Há uma nota <P_Yellow></> na mesa; você saberá assim que pegá-lo. Não o perca, <P_Yellow> você pode verificá-lo a qualquer momento se carregá-lo com você </> .",
  [1130369090180864] = "Tudo bem, me diga, qual é a história?",
  [1130369090180608] = "Diga-me qual é a história primeiro e eu a considerarei.",
  [1130369090180352] = "<P_Heart> (Amargamente) </> Mas agora sou uma carta; Só posso responder às perguntas dos outros e não posso perguntar a mim mesmo. Então... <P_Yellow> você pode me ajudar a perguntar? </>",
  [1130369090180096] = "Minha consciência está presa aqui, e só posso sair encontrando a <P_Yellow> verdade da história </>.",
  [1130369090179840] = "<P_Heart> (Vigilante) </> Você é aquela carta de Tarô? É você quem está falando?",
  [1130369090179584] = "Me ajude!!!",
  [1130369090179328] = "Agora... faça-me uma pergunta...",
  [1130369090179072] = "Quem está falando! Tantas vozes... minha cabeça está prestes a rachar...",
  [1130369090178816] = "A carta é... Morte?",
  [1130369090178304] = "Pelo menos você eliminou completamente o perigo e ninguém mais será prejudicado por causa disso, certo?",
  [1130369090174464] = "Hmm... eu entendo, obrigada, Rebecca.",
  [1130369090174208] = "Pelo menos você descobriu a verdade e ninguém mais morrerá inexplicavelmente, certo?",
  [1130369090173952] = "Freqüentemente, não conseguimos resolver os problemas perfeitamente e todos enfrentaremos escolhas difíceis.",
  [1130369090173696] = "Hmm, o Mundo Extraordinário é muito cruel. Também tratei de alguns casos que não pude deixar de lado...",
  [1130369090173440] = "Rebecca, ainda não consigo deixar de pensar neste caso...",
  [1130369090173184] = "Você está bem? Hum... você não parece muito bem.",
  [1130369090172928] = "Espere um momento, {{PlayerName}}!",
  [1130369090172416] = "Uh... minha cabeça dói... Onde está Skana?",
  [1130369090172160] = "……{{NomedoJogador}}! Acordar!",
  [1130369090171648] = "……{{nomedojogador}}……",
  [1130369090170624] = "A névoa... ficou ainda mais espessa.",
  [1130369090170368] = "Ah, você quer dizer os almoços grátis que o pequeno Foga oferece aos trabalhadores?",
  [1130369090169856] = "...... Tosse, um cheiro tão forte de sangue.",
  [1130369090169600] = "Névoa?",
  [1130369090166016] = "Hum... eu sou apenas a esposa dele, só preciso apoiá-lo.",
  [1130369090165760] = "Oh... Tempestade acima... esse era na verdade o desejo do meu marido.",
  [1130369090163712] = "O Opportunity não tratará injustamente ninguém que esteja preparado; o momento em que abre o concurso para funcionários públicos é a melhor chance para as pessoas comuns.",
  [1130369090163200] = "A senhora disse que quem aproveitou a oportunidade mudou-se para lugares mais ricos, North Borough, ou Backlund, e quem não o fez... desculpe, a senhora não disse isso.",
  [1130369090162688] = "A loja de roupas do Sr. Watt, o café da Sra. Sanga, minha antiga casa... tudo na Rua Daffodil é nostálgico.",
  [1130369090162432] = "......Afinal, algumas pessoas não deixam nada para trás.",
  [1130369090160640] = "Eles fazem mais uso de artesanato moderno e complexo, e seus designs são mais nítidos e exclusivos. Engrenagens, formas geométricas e estrelas farão você parecer individualista e elegante, e os preços também são bastante amigáveis.",
  [1130369090160384] = "Se você se preocupa mais com tendências, pode dar uma olhada nas joias à esquerda.",
  [1130369090159872] = "Se preferir romance, pode dar uma olhada nos colares e tiaras à direita.",
  [1130369090159616] = "Tiro vazio",
  [1130369090159360] = "……Adeus.",
  [1130369090159104] = "A delegacia ficará de olho neste local; é melhor você rezar para que sua história possa convencê-los.",
  [1130369090158848] = "Para ser sincero, não acredito em você.",
  [1130369090158592] = "Passe mais tempo com Lola, mesmo que ela não possa mais te ver.",
  [1130369090158336] = "Tudo bem, você me convenceu.",
  [1130369090158080] = "Esta é a promessa de uma mãe para seu filho.",
  [1130369090157824] = "Antes de desaparecer, farei o meu melhor para proteger Lola e esta vizinhança.",
  [1130369090157568] = "Meu senhor, talvez daqui a pouco... ou na próxima semana, ou amanhã, eu posso desaparecer...",
  [1130369090157312] = "Sim, é realmente uma linda casa...",
  [1130369090157056] = "Eles moram aqui?",
  [1130369090156800] = "Ela também tem muita sorte... Morri de doença logo depois, e ela foi levada pela Igreja... Mais tarde, um simpático casal que vendia carne no mercado a adotou.",
  [1130369090156544] = "Ela é muito inteligente. Com apenas cinco anos, ela recolhia bexigas de porco no mercado para vender aos vendedores ambulantes de vinho amargo... Ela também me ajudava cuidadosamente a separar o lixo, enviando os restos de tecido branco para a fábrica de papel, pois poderiam ter um preço mais elevado.",
  [1130369090156288] = "Ela é muito infeliz por ter uma mãe como eu, deixando-a crescer nas pilhas de lixo da Lower Street.",
  [1130369090156032] = "Para minha pequena Lola viver em paz.",
  [1130369090155520] = "Parece que tem algo a ver com você?",
  [1130369090155264] = "......Se você não acredita em mim, você pode perguntar por aí; você saberá o quão seguro este bairro é.",
  [1130369090153728] = "Suspiro... esqueça.",
  [1130369090152960] = "Tenha pena desse homem que perdeu quinze vezes, estranho, esse é o seu raro intervalo! Hahaha!",
  [1130369090151424] = "Uau! Uau, au! Uau, au, au!",
  [1130369090112768] = "Ajude a resolver o animal fora de controle",
  [1130369090112512] = "<P_Heart> (Incoerente) </> E-há um monstro ali, as coisas tocadas por ele também se transformarão em monstros. D-não venha—",
  [1130369090112256] = "<P_Heart> (Parece alguém da Golden Autumn Town, o que aconteceu com ele?) </> Quem quer comer você?",
  [1130369090112000] = "Não, não me coma, não me coma!!!",
  [1130369090110208] = "Ok, obrigado.",
  [1130369090109952] = "Aqui está este jornal para você.",
  [1130369090109696] = "Não há necessidade de perguntar mais.",
  [1130369090109440] = "Me siga.",
  [1130369090109184] = "Boa noite, estou te procurando.",
  [1130369090105600] = "Transição de Cena",
  [1130369090105344] = "Acompanhando café Desi até tarde da noite",
  [1130369090104576] = "Em momentos como este, tenho muita vontade de voltar ao Intis...",
  [1130369090104320] = "Por que... por que Sua doutrinação está se tornando cada vez mais frequente?",
  [1130369090104064] = "É uma ilusão?",
  [1130369090103296] = "Não consigo pensar, só posso usar todo o meu tempo para desenhar o mapa do Continente Sul...",
  [1130369090103040] = "O que a abertura da rota do Mar Berserk realmente significa para as pessoas deste continente? O que isso significa para mim?",
  [1130369090102784] = "Fiquei imerso no ar do Continente Sul e me afoguei, perdendo gradativamente todas as minhas forças.",
  [1130369090102528] = "Ela cantou: 'Durma, durma, quando as asas do Deus da Morte descerem, colheremos bons sonhos.'",
  [1130369090102272] = "Certa vez, vi uma mulher que havia perdido metade do corpo acariciando a criança murcha ao seu lado, e ela estava realmente sorrindo!",
  [1130369090102016] = "Quem é?",
  [1130369090101504] = "<P_Heart> (Ela está com muita dor, como se estivesse sofrendo um tormento desumano.) </>",
  [1130369090100736] = "Hmm, vá até lá e dê uma olhada.",
  [1130369090100480] = "<P_Heart> (Ela não fez nenhum movimento neste momento, então não deveria haver nenhum perigo ainda.) </>",
  [1130369090100224] = "<P_Heart> (A presidente disse que sempre cuidaria de mim.) </>",
  [1130369090099968] = "Uma... garotinha?",
  [1130369090099456] = "Há resquícios de poder extraordinário por toda parte... Um sacrifício? Ou algum tipo de ritual?",
  [1130369090098688] = "A boa notícia é que o Inseto Misterioso também parece um pouco atordoado.",
  [1130369090098432] = "Isso... isso não é nada, ter medo de insetos é da natureza humana...",
  [1130369090098176] = "Oh... querido, me desculpe, eu fiquei um pouco assustado...",
  [1130369090097920] = "O grito privou o livro de seu centro de gravidade e você sofreu um golpe de conhecimento.",
  [1130369090097664] = "Ahhhhh, não venha!",
  [1130369090097408] = "Este momento!",
  [1130369090097152] = "A penugem do Inseto Misterioso começou a balançar violentamente—",
  [1130369090096896] = "Essa distância é suficiente para você beijar toda a penugem de seus membros.",
  [1130369090096640] = "Deu um passo para a direita ligeiramente trêmulo – você e o Inseto Misterioso estavam com medo de assustar um ao outro.",
  [1130369090096384] = "Cautelosamente deu um passo firme com o pé esquerdo, aproximando-se um passo do alvo da caça.",
  [1130369090096128] = "Você se aproxima da minúscula criatura com membros abundantes, tão quieta quanto um gato agachado no beiral.",
  [1130369090095616] = "Já é muito tarde, aproveite seu café e descanse cedo.",
  [1130369090095104] = "Tomar café antes de dormir é um privilégio dos jovens – aqui, seu café Desi, durma cedo, querido.",
  [1130369090094848] = "Sim, senhora. Um pouco de café não afetará o sono.",
  [1130369090094592] = "Ah, {{PlayerName}}, minha corujinha, ficar acordado até tarde não é um bom hábito. Tem certeza que quer café?",
  [1130369090094336] = "Decidido, quero uma xícara de café Desi.",
  [1130369090093312] = "Aqui, o chá gelado doce tem um sabor rico do sul de Loen; certamente permitirá que você tenha um sonho refrescante.",
  [1130369090093056] = "Ah,{{PlayerName}}, pessoas que gostam de chá gelado doce são todas muito fofas — pelo menos é o que eu acho.",
  [1130369090092800] = "Hmm, um copo de chá gelado doce, claro que é chá gelado doce.",
  [1130369090092544] = "Acredito que o autor deste livro e o administrador da sala de documentos, Sr. Heródoto, lhe agradecerão.",
  [1130369090092288] = "Um tremor veio da ponta dos seus dedos – você captou com precisão.",
  [1130369090092032] = "Com a ajuda dos Olhos do Inquisidor Misterioso, você encontrou o Verme Misterioso vagando pelas páginas a uma velocidade incrível.",
  [1130369090091776] = "<P_Heart> (Afinal, ela também é alguém que saiu dos livros de história...) </>",
  [1130369090091520] = "<P_Heart> (Princesa Intis, líder do Element Dawn, Mystic Queen, Clube do Tarô ... as experiências do presidente são muito ricas.) </>",
  [1130369090091264] = "A resposta conhecida por todos - Bernadette Gustav - a presidente do Clube do Tarô .",
  [1130369090091008] = "<P_Heart> (Por que ninguém mencionou isso? Espere, não sou o último a saber, sou?) </>",
  [1130298758791424] = "Um Beyonder tentando avançar",
  [1130298758664448] = "Você acordou...",
  [1130298758662400] = "Comece a agir",
  [1130369090090752] = "<P_Heart> (A presidente é na verdade a princesa mais velha de Intis? Ela é filha do próprio imperador Roselle?) </>",
  [1130369090090496] = "<P_Heart> (Esse nome... é o presidente?) </>",
  [1130369090090240] = "Hum? Este nome é...",
  [1130369090089984] = "Anel de opção",
  [1130369090089728] = "Estou tentando.",
  [1130369090089472] = "Querido, você pegou?",
  [1130369090089216] = "<P_Heart> (O Imperador já foi comido um pouco... Se o administrador, Sr. Heródoto, vir isso, ele definitivamente ficará tão zangado quanto uma Fornalha Misteriosa!) </>",
  [1130369090088960] = "Ah... espero que este pequenino poupe os livros preciosos.",
  [1130369090088704] = "Bem, você pode vir até mim a qualquer momento se tiver pistas.",
  [1130369090088448] = "......Se for esse o caso, então as coisas serão difíceis de lidar.",
  [1130369090088192] = "O principal problema é que a pessoa no canto parece completamente diferente do assassino que estamos rastreando. A menos que...",
  [1130369090087936] = "Então o que estamos esperando?",
  [1130369090087680] = "Esse cara é muito misterioso... O barman, Alex, me contou que só apareceu no Evil Dragon Bar recentemente. Toda vez ele fica sentado sozinho no canto, resmungando para si mesmo, e às vezes até mostra um sorriso estranho.",
  [1130369090087424] = "Nada mal, penso o mesmo que você.",
  [1130369090086912] = "No entanto, ele não deveria estar relacionado a este caso de assassinato cruel. Ele tem um álibi; ele estava participando de outra luta de boxe no momento de sua morte.",
  [1130369090086656] = "Hmm... aquele boxeador tem um problema. Existem vestígios de Beyonder itens nele.",
  [1130369090086400] = "Observe atentamente novamente.",
  [1130369090086144] = "Nas palavras do Imperador Roselle, ele tem o coração de um ladrão, mas não a coragem de um ladrão.",
  [1130369090085888] = "Rubi? Não, ele não é um Beyonder . Ele é apenas uma pessoa comum que adora jogar e beber e tem medo da esposa.",
  [1130369090085632] = "Quem você acha que é o mais suspeito aqui?",
  [1130369090085376] = "Pegue esta taça de vinho, vá até lá e compre um drink para ela, garanto que todas as suas preocupações serão dissipadas!",
  [1130369090085120] = "Hehe, acho que o Hein ali não é ruim. Olha o sorriso dela, que charmoso!",
  [1130369090084864] = "Coisas interessantes?",
  [1130369090084608] = "Não se preocupe com esses caras, você deveria prestar mais atenção às coisas interessantes.",
  [1130369090084352] = "Hmph, do que você tem medo? O Evil Dragon Bar é o território de Swayne; quem se atreveria a causar problemas aqui?",
  [1130369090084096] = "Quando passei por aqui agora há pouco, ouvi-o falando sozinho e fazendo sons estranhos de risada. Foi bem assustador...",
  [1130369090083840] = "Além disso, aquele homem na mesa do canto também está agindo de forma misteriosa.",
  [1130369090083584] = "Shh, fale baixo. Essa pessoa não parece alguém com quem mexer. Quando ele estava olhando para mim agora há pouco, todos os pelos do meu corpo se arrepiaram.",
  [1130369090083328] = "Esse cara está lá em cima há muito tempo, me pergunto o que ele está realmente fazendo?",
  [1130369090083072] = "Tempestade acima, garanto que desta vez não há problema!",
  [1130369090082816] = "Ah, desculpe Edgar, acho que devo ter errado em algum lugar! Aqui está, esta é uma erva fresca com aroma noturno.",
  [1130298758781184] = "Verifique cuidadosamente a gaita",
  [1130369089409536] = "{{Sr.|Sra.}}, são 3 Sol no total.",
  [1130369090082048] = "Deve ser a sua receita que está errada, por que você está me culpando!",
  [813709740222720] = "Desejo a você um futuro brilhante hoje! Apenas um pequeno desejo de um estranho.",
  [813709740521216] = "Aham! É aí que você está errado! Vá em frente, vá em frente! Não perturbe meus negócios!",
  [1130369090080512] = "Hmph, ele apenas fornece um local para negociação!",
  [1130369090080256] = "Swayne não apenas empresta dinheiro a juros, mas também recebe um vigésimo dos ganhos de todas as barracas daqui! É realmente um negócio lucrativo.",
  [1130369090043392] = "Obrigado, de repente perdi o apetite.",
  [1130369090043136] = "Mas diz-se que este cogumelo deve estar completamente cozido antes de poder ser consumido. Caso contrário, esses cogumelos drenarão o sangue e a carne de uma pessoa até se transformarem em um cogumelo gigante.",
  [1130369090042880] = "Que mágico!",
  [1130369090042624] = "Recentemente, tem circulado no mar que existe um cogumelo branco-leitoso popular entre os piratas. Se você cortar a pele, o leite branco como a neve escorrerá e terá gosto de carne de peixe tenra.",
  [1130369090042112] = "Eu... vou tentar! Obrigado!",
  [1130369090041856] = "Eu caí no atoleiro da tentação quando era jovem, mas pequena Eve, você ainda tem uma chance de começar de novo.",
  [1130369090041600] = "Você pode ir até a 'Associação da cidade de Tingen para ajudar os empregados domésticos' na Champagne Street para se registrar. Eles organizam treinamento básico regularmente para ajudá-lo a encontrar um emprego adequado.",
  [1130369090041344] = "Eu... eu realmente não sei o que posso fazer.",
  [1130369090041088] = "Pequena Eve, por que você não muda para um emprego decente?",
  [1130369090040832] = "Do dinheiro que ganhamos, quantos centavos podemos guardar para nós mesmos?",
  [1130369090040320] = "Depois que papai foi demitido da fábrica, ele começou a beber suas mágoas todos os dias. Tive que abandonar a escola dominical da igreja para ajudar minha mãe a lavar roupas para outras pessoas, mas agora minha mãe também está doente e eu tenho que...",
  [1130369090040064] = "Embora pareça uma piada, tudo pode acontecer no Mundo Extraordinário, então vamos lá.",
  [1130369090039808] = "Sra. Luna trata materiais contendo espiritualidade como alimento. Só precisamos levar um pouquinho de pó e saberemos se a transação é honesta.",
  [1130369090039552] = "Tudo bem... então como esse gato, er, quero dizer, a respeitável Sra. Luna, verifica a autenticidade do material Beyonder para nós?",
  [1130369090039296] = "Não a subestime. Dona Luna nasceu da morte e suas pupilas esmeraldas sustentam o olhar do Deus da Morte. Qualquer um que ofender a Sra. Luna será embutido nas paredes escuras.",
  [1130369090039040] = "Lua? Aquele gato andando por aí?",
  [1130369090038784] = "Escreva os itens que você está vendendo no quadro negro da câmara escura. Assim que o acordo for alcançado, a Sra. Luna verificará a autenticidade do Beyonder material para nós.",
  [1130369090038016] = "Ahem... Larry, para ser honesto, sua cabeça não era muito exuberante antes de você se juntar aos Mandated Punishers. Talvez isso não seja causado por fatores Beyonder.",
  [1130369090037760] = "Na verdade, tenho tido pesadelos todas as noites recentemente e notei bastante cabelo no meu travesseiro quando acordo de manhã.",
  [1130369090037504] = "Sim, estamos sempre lutando contra perigos desconhecidos...",
  [1130369090037248] = "Se os diáconos não tivessem chegado a tempo de conter a perda de controle, ele quase teria se transformado em um monstro...",
  [1130369090036992] = "Suspiro, tenho pensado ultimamente que talvez se aposentar mais cedo como o capitão Swain e encontrar um emprego estável seria uma escolha melhor.",
  [1130369090036736] = "A situação é terrível. Da última vez, eu estava em uma missão ao longo do rio Tussock e quase fui arrastado para a água por um fantasma aquático.",
  [1130369090036224] = "Você realmente deveria ir ao Restaurante Bonaparte e ser um crítico gastronômico. Vou levar esse peixe também.",
  [1130369090035968] = "O peixe Tussock é macio e tem poucas espinhas, o que o torna perfeito para fritar. Polvilhe um pouco de cominho e alecrim e fica crocante por fora e macio por dentro, dourado e delicioso. Absolutamente saboroso!",
  [1130369090035200] = "Tempestade acima, sugiro que ele vá à igreja orar no domingo e pare de ir ao mar por um tempo. Ele deve ter cuidado para não ganhar dinheiro que não viverá para gastar.",
  [1130369090034944] = "Desde então, ele tem ouvido frequentemente sussurros aterrorizantes, por isso está desesperado para encontrar um guarda-costas confiável para acompanhá-lo nesta viagem.",
  [1130369090034688] = "Ele encontrou algumas situações estranhas. Em sua última viagem, ele viu uma estranha estátua de pedra resgatada no porto de Bansy. Dizem que estava coberto de algas pegajosas e os padrões esculpidos eram ainda mais bizarros e assustadores...",
  [1130369090034432] = "Uma comissão tão alta é rara. No que ele se meteu?",
  [1130369090034176] = "A comissão visa proteger um comerciante que viaja para o continente sul para o comércio de especiarias, 600 libras. Interessado?",
  [1130369090033920] = "Que idiota! Espero que ele tenha um olho melhor para as pessoas do que para os cães, ou não durará muito aqui.",
  [1130369090033664] = "Alex deve ter se enganado com sua aparência feroz! Os cães vadios que Ruby vende aqui são sempre exibidos e proibidos.",
  [1130369090033408] = "Suspiro, não mencione isso! Isso me fez perder meio mês bebendo dinheiro na última competição. Eu realmente não consigo entender como foi escolhido.",
  [1130369090033152] = "E seu oponente, aquele grande cachorro preto e branco, parece tão estúpido. Algumas vezes até começou a brincar com os ratos com entusiasmo!",
  [1130369090032896] = "Amigo, você deve apostar no House na próxima corrida 'Dog Catches Mouse'. Ouvi dizer que tem a linhagem de um cão de caça do Condado de Winter; com certeza pegará mais ratos!",
  [1130369090032640] = "Hehe, se você estiver com pouco dinheiro, pode vir até mim.",
  [1130369090032384] = "Obrigado pela sua orientação!",
  [1130369090031872] = "Mas em locais que não conseguimos ver, ainda há muitas pessoas que arriscam as suas vidas para proteger Tingen.",
  [1130369090031616] = "Que loucura!",
  [1130369090031360] = "Alguns ficam ricos da noite para o dia, outros ficam em perigo.",
  [1130369090031104] = "Tingen? Como sempre, esta é uma cidade onde coexistem riscos e oportunidades.",
  [1130369090030848] = "Você pode me apresentar a situação em Tingen?",
  [1130369090030592] = "Você pode encontrar aqui muitas coisas que precisa: novidades, itens, recompensas... quanto ao resto, vá e descubra você mesmo.",
  [1130369090030336] = "O Evil Dragon Bar é um dos bares mais animados de Tingen e ponto de encontro de algumas organizações oficiais. Os trabalhadores das docas e das fábricas adoram reunir-se aqui.",
  [1130369090030080] = "Jovem, você tem perguntas que deseja fazer?",
  [1130369090029824] = "Desejo a você uma noite maravilhosa.",
  [1130369090029568] = "Além disso, Loen já aprovou leis proibindo essas coisas.",
  [1130369090029312] = "Ah, não, somos pessoas civilizadas e não faríamos coisas tão incivilizadas.",
  [1130369090029056] = "Cães ferozes? Você está tendo brigas de cães?",
  [1130369090028800] = "Ah, também há cães ferozes no bar. Embora eu ache que não, é melhor você também não tocá-los.",
  [1130369090028544] = "Assim como o nome, cada taça de vinho aqui é um presente do dragão.",
  [1130369090027520] = "A cerveja de centeio custa 1 centavo o copo, a cerveja Enmat custa 2 centavos, a cerveja Southwell custa 4 centavos ou você gostaria de um copo de Ronchi puro malte?",
  [1130369090027264] = "Se for o último caso, os livros na estante devem atender às suas necessidades nesta fase. Eu recomendo que você comece a ler da esquerda para a direita.",
  [1130369090027008] = "Se for o primeiro, você pode tentar com confiança. Mesmo que haja alguns pequenos acidentes, eu devo ser capaz de salvá-lo.",
  [1130369090026752] = "Ah... você quer refinar algumas poções ou amuletos? Ou você quer aprender algum conhecimento oculto?",
  [1130369090026496] = "Quanto ao resto, só posso dizer que ele tem sentimentos muito profundos pela equipa do Tingen Vigia Noturno.",
  [1130369090026240] = "Ele foi designado para o time de Soest antes. Embora ele tenha ficado apenas meio ano, ouvi dizer que ele ainda se preocupa muito com seus companheiros de equipe do Soest.",
  [1130369090025984] = "Um cara que parece um pouco frívolo, mas na verdade é muito educado.",
  [1130369090025728] = "Minha tarefa é reforçar o esquadrão Vigia Noturno que enviou o sinal, mas também tenho tempo livre.",
  [1130369090025472] = "Então a razão pela qual você está aqui é...",
  [1130369090025216] = "Red Gloves pode rastrear e prender criminosos e indivíduos malvados sob vigilância sem restrições.",
  [1130369090024960] = "Geralmente, Vigia Noturno esquadrões precisam estar estacionados dentro de suas próprias jurisdições e não podem perseguir criminosos fora delas sem permissão, o que na verdade é bastante inconveniente.",
  [1130369090024448] = "Alguns nos chamam de rastreadores, outros nos chamam de cães de caça.",
  [1130369090024192] = "O que as Luvas Vermelhas representam?",
  [1130369090023936] = "Há mais alguma coisa que você gostaria de perguntar?",
  [1130369090023680] = "Perto da lareira é mais seco e raramente as pessoas vêm aqui. Ocasionalmente, ouve-se o som de garrafas e potes tilintando; Eu gosto dessa sensação.",
  [1130369090023424] = "Por que não ficar no amplo e luminoso Hall do primeiro andar?",
  [1130369090023168] = "As Luvas Vermelhas não têm jurisdição fixa. Leonard sempre gosta de voltar aqui, e eu também apareço de vez em quando.",
  [1130369090022912] = "Luva Vermelha... assim como Leonard.",
  [1130369090022656] = "Olá.",
  [1130369089979392] = "Que incrível, sinto que o Aiden está ao meu lado... Estou muito ansiosa pelo dia em que nos reencontraremos!",
  [1130369089979136] = "No dia em que vocês se encontrarem novamente, use sua música para contar a ele sobre sua alegria e crescimento.",
  [1130369089978880] = "A parte inacabada da música fica para você continuar escrevendo. Não importa quão difícil seja o caminho a seguir, mantenha viva esta esperança.",
  [1130369089978624] = "Esta gaita e partitura, que carregam amor e esperança, são suas bênçãos para você.",
  [1130369089978368] = "Ele espera mais do que ninguém que você seja forte; ele espera mais do que ninguém que você encontre a felicidade.",
  [1130369089978112] = "Isto também é o que Aiden mais espera ver.",
  [1130369089977856] = "Sinto que estou um passo mais perto do dia em que me reencontrarei com meus pais!",
  [1130369089977600] = "Isso é maravilhoso! Essa música realmente tem magia. Aiden estava certo – contanto que você acredite, isso definitivamente pode ser feito!",
  [1130369089977344] = "Aiden e os outros estão indo muito bem. Ele nunca esqueceu sua promessa para você; foi a preocupação dele que me levou a encontrar você.",
  [1130369089977088] = "......Aiden......",
  [1130369089976832] = "A alma de Aiden irá cercá-lo na forma de uma melodia, dizendo que ele nunca foi embora.",
  [1130369089976576] = "Algum dia, quando você encontrar sua família, quando você tocar essa gaita novamente...",
  [1130369089976320] = "Você pode. No final de um conto de fadas, o protagonista sempre consegue superar as dificuldades, não é mesmo?",
  [1130369089976064] = "Eu... posso?",
  [1130369089975808] = "Martha, viva com essa força dele, continue buscando sua família e realize seu sonho inacabado.",
  [1130369089975552] = "Ele deixou para você não apenas uma gaita e uma partitura, mas também o presente mais precioso: o amor e a esperança.",
  [822439798126848] = "O que aconteceu?",
  [1130369089832192] = "Aqui, seu leite quente. Espero que ajude você a ter um bom sonho.",
  [1130369089809664] = "Convidado especial —{{PlayerName}}— esteja atento ao seu status. Você não tem o direito de interferir no andamento normal da apresentação.",
  [1130369089975296] = "Esse apego se transformou em uma melodia inacabada, persistente e sem vontade de sair, me levando a te encontrar.",
  [1130369089975040] = "Ele nunca esqueceu sua promessa para você. Mesmo no último momento de sua vida, seu coração ainda estava cheio de preocupação por você.",
  [822439797928192] = "Perguntar",
  [1130369089160448] = "Diz trinta centavos.",
  [1130369089029376] = "Muito obrigado, sua eficiência é admirável.",
  [1130369088937216] = "Estamos limpando; há poeira e desordem por toda parte na empresa, e todo mundo simplesmente não consegue aprender a colocar as coisas onde elas pertencem!",
  [1130369088767232] = "Certamente podemos pedir comida de outros restaurantes ocasionalmente, mas talvez algumas coisas não possam ser substituídas.",
  [1130369088752896] = "O Capitão Frye enviou você? Ou você se voluntariou?",
  [1130369089553664] = "Parece... coisas que pertencem a crianças.",
  [1130369089422592] = "Ainda não sei, então preciso que você vá investigar.",
  [1130369089363200] = "Então precisamos encontrar as pessoas que estiveram aqui recentemente e verificar suas condições?",
  [1130369089974784] = "C-como isso é possível! Prometemos terminar esta música juntos...",
  [1130369089974528] = "Esta gaita e a partitura são os últimos vestígios que ele deixou neste mundo...",
  [1130369089974272] = "Aiden... ele não pode mais vir... Aiden e seu filho já deixaram este mundo.",
  [1130369089974016] = "Por falar nisso! Como estão Aiden e seu filho agora? Não sei quando poderei vê-los novamente.",
  [1130369089973760] = "<P_Heart> (Então por trás dessa melodia inacabada, há uma esperança de viver...) </>",
  [1130369089973504] = "A criança intimidada conheceu um mágico misterioso. E o final de um conto de fadas é sempre lindo.",
  [1130369089973248] = "Desde que conheci Aiden, me sinto protagonista de um conto de fadas.",
  [1130369089972736] = "Hum! É um acordo!",
  [1130369089972480] = "Com certeza terminarei esta peça musical inacabada. Quando você ouvir essa melodia novamente, será o dia em que nos reuniremos.",
  [1130369089972224] = "Espero que sim. A família de Martha também deve estar ansiosa para se reunir com você em breve.",
  [1130369089971968] = "Isso é maravilhoso! Você se reunirá com seu filho em breve!",
  [1130369089971712] = "Sim, alguém viu uma criança perto do cais que se parecia muito com o meu pequeno Bart. Desta vez com certeza vou encontrá-lo!",
  [1130369089971456] = "Aiden, você vai embora amanhã de manhã?",
  [1130369089971200] = "Contanto que você acredite, isso definitivamente acontecerá.",
  [1130369089970944] = "Então espero que todos que ouvirem esta música possam se reunir com sua família perdida.",
  [1130369089970688] = "Claro! Mágica Marta.",
  [1130369089970432] = "Eu... posso mesmo?",
  [1130369089970176] = "Podemos gravar a melodia que você acabou de tocar e criar uma peça musical juntos.",
  [1130369089969920] = "Que ótimo, Martha, você aprende tão rápido!",
  [1130369089969664] = "Claro! Venha, assim...",
  [1130369089969408] = "Aiden, posso aprender gaita com você? Espero também poder trazer força para outras pessoas com minha música como você.",
  [1130369089969152] = "<P_Heart> (Para Aiden neste momento, talvez a música seja seu melhor conforto...) </>",
  [1130369089968896] = "<P_Heart> (Quando eu estava indefeso, Aiden me deu forças. Agora, como devo confortar Aiden...) </>",
  [1130369089968640] = "Obrigado, Marta. Espero que ele possa ser tão forte quanto você!",
  [1130369089968384] = "Acredito que o pequeno Bart deve estar pensando a mesma coisa!",
  [1130369089968128] = "Mas se eu morrer sem ver meus pais mais uma vez, seria uma pena. Então, tenho me esforçado muito para sobreviver.",
  [1130369089967872] = "Muitas vezes sinto que não viverei para ver o sol de amanhã.",
  [1130369089967616] = "Na verdade... também perdi meus pais e agora estou sozinho. não sei onde eles estão...",
  [1130369089967360] = "Obrigado, Marta.",
  [1130369089967104] = "Olha, eu me lembrei disso depois de ouvir apenas uma vez. O pequeno Bart com certeza não esquecerá a música que você escreveu para ele!",
  [1130369089966848] = "Esta é... a música que escrevi para o pequeno Bart.",
  [1130369089966592] = "<P_Heart> (cantarolando a música de Aiden) </>",
  [1130369089966336] = "Obrigado, Marta. Antes de me separar do pequeno Bart, ele também me abraçou gentilmente assim.",
  [1130369089966080] = "Aiden, acredito que o pequeno Bart está trabalhando tanto quanto você e também está ansioso para se reunir com você.",
  [1130369089965824] = "Mas... já faz um ano, talvez o pequeno Bart tenha esquecido há muito tempo, ou ele já...",
  [1130369089965568] = "Acredito que se ele ouvir essa música por perto, com certeza aparecerá diante de mim.",
  [1130369089965312] = "Tenho procurado por ele em todos os lugares. Essa música foi o que escrevi para ele; ele me ouvia tocar desde que era pequeno.",
  [1130369089965056] = "Meu pequeno Bart, ele tinha mais ou menos a sua idade.",
  [1130369089964800] = "Hoje, há um ano... meu filho e eu fomos separados por outro asilo... e eventualmente nos perdemos.",
  [1130369089964544] = "O que... o que há de errado?",
  [1130369089964032] = "Essa maldita regra de separar adultos e crianças torna impossível para mim encontrar você durante o dia.",
  [1130369089963776] = "Aiden! Eu sabia que era você!",
  [1130369089963520] = "Parece que nem um mágico é páreo para Duncan.",
  [1130369089963008] = "Quem está gritando lá fora!",
  [1130369089962752] = "Por favor, comece sua apresentação, Sr. Aiden.",
  [1130369089962496] = "Uau! Depois quero sentar-me elegantemente como eles e comer pão em pequenas porções.",
  [1130369089962240] = "Você pode curtir a Música enquanto saboreia o Pão, assim como aquelas crianças nobres.",
  [1130369089961984] = "Se você gostou, deixe eu, esse mágico, tocar outra música para você.",
  [1130369089961728] = "As pessoas aqui nunca fariam isso! Cada um só se preocupa com a sua própria sobrevivência...",
  [1130369089961472] = "E quando eu estava com fome, você até tirou pão para dividir comigo!",
  [1130369089961216] = "Ser capaz de tocar uma música tão linda em um lugar como o asilo.",
  [1130369089960960] = "Você é como... como um mágico de uma lenda!",
  [1130369089960704] = "Não, não, não, quero dizer, tudo isso é como um sonho...",
  [1130369089960448] = "......Por que isso soa como um insulto?",
  [1130369089960192] = "Aiden... você é... você é humano?",
  [1130369089959936] = "Obrigado, Aiden!",
  [1130369089959680] = "Aqui, coma um pouco de pão.",
  [1130369089959424] = "Hehe, esse som não é tão agradável.",
  [1130369089959168] = "<P_Heart> (Gorgolejo - gorgolejo) </>",
  [1130369089958912] = "Meu nome é Marta.",
  [1130369089958400] = "Tenho a honra de conhecer um ouvinte que sabe apreciá-lo.",
  [813709740222464] = "Quando você chegar à minha idade, perceberá como é confortável ser saudável, não se preocupar e sentar em um banco lendo um jornal.",
  [813709740520960] = "Mas lembro que nos livros o grande aventureiro Gehrman só usava cartola?",
  [1130298758780672] = "Pergunte aos moradores sobre a situação",
  [1130369089409280] = "Olá, gostaria de comprar presunto de boa qualidade.",
  [1130369089957120] = "Ah! Ah! Se você tiver coragem... me mate!",
  [1130369089884160] = "Voltar?",
  [1130369089883904] = "Parece que isso não é fácil Missão .",
  [1130369089883648] = "...... Diga a Sua Alteza Bernadette ......",
  [1130369089883392] = "Meu único arrependimento... é não ter trazido histórias para dormir... de todo o mundo...",
  [1130369089883136] = "Mesmo que eu tenha perdido para o Sábio Oculto, não parei meus passos.",
  [1130369089882880] = "Atravessei o Mar Berserk, viajei pelo continente, desenhei um mapa-múndi. Meu querido, fiz tudo que pude...",
  [1130369089882624] = "...... Toda a minha vida foi perseguida pelo conhecimento, mas eu também não passei a vida inteira perseguindo o conhecimento?",
  [1130369089882368] = "Claro.",
  [1130369089882112] = "......Você é tão gentil, minha querida. Você poderia fazer mais uma coisa por mim?",
  [1130369089881600] = "Posso servir alguma bebida? As habilidades da Sra. Amanda são muito boas, e a Presidente... Sua Alteza Bernadette, também ficará muito feliz em vê-la.",
  [1130369089881344] = "Me desculpe... eu machuquei você? Eu realmente sinto muito...",
  [1130369089881088] = "......Estou muito feliz em ver você aqui.",
  [1130369089880832] = "......É você.",
  [1130369089880576] = "Sra.",
  [1130369089880320] = "Sua Alteza... eu não quero te machucar... eu não quero te machucar...",
  [1130369089880064] = "Eu não sou um monstro! <P_Yellow> Sua Alteza Bernadette </> ... Eu não sou um monstro... Eu não sou um monstro!",
  [1130369089879808] = "Não venha! Não venha!",
  [1130369089879552] = "Você realmente fugiu, nada mal.",
  [1130369089879296] = "Porque este não é um tipo de criatura inteligente do Mundo Espiritual. Contanto que o corpo-mãe seja controlado, a maré de insetos pode ser facilmente eliminada.",
  [1130369089879040] = "Os insetos... desapareceram todos?",
  [1130369089878528] = "Pare, eu vou controlá-la.",
  [1130369089878016] = "Boa noite.",
  [1130369089877504] = "......Boa noite, presidente.",
  [1130369089877248] = "Obrigado por poder me contar essas histórias.",
  [1130369089876992] = "Meus velhos amigos são muito, muito poucos agora.",
  [1130369089875968] = "Ela tem muitas, muitas histórias para contar.",
  [1130369089875456] = "Presidente...",
  [1130369089875200] = "Ela disse que há muito, muito tempo atrás, no leste do leste, vivia um grupo de gigantes...",
  [1130369089874944] = "Uma voz nos fez voltar a ser 'eu'.",
  [1130369089874688] = "Mais tarde...",
  [1130369089874432] = "Nós, que estamos desmoronando em todas as direções, somos como fogos de artifício florescendo.",
  [1130369089874176] = "Eu... não, nós suportamos milhares de doutrinações de conhecimento, gestando constantemente, nascendo constantemente, morrendo constantemente.",
  [1130369089873920] = "......Mais profundo que o núcleo da Terra, mais alto que o céu estrelado......",
  [1130369089873664] = "Eu quero ir para lá... é mais ao sul que o Continente Sul, mais ao norte que o Continente Norte, mais a leste que o Mar Sônia, mais a oeste que o Mar da Neblina...",
  [1130369089873408] = "<P_Heart> (Lembrei-me daquela Flesh Magic, deixando o Inseto Misterioso do Mundo Espiritual devorar meu corpo.) </>",
  [1130369089873152] = "<P_Heart> (Mesmo que eu tenha que pagar com meu corpo, minha vida, meu tudo...) </>",
  [1130369089872896] = "<P_Heart> (Só mais um pouco... contanto que eu aguente um pouco mais... posso encontrar a resposta...) </>",
  [1130369089872640] = "Não... eu nunca vou desistir assim...",
  [1130369089872384] = "Diga-me... diga-me! Deus Onisciente, Sábio Oculto, conte-me tudo!",
  [1130369089872128] = "Eu... eu nunca esquecerei... o continente oriental que você mencionou! O Continente Ocidental que deve existir!",
  [1130369089871872] = "Não... impossível!",
  [1130369089871616] = "<P_Heart> (Não sobrou nada... nada restou... nem mesmo uma direção para dar um passo à frente...) </>",
  [1130369089871360] = "<P_Heart> (O céu estrelado, e acima do céu estrelado...) </>",
  [1130369089871104] = "<P_Heart> (Além dos Cinco Mares... abaixo da terra...) </>",
  [1130369089870848] = "<P_Heart> (Mais ao sul que o Continente Sul, mais ao norte que o Continente Norte, mais a leste que o Mar Sônia, mais a oeste que o Mar Nevoeiro...) </>",
  [1130369089870336] = "<P_Heart> (Este mundo... parece terminar aqui.) </>",
  [1130369089870080] = "<P_Heart> (Mas ganância.) </>",
  [1130369089869824] = "<P_Heart> (No momento em que terminei o mapa, o que tomou conta de mim não foi a satisfação...) </>",
  [1130369089869312] = "É governado pelo dividido Império Balam. Depois que as rotas marítimas foram abertas, mais e mais frotas do Continente Norte navegaram, lutando pelas terras, recursos e pessoas aqui, transformando o lugar em uma bagunça lamacenta.",
  [1130369089869056] = "Este é um continente atrasado. As pessoas acreditam no Deus da Morte. O meio de transporte mais comum não é uma carruagem, mas um caixão.",
  [1130369089868800] = "Quanto às perigosas correntes e tempestades do Mar Berserk... comigo aqui, o navio não se perderá.",
  [1130369089868544] = "Devo ir mais longe... até... ao lendário Continente Oriental, ao Continente Ocidental, até ao centro da terra, até ao céu estrelado.",
  [1130369089868288] = "Eu mal podia esperar para assumir o trabalho de expandir as rotas marítimas. Quero atravessar o mar sozinho, quero ver o outro lado do mundo com os meus próprios olhos e quero desenhar o mapa do Continente Sul com as minhas próprias mãos.",
  [1130369089868032] = "Oh... louvado seja o Imperador Roselle. Ele cruzou o Mar Berserk e descobriu o Continente Sul, que originalmente só existia em livros antigos.",
  [1130369089867776] = "Desde o início da Quinta Época, tem sido a barreira natural que isola o Continente Norte.",
  [1130369089867520] = "Embarquei em um navio para o Continente Sul e naveguei até o Mar Berserk, que tem inúmeras correntes perigosas.",
  [1130369089867264] = "<P_Heart> (...tentei encontrar a resposta a partir do conhecimento que Ele me incutiu, mas a dor de cabeça tornou-se cada vez mais insuportável.) </>",
  [1130369089867008] = "<P_Heart> (E além dos Cinco Mares? Poderia haver um Sexto Mar, um mar subterrâneo... o céu é um mar?) </>",
  [176266263183104] = "Fantoche",
  [1130369089866752] = "<P_Heart> (Vivemos no Continente Norte. Poderia haver um Continente Sul? Ou um Continente Oriental? Um Continente Ocidental?) </>",
  [176266263189504] = "Monstro",
  [176266263158528] = "Lua",
  [1130369089866496] = "<P_Heart> (Sua Alteza Bernadette, eu sei que a leste da Cordilheira Hornacis fica o Reino de Loen, mas não sei onde fica mais a oeste do que o Mar Nevoeiro.) </>",
  [1130369089866240] = "<P_Heart> (Lembrança) </> Existe algum lugar mais a leste do que a Cordilheira Hornacis, ou mais a oeste do que o Mar Nevoeiro?",
  [1130369089865984] = "<P_Heart> (O extremo oeste do Continente Norte, e também o extremo oeste de Intis, que é o Mar Nevoeiro.) </>",
  [1130369089865728] = "<P_Heart> (Finalmente... acabou...) </>",
  [1130369089864960] = "......Sua Alteza Bernadette é uma pessoa honesta!",
  [1130369089864704] = "Aquela era uma criança travessa cujo nariz cresceria o suficiente para ser um pé de cabra quando ele mentisse. A Mãe Terra tolerou-o e guiou-o para se tornar um bom filho.",
  [1130369089864448] = "Talvez venha de um antigo conto de fadas local – fala de um boneco de madeira que ganhou vida pela Mãe Terra.",
  [1130369089864192] = "Há um provérbio aqui: \"Os mentirosos têm nariz comprido.\"",
  [1130369089863936] = "Existem vastas planícies em Feynapotter, ricas em café, cacau, tabaco e vários grãos. O macarrão Feynapotter é delicioso, ah! Um presente da Mãe Terra.",
  [1130369089863680] = "O Reino Feynapotter é uma grande potência no sul do Continente Norte, acreditando na Igreja Mãe Terra. É quente e úmido aqui, e o ar está repleto do som da brisa do mar e da música de Feynapotter.",
  [1130369089863424] = "......Talvez Sua Alteza Bernadette gostasse.",
  [1130369089863168] = "Dream Island é a Ilha Sonia a leste de Loen? É chamada de pérola do Mar Sônia, e diz a lenda que lá vivem elfos.",
  [1130369089862912] = "Na história de ninar contada pela esposa do vizinho, o protagonista é um garotinho que mora na Ilha dos Sonhos, usa um cogumelo como chaminé, convive com fadas e sereias e nunca vai crescer...",
  [1130369089862656] = "Ah... não está tão quente quanto Intis aqui. Está sempre com neblina e muitas vezes chove... precisa do favor do sol.",
  [1130369089862400] = "A capital, Backlund, é chamada de “Cidade da Esperança”, mas a sua atmosfera social é muito mais conservadora do que Intis; casos extraconjugais se tornariam fofocas chocantes.",
  [1130369089862144] = "Aqui, a Igreja do Deus do Vapor e das Máquinas, a Igreja da Deusa da Noite Eterna e a Igreja do Senhor das Tempestades são as religiões dominantes. Também permite que a Igreja Mãe Terra pregue. Acho que a tolerância é um sinal de forte produtividade.",
  [1130369089861888] = "Mesmo sendo uma pessoa Intis, tenho que admitir a força do Reino Loen.",
  [1130369089861632] = "......Sua Alteza Bernadette gostaria disso?",
  [1130369089861376] = "Esta é uma música para guerreiros que vão para a guerra. A fé no Deus do Combate contagia tudo aqui.",
  [1130369089861120] = "...... Uma linda garota está na margem íngreme, cantando como uma luz brilhante de primavera.",
  [1130369089860864] = "......Sempre que flores de pera florescem no horizonte, uma gaze macia flutua sobre o rio.",
  [1130369089860608] = "Ah, tem uma música popular aqui...",
  [1130369089860352] = "O povo de Feysac acredita na Igreja Deus do Combate. Eles têm linhagens gigantes; todo mundo é alto e forte. Talvez esta seja uma das razões pelas quais conseguiram derrotar o Reino de Loen na Guerra dos Vinte Anos.",
  [1130369089860096] = "O Império Feysac é um país frio. Ao norte fica o vasto Mar do Norte. Na capital, Saint-Malo, eu usava roupas muito grossas todos os dias; o vento frio me deixou com medo de sair.",
  [1130369089859840] = "Pelo menos o Imperador nunca deveu salário a ninguém...",
  [1130369089859584] = "Oh, o Imperador Roselle era realmente uma pessoa inquieta. Ouvi dizer que a partida de Sua Alteza Bernadette também ocorreu porque ela estava insatisfeita com o governo de seu pai.",
  [1130369089859328] = "<P_Heart> (Tão caprichoso, é assim que é um \"Imperador\"? Parece que Intis é uma república agora.) </>",
  [1130369089859072] = "<P_Heart> (Que história nacional complicada... Intis é uma república agora.) </>",
  [1130369089858816] = "Mas em 1192, o Imperador Roselle transformou a República Intis de volta no Império Intis...",
  [1130369089858560] = "Em 1173, o Imperador Roselle ascendeu ao trono e transformou o Reino de Intis na República Intis.",
  [1130369089858304] = "Intis acredita no Eterno Sol Ardente e no Deus do Vapor e das Máquinas. É um dos países mais poderosos do Continente Norte... bem.",
  [1130369089858048] = "O <P_Yellow> Império Feysac </> ocupa o extremo norte, o <P_Yellow> Reino Loen </> fica no leste, o <P_Yellow> Reino Feynapotter </> guarda o sul, e a oeste está nossa grande <P_Yellow> República Intis </>.",
  [1130369089857792] = "Esta é a época em que o mundo se encontra atualmente, com quatro países governando o Continente Norte.",
  [1130369089857536] = "Os deuses expulsaram o desastre... ou o desastre expulsou os deuses...",
  [1130369089857280] = "Mais de mil anos atrás, um <P_Yellow> \"Pálido Desastre\" </> desceu sobre o Continente Norte. Desde então, os deuses não apareceram mais no mundo, apenas transmitindo oráculos através das igrejas.",
  [1130369089857024] = "Os Sete Deuses guiam o Continente Norte, enquanto o suposto <P_Yellow> Continente Sul </> está sob o governo do Deus da Morte. Os atuais <P_Yellow> Quatro Reinos Principais do Continente Norte </> foram estabelecidos nesta época com o apoio dos deuses.",
  [1130369089856768] = "Os livros da igreja dizem que os deuses conduziram a humanidade através do <P_Yellow> Império Salomão </>, <P_Yellow> Império Unido Tudor-Trunsoest </>, <P_Yellow> Período dos Quatro Imperadores </> ...",
  [1130369089856512] = "Esta é uma era em que muitos deuses andam pelo mundo. Mesmo agora, muitas pessoas estão interessadas em escavar a história da Quarta Época...",
  [1130369089856256] = "De modo geral, a história do mundo é dividida em cinco épocas, que são...",
  [1130369089856000] = "Felizmente, Sua doutrinação contém algum conhecimento útil. Hmm... preciso organizar isso...",
  [1130369089855744] = "Eu odeio história. É tudo uma massa de neblina, tão causadora de dor de cabeça quanto a doutrinação do Sábio Oculto!",
  [1130369089855488] = "Mas por que a equipe de exploração testa a história?",
  [1130369089855232] = "Primeiro, vamos começar pelo nosso país, Intis...",
  [1130369089854976] = "O Imperador disse para “abrir os olhos e olhar o mundo”. Essa frase é muito legal!",
  [1130369089854720] = "......Oh, se você quiser se juntar à equipe de Exploração do Imperador Roselle, você deve se preparar bem.",
  [1130369089854464] = "Da próxima vez que nos encontrarmos, conte-me as histórias de ninar que eles contaram para você.",
  [1130369089853696] = "E-então, como devo retribuir?",
  [1130369089853440] = "Assim como você, não sei onde fica o lugar mais a oeste do que o Mar Nevoeiro. Talvez ninguém saiba ainda.",
  [1130369089853184] = "Sinto muito, não posso ajudá-lo a se livrar completamente da dor de cabeça. Ainda estou recebendo a doutrinação do Sábio Oculto.",
  [1130369089852928] = "Vossa Alteza certamente conseguirá me levar a um lugar mais a leste que a Cordilheira Hornacis e mais a oeste que o Mar Nevoeiro!",
  [1130369089852672] = "M-mas, Sua Alteza pode me levar embora... Sua Alteza pode impedir que minha cabeça doa...",
  [1130369089852416] = "Criança, Sua Alteza está muito ocupada. A Igreja cuidará de você.",
  [1130369089852160] = "......Posso escolher não seguir Sua Alteza?",
  [1130369089851904] = "Também lhe ensinará como verificar por si mesmo a credibilidade de Suas palavras, porque tudo no mundo é evidência.",
  [1130369089851648] = "No futuro, pessoas da igreja irão orientá-lo no uso de Beyonder poderes e dizer onde ficam esses lugares.",
  [1130369089851392] = "São muitos, este mundo é muito grande.",
  [1130369089851136] = "<P_Heart> (Olhos bem abertos) </> Existe algum lugar mais a leste do que a Cordilheira Hornacis, ou mais a oeste do que o Mar Nevoeiro?",
  [1130369089850880] = "Mas o sol não se põe apenas no Intis.",
  [1130369089850624] = "Isso mesmo, o extremo oeste de Intis é o Mar Nevoeiro.",
  [1130369089850368] = "<P_Heart> (Um pouco em pânico) </> Não, não posso confiar Nele levianamente, não posso acreditar Nele.",
  [1130369089850112] = "Ele... aquele \"Sábio Oculto\", quando eu estava com dor de cabeça, disse... que o extremo oeste de Intis é o Mar Nevoeiro.",
  [1130369089849856] = "O lugar onde o sol se põe no oeste... é mesmo um vale?",
  [1130369089849344] = "Vossa Alteza.",
  [1130369089849088] = "Sua Alteza, por favor, deixe isso comigo.",
  [1130369089848576] = "Acabou a doutrinação dele, vamos sair deste lugar.",
  [1130369089848064] = "<P_Heart> (A respiração se estabiliza gradativamente) </> ... Acho que não dói mais tanto.",
  [1130369089847808] = "......Até chegarem ao vale onde o sol se põe no oeste, eles entraram em um longo sono junto com o sol.",
  [1130369089847552] = "Depois de muito... muito tempo",
  [1130369089847296] = "Sua voz é muito calma, como se estivesse contando uma história para dormir.",
  [1130369089847040] = "Perseguindo-o até o rio dourado e depois bebendo o rio até secar...",
  [1130369089846784] = "Eles passaram a vida inteira perseguindo o sol, começando de onde o sol nasce, perseguindo-o até as montanhas que chegam ao céu, e depois cruzando os picos...",
  [1130369089846528] = "Há muito, muito tempo atrás, no extremo leste, vivia um grupo de gigantes.",
  [1130369089846016] = "Por favor, tente ouvir minha voz.",
  [1130369089845760] = "Tão... doloroso... tão doloroso...",
  [1130369089845504] = "A garota tomou a Poção da Tranquilidade, seu corpo ainda tremendo de dor.",
  [1130369089845248] = "Muito bom.",
  [1130369089844992] = "......Hmm......ok......",
  [1130369089844736] = "Esta é uma Poção da Tranquilidade. Depois de tomá-lo, tente ouvir minha voz e não pense em mais nada.",
  [1130369089844480] = "Eu também já fui um Espreitador de Mistérios. Eu sei o que você está enfrentando, então posso ajudá-lo.",
  [1130369089844224] = "Uau... uau...",
  [1130369089843968] = "<P_Heart> (Alguém está se aproximando...) </>",
  [1130369089843712] = "Entendido, negociarei com o sobrevivente.",
  [1130369089843200] = "Definitivamente vou trazê-la de volta.",
  [1130369089842944] = "Eu cuidarei de você, não se preocupe muito.",
  [1130369089842688] = "Só há um requisito: não seja muito curioso.",
  [1130369089842432] = "Então... vá e traga o espírito dela para fora, considere isso um treinamento noturno.",
  [1130369089842176] = "Deixe-me fazer alguma coisa? Presidente.",
  [1130369089841920] = "Acho que não vou conseguir dormir esta noite...",
  [1130369089841664] = "Não fique nervoso. Os insetos misteriosos do mundo espiritual não são muito perigosos. Deixe isso comigo; você volta e descansa.",
  [1130369089841408] = "Minha intuição espiritual me diz que ela se sentiu atraída por mim.",
  [1130369089841152] = "Ela não tem malícia, ou talvez...",
  [1130369089840896] = "Como, como ela rompeu as defesas da escola para entrar?",
  [1130369089840640] = "Parece que ela se escondeu em um livro... talvez seja o lugar que ela considera mais seguro.",
  [1130369089840384] = "Sim, mas o que resta aqui é apenas uma casca; seu espírito está escondido.",
  [1130369089840128] = "Ela... ela é um inseto?",
  [1130369089839872] = "O que diabos...",
  [1130369089839616] = "Presidente!",
  [1130369089839360] = "Denso e numeroso, cada vez mais.",
  [1130369089839104] = "Anel de Desempenho",
  [1130369089838848] = "Um, dois, três... Você sente perninhas de inseto rastejando por baixo da saia e subindo pelas suas pernas.",
  [1130369089838592] = "Ah não... vou controlar isso o mais rápido possível...",
  [1130369089838336] = "Um, dois, três... Você avalia a quantidade pelo movimento dos lábios e dos dentes dela.",
  [1130369089838080] = "A Sra. Skana respondeu com suas ações – ela ansiosamente enviou o Inseto Misterioso do Mundo Espiritual em sua boca.",
  [822510396488448] = "Mas o valor das joias está nas matérias-primas",
  [1130369089837568] = "Como devemos lidar com...",
  [1130369089837312] = "Obrigado, realmente, obrigado.",
  [1130369089837056] = "Rapidamente... saia...",
  [1130369089836544] = "Meu caro, depois que o problema for resolvido, com certeza irei me apresentar adequadamente.",
  [1130369089836288] = "......Oh, como tal coisa poderia acontecer? É simplesmente um desastre!",
  [1130369089836032] = "Você nunca imaginaria que este lugar foi invadido por Insetos Misteriosos!",
  [804913646963200] = "O que você quer dizer?",
  [822511738751232] = "Boa sorte",
  [1130369089835776] = "De todas as direções! No entanto, acho que você pode encontrá-los usando Visão Espiritual .",
  [822511738673408] = "Parece triste...",
  [1130369089835520] = "Para onde eles fugiram?",
  [822505833129216] = "E seu coelhinho? Urso? Uh, pato? De qualquer forma, seja lá o que for, a vovó consertou para você, exatamente como antes.",
  [813709740222208] = "Ah, {{Sr.|Senhorita}}, bem-vindo para pegar um número na janela dentro da agência. Temos estado muito ocupados ultimamente, por favor, entenda.",
  [1130369089835008] = "Sim, insetos, enxames de insetos que devoram todos os “mistérios”, e os livros são os cadáveres dos mistérios.",
  [822505833055488] = "Cachorro nasce para latir... Você perdeu, velho, não leve para cima do cachorro sua raiva de cuidar de um bebê.",
  [822505833093376] = "Como você pode ver, o final não foi feliz... então ele me contratou para usar as lembranças da garota e a aliança de casamento que ele havia preparado para criar um anel totalmente novo, para comemorar para sempre seu amante falecido.",
  [1130369089834752] = "<P_Heart> (O consenso de toda a humanidade – quando você vê um ■■, significa que há mais mil!) </>",
  [1130369089834496] = "Durante um maravilhoso período de descanso, a Sra. Skana está ocupada e nervosa.",
  [1130369089834240] = "Ah, meu salvador! Quer dizer... estou muito feliz em ver você aqui!",
  [1130369089833984] = "Vá dar uma olhada.",
  [1130369089833728] = "Estranho, a esta hora, quem ainda está nos arquivos?",
  [813709740520704] = "Isso mesmo! Preços acessíveis, quantidade limitada, primeiro a chegar, primeiro a ser servido!",
  [1130298758780416] = "Você é excelente",
  [1130369089409024] = "{{Sr.|Sra.}}, o que você precisa?",
  [862018190014720] = "Toque cuidadoso",
  [1130369089811456] = "Desculpe, este é um assunto de família...",
  [813709740221952] = "Uh, olá, posso falar com um humano?",
  [813709740520448] = "Você tem tantos tipos diferentes de chapéus aqui, e todos são do mesmo estilo dos de Gehrman...?",
  [1130298758780160] = "A verdade é mais importante que a vida?",
  [1130369089408768] = "Então nos encontraremos no Reino perto do Lago Tingen mais tarde!",
  [1130369089732864] = "Senhor! Senhor...",
  [1130369089732608] = "Bom, então o tema da palestra será 'Partindo dos Detalhes da Vida: Como o Sorvete Auxiliou na Solução do Caso'. Prepare-se bem, tenho grandes esperanças em você!",
  [1130369089732352] = "Sim!",
  [862024900873984] = "Confira o cardápio",
  [1130369089732096] = "Então foi assim que foi resolvido?",
  [1130369089731840] = "Fui comprar um sorvete e, na volta, vi o assassino caído na beira da estrada.",
  [1130369089731584] = "Não seja modesto. Apanhar o assassino num dia não pode ser resumido pela palavra “sorte”.",
  [1130369089731328] = "Ah? Meu? Agente, isto é um acidente...",
  [1130369089731072] = "Royce, você lidou com esse caso lindamente. Prepare-se, dê uma palestra para todos e compartilhe sua experiência.",
  [862028122260225] = "Uau...",
  [1130369089730816] = "Mais alto que a vida!",
  [1130369089730560] = "Trezentos centavos são suficientes para uma refeição completa. Os deuses do mal não precisam comer? A criação artística deve integrar-se na vida...",
  [1130369089730304] = "Deus malvado! Esse é um deus do mal! O estilo deve ser elevado; não se limite a essas ninharias.",
  [1130369089730048] = "São novecentos e trinta e sete centavos...",
  [1130369089729792] = "Até um babuíno de cabelos cacheados acharia isso um absurdo. Veja o que você escreveu! Deusa, já estou farto. Qual deus do mal se preocupa com algumas centenas de centavos?",
  [1130369089729536] = "Se eu menti para você, sou um babuíno de cabelos cacheados!",
  [1130369089729280] = "Juro em nome da Deusa! Eu estava absolutamente sóbrio quando escrevi!",
  [1130369089729024] = "O prazo é hoje! Esse não é o ponto. Você bebeu de novo enquanto escrevia?",
  [1130369089728768] = "Ah, Diana, vou entregar o manuscrito amanhã, não, depois de amanhã, definitivamente depois de amanhã!",
  [1130369089728512] = "Júlia!",
  [1130369089727744] = "Você não olhou atentamente para aquele moinho de vento? As lâminas estão cobertas de... pelos!",
  [1130369089727232] = "<P_Heart> (Certo, aquele Elio desaparecido, me pergunto onde ele foi...) </>",
  [1130369089726976] = "Para um Beyonder , viver uma vida tranquila já é um luxo. Espero que você possa pelo menos sentir felicidade em seu reencontro.",
  [1130369089726720] = "De nada, este é meu dever.",
  [1130369089726464] = "{{PlayerName}}, obrigado pela sua ajuda.",
  [1130369089726208] = "Estou feliz que você tomou essa decisão. Para uma criança desta idade, a falta de companhia também é uma espécie de perigo.",
  [1130369089725952] = "Mesmo que a nossa vida pareça absurda aos olhos dos outros... mas pelo menos, estamos juntos.",
  [1130369089725696] = "Albert quer tanto ir para o mar, mas eu não entendi seu desejo... Eu também deveria assumir minhas responsabilidades como pai.",
  [1130369089725440] = "Talvez compreender o mundo Beyonder sob orientação adequada seja mais seguro do que não saber nada ou conhecer apenas meias verdades.",
  [1130369089725184] = "Você planeja levar Albert para o mar?",
  [1130369089724928] = "Ir para o mar? Isso é ótimo! Quero contar a Marilyn esta boa notícia!",
  [1130369089724672] = "Vou te contar muito mais coisas: poderes mágicos, aventuras no convés, as potências dos Cinco Mares... Antes de ir para o mar, vou apresentar essas coisas para você.",
  [1130369089724416] = "Sim, eu vou te ensinar, do jeito certo.",
  [1130369089724160] = "Então... Pai, você pode me ensinar como controlar o vento? Eu, eu realmente quero ir para o mar com você.",
  [1130369089723904] = "Não tenha medo, está tudo bem agora, Albert.",
  [1130369089723648] = "Pai, o que foi isso agora? Aquele Monstro Terrível... eu trouxe ele aqui?",
  [1130369089723136] = "Papai—ah—",
  [1130369089722880] = "Rezo por seu favor, favor para seu cordeiro perdido, Albert Orm!",
  [1130369089722624] = "Senhor das Tempestades, Você é o Rei que governa o céu, o Imperador que domina o mar.",
  [1130369089722368] = "Vamos começar!",
  [1130369089722112] = "Eu posso ajudar.",
  [1130369089721856] = "Você pode ver isso também? Pretendo eliminar essas influências dentro de um muro de espiritualidade . Espero... que ainda não seja muito sério.",
  [1130369089721600] = "Girel, devemos lidar com a energia maligna de Albert imediatamente!",
  [1130369089721344] = "<P_Heart> (A oração já começou. Albert poderia ter sido contaminado por uma aura maligna? É melhor verificar com Visão Espiritual .) </>",
  [1130369089721088] = "Criança boba, por que você simplesmente não me contou?",
  [1130369089720832] = "Você não disse que é preciso ter a habilidade de controlar o vento e as ondas como você para sobreviver no mar? Pensei que se tivesse um deles, talvez você concordasse em me levar.",
  [1130369089720576] = "Você fez tudo isso... só para que eu te levasse ao mar?",
  [1130369089720320] = "Olha, o moinho de vento está girando! Eu posso invocar o vento! Com isso, você pode me levar para o mar?",
  [1130369089720064] = "Pai? Você, você está de volta! O ritual... funcionou?",
  [1130369089719808] = "Alberto!",
  [1130369089719552] = "...... Eu ofereço a você minha carne e sangue, meu cabelo e pele, por favor conceda este lugar......",
  [1130369089719296] = "Vou te levar até lá, siga-me de perto.",
  [1130369089719040] = "Moinho de vento... O moinho de vento! Albert não estava pregando peças lá antes; foi uma prática de Magia Ritual!",
  [1130369089718784] = "Claro... Agora não é hora para isso. Devo encontrar Albert imediatamente!",
  [1130369089718528] = "Você conhece a Magia Ritual?",
  [1130369089718272] = "Magia Ritual Maligna?!",
  [1130369089718016] = "Girel, Albert parece estar se preparando...",
  [1130369089717760] = "Não sei. Ele tem dito coisas que não entendo ultimamente, como controlar o vento, invocar chuva e assim por diante.",
  [1130369089717504] = "O que ele está fazendo com as velas?",
  [1130369089717248] = "Ele faz uma bagunça e sou eu quem tem que limpar. Há poucos dias ele até tirou todas as velas da gaveta...",
  [1130369089716992] = "Parece que... desenhando? Ele não me deixa olhar, nem chegar perto!",
  [1130369089716736] = "O que Albert costuma fazer no quintal?",
  [1130369089716480] = "Vamos, vou te levar para encontrá-lo.",
  [1130369089716224] = "Oh! Girel, você realmente precisa disciplinar Albert adequadamente. Ele tem sido muito desobediente ultimamente.",
  [1130369089715968] = "Moinho de vento? ...Preciso conversar com ele.",
  [1130369089715712] = "Albert tem pregado peças no moinho de vento da esquina, manchando tinta vermelha, pendurando linhas de pesca e girando o moinho no meio da noite.",
  [1130369089715456] = "O que é? Aquela criança Albert, suspiro.",
  [1130369089715200] = "Olá, meu nome é {{PlayerName}}. Alberto está?",
  [1130369089714944] = "<P_Heart> (Girel voltou do mar?) </>",
  [1130369089714688] = "Estou feliz que você esteja de volta em segurança. O mar é tão perigoso; só de ouvir sobre as 'aventuras' e 'piratas' que você descreveu em suas cartas me fez suar frio... Albert e eu estávamos muito preocupados com você.",
  [1130369089714432] = "Mais de dois anos. As condições no mar mudam rapidamente; não está claro quando poderemos atracar na próxima vez. Obrigado por cuidar de Albert todo esse tempo.",
  [1130369089714176] = "Girel, você finalmente voltou! Quanto tempo faz?",
  [1130369089713920] = "Alguém deveria reclamar com Marilyn! A casa deles fica ao lado da clínica, aquela que tem quintal.",
  [1130369089713664] = "Onde fica a casa de Alberto?",
  [1130369089713408] = "<P_Heart> (Poderes mágicos no mar... Girel sabe sobre Beyonder poderes? Albert poderia ter sido influenciado por ele?) </>",
  [1130369089713152] = "<P_Heart> (Embora não haja perigo imediato, não é tão simples quanto uma pegadinha.) </>",
  [1130369089712896] = "Albert ficou sob os cuidados de sua tia Marilyn. Aos oito ou nove anos, é a idade das travessuras; Marilyn também deve estar com dor de cabeça.",
  [1130369089712640] = "No final, quando aquela pobre mulher morreu, Girel nem estava lá. Ele voltou para dar uma olhada na lápide e depois voltou para o mar. Verdadeiramente de sangue frio.",
  [1130369089712384] = "Certo, você ainda não se mudou para cá. Há três anos, a esposa de Girel pegou uma doença estranha e Girel insistiu em ir para o mar, dizendo que “poderes mágicos podem curar doenças”. Acho que ele foi enfeitiçado por alguma coisa no mar!",
  [1130369089712128] = "O que aconteceu com o pai de Albert?",
  [1130369089711872] = "Eu sabia, aquele pirralho do Albert, mais cedo ou mais tarde, se tornaria tão chato quanto o pai. Uma macieira podre não pode dar bons frutos!",
  [1130369089711616] = "Alberto? Ah, filho daquele marinheiro maluco Girel! Ha, essa linha de pesca deve ser da casa dele também.",
  [1130369089711360] = "Este... este é o balde de tinta da minha família. Albert pegou emprestado ontem.",
  [1130369089711104] = "Encontrei este balde de tinta aqui perto.",
  [1130369089710848] = "Tinta vermelha?",
  [1130369089710592] = "As \"manchas de sangue\" próximas ao moinho de vento parecem ser de tinta vermelha.",
  [1130369089710336] = "Cabelo... não, é linha de pesca?",
  [1130369089710080] = "Esperem, olhem atentamente, todos.",
  [1130369089709824] = "{{Ele|Ela}} está segurando alguma coisa. Céus, é cabelo crescendo no moinho de vento!",
  [1130369089709568] = "Você, você foi ao moinho de vento? Senhor das Tempestades acima, você deveria correr para a igreja e orar por segurança.",
  [1130369089709056] = "Eles foram embora tão rápido...",
  [1130369089708544] = "Minha intuição me diz que seus restos mortais podem despertar minhas memórias passadas.",
  [1130369089708288] = "Irei para Midseashire, lugar onde ele nasceu e foi enterrado.",
  [1130369089708032] = "......Eu acordei muitas vezes com memórias confusas, mas pelo menos desta vez, eu me lembro dele.",
  [1130369089707776] = "Ha! Não se preocupe, a carne humana nunca foi do meu agrado desde o início.",
  [1130369089707520] = "O que você planeja fazer a seguir?",
  [1130369089707264] = "Você sabe muito sobre isso; você certamente não é comum Beyonder .",
  [1130369089707008] = "Os segredos envolvidos neste assunto são algo que nem eu seria capaz de suportar.",
  [1130369089706752] = "Antígono... Isso é ainda mais complicado do que eu pensava.",
  [1130369089706240] = "Você já deveria ter descoberto que Welch não está mais conosco.",
  [1130369089705984] = "Por favor, entre, não seja formal. O mestre ordenou que a casa fosse mantida exatamente como era quando o jovem mestre ainda estava aqui.",
  [1130369089705728] = "Com licença, não é assim que a família McGovern trata os hóspedes.",
  [1130369089705472] = "O jovem mestre nos instruiu a ‘deixar sempre uma janela aberta para isso’.",
  [1130369089705216] = "Um gatinho muito peculiar que aparecia de repente em casa como num passe de mágica.",
  [1130369089704960] = "Eu me lembro, Welch não tinha um gato antes?",
  [1130369089704704] = "Todos nós sentimos muita falta dele.",
  [1130369089704448] = "Ainda penso nele de vez em quando ao longo desses anos, e hoje, por acaso, passei por aqui.",
  [1130369089704192] = "......Eu sou amigo de Welch.",
  [1130369089703680] = "Um lindo gato malhado com olhos tão puros quanto o céu noturno claro.",
  [1130369089703424] = "Desculpe, estou perseguindo um gato. Você já viu isso?",
  [1130369089703168] = "Quem é você?",
  [1130369089702912] = "Mas acho que a paixão dele pela comida gourmet acabou despertando algo dentro de mim.",
  [1130369089702656] = "Eu não posso culpá-lo. Olhe para mim; até eu ocasionalmente fico fascinado por mim mesmo!",
  [1130369089702400] = "Eu não aguentei mais e o repreendi, mas isso só fez com que ele me visitasse com mais frequência.",
  [1130369089702144] = "Ele continuou me trazendo comida que tinha um gosto absolutamente horrível, uma e outra vez.",
  [1130369089701888] = "Quando você não tem mais conexão com nada, esse se torna o único sentimento.",
  [1130369089701632] = "Eu já estava vagando há muito tempo e tudo que conseguia sentir era... vazio.",
  [1130369089701376] = "Claro. Só não consigo lembrar onde era a casa dele, mas lembro de quando o conheci.",
  [1130369089701120] = "Você está bem?",
  [1130369089700608] = "A julgar pela cor, esta deve ser uma panela de sopa decente.",
  [1130369089700352] = "Isso fede! Você tem algum bom senso?!",
  [1130369089700096] = "Tem um cheiro delicioso! Até mais!",
  [1130369089699840] = "Não tem problema, deixe-me ver.",
  [1130369089699584] = "Tenho que voltar correndo para realizar meu experimento! Apenas me dê o que você tiver para comer!",
  [1130369089699328] = "Muito obrigado. Por favor, espere um momento; Compartilharei um pouco de sopa de frutas com você quando estiver pronta.",
  [1130369089699072] = "Será... consertado em breve!",
  [1130369089698816] = "Ainda pode ser consertado?",
  [1130369089698560] = "<P_Heart> (O gatinho não parece bem. Vamos nos apressar e pedir a Lastra.) </>",
  [1130369089698304] = "Ufa, você me assustou!",
  [1130369089698048] = "Desculpe, gosto de falar sozinho.",
  [1130369089697792] = "Será que tenho ficado acordado até tarde recentemente?",
  [1130369089697536] = "Como isso é possível?",
  [1130369089697280] = "......Acabei de ouvir um gato falar?",
  [1130369089697024] = "...... Bem?",
  [1130369089696768] = "<P_Heart> (Uma das vítimas daquele \"Caderno da Família Antigonus\" na história, acho que o nome dele era Welch!) </>",
  [1130369089696512] = "<P_Heart> (Sinto que já ouvi esse nome em algum lugar antes.) </>",
  [1130369089696256] = "Desculpe, essa deveria ser minha carta.",
  [1130369089696000] = "<P_Heart> (O pote na memória do gatinho, também inscrito com \"Amigo Desperto\", esta deve ser a carta do gatinho?) </>",
  [1130369089695744] = "“Para meu amigo desperto”?",
  [1130369089695488] = "Hum? O que aconteceu?",
  [1130369089695232] = "Uma estrutura muito simples, será corrigida em breve.",
  [1130369089692928] = "Lembro-me do calor do fogo e da névoa perfumada... siga-me!",
  [1130369089692672] = "Não há cozinha por perto; o que devo fazer com os utensílios de cozinha?",
  [1130369089692416] = "Obrigado pela sua generosidade.",
  [1130369089692160] = "Claro, não há problema. Tenho outros lanches, vou dar para você como presente de agradecimento também.",
  [1130369089691904] = "Você pode compartilhar algumas frutas comigo?",
  [1130369089691648] = "Originalmente, eu queria deixá-los aqui e levá-los ao mercado aos poucos, mas não esperava que os ratos chegassem tão rapidamente.",
  [1130369089691392] = "Haha... Queria levar eles ao mercado para vender e ganhar alguma mensalidade.",
  [1130369089691136] = "Muitas... você colheu todas as frutas?",
  [1130369089690880] = "Ufa... graças a você. Parece que colher muitas frutas de uma vez foi uma decisão errada.",
  [1130369089690624] = "De nada, você está bem?",
  [1130369089690368] = "Proteção da Deusa! Obrigado!",
  [1130369089690112] = "Espero que você se lembre de tudo depois de tomar a sopa de frutas.",
  [1130369089689856] = "Mas... o que exatamente “ele” fez?",
  [1130369089689600] = "Talvez ele seja um servo despreocupado.",
  [1130369089689344] = "Você deve valorizar muito “ele”?",
  [1130369089689088] = "...... Eu realmente ajudei alguém a pegar um rato? Meu?! Como isso é possível!",
  [1130369089688832] = "Ao contrário de um garoto rico, ele só sabe subir em uma árvore e me pedir ajuda, como se eu não tivesse nada melhor para fazer.",
  [1130369089688576] = "Você é mais capaz do que eu imaginava.",
  [633321918830080] = "Inspecionar",
  [1130369089688320] = "Ou devo dizer \"por favor\"? Ótimo Beyonder ?",
  [1130369089688064] = "Por favor, não quero sujar minhas garras!",
  [1130369089687808] = "Você deveria ser mais profissional do que eu na captura de ratos, certo?",
  [1130369089687552] = "Então mãos à obra, pessoa intrometida e de bom coração.",
  [1130369089687296] = "Deixe isso comigo.",
  [1130369089687040] = "É a sua vez de brilhar, pessoa obediente e de bom coração.",
  [1130369089686784] = "Você! Aquele ali! Por favor, salve-me!",
  [1130369089686528] = "Primeiro, tenho que encontrar os ingredientes e os utensílios de cozinha.",
  [1130369089686272] = "...... eu farei o meu melhor.",
  [1130369089686016] = "Que pena, então terei que me contentar em encher meu estômago com você!",
  [1130369089685760] = "Por favor, me perdoe, na verdade não sou muito bom em cozinhar.",
  [1130369089685504] = "Vou procurar os ingredientes e os utensílios de cozinha agora mesmo.",
  [1130369089685248] = "Fique tranquilo, com certeza farei a sopa de frutas mais perfeita.",
  [1130369089684992] = "<P_Heart> (Suspiro, quem suportaria recusar o pedido de um gatinho?) </>",
  [1130369089684736] = "Hmph... então você me ajuda a fazer uma porção. Eu deveria ser capaz de lembrar de tudo depois de beber!",
  [1130369089684480] = "Talvez esta sopa de frutas seja o que você procura?",
  [1130369089684224] = "Muitas frutas agridoces que podem ser transformadas em uma sopa muito deliciosa.",
  [1130369089683968] = "Lembro-me do formato dessas árvores, da sensação do solo e dos frutos.",
  [1130369089683712] = "Tem certeza que quer me perguntar? Afinal, sou apenas um gato com amnésia.",
  [1130369089683456] = "Talvez você esteja falando sobre o gramado da Hoy University? Muitos estudantes vão lá para piqueniques.",
  [1130369089683200] = "Grama, lembro-me de muita grama.",
  [1130369089682944] = "Você se lembra de mais alguma coisa?",
  [1130369089682688] = "Esta é a sua honra, jovem Beyonder .",
  [1130369089682432] = "......Por que não ajudo você a procurar, Excelência Gato?",
  [1130369089682176] = "Talvez tenha sido o sabor da carne daquela pessoa? Você pode me deixar dar uma mordida?",
  [1130369089681920] = "Aquele aroma frutado e ácido – cada mordida fazia meu corpo ficar quente.",
  [1130369089681664] = "Talvez não seja fruta. Na minha memória, há uma figura borrada que sempre me alimentava com uma colher.",
  [1130369089681408] = "Você sente falta do sabor dessa fruta?",
  [1130369089681152] = "Exceto por um leve aroma frutado e ácido.",
  [1130369089680896] = "Dormi muito tempo e agora minha memória de tudo está muito embaçada.",
  [1130369089680640] = "Hmph, não é tão estúpido, afinal!",
  [1130369089680384] = "Um gato tão nobre quanto você deve ter seus próprios motivos para fazer as coisas?",
  [1130369089680128] = "Foi minha imprudência.",
  [1130369089679872] = "<P_Heart> (Vamos estabilizá-lo primeiro.) </>",
  [1130369089679616] = "<P_Heart> (O perigo é grande, poderia ser uma criatura alta Sequência?) </>",
  [1130369089679360] = "<P_Heart> (O pêndulo está se movendo no sentido horário em alta velocidade.) </>",
  [1130369089679104] = "<P_Heart> (Por que minha inspiração está me avisando?) </>",
  [1130369089678848] = "Você...",
  [1130369089678592] = "Por você? Todos Beyonders são tão rudes hoje em dia?",
  [1130369089678336] = "Pode falar, você não é um gatinho comum. Roubar coisas deve ser punido!",
  [1130369089678080] = "Não seja tão mesquinho; Acabei de cometer um erro que todos os gatinhos cometem.",
  [1130369089677824] = "Ladrão! Por que você está roubando o almoço de todo mundo?",
  [1130369089677568] = "......De qualquer forma, não posso deixar uma criatura Beyonder vagando lá fora.",
  [1130369089677312] = "E daí? Sou uma pobre gatinha que está com fome há muito tempo!",
  [1130369089677056] = "Gatinha, você levou o almoço de todo mundo?",
  [1130369089676800] = "<P_Heart> (Ele pode falar? É realmente uma criatura Beyonder.) </>",
  [1130369089676544] = "Tão rude! Como ousa sujar meu pelo?!",
  [1130369089676288] = "<P_Heart> (Pode haver Beyonder poderes envolvidos? Vamos acompanhar e ver!) </>",
  [1130369089676032] = "<P_Heart> (Um gato desapareceu com a comida?) </>",
  [1130369089675776] = "Ninguém viu o culpado ainda, mas acho que é apenas uma pegadinha de algum estudante.",
  [1130369089675520] = "Se você desviar o olhar durante o almoço, a comida será levada por um fantasma.",
  [1130369089675264] = "Suspiro, é um boato que se tornou popular no distrito universitário recentemente.",
  [1130369089675008] = "Desaparecido?",
  [1130369089674752] = "Tive um pequeno problema, o almoço do meu irmão desapareceu novamente.",
  [1130369089674496] = "Discutindo durante uma adorável hora de almoço, aconteceu alguma coisa?",
  [1130369089674240] = "Cale a boca, Damon. Pare de adivinhar descontroladamente!",
  [1130369089673984] = "Deusa, não poderei almoçar de agora em diante, não é?",
  [1130369089673728] = "Sim, esta é a segunda vez que o encontro!",
  [1130369089673472] = "Eu ouvi você dizendo que o almoço desapareceu no ar?",
  [1130369089673216] = "Não há necessidade de se desculpar, senhora.",
  [1130369089672704] = "<P_Heart> (Sobre o que eles estão discutindo?) </>",
  [1130369089672448] = "Tudo bem, pare de gritar. Vou dividir meu almoço com você!",
  [1130369089671936] = "<P_Heart> (Horror) </> Ninguém esteve aqui, desapareceu no ar! Como se realmente existissem... existissem...",
  [1130369089671680] = "Não é um ladrão!",
  [1130369089671424] = "Um ladrão até roubando o almoço? Bah! Sempre perdendo coisas desde criança!",
  [1130369089671168] = "Desapareceu por conta própria!",
  [1130369089670912] = "Caramba! Você fez seu almoço desaparecer de novo?!",
  [1130369089670656] = "Aham, vamos.",
  [1130369089670400] = "Este é o seu gato? Que fofo.",
  [1130369089670144] = "Miau miau miau.",
  [1130369089669632] = "Tudo bem, mas você tem que me dar um pouco de comida como pagamento. Meu almoço desapareceu há meia hora.",
  [1130369089669376] = "Quero consertar aquela panela simples ali. Pode me ajudar?",
  [1130369089669120] = "Sim, o que você precisa?",
  [1130369089668864] = "Com licença, você é aluno do departamento de Vapor e Máquinas?",
  [1130369089668608] = "Não será se você acertar o objeto da oração. Se você quiser deixar de lado seu preconceito e me fazer fazer um adivinhação , estarei sempre à sua disposição.",
  [1130369089668352] = "Você ainda está pesquisando Magic Mirror adivinhação?! Tempestade acima, você deve saber o quão perigoso isso é.",
  [1130369089668096] = "E pensei que você queria ter uma discussão acadêmica séria. Parece que eu estava enganado.",
  [1130369089667840] = "Achei que você era melhor no Magic Mirror adivinhação? Talvez você possa ensinar o pobre Murray; ele está prestes a folhear seus livros até que faíscas voem.",
  [1130369089667584] = "Ha, eu não ousaria elogiar a precisão dessas coisas.",
  [1130369089667328] = "Para obter um resultado mais preciso, vale a pena fazer algum esforço. Sr. Diego, talvez você pudesse simplesmente usar constelações para interpretação?",
  [1130369089667072] = "Nos encontraremos novamente.",
  [1130369089666816] = "O destino de cada um pertence a si mesmo; apenas \"você\" é a resposta. Vamos começar.",
  [1130369089666560] = "Tarot adivinhação , você faz o embaralhamento e corte das cartas.",
  [1130369089666304] = "Você é a primeira pessoa a vir adivinhação hoje, é grátis.",
  [1130369089665280] = "Feliz por poder servir, sua esquisitice entre as esquisitices.",
  [1130369089665024] = "Adeus!",
  [1130369089664768] = "Acredite, se não gostar do resultado é só virar mais algumas vezes; pelo menos fará você se sentir melhor!",
  [1130369089664512] = "Você ainda nem sabe qual foi a minha pergunta?",
  [1130369089664256] = "Parabéns!!",
  [1130369089664000] = "Cabeças.",
  [1130369089663232] = "Recite a pergunta 7 vezes em seu coração e depois jogue a moeda. Cara representa afirmação, coroa representa negação.",
  [1130369089662976] = "Claro, em termos de probabilidade.",
  [1130369089662720] = "Quatro vezes sim, três vezes não. Deve haver um bom resultado, certo?",
  [1130369089662464] = "Então, o que o adivinhação diz?",
  [1130369089662208] = "Se a Universidade Tingen vai me admitir. O e-mail deverá chegar nos próximos dias; Não me atrevo a ficar em casa de jeito nenhum!",
  [1130369089661952] = "Moeda adivinhação ! Você quer experimentar também? Posso te emprestar esta moeda de cobre!",
  [1130369089603584] = "Verificando o pulso da Srta. Daisy – senti uma pulsação fraca e pulsante!",
  [1130369089603072] = "Colocando um dedo sob o nariz da senhorita Daisy... senti o fluxo de ar?",
  [1130369089602304] = "Então... deixe-me ver seu crescimento recente!",
  [1130369089602048] = "Parece que você está totalmente preparado!",
  [1130369089601792] = "Tocando o braço da Srta. Daisy, uma sensação de calor surgiu.",
  [1130369089601280] = "Pressionando suavemente as costas da minha mão contra a lateral do pescoço da Srta. Daisy, não havia sinal de pulso.",
  [1130369089601024] = "<P_Heart> Essas luvas têm uma certa espessura, podem estar isolando meu tato... </>",
  [1130369089600512] = "Colocando um dedo sob o nariz da Srta. Daisy, não senti nenhum traço de fluxo de ar.",
  [1130369089598976] = "<P_Heart> (Daisy? Tem outra Daisy?!) </>",
  [1130369089594624] = "Os quebra-cabeças desconhecidos do \"Anel Mobius\" aumentaram para 11, decidi aumentar seu nível de perigo para o nível 2.",
  [1130369089593856] = "Não há necessidade, obrigado. Não posso beber nada.",
  [1130369089593600] = "O mesmo de antes? Ou por que não tentar algo novo, como taro ball boba?",
  [1130369089593344] = "Hmm, vou pensar sobre isso com cuidado.",
  [1130369089593088] = "Você não fez nada de errado. Porém, à medida que o seu Sequência avança, as emoções humanas se tornarão cada vez mais escassas; você precisa estar vigilante.",
  [1130369089592832] = "Vocês fizeram os criminosos aceitarem a punição e trouxeram de volta o Artefato Selado 3-888, eliminando perigos potenciais.",
  [1130369089592576] = "Obrigado pela sua gentileza, Senhora Presidente.",
  [1130369089591808] = "<P_Heart> (Explique a situação) </> Presidente... Meus princípios e racionalidade me levaram a fazer isso. Mas aquelas três pessoas que sofreram um desastre...",
  [1130369089591296] = "Você deveria ir falar com o presidente. Na verdade, este caso foi-lhe confiado pelo Presidente.",
  [1130369089591040] = "Mas isto facilmente cria uma ilusão de estar “vivo”, fazendo com que mais pessoas inocentes se envolvam e até percam as suas vidas.",
  [1130369089590784] = "A respiração e os batimentos cardíacos são símbolos de estar vivo; talvez existam outras coisas que podem se tornar a “respiração” e o “batimento cardíaco” de uma pessoa...",
  [1130369089590016] = "Também estou muito triste... Mas tive que trazer de volta o Artefato Selado e deixá-los aceitar o castigo que merecem.",
  [1130369089589760] = "Suspiro, três pessoas inocentes morreram desta vez, e a família de três pessoas de Liana também está...",
  [1130369089589248] = "Basta torcer o nariz diretamente e não haverá problema de esquerda ou direita!",
  [1130369089588224] = "Claro que sim, e uma cesta cheia deles.",
  [1130369089587968] = "Senhora Amanda, você tem coisas difíceis de decidir?",
  [1130369089587712] = "Você pode precisar de algum tempo para descansar; Rebecca cuidará do resto.",
  [1130369089587456] = "Obrigado pelo seu incentivo, Senhora Presidente.",
  [1130369089586944] = "Obrigado pela sua tolerância e compreensão, Senhora Presidente. Este é o Artefato Selado que trouxe de volta.",
  [1130369089586432] = "Enviarei gente para acompanhar a situação da família de Liana para evitar acidentes. É claro que também devem aceitar punições iguais pelos crimes que cometeram.",
  [1130369089586176] = "Obrigado, senhora presidente, então Liana...",
  [1130369089583616] = "Também estou muito triste... Embora tenha trazido de volta o Artefato Selado, não suportaria extinguir a última esperança de Liana.",
  [1130369089582848] = "A família deles se reuniu... deve ser assim...",
  [1130369089582336] = "Sinto muito, Liana, Dr. Jonar...",
  [1130369089581568] = "Tudo bem... esta é a última coisa que posso fazer por você...",
  [1130369089581312] = "Sim, reunir-se com a família... é o sentido da nossa existência neste mundo.",
  [1130369089581056] = "Você... quer entrar na ciclovia da pequena Daisy?",
  [1130369089580800] = "Sim, isso não afeta a sua missão, o seu dever...",
  [1130369089580544] = "Por favor, pelo menos deixe a nossa família... reunir-se uma última vez.",
  [1130369089580288] = "Não, pela pequena Daisy, pela pequena Daisy!",
  [1130369089580032] = "Dr. Jonar, sua profissão é curar os enfermos e salvar pessoas, e meu dever também é proteger mais pessoas do infortúnio.",
  [1130369089579776] = "Não, você não pode tirar isso. Sem o espaço do ciclo, a pequena Margarida vai morrer, ela vai morrer!",
  [1130369089579520] = "A existência do ciclo é uma ameaça fatal para os outros, assim como a tragédia que ocorreu na casa de Miss Daisy.",
  [1130369089579264] = "Não, você já quebrou o ciclo da pequena Daisy e ela avançará passo a passo em direção à morte.",
  [1130369089579008] = "Em suma, de acordo com as minhas funções, você deve assumir a responsabilidade pelos crimes que cometeu.",
  [1130369089578752] = "Sua posse e uso do Artefato Selado 3-888 violam as regras do Artefato Selado. Tenho que ligar para 3-888 e contar toda a verdade.",
  [1130369089578496] = "Eles eram todos pessoas que viviam e respiravam e, assim como você, tinham suas próprias famílias e amigos... Suas mortes são uma tragédia absoluta.",
  [1130369089578240] = "Suas tentativas contra a Srta. Daisy causaram indiretamente a morte de dois criados e um mordomo...",
  [1130369089577984] = "Sinto muito. Também simpatizo com a situação da pequena Daisy, mas não se pode viver para sempre numa ilusão perigosa.",
  [1130369089577472] = "Ah, não... pequena Margarida...",
  [1130369089577216] = "Eu peguei o Artefato Selado. Não corra o risco de entrar novamente no espaço do loop da pequena Daisy. Caso contrário, você morrerá ou causará a morte da pequena Daisy.",
  [1130369089576960] = "Sinto muito, isso é tudo que posso fazer por você. Eu tenho meus próprios deveres.",
  [1130369089575936] = "Não, é a nossa única esperança, você não pode tirá-la!",
  [1130369089575680] = "Então sugiro que você não entre; afinal, fazer isso acarreta riscos significativos.",
  [1130369089575424] = "Mas depois disso, teremos apenas uma chance de entrar e nos reunir com a pequena Daisy, e isso também causará sua morte.",
  [1130369089575168] = "Isso não vai acontecer. Antes de retirar 3-888, deixarei a pequena Daisy entrar no ciclo novamente.",
  [1130369089574912] = "Não, você já quebrou o ciclo da pequena Daisy e ela caminhará em direção à morte.",
  [1130369089574400] = "Eles eram todos pessoas que viviam e respiravam e, assim como você, tinham suas próprias famílias e amigos... Tal final também é uma tragédia para eles.",
  [1130369089574144] = "E os seus atentados contra Miss Daisy causaram a morte de dois criados e de um mordomo...",
  [1130369089573888] = "Espero também que a pequena Daisy possa “viver” de uma forma especial. Mas de acordo com nossas regras de gerenciamento para Artefatos Selados, devo trazer de volta 3-888.",
  [1130369089573632] = "Droga, acabei amolecendo meu coração e não torci nenhuma das orelhas.",
  [1130369089573376] = "Como você finalmente fez sua escolha?",
  [1130369089573120] = "Por exemplo, devo torcer a orelha esquerda ou a orelha direita de Heródoto?",
  [1130369089572864] = "Por exemplo?",
  [1130369089572608] = "Claro que sim, e uma cesta cheia deles!",
  [1130369089572352] = "Senhora Amanda, você tem coisas difíceis de escolher?",
  [1130369089571840] = "O mesmo de antes? Por que não tentar algo novo, como taro ball boba?",
  [1130369089571584] = "Uma xícara de café, com um cubo de açúcar e duas colheres de leite.",
  [1130369089571328] = "Você pode precisar de algum tempo para descansar; Rebecca cuidará do resto.",
  [1130369089571072] = "Os quebra-cabeças desconhecidos do \"Anel Mobius\" aumentaram para 8, decidi aumentar seu nível de perigo para o nível 2.",
  [1130369089570816] = "Obrigado pela sua tolerância e compreensão, Senhora Presidente.",
  [1130369089570560] = "Mas garanto que respeitarei parcialmente as escolhas que você fez.",
  [1130369089570304] = "Enviarei pessoas para acompanhar a situação de Liana e do Artefato Selado para evitar mais acidentes. É claro que também devem aceitar punições iguais pelos crimes que cometeram.",
  [1130369089570048] = "Obrigado, Senhora Presidente, então Liana e Sealed Artifact 3-888...",
  [1130369089569792] = "Enviarei pessoas para confortar e proteger suas famílias e fornecer uma pensão para que possam viver bem.",
  [1130369089569536] = "É sempre lamentável quando pessoas inocentes enfrentam desastres em Beyonder incidentes, mas o que é feito não pode ser desfeito.",
  [1130369089569280] = "<P_Heart> (Explique a situação) </> Presidente... Minha orientação interior me levou a fazer isso, mas aquelas três pessoas que sofreram um desastre...",
  [1130369089569024] = "A comissão do presidente? Onde ela está?",
  [1130369089568768] = "Você deveria ir falar com o presidente. Na verdade, foi ela quem me pediu para confiar esse assunto a você.",
  [1130369089568512] = "O amor e o apego do casal Jonar são a “respiração” e os “batimentos cardíacos” da pequena Daisy, os sinais de que ela está “viva”.",
  [1130369089568256] = "A respiração e os batimentos cardíacos são símbolos de estar vivo, mas existem coisas mais preciosas que podem se tornar a “respiração” e os “batimentos cardíacos” de uma pessoa.",
  [1130369089568000] = "Sobre a fronteira entre a vida e a morte? Você tem uma nova resposta?",
  [1130369089567744] = "Vou relatar toda a situação ao presidente. Arrodes, gostaria de responder sua pergunta novamente.",
  [1130369089567488] = "Também estou muito triste, Rebecca... Deixar o Sealed Artifact 3-888 com Liana também é uma decisão temporária.",
  [1130369089567232] = "Suspiro, três pessoas inocentes morreram desta vez. Eu realmente espero que possamos proteger a todos. No entanto...",
  [1130369089566976] = "<P_Heart> (Explique a situação) </> É assim que as coisas são...",
  [1130369089566720] = "Se houver uma chance, voltarei para sentir novamente o perfume das margaridas. Adeus.",
  [1130369089566464] = "Obrigado de coração. Devemos deixar a pequena Daisy entrar no ciclo novamente imediatamente.",
  [1130369089566208] = "Obrigado; para nós, isso já é gentileza suficiente.",
  [1130369089565952] = "Vou relatar toda a verdade, bem como minhas próprias opiniões. Você ainda precisa esperar pela decisão final.",
  [1130369089565696] = "Eles eram todos pessoas vivas e, como você, tinham suas próprias famílias e amigos... esse final é sempre uma tragédia para eles.",
  [1130369089565440] = "Não vou retirar 3-888 por enquanto. Mas os seus atentados contra Miss Daisy causaram indirectamente a morte de dois criados e de um mordomo...",
  [1130369089565184] = "Dr. Jonar, também espero que a pequena Daisy possa continuar a “viver” de uma forma especial.",
  [1130369089564672] = "Difícil de acreditar, todas as três vezes foi um quebra-cabeça, e todas eram padrões de margaridas...",
  [1130369089564160] = "Isso é... Pequena Margarida?",
  [1130369089563392] = "Eu entendo... Jonar, por favor, deixe-me falar com {{ele|ela}} <P_Yellow> sozinho </> .",
  [1130369089563136] = "Liana, meu dever não é apenas resolver o caso, mas também trazer de volta o Artefato Selado e eliminar perigos potenciais.",
  [1130369089562880] = "Estamos dispostos a deixar a Pequena Margarida “viver” de uma forma especial. Você deve concordar com essa abordagem, certo?",
  [1130369089562624] = "Eu também estava muito cético, mas graças ao nosso último encontro, você me inspirou profundamente.",
  [1130369089562368] = "Dr. Jonar, parece que o senhor tem uma nova perspectiva sobre \"vida\" e \"morte\".",
  [1130369089562112] = "Então... eu gostaria de pedir que você visse a Pequena Margarida antes de tomar uma decisão.",
  [1130369089561856] = "Você representa o Clube do Tarô e não faz sentido se opor a você. Eu só espero que você possa entender. Viva a compreensão – o Imperador Roselle disse isso?",
  [1130369089561600] = "Por que me contar? Quer dizer, me conte tudo honestamente?",
  [1130369089561344] = "Mas somente dominando as respostas dos quebra-cabeças poderemos entrar e sair com segurança do espaço do loop de vez em quando para ver a Pequena Margarida no seu estado mais feliz.",
  [1130369089560832] = "Mesmo assim... você ainda me enganou.",
  [1130369089560576] = "Esse acidente não tem nada a ver conosco! Isto foi comprado no mercado subterrâneo, por favor, acredite em mim.",
  [1130369089560320] = "Os registros afirmam claramente que 3-888 desapareceu em um acidente, então como está você aqui?",
  [1130369089560064] = "Você... acho que entendo tudo agora.",
  [1130369089559808] = "Sim, obrigado de coração e sincero.",
  [1130369089559552] = "Sinto muito, mas obrigado pela sua ajuda.",
  [813709740518400] = "Desculpe, só estou de passagem.",
  [1130369089558272] = "Claro, não há erro; já verificamos isso com Miss Daisy.",
  [1130369089558016] = "<P_Yellow> A pequena Margarida </> viverá seu momento mais feliz para sempre, e também nos encontraremos lá, certo?",
  [1130369089557760] = "<P_Heart> (Liana?! Ela e o Dr. Jonar se conhecem?) </>",
  [1130369089557504] = "Ah, <P_Yellow> Liana </> , eu sabia que você seria capaz de memorizá-los completamente.",
  [1130369089557248] = "Terminei de escrever tudo! Jonar, as respostas para todos os 90 quebra-cabeças estão aqui.",
  [1130369089555200] = "Certo, senhorita Daisy... não devemos demorar muito, vamos acordá-la.",
  [1130369089554944] = "É assim mesmo? Simpatizo com a situação da Srta. Daisy.",
  [1130369089554688] = "Ouvi dizer que aqueles que conseguem apreciar a fragrância das margaridas são todos pessoas compassivas.",
  [1130369089554432] = "Um perfume especial, uma sensação há muito perdida.",
  [1130298758777600] = "Formigas xingando?",
  [1130369089407744] = "Bom, irei logo pela manhã!",
  [813709740219648] = "Ela vai melhorar. Ela definitivamente irá. \n Assim que economizarmos dinheiro suficiente, vou levá-la à clínica do Dr. Horsen.",
  [1130369089552384] = "Eu ficaria feliz em fazê-lo. Que caso específico é? Há alguma pista?",
  [1130369089552128] = "Esse caso não é perigoso para você. Talvez eu possa deixar isso para você como uma experiência de aprendizado.",
  [1130369089551872] = "Ótimo, você passou, meu ajudante aumentou de novo!",
  [1130369089551616] = "Embora, embora possamos ser apenas observadores...",
  [1130369089551360] = "Sim, também podemos entrar no espaço circular da Pequena Daisy e nos reunir com ela.",
  [1130369089551104] = "Usando a habilidade de 3-888 para deixar corpo espiritual de Little Daisy entrar no loop, evitando assim que seu corpo morra?",
  [1130369089550848] = "Mas ela ainda caminha em direção à morte dia após dia... Queremos que a pequena Daisy \"viva\" para sempre, para sempre <P_Yellow> \"viva\" </> .",
  [1130369089550592] = "Não temos como acordá-la e só podemos contar com alguns rituais para manter sua vida fraca.",
  [1130369089550336] = "Sim, ela é nossa filha e sua coluna foi esmagada por aquela carruagem.",
  [1130369089550080] = "Ela é a Pequena Margarida? Acho que a vi... no espaço circular da Srta. Daisy, ela estava correndo na estrada segurando margaridas, mas...",
  [1130369089549824] = "Será que você mudou sua visão? Qual é a sua opinião sobre “vida” e “morte”?",
  [1130369089549568] = "Ah, não, tudo ali é muito real; é a realidade mais linda da vida da Pequena Margarida.",
  [1130369089549312] = "Liana, a pequena Daisy está presa em um espaço circular e tudo dentro é uma ilusão.",
  [1130369089549056] = "Ah, isso é uma pena. Achei que você definitivamente conseguiria sentir o cheiro da fragrância das margaridas.",
  [1130369089548800] = "No espaço do loop, eu era apenas um observador. Eu podia ver as margaridas florescendo lindamente, mas não tinha olfato.",
  [1130369089548544] = "Fico muito feliz em ouvir você dizer que... você realmente tem um coração gentil.",
  [1130369089548288] = "Era um perfume de inocência, pureza, despreocupação e felicidade eterna.",
  [1130369089548032] = "Sim, eu senti o cheiro. As margaridas floresceram lindamente e a fragrância era muito rica.",
  [1130369089547776] = "Então, {{PlayerName}}, você sentiu o cheiro das margaridas naquela hora? \n <P_Yellow> (Observação: escolhas diferentes levarão a história a finais diferentes.) </>",
  [1130369089547520] = "A pequena Margarida colheu um ramo de margaridas, trouxe-as para mim e convidou-me a sentir o seu perfume.",
  [1130369089547264] = "O que você viu no espaço loop da Little Daisy?",
  [1130369089546752] = "Quer dizer, convido você a conhecer o momento mais feliz da curta vida da Pequena Margarida.",
  [1130369089546496] = "Também entendo perfeitamente a decisão que você está prestes a tomar. Mas antes gostaria de convidá-lo a sentir novamente o perfume das margaridas.",
  [1130369089546240] = "Também não me lembro do passado e também senti o calor de ser ajudado. Eu entendo como você se sente, mas...",
  [1130369089545984] = "Mas os pequenos Daisy e Jonar compensaram uma certa deficiência em meu coração, talvez uma deficiência que eu havia esquecido. Eles são o significado da minha vida neste mundo.",
  [1130369089545728] = "Não me lembro do passado, o que uma vez me fez não saber quem eu era.",
  [1130369089545472] = "E encontrei o que há de mais precioso na vida deste mundo: o carinho entre parentes. A inocência e alegria da Pequena Daisy, e a bondade e gentileza de Jonar me contagiaram, e gradualmente me integrei e aceitei este mundo.",
  [1130369089545216] = "Neste mundo, devemos assumir responsabilidades e também buscar o sentido da vida. Vejo que você defende a filosofia do clube, zelando pela justiça no mundo, mas ao mesmo tempo tem a delicadeza e a compaixão da humanidade.",
  [1130369089544960] = "Ao ingressar no Clube do Tarô , todos nós juramos diante dos fragmentos da Barreira: \"Guardar o futuro com a humanidade e cuidar uns dos outros no fim do mundo.\" Cada membro do Clube do Tarô entende o significado desta frase.",
  [1130369089543936] = "<P_Heart> (Poderia ser...?) </>",
  [1130369089543680] = "Não consigo encontrar esse documento em lugar nenhum, onde mais poderia estar...",
  [1130369089543424] = "É impossível determinar o significado por enquanto... Preciso aprender mais sobre a situação.",
  [1130369089543168] = "Um símbolo misterioso <P_Yellow> \"∞\" </> ? Há luz fluindo em loop no símbolo?",
  [1130369089542400] = "Esta deveria ser a casa da <P_Yellow> Senhorita Daisy </>.",
  [1130369089540096] = "Claro que não, somos apenas pacientes comuns e médicos.",
  [1130369089539840] = "Obrigado pela introdução. Você sabe onde o Dr. Jonar mora?",
  [1130369089539584] = "Se você me perguntar, ele realmente deveria estar tratando de duques e conselheiros, mas ficou nesta pequena clínica por causa de sua gentileza.",
  [1130369089539328] = "Certa vez, ele costurou o braço de um lenhador e curou a dor oculta no fígado de Castor com apenas três doses de remédio.",
  [1130369089539072] = "Dr. Jonar ainda não chegou. A esta hora de ontem, ele já havia atendido seu 10º paciente.",
  [1130369089538816] = "Senhora, sabe a que horas ele começa a atender os pacientes?",
  [1130369089538560] = "Obrigado, Sra. Hannah, adeus.",
  [1130369089538304] = "Não sei. Geralmente vamos à clínica dele para convidá-lo, na <P_Yellow> Olsna Street </> .",
  [1130369089538048] = "Tem havido muitas coisas ultimamente; Posso contar a ela lentamente. A propósito, onde mora o Dr. Jonar?",
  [1130369089537792] = "Realmente? Obrigado, obrigado, vou ver a jovem agora mesmo.",
  [1130369089537536] = "Miss Daisy acordou; o infortúnio anterior nunca mais acontecerá.",
  [1130369089537280] = "Hmm... quando recuperar as forças, você pode ir para o jardim lá fora para relaxar; todas as margaridas floresceram.",
  [1130369089537024] = "Eu realmente vi Edmund, e... e eu o vi milhares e milhares de vezes.",
  [1130369089536768] = "Ainda não sei o que aconteceu, mas o Dr. Jonar é uma boa pessoa; ele não mentiu para mim.",
  [1130369089536512] = "Obrigado, senhorita Margarida. Você precisa descansar; Vou chamar o mordomo.",
  [1130369089536256] = "Isso mesmo, é exatamente igual a este. Sinto um pouco de tontura só de olhar...",
  [1130369089536000] = "Os registros médicos do Dr. Jonar? Sinta-se à vontade para usá-los.",
  [1130369089535744] = "Senhorita Daisy, este livreto ainda é útil?",
  [1130369089535488] = "Dourado, muito fino... o formato é difícil de descrever; minhas notas nas aulas de gramática sempre foram ruins.",
  [1130369089535232] = "Dr. Um anel? Você se lembra que tipo de anel era?",
  [1130369089534976] = "É... Dr. Jonar, ele veio tratar minha febre alta. Ele pediu que todos fossem embora, dizendo que havia um jeito especial de me fazer sonhar com Edmund. Eu concordei com a proposta dele e coloquei meu dedo indicador naquele anel...",
  [1130369089534720] = "Você se lembra quem foi a última pessoa que viu antes de entrar em coma?",
  [1130369089534464] = "Acabei de acordar, mas ainda tenho forças para responder suas perguntas.",
  [1130369089534208] = "O mordomo lhe contará tudo. Tenho algumas perguntas que devo lhe fazer.",
  [1130369089533952] = "O que aconteceu? Parece que estive sonhando, o mesmo sonho, sonhando com Edmundo...",
  [1130369089533696] = "Senhorita Daisy, sou o oficial {{PlayerName}}. Muita coisa aconteceu enquanto você estava em coma.",
  [1130369089533184] = "Nos encontraremos novamente, no Clube do Tarô ... ou em outro lugar.",
  [1130369089532928] = "Então, pegue esta garrafa de Awakening Flower Dew; pode ajudar Miss Daisy a recuperar a consciência.",
  [1130369089532672] = "Então ficarei aqui e esperarei a senhorita Daisy acordar; talvez eu possa pedir algumas pistas úteis.",
  [1130369089532416] = "Ainda preciso continuar procurando o paradeiro do Artefato Selado 3-888; quanto mais demora, mais perigoso se torna.",
  [1130369089532160] = "Sua responsabilidade era investigar o caso de Miss Daisy, e agora a investigação terminou.",
  [1130369089531904] = "Então, você tem outros planos?",
  [1130369089531648] = "Então deixo o resto com você.",
  [1130369089531392] = "O símbolo deixado por 3-888 também desapareceu; ela deveria acordar logo.",
  [1130369089531136] = "Estou muito feliz em ouvir você dizer isso, de verdade, {{PlayerName}}.",
  [1130369089530880] = "Embora eu fosse apenas um observador e não tivesse olfato, pude imaginar sua fragrância.",
  [1130369089530624] = "...Você sentiu o cheiro de margaridas naquela época?",
  [1130369089530368] = "Ah... também vi uma garotinha correndo para a rua para colher um ramo de margaridas e foi atropelada por uma carruagem...",
  [1130369089530112] = "Desculpe, ainda estou pensando nas cenas que você viu... além das lindas lembranças, você viu mais alguma coisa?",
  [1130369089529600] = "Os batimentos cardíacos e a respiração retornaram; este é sem dúvida um sinal de estar “vivo”.",
  [1130369089529344] = "Não admira que Miss Daisy estivesse presa naquela memória tão linda e romântica.",
  [1130369089529088] = "Para provar seu valor, Edmund escolheu ir para o continente sul em busca de aventura, mas morreu lá de doença.",
  [1130369089528832] = "...Ei, aquele cavalheiro se chama Edmund, ele é o namorado da senhorita Daisy, mas o visconde Elton e sua esposa sempre se opuseram a isso.",
  [1130369089528576] = "No início ela e um senhor andavam juntos de carruagem, muito felizes, muito inocentes...",
  [1130369089528320] = "O que você viu no espaço circular da senhorita Daisy?",
  [1130369089528064] = "Na verdade, não há sinais óbvios de recuperação por enquanto.",
  [1130369089527808] = "Talvez demore um pouco mais, mas não há nada com que se preocupar agora.",
  [1130369089527552] = "Graças à misericórdia da senhorita Daisy, ela ainda não acordou?",
  [1130369089527296] = "A dificuldade e o tipo dos quebra-cabeças estão relacionados ao subconsciente da vítima.",
  [1130369089527040] = "Encontrei alguns testes, mas minha sorte foi decente e os quebra-cabeças foram todos resolvidos.",
  [1130369089526784] = "Você realmente conseguiu! Como foi? Tudo correu bem?",
  [1130369089526528] = "Eu acredito em você; você definitivamente conseguirá acordar Miss Daisy com sucesso.",
  [1130369089526272] = "Estou pronto... isso não é nada perigoso, certo?",
  [1130369089526016] = "Acredito plenamente que você pode acordar Miss Daisy com sucesso.",
  [1130369089525760] = "Estou pronto. Quando eu estava no Clube do Tarô , eu já tinha me decidido.",
  [1130369089525504] = "Cours também morreu, o número de quebra-cabeças desconhecidos aumentou para 8. Você está pronto?",
  [1130369089525248] = "É claro que você tem um coração delicado e gentil.",
  [1130369089524992] = "Depois de acordar de um longo coma, as luzes fortes podem cegar, então primeiro diminuirei as luzes próximas.",
  [1130369089524480] = "Como você comanda, oficial.",
  [1130369089524224] = "Eu entendo. Sra. Hannah, por favor, não deixe ninguém entrar no quarto até sairmos.",
  [1130369089523968] = "Por causa do casamento, Miss Daisy sempre esteve distante da família e raramente os vê.",
  [1130369089523712] = "Onde estão o visconde Elton e sua esposa? Nós não os vimos nenhuma vez.",
  [1130369089523456] = "Basicamente, sim. No entanto, ainda precisamos confirmar novamente o estado de Miss Daisy.",
  [1130369089523200] = "Então, o assunto foi esclarecido?",
  [1130369089522944] = "O mais importante agora é acordar Miss Daisy e evitar que coisas semelhantes aconteçam novamente.",
  [1130369089522688] = "Isso não é culpa de mais ninguém; Cours foi morto inteiramente por sua própria curiosidade.",
  [1130369089522432] = "Sinto muito. Se tivéssemos chegado mais cedo, isso não teria acontecido.",
  [1130369089522176] = "Atormentado por esse pensamento, ele finalmente não conseguiu se controlar e estendeu a mão para tocar o pulso da senhorita Daisy...",
  [1130369089521920] = "Cours era originalmente rígido consigo mesmo, mas depois de avisar a todos para não tocarem na senhorita Daisy, ele próprio foi controlado por um pensamento paranóico: o que aconteceria se eu tocasse na senhorita Daisy?",
  [1130369089521664] = "Suspiro... por favor, entre primeiro e podemos conversar.",
  [1130369089521408] = "Faleceu? Em tão pouco tempo, o que aconteceu?",
  [1130369089521152] = "Sinto muito... Cours faleceu há uma hora. Sou deputado do Cours e estou ocupando temporariamente o seu lugar.",
  [1130369089520896] = "Novo mordomo? E o Sr. Cours? Somos policiais.",
  [1130369089520640] = "Ah, claro. Eu sou o <P_Yellow> novo mordomo—Hannah </> . Posso perguntar quem você é?",
  [1130369089520384] = "Se bem me lembro, esta é a residência da senhorita Daisy?",
  [1130369089520128] = "Obrigado, o velho Heródoto está muito feliz!",
  [1130369089519872] = "Adeus, Sr. Heródoto. Desejo a você e à dona Amanda uma vida agradável.",
  [1143563228325120] = "Somos uma empresa de segurança, não uma guilda de aventureiros.",
  [1130369089519360] = "Sr. Heródoto, vim devolver o documento.",
  [1130369089519104] = "Tudo bem. Devolverei este documento primeiro e partiremos imediatamente.",
  [1130369089518848] = "Eu irei com você. Também possuo algumas informações que podem ser úteis para você.",
  [1130369089518592] = "Enquanto minha memória ainda está clara, devo sair para acordar a Srta. Daisy.",
  [1130369089518336] = "Cerca de metade... tenho que admitir, sua memória está melhor.",
  [1130369089518080] = "Claro, esta é uma questão de vida ou morte. E você, Liana?",
  [1130369089517824] = "Tão rápido? Você não está mentindo, está?",
  [1130369089517568] = "Acredito que os memorizei completamente.",
  [1130504917094912] = "Assim como no sanatório Backlund, enquanto Pete cantava ao lado da cama de hospital de sua irmã Enid - \n 'A dor, a dor voa, o ursinho assusta a dor, Enid dorme lindamente...'",
  [1130504917092864] = "Demorou um pouco, mas finalmente cheguei ao primeiro.",
  [1130369089516800] = "Vamos gravar juntos? Caso haja um acidente, talvez eu possa ajudar.",
  [1130369089516544] = "Tenho alguma confiança na minha memória; não deve ser difícil lembrar as respostas dos quebra-cabeças.",
  [1130369089516288] = "Mas... {{PlayerName}}, afinal, este é um assunto arriscado.",
  [1130369089516032] = "Peguei emprestado o arquivo. Sou responsável por investigar o caso, então também devo acordar a Srta. Daisy.",
  [1130369089515776] = "Eu entendo, obrigado.",
  [1130369089515520] = "Você ainda terá que destrancar a caixa para obter o documento – este é um teste necessário para garantir que você tenha habilidade suficiente e não correrá perigo por causa disso.",
  [1130369089515264] = "Este documento está na caixa de armazenamento <P_Yellow> no canto </> . No entanto, embora o Presidente lhe tenha concedido permissão especial...",
  [1130369089515008] = "Sr. Heródoto, gostaria de pegar emprestado \"90 Soluções de Enigmas de Mecanismos Existentes para Artefato Selado 3-888\".",
  [1130369089514752] = "No entanto, devido ao desaparecimento de 3-888, o nível de confidencialidade dos \"Métodos de resolução de quebra-cabeças\" foi aumentado; você precisa <P_Yellow> se inscrever em Heródoto para </> .",
  [1130369089514496] = "É precisamente por isso que o nível de perigo 3-888 é atualmente apenas o Nível 3.",
  [1130369089514240] = "97 quebra-cabeças, 7 desconhecidos, com certo grau de perigo, mas a probabilidade de sucesso não é baixa.",
  [1130369089513984] = "Pelo que eu sei, pelo menos 5 quebra-cabeças não foram registrados, e depois tem aquelas duas empregadas...",
  [1130369089513728] = "Precisamos estudar esse livro, “Métodos de resolução de quebra-cabeças”, cuidadosamente e usar seu conteúdo para resolver os quebra-cabeças e quebrar o ciclo.",
  [1130369089513472] = "Se existe uma maneira de entrar no espaço do loop, deve haver uma maneira de quebrar o loop.",
  [1130369089513216] = "Essas duas empregadas morreram porque tocaram no símbolo no pulso da Srta. Daisy, entraram no espaço do laço e não conseguiram resolver o quebra-cabeça?",
  [1130369089512960] = "Mas ela também não vai acordar...",
  [1130369089512704] = "Isso mesmo. Enquanto o loop continuar, o símbolo emitirá uma luz fluida e Miss Daisy não morrerá de verdade.",
  [1130369089512448] = "Será que a alma da senhorita Daisy está selada em alguma cena, e é por isso que seu corpo mostra sinais de morte?",
  [1130369089512192] = "<P_Yellow> Estas páginas </> são as informações detalhadas sobre 3-888, você pode dar uma olhada.",
  [1130369089511936] = "Sim. Rebecca me pediu para saber mais, e eu investiguei como policial e também descobri a marca do Artefato Selado.",
  [1130369089511680] = "Liana? Você forneceu a inteligência para este caso?",
  [1130369089511424] = "Rebecca confiou o caso a você? Ah, meu nome é <P_Yellow> Liana </>.",
  [1130369089511168] = "Estou investigando o caso de coma de Miss Daisy e quero procurar as informações sobre o Artefato Selado 3-888.",
  [1130369089510912] = "Desculpe, este é o livro que tenho em mãos, ainda não terminei de lê-lo. Está com pressa?",
  [1130369089510656] = "Senhora, você viu as informações sobre Artefatos Selados de Grau 3?",
  [1130369089510400] = "Obrigado pela explicação, Sr. Heródoto.",
  [1130369089510144] = "Somente o empréstimo de informações com maior nível de confidencialidade requer a aprovação do antigo Heródoto, dos mentores ou mesmo do presidente.",
  [1130369089509888] = "Ah, dentro do Clube do Tarô , as informações sobre os Artefatos Selados de Grau 3 são quase públicas; você pode simplesmente ir ao <P_Yellow> segundo andar </> para lê-lo.",
  [1130369089509632] = "Sr. Heródoto, gostaria de pegar emprestadas as informações sobre Artefatos Selados de Grau 3.",
  [1130369089509376] = "Uma resposta honesta. Talvez você possa encontrar a resposta através da investigação.",
  [1130369089509120] = "... <P_Heart> (Suspiros de alívio) </> Eu costumava pensar que a respiração e os batimentos cardíacos eram símbolos da vida, mas recentemente tive muitas dúvidas.",
  [1130369089508864] = "Claro, é minha vez de perguntar novamente: qual você acha que é a fronteira entre a vida e a morte?",
  [1130369089508608] = "Tudo bem. Isso conta como resposta a uma pergunta?",
  [1130369089508352] = "Você pode ir até a sala de arquivos e procurar as informações sobre Artefatos Selados de Grau 3.",
  [1130369089508096] = "Tenho mais uma pergunta... o que é o Artefato Selado 3-888?",
  [1130369089507328] = "É assim mesmo? Eu também nunca atinjo pessoas com raios.",
  [1130369089507072] = "Não, nunca fico com o nariz escorrendo.",
  [1130369089506304] = "Talvez... sim, mas esqueci? Se eu esqueci, significa que não esqueci.",
  [1130369089506048] = "Tem certeza?",
  [1130369089505792] = "Quem iria querer provar esse tipo de coisa?",
  [1130369089505536] = "Uma resposta muito honesta e confiante. Se ao menos eu pudesse ficar com o nariz escorrendo...",
  [1130369089505280] = "Não apenas pensei nisso, nesta vida, por que não tentar! Eu só tentei algumas vezes.",
  [1130369089505024] = "Uma resposta honesta. Da próxima vez, limitarei a pergunta a depois que você crescer.",
  [1130369089504768] = "Claro! Quem... não teve curiosidade em saber o sabor de tudo quando era criança?",
  [1130369089504512] = "De acordo com o princípio da reciprocidade, é minha vez de perguntar: você já pensou em provar o seu próprio ranho?",
  [1130369089504256] = "Eu sei, este símbolo é a marca deixada por <P_Yellow> Sealed Artifact 3-888 </> .",
  [1130369089504000] = "Arrodes, <P_Heart> (descreva a forma do símbolo) </> você sabe o que ele representa?",
  [1130369089503488] = "Não deixe ninguém tocar na senhorita Daisy, é perigoso. Estarei de volta em breve.",
  [1130369089503232] = "<P_Heart> (Relacionado ao símbolo na mão? Talvez... volte e pergunte a Arrodes...) </>",
  [1130369089502976] = "O Dr. Jonar verificou e não encontrou nenhuma anormalidade, e o policial anterior também concordou com esta conclusão.",
  [1130369089502720] = "Limpando as mãos? Talvez... alguém verificou a causa da morte das duas empregadas?",
  [1130369089502464] = "Às nove horas da noite, Kara foi <P_Yellow> limpar as mãos da jovem </>, mas de repente caiu no chão e logo sua respiração e batimentos cardíacos desapareceram. Primeiro deixamos a empregada Irene assumir os cuidados da jovem, mas inesperadamente ela faleceu da mesma forma.",
  [1130369089502208] = "Na manhã seguinte, a empregada Cara constatou que a febre da jovem havia diminuído, mas ela não conseguia acordá-la. Achamos que provavelmente era sonolência depois que a febre baixou, então planejamos observar por um tempo primeiro.",
  [1130369089501952] = "Naquela noite, a jovem teve febre alta, então convidamos o Dr. Jonar para tratá-la. Depois que a jovem tomou o remédio, ela adormeceu, então não a incomodamos a noite toda.",
  [1130369089501696] = "Sr. Cours, como descobriu que Miss Daisy estava dormindo profundamente?",
  [1130369089500672] = "Mas os milagres médicos são muito escassos; Não tenho mais como tratá-la.",
  [1130369089500416] = "Uma visão única. Pelo menos emocionalmente, concordo total e plenamente com a sua opinião.",
  [1130369089500160] = "Claro, existem muitos fenômenos que apoiam o seu veredicto de morte. Mas também há muitos sinais que indicam que Miss Daisy não está morta. Talvez isso possa ser considerado... vivo em certo sentido?",
  [1130369089499904] = "Como médico, devo julgar a vida e a morte de acordo com os princípios médicos.",
  [1130369089499648] = "Mas os braços da senhorita Daisy são quentes, macios e elásticos... Prefiro acreditar que ela está dormindo.",
  [1130369089499392] = "Sem respiração, sem pulso; certamente atende aos critérios de morte.",
  [1130369089499136] = "Por favor, me perdoe, você pode me deixar dar uma outra olhada na condição da Srta. Daisy?",
  [1130369089498880] = "Isso não é impossível. Mas, como médico, nunca cometi um erro ao julgar a vida e a morte.",
  [1130369089498624] = "Será que, por algum motivo, criou a ilusão da morte?",
  [1130369089498368] = "<P_Heart> (Faleceu? Mas a informação que recebi foi que ela estava dormindo profundamente...) </>",
  [1130369089498112] = "Senhorita Daisy... infelizmente, ela faleceu de certa forma.",
  [1130369089497856] = "Você tem razão. Dr. Jonar, como está o estado da senhorita Daisy?",
  [1130369089497600] = "Num certo sentido, a profissão médica é também uma espécie de “investigação”.",
  [1130369089497344] = "Este é o oficial {{PlayerName}}, responsável por investigar a verdade.",
  [1130369089497088] = "É ótimo ser saudável; Muitas vezes sou atormentado por dores de cabeça.",
  [1130369089496832] = "Olá, Dr. Raramente vou ao médico, então...",
  [1130369089496576] = "Se você morou em Tingen nos últimos dois anos, deve ter ouvido o nome do <P_Yellow> Dr. Jonar </> .",
  [1130369089496320] = "Vou levá-lo primeiro para ver a situação da jovem. Eu entendo, este é um procedimento necessário.",
  [1130369089496064] = "Você está certo. O Conde me confiou a importante tarefa de cuidar da jovem, então devo manter a calma.",
  [1130369089495808] = "A verdade sempre surgirá; o medo cegará nossos olhos, Sr. Cours.",
  [1130369089495552] = "Sim, mas quem pode ter certeza de que o desastre não cairá sobre eles?",
  [1130369089495296] = "Pelo que eu sei, os infelizes que faleceram foram as duas senhoras que serviam a senhorita Daisy?",
  [1130369089495040] = "Se demorarmos mais, temo que estarei no necrotério esta noite.",
  [1130369089494784] = "Ah, outro policial? Espero que você possa descobrir a verdade.",
  [1130369089494528] = "A delegacia recebeu seu relatório. Eu sou o policial {{PlayerName}} que está investigando o caso.",
  [1130369089494272] = "Sim, sou o mordomo, Cours. Posso perguntar quem você é?",
  [1130369089494016] = "A senhorita Daisy da família do Visconde Elton mora aqui?",
  [1130369089493760] = "Na verdade, este já é o preço mais favorável. Louvado seja o Sr. Tolo!",
  [1130369089493504] = "As bebidas não são gratuitas. Está tudo bem, muitos recém-chegados têm esse mal-entendido.",
  [1130369089493248] = "Ah... me desculpe, pensei que fosse... grátis.",
  [1130369089492992] = "Aliás, o preço do café é <P_Yellow> 1 Soule </> .",
  [1130369089492736] = "Hmm, talvez o efeito colateral seja um pouco forte... Tudo bem, você vai se acostumar daqui a pouco!",
  [1130369089492480] = "Ha, agora você pode começar sua ação com alto astral!",
  [1130369089492224] = "Como é? Os grãos de café feitos especialmente fazem você se sentir cheio de energia?",
  [1130369089491968] = "Heródoto disse que os romances policiais também são sempre escritos assim. Desejo a todos o melhor!",
  [1130369089491712] = "Correto. Muitos casos bizarros são causados ​​por pequenas coisas imperceptíveis.",
  [1130369089491456] = "Espero que ajude você a esclarecer o caso. Algumas coisas parecem comuns, mas a verdade é assustadora.",
  [1130369089491200] = "Sim, Sra. Amanda. O café pode refrescar a mente e um pouco de doçura faz bem para pensar.",
  [1130369089490944] = "Estilo clássico? Muitos jovens no Clube do Tarô têm essas preferências.",
  [1130369089490688] = "Uma xícara de café, um cubo de açúcar, duas colheres de leite, por favor.",
  [1130369089490176] = "Aguardamos suas boas notícias.",
  [1130369089489920] = "Então, tenho algum trabalho para fazer, irei primeiro.",
  [1130369089489664] = "Ok, obrigado pela introdução, Rebecca.",
  [1130369089489408] = "Bom. Se você encontrar algum acidente durante a investigação, certifique-se de garantir sua própria segurança. Entre em contato comigo se tiver algum problema.",
  [1130369089489152] = "Eu tenho isso comigo. Quer dizer... intervir na investigação como policial?",
  [1130369089488896] = "O domínio Beyonder é estritamente confidencial para pessoas comuns. Seu distintivo policial ainda está com você?",
  [1130369089488640] = "Sua cabeça deve estar cheia de perguntas? Investigação é o processo de responder perguntas!",
  [1130369089488384] = "Este é o relatório, tem o endereço da senhorita Daisy <P_Yellow></> , dê uma olhada.",
  [1130369089488128] = "A presidente baixou, portanto, o seu nível de confidencialidade, permitindo-lhe apenas ocasionalmente ajudar na investigação de incidentes extraordinários em Tingen, concentrando-se principalmente na recolha de informações.",
  [1130369089487872] = "Liana também é membro do Clube do Tarô , mas a maior parte de sua energia está focada em sua família, então ela sempre foi uma Sequência 9.",
  [1130369089487616] = "Recentemente, uma senhorita <P_Yellow> Daisy </> em Tingen entrou repentinamente em coma. As duas empregadas que cuidavam dela morreram uma após a outra, e o mordomo da casa relatou o caso. <P_Yellow> Liana </> relatou este caso, suspeitando da influência de fatores extraordinários.",
  [1130369089487104] = "<P_Heart> (Pensando) </> Perfeito! Há um caso envolvendo Beyonder fatores... Você é um membro oficial do 'Dawn Squad', então não deve ser muito perigoso.",
  [1130369089486848] = "Então, eu queria voltar e ver se há algo em que eu possa ajudar?",
  [1130369089486592] = "Recentemente, recebi muita orientação e ajuda da Clube do Tarô —Sra. Justiça, Sr. Estrela...",
  [1130369089486336] = "Ah, é {{PlayerName}}! Precisa de alguma coisa agora que voltou?",
  [1130369089486080] = "Dor de cabeça... ainda tem alguns casos que não foram atribuídos, preciso me apressar e cuidar deles...",
  [1130369089447168] = "Lembro-me do que prometi a você, não vou voltar atrás em minha palavra... Vamos nos encontrar no <P_Yellow> Cemitério Rafael </> , e vou levá-lo até onde crescem as rosas.",
  [1130369089446912] = "Depois de entender tudo... talvez eu publique essas coisas em nome de Rosalind. Nós, pessoas pequenas, nunca somos vistos por aqueles figurões, mas esta cidade deveria se lembrar do nome da minha irmã.",
  [1130298758791680] = "Falha no avanço",
  [1130298758666752] = "Estou em casa",
  [1130298758662656] = "Ressurreição?",
  [1130369089445888] = "{{Sr.|Sra.}} Você gostaria de comprar algumas flores? Flores como rubis, recém-colhidas da árvore, as rosas mais frescas de Tingen.",
  [1130369089445632] = "Caractere de espaço reservado",
  [1147890944710912] = "O que está errado?",
  [1130369089444864] = "Tela preta com texto branco",
  [1130369089444352] = "Animação de entrada",
  [1130369089444096] = "Recursos para testar o desempenho do gráfico",
  [1130369089443840] = "Combinado com o aumento temporário de minhas próprias habilidades do Bardo, posso enfrentar totalmente monstros do tipo Sequência de nível corpo a corpo.",
  [1130369089443328] = "Esse machado pode criar um raio muito prejudicial com apenas duas ou três colisões.",
  [1130369089443072] = "Usarei meu mérito restante para contratar ajudantes nos próximos dois dias para obter as verdadeiras raízes e seiva da Árvore da Névoa, e poderei concluir a transação em breve.",
  [1130369089442816] = "\"The World\", a arma Beyonder que você forneceu foi melhor do que eu esperava. Economizei mérito suficiente para trocar por materiais e avançar para Sequência 8.",
  [1130369089442048] = "Às vezes, a arte de falar também é muito importante.",
  [1130369089441792] = "O editor continuará a iterar e atualizar no futuro, mas por enquanto vamos comer.",
  [1130369089441536] = "Tudo bem, a demonstração de hoje termina aqui.",
  [1130369089441280] = "A honestidade é uma grande virtude.",
  [1130369089441024] = "Pergunta: Como é a comida no refeitório?",
  [1130369089440768] = "Próxima função, vamos mostrar as opções de ramificação.",
  [1130369089440512] = "Sim, também pode ser usado para mostrar cenas grandes...",
  [1130369089440256] = "Objetos como este que não estão no modelo precisam ser implementados adicionando uma nova trilha de câmera.",
  [1130369089440000] = "Por exemplo, podemos ampliar para ver isso na cena...",
  [1130369089439744] = "A operação pode ser otimizada posteriormente; vamos executar o fluxo de trabalho primeiro.",
  [1130369089439488] = "A câmera geralmente está no bloco da trama, então a câmera aqui fica em uma posição relativa, certo?",
  [1130369089439232] = "A próxima coisa a demonstrar é o desempenho da cena do jogo. Obviamente, estamos atualmente em um verdadeiro cenário urbano principal.",
  [1130369089438976] = "Não é ótimo. Não é recomendado usar a função fade-in/fade-out com frequência, pois pode ser bastante perturbador.",
  [1130369089438720] = "Hehe, como foi isso?",
  [1130369089438208] = "Eh? Meu? Tudo bem então.",
  [1130369089437952] = "Por exemplo, você aí, venha recitar um poema.",
  [1130369089437696] = "A seguir, demonstrarei a função fade-in e fade-out; esta função é muito comum.",
  [1130369089437440] = "Parece que o planejador quer ser preguiçoso e não quer fazer isso de novo.",
  [1130369089437184] = "O mesmo método também pode ser usado para conseguir a saída do personagem, então não vou demonstrar isso.",
  [1130369089436928] = "O movimento tem dois modos: caminhar e correr, e você pode escolher livremente o caminho.",
  [1130369089436672] = "Fora da câmera ou adicionando um novo objeto; há muitas maneiras de conseguir isso.",
  [1130369089436416] = "Onde você estava se escondendo agora?",
  [1130369089436160] = "Capitão, estou aqui.",
  [1130369089435904] = "Entrada e saída de personagem, suponho. Você aí, por favor, venha.",
  [1130369089435648] = "O que vem a seguir?",
  [1130369089435392] = "Parece que vejo muitos fígados.",
  [1130369089435136] = "Este tipo de câmera não pertence ao conteúdo do template e precisa ser digitada manualmente pelo planejador de acordo com necessidades específicas. De modo geral, quanto mais detalhada for a codificação, melhor será o efeito.",
  [1130369089434880] = "Sim, por exemplo, esta câmera empurrada em direção ao meu rosto geralmente é usada para expressar choque.",
  [1130369089434624] = "É aquele tipo de câmera que consegue se movimentar, certo?",
  [1130369089434368] = "Para alguns detalhes, consulte a documentação; Não vou repeti-los aqui. Aliás, preciso falar um pouco mais de besteira aqui para demonstrar a câmera dinâmica.",
  [1130369089434112] = "Perverter.",
  [1130369089433856] = "Os planejadores dizem que estão trabalhando nisso. Se você apressá-los novamente, eles vomitarão o fígado em seu rosto.",
  [1130369089433600] = "Há também expressões e sincronização labial; performances de enredo vívidas requerem a cooperação de vários módulos.",
  [1130369089433344] = "Uma dona de casa inteligente não consegue cozinhar sem arroz. Vou apenas chamar uma ação aleatoriamente primeiro. Os requisitos para ações de diálogo geral já foram apresentados; uma vez que os recursos estejam disponíveis, o efeito visual geral será melhor.",
  [1130369089433088] = "Sim, o editor também suporta ações de chamada e recursos de voz baseados em texto.",
  [1130369089432832] = "Eu sei, isso pode ser preenchido diretamente na tabela ou chamado diretamente no editor, e os dois lados podem influenciar um ao outro.",
  [1130369089432576] = "Nosso posicionamento atual e ângulos de câmera são todos baseados em modelos de plotagem, chamados diretamente de acordo com necessidades específicas.",
  [1130369089432320] = "É muito simples, basta ficar aí.",
  [1130369089432064] = "O que exatamente você precisa que eu faça?",
  [1130369089431808] = "Preciso demonstrar alguns recursos do editor de enredo hoje e preciso da sua cooperação.",
  [1130369089431552] = "Capitão, por que você me chamou aqui?",
  [1130369089431296] = "...Meu bom Parceiro, vou me candidatar à Associação.",
  [1130369089431040] = "Um caso de empregada desaparecida. Parece que há mais de um caso para resolver desta vez. Eu me pergunto se a recompensa será dobrada.",
  [1130369089430784] = "Você quer saber disso? Contanto que você encontre minha irmã, tudo está bem. Caso contrário, não direi nada, não direi uma palavra!",
  [1130369089430528] = "Iremos verificar com essas pessoas. Por enquanto, você precisa parar de vender essas rosas e nos contar onde elas foram colhidas.",
  [1130369089430272] = "Eu perguntei a todos eles. Assim como as pessoas da residência do duque, eles se recusam a dizer qualquer coisa.",
  [1130369089430016] = "Essas cartas mencionam alguns lugares que sua irmã visitou e pessoas que conheceu. O imperador Roselle disse uma vez: 'Tudo o que é pisado deixa um rastro'.",
  [1130369089429504] = "Posso ir com você, Sr. Constable, mas por favor encontre minha irmã. Esse é o seu dever, não é?",
  [1130369089429248] = "Não sei o que aconteceu com minha irmã, mas ela desapareceu mesmo, e essas pessoas estão todas mentindo! Dizem que ela não existe, mas ela é minha irmã, como poderia não existir!!",
  [1130369089428992] = "Olha, essa é a carta que minha irmã me deu, não estou mentindo!",
  [1130369089428736] = "Sim, o nome da minha irmã é Rosalind, e ela é <P_Yellow> empregada doméstica na residência do duque de Negan </>. Mas ela desapareceu há pouco tempo e não consigo encontrá-la em lugar nenhum. Só posso vender flores aqui enquanto continuo procurando por ela.",
  [1130369089428480] = "Você está dizendo que está procurando por sua irmã e que ela desapareceu?",
  [1130369089428224] = "Hmm... parecemos um bando de bandidos irracionais.",
  [1130369089427968] = "Oh! A Vigias Noturnos , Deusa acima, orei para que você me ajudasse a encontrar minha irmã, mas você não respondeu. Agora você vem me intimidar e tentar roubar minhas flores!",
  [1130369089427712] = "Você deve ter entendido algo errado. Juro pela Deusa, não fiz nada de mal e minhas rosas são apenas rosas comuns. Acabei de vir de Tingen para Backlund procurar minha irmã...",
  [1130369089427456] = "Devo dizer que você é uma jovem inteligente, então, por favor, seja inteligente e venha conosco agora.",
  [1130369089427200] = "Você sabe meu nome? Quais itens perigosos? Só estou vendendo flores aqui... você está dizendo que minhas rosas são itens perigosos?",
  [1130369089426944] = "Descobrimos que você está vendendo itens perigosos. Os Vigias Noturnos agora estão intervindo oficialmente na investigação contra você, Srta. Daisy.",
  [1130369089426688] = "Você muda sua expressão muito rápido.",
  [1130369089426432] = "...Ah, é o cliente que comprou minhas rosas ontem. Você precisa de rosas hoje também? As rosas mais frescas, acabadas de colher da árvore.",
  [1130369089426176] = "Heh, então você pode voltar para a delegacia conosco para confirmar isso. Além disso, meu amigo aqui ficará muito triste se você afastar um convidado bem-intencionado como este.",
  [1130369089425920] = "...Documentos também podem ser falsificados. Na minha cidade natal, esses documentos de baixa qualidade custam dois Sol cada.",
  [1130369089425664] = "Relaxe, não precisa ficar tão nervoso. Sou policial, aqui está meu distintivo.",
  [813709740518144] = "O que? Este é o nosso território ou você tem negócios a fazer?",
  [1130369089425152] = "Leonardo, você está atrasado.",
  [1130369089424896] = "Ver você sem palavras é uma visão rara e divertida.",
  [1130369089424640] = "Você! EU...",
  [1130369089424384] = "E você? Você afastou meu cliente e agora está dando em cima de uma garota solitária. Como você pode provar que é diferente daquela pessoa agora?",
  [1130369089424128] = "Minha irmã me ensinou; Eu não irei com ela. Mas quem sabe ela me compre uma rosa!",
  [1130369089423872] = "Então você sabe.",
  [1130369089423616] = "Eu sei que em uma cidade grande como Backlund, qualquer pessoa que casualmente puxa conversa com uma garota sozinha provavelmente não é um cavalheiro de bom coração.",
  [1130369089423360] = "Cliente? Aquele cara agora não tinha boas intenções.",
  [1130298758777344] = "Subir pela janela?",
  [1130369089407488] = "Talvez você possa pegar o bolo primeiro, vir até mim amanhã e trabalhar para pagá-lo.",
  [813709740219392] = "Você provavelmente notou que quando o anjo desceu ao mundo, ela parecia um pouco ferida, certo?",
  [1130369089421312] = "Ouvi falar disso, o documento de planejamento foi roubado!",
  [1130369089421056] = "Você vai se acostumar com isso em breve. Ocorreu um caso em Backlund e você precisa investigá-lo.",
  [1130369089420800] = "Oh! Ainda não estou acostumada com esse título!",
  [1130369089420544] = "Olá, Grande Detetive!",
  [1130369089420288] = "Amanhã à tarde. Se você tiver quaisquer outros produtos, envie-os o mais rápido possível.",
  [1130369089420032] = "Negócio! Quando você vai zarpar?",
  [1130369089419776] = "Eu não me importo com isso. Mas depois de deduzir a taxa de risco, só posso oferecer 2.000 centavos. Os hóspedes do mar não são todos tolos.",
  [1130369089419520] = "...Não estou mais vendendo o colar, me devolva.",
  [1130369089419264] = "É verdade que muitas vezes as empregadas levam os colares das patroas para vender, mas poucas pessoas se atrevem a aceitá-los.",
  [1130369089419008] = "Eu não roubei o colar da Sra. Susanna! Ela me deu!",
  [1130369089418752] = "Você trabalha na casa da Sra. Susanna? Trouxe este colar para Tingen há três anos e vendi para o marido dela.",
  [1130369089418496] = "Parece... que assim que um adulto se aproxima, ela desaparece.",
  [1130369089418240] = "Quando ela geralmente desaparece?",
  [1130369089417984] = "Muitas vezes brincamos juntos, mas ela sempre desaparece de repente.",
  [1130369089417728] = "Vou te contar calmamente, não conte a mais ninguém. May é... uma ministra do Reino Errante!",
  [1130369089417472] = "Quem é maio?",
  [1130369089417216] = "Você viu May por perto?",
  [1130369089416960] = "São folhas levadas pelo vento.",
  [1130369089416704] = "Jogos de azar... dizem que um Jogador tem tudo, eu... eu tenho tudo... Esse não é o meu dinheiro que está no chão?",
  [1130369089416448] = "Eu costumava... Eu costumava ser uma pessoa rica e notável no Empress Borough. O dono do Restaurante Coastline teve que me convidar para jantar!",
  [1130369089414656] = "Este pode ser o primeiro presente do Embaixador das Relações Exteriores no Reino Errante.",
  [1130369089414144] = "É realmente melhor ir para casa no aniversário!",
  [1130369089413888] = "Meu presente é um chapéu, para o querido Ministro da Administração Anthony, feliz aniversário!",
  [1130369089413632] = "Eu tenho uma xícara nova! Quando eu receber meu salário no mês que vem, vou beber um copo grande de refrigerante!",
  [1130369089413376] = "Nosso Ministro da Administração Interna, May, feliz aniversário! Meu presente é um copo d'água.",
  [1130369089413120] = "Obrigado, novo amigo!",
  [1130369089412864] = "Maio, feliz aniversário!",
  [1130369089412608] = "Bom, eu lhe dou uma promessa do Rei.",
  [1130369089412352] = "Então serei o Embaixador dos Negócios Estrangeiros.",
  [1130369089412096] = "Você escolhe um.",
  [1130369089411840] = "Que tipo de ministro eu poderia ser?",
  [1130369089411584] = "Reino Errante? Que ótimo nome! Gostaria de convidá-lo a se juntar ao Reino Errante em nome do Rei.",
  [1130369089411328] = "Este é o seu reino errante.",
  [1130369089411072] = "Você é realmente uma nação rigorosa e independente.",
  [1130369089410816] = "É claro que os meus ministros são todos muito capazes. Até ajudamos outros órfãos.",
  [1130369089410560] = "Os seus ministros estão cumprindo bem os seus deveres e vocês fizeram o seu melhor para protegê-los. Você merece ser o rei deles.",
  [1130369089410304] = "Você me chamou de rei?",
  [1130369089410048] = "De nada, rei.",
  [1130369089409792] = "Obrigado por nos levar para casa.",
  [1130369090082304] = "Pare com essa merda, Gner, você não faz isso há apenas um ou dois dias. Vou contar ao Swain sobre isso!",
  [1130369089957376] = "Quando chegar a hora... e o comitê gestor vier investigar... não pense que você conseguirá escapar das consequências!",
  [1130369089832448] = "Obrigado, parece muito bom.",
  [1130369089809920] = "Não houve nem uma única salva de palmas quando fiz minha reverência... Minha peça acabou...",
  [1130369089408512] = "Bom, então prepararei os presentes surpresa.",
  [1130369089408256] = "{{Sr.|Sra.}}, vamos nos separar!",
  [1130369089408000] = "Além do bolo... também precisamos convidar os súditos e preparar presentes surpresa para o aniversário.",
  [1130369089029632] = "Em eventos como este, só podemos fazer o nosso melhor para ajudá-lo... mas se agirmos um pouco mais rápido, talvez você possa salvar mais pessoas.",
  [1130369088937472] = "E o Capitão Frye e os outros foram chamados por uma missão repentina agora há pouco, então só nos resta continuar esta enorme tarefa. {{PlayerName}}... talvez você tenha tempo para me ajudar?",
  [1130369088767488] = "Ah! Tenho que voltar e terminar os documentos do caso. Espero que o Capitão Frye ainda não tenha notado...",
  [1130369088751104] = "Convidado, gostaria de participar do nosso evento de degustação hoje?",
  [1130369089553920] = "Sim, estes são sempre escassos para adultos.",
  [1130369089422848] = "Tudo bem, irei para lá imediatamente.",
  [1130369089363456] = "Sim, olhe aqui.",
  [1130369089407232] = "Esta é uma responsabilidade que deve ser cumprida pelo Rei, não posso deixar que outros façam isso por mim.",
  [1130369089406976] = "Tudo bem, eu pago, basta escolher o que você gosta.",
  [1130369089406720] = "Esse aqui custa 2 Sol... tem algo mais barato?",
  [1130369089406464] = "Olá, Sra. Lange, que tipo de bolo você quer?",
  [1130369089406208] = "Criança, veio comprar um bolo?",
  [1130369089405952] = "Conheço uma padaria que faz bolos deliciosos. Eu te levo lá!",
  [1130369089405696] = "Para ir a uma festa de aniversário, claro que tenho que levar um bolo.",
  [1130369089405440] = "Onde você está indo?",
  [1130369089405184] = "Não é nada. Já vou indo, até logo.",
  [1130369089404672] = "Todos! Nosso novo amigo resolveu o problema para nós, podemos voltar ao reino para comemorar o aniversário!",
  [1130369089404416] = "Claro! Obrigado!",
  [1130369089404160] = "Você pode voltar para o Lago Tingen esta noite, mas preciso acompanhá-lo o tempo todo, tudo bem?",
  [1130369089403904] = "Você está de volta! <P_Heart> (Nervoso) </> Qual é o resultado?",
  [1130369089403648] = "Ótimo! Obrigado, Sr. Frye!",
  [1130369089403392] = "Meus colegas farão uma reinspeção completa do lago e depois os trarão.",
  [1130369089403136] = "<P_Heart> (O Sr. Frye parece saber muito sobre o asilo...) </>",
  [1130369089402880] = "Para poder construir uma vida assim sem o tormento do asilo, eles são notáveis.",
  [1130369089402624] = "Vou acompanhá-los o tempo todo para garantir sua segurança.",
  [1130369089402368] = "Hmm... todas as pessoas atualmente ativas no lago foram verificadas, não há problemas. Mas não posso garantir se ainda existem perigos potenciais.",
  [1130369089402112] = "Sim... ultimamente estão todos lotados nas favelas, o ambiente é muito ruim.",
  [1130369089401856] = "Você quer levá-los de volta para comemorar o aniversário?",
  [1130369089401600] = "Sr. Frye, tenho mais uma coisa... Os órfãos planejavam originalmente comemorar seu aniversário lá hoje.",
  [1130369089401344] = "Já selecionamos Hunter e o velho Martin do nosso lado e não há problemas. Louvado seja a Deusa, ninguém foi corrompido; este é o melhor resultado.",
  [1130369089401088] = "E antes do bloqueio, Hunter da Hat Gang e o velho Martin, que conduz cavalos na Lower Street, também vieram ao lago.",
  [1130369089400832] = "Tudo está claro. Aqueles que vivem lá são um grupo de órfãos. Já os verifiquei com Visão Espiritual e eles não têm problemas.",
  [1130369089400576] = "Eu não esperava encontrar você aqui também. Você teve alguma nova descoberta?",
  [1130369089400320] = "É você. Encontrei algumas pistas; é possível que as pessoas que vivem no Lago Tingen tenham vindo para esta vizinhança.",
  [1130369089400064] = "Sr. Frye, você está aqui!",
  [1130369089399808] = "Realmente? Independentemente disso, obrigado primeiro.",
  [1130369089399552] = "Se eu puder confirmar que não há perigo aí, talvez eu encontre um jeito... Aguarde minhas notícias.",
  [1130369089399296] = "Eu... faremos uma reunião do reino para discutir isso.",
  [1130369089399040] = "Ainda há policiais patrulhando o lago, como você vai levá-los para casa?",
  [1130369089398784] = "Então este é o aniversário de todos. Como Rei, com certeza irei levá-los para casa para comemorar.",
  [1130369089398528] = "Somos crianças sem-abrigo. A Ministra da Administração Interna é a única entre nós que sabe o seu aniversário; sua mãe costurou o aniversário em seus panos antes de morrer.",
  [1130369089398272] = "Eu sei que o lago é muito importante para você, mas ele precisa estar lá?",
  [1130369089398016] = "Vou levá-los de volta ao Lago Tingen.",
  [1130369089397760] = "É realmente um pouco terrível aqui. Posso ajudá-lo a organizar outro lugar para comemorar seu aniversário.",
  [1130369089397504] = "Esta é exatamente a informação que preciso, obrigado.",
  [1130369089397248] = "Isso mesmo, ouvi sua pergunta. Ficamos de olho no lago antes de ser selado. Hunter, da Hat Gang, e o velho Martin, que conduz cavalos na Lower Street, estiveram lá. Depois que a polícia selou o lago, ninguém mais esteve lá.",
  [1130369089396992] = "Você é o Ministro da Inteligência Militar?",
  [1130369089396736] = "Essa pergunta você tem que perguntar ao Ministro da Inteligência Militar, ele está em patrulha de rotina no barril de madeira ali.",
  [1130369089396480] = "Além de você, alguém esteve nas margens do Lago Tingen recentemente?",
  [1130369089396224] = "Obrigado! Meu novo amigo, você tem mais alguma coisa que queira perguntar?",
  [1130369089395968] = "Não há necessidade, mas você tem excelentes habilidades diplomáticas.",
  [1130369089395712] = "Hehe, sou eu. Você quer comprar fósforos? Já somos amigos, posso te dar um.",
  [1130369089395456] = "Você é o Ministro das Relações Exteriores que tentou me vender fósforos antes?",
  [1130369089395200] = "O Ministro das Relações Exteriores sou eu, {{Sr.|Sra.}}, nós nos conhecemos. A Hat Gang é outra organização de crianças sem-teto ativa neste bairro, a maioria delas fugiu das fábricas têxteis.",
  [1130369089394944] = "Ministro das Relações Exteriores? Gangue do Chapéu?",
  [1130369089394688] = "Este já é o melhor ambiente em que vivemos recentemente. Para isso, o Ministro das Relações Exteriores negociou durante muito tempo com a Hat Gang.",
  [1130369089394432] = "Este... ambiente é realmente muito ruim.",
  [1130369089394176] = "Poderíamos ter feito um bom aniversário à beira do lago, mas agora só podemos comemorar em uma pilha de lixo.",
  [1130369089393920] = "Não, Anthony, hoje é nosso aniversário coletivo.",
  [1130369089393664] = "Ela é a Ministra da Administração Interna, maio. Todos os anos nosso reino comemora apenas um aniversário, e ela é sempre a protagonista.",
  [1130369089393152] = "Hoje é aniversário do Ministro da Administração Interna?",
  [1130369089392896] = "Oh não! A taça foi um presente de aniversário que dei ao Ministro da Administração Interna, tenho que voltar e buscá-la!",
  [1130369089392640] = "Então posso perguntar, Senhor Ministro da Administração, as taças e os fósforos do Lago Tingen são itens do tesouro nacional?",
  [1130369089392384] = "Meu nome é Anthony, o Ministro da Administração. Somos uma nação rigorosa e independente.",
  [1130369089392128] = "Lange é o rei, então que ministro é você?",
  [1130369089391872] = "Estou bem, obrigado por me salvar hoje. O Rei disse que você se tornou nosso amigo.",
  [1130369089391616] = "Lembro que você é a criança que acabou de apanhar do capataz. Você está bem?",
  [1130369089391360] = "Pessoal, este é o nosso novo amigo que nos salvou hoje. Nosso novo amigo tem perguntas a fazer, todos, por favor, cooperem.",
  [1130369089391104] = "Um cavalheiro disse isso durante um discurso, e uso esta frase para descrever nosso relacionamento com o reino. No início era apenas um terreno baldio e passamos por muito para torná-lo o que é hoje.",
  [1130369089390848] = "Isso realmente não parece algo que uma criança diria.",
  [1130369089390592] = "Mas esse lugar é toda a nossa vida, toda a nossa história.",
  [1130369089389824] = "E se você nunca puder voltar?",
  [1130369089389568] = "Se o reino não tivesse sido “ocupado” pela polícia... este é apenas um lugar onde somos forçados a ficar temporariamente.",
  [1130369089389312] = "Não esperava que fosse um lugar tão dilapidado, sem sequer um quarto decente...",
  [1130369089389056] = "Você nunca viu a residência de uma criança sem-teto?",
  [1130369089388800] = "Essa é a base...",
  [1130369089388544] = "...Então vamos, venha comigo até a base. Você me salvou, eu deveria te ajudar. Além disso, meu nome é Lange.",
  [1130369089387776] = "Quero confirmar uma coisa. Mas não se preocupe, se eu tivesse intenções maliciosas, não teria salvado você agora.",
  [1130369089387264] = "Preciso que você me faça um favor: leve-me para ver todos da sua organização que estiveram no Lago Tingen.",
  [1130369089387008] = "<P_Heart> (Hesita) </> O que exatamente você quer fazer?",
  [1130369089386752] = "Um aniversário?",
  [1130369089386496] = "Notícias do Reino? O aniversário do Ministro da Administração Interna é hoje, isso conta?",
  [1130369089386240] = "<P_Heart> (Suspiros) </> Você... o reino encontrou alguma coisa recentemente?",
  [1130369089385728] = "E para nós, a melhor coisa que podemos esperar todos os dias é que alguém como você esteja disposto a enfiar a mão no bolso e nos jogar alguma coisa, pedindo-nos para ajudar a carregar a bagagem, conduzir um cavalo ou entregar uma carta.",
  [1130369089385472] = "Sim. {{Sr.|Sra.}}, você é o tipo de pessoa que tem dinheiro para viver.",
  [1130369089383680] = "Nada. Conheci uma criança que se autodenominava Ministro das Finanças e ele me pediu algum dinheiro. Ele também é seu assunto?",
  [1130369089383424] = "O que você está olhando?",
  [1130369089383168] = "Então é assim.",
  [1130369089382912] = "Você esteve no Lago Tingen! Há tantos policiais lá que não nos atrevemos mais a chegar perto. Como você soube disso?",
  [1130369089382656] = "O... Reino do Lago Tingen, é seu?",
  [1130369089382400] = "<P_Heart> (A vareta radiestesia adivinhação sempre aponta para a localização dessas crianças. Poderiam ser elas as pessoas que estou procurando? Vou perguntar.) </>",
  [1130369089382144] = "Sim, {{Sr.|Sra.}}. Você tem alguma pergunta que queira me fazer?",
  [1130369089381888] = "Então você é o rei deles?",
  [1130369089381632] = "Isso precisa ser tratado o mais rápido possível. Volte para a base e faça um curativo.",
  [1130369089381376] = "Não tenho nenhum ferimento grave, apenas meu pulso dói um pouco.",
  [1130369089381120] = "Ele... hum, seu assunto... ele está bem?",
  [1130369089380864] = "Não é nada. Mas por assuntos, você quer dizer esse garotinho ao seu lado?",
  [1130369089380608] = "Obrigado, proteger meus súditos é minha responsabilidade... mas arrastei você para isso, sinto muito.",
  [1130369089380352] = "Droga, vocês, apenas esperem!",
  [1130369089380096] = "Isso é demais. Vamos proteger as crianças primeiro.",
  [1130369089379840] = "Claro. Se você não trabalhar duro, terá que ser punido. Isso é justo com os outros. Especialmente esse líder, com certeza vou fazê-lo pagar um preço hoje!",
  [1130369089379584] = "Isso também está especificado nesses contratos?",
  [1130369089379328] = "Eles me fazem trabalhar dezoito horas por dia! Eles me chicoteiam! Eles não me dão comida!",
  [1130369089379072] = "Ele precisa trabalhar na Fábrica até o final deste trimestre, mas fugiu mais cedo!",
  [1130369089378816] = "Qual contrato?",
  [1130369089378560] = "Um intrometido? Aconselho que não interfiram, temos um contrato.",
  [1130369089378304] = "Então eles não são apenas mendigos, são crianças trabalhadoras que fugiram da Fábrica... Eles serão espancados até a morte. Não, eu tenho que ir detê-los!",
  [1130369089378048] = "Nada mais do que fazê-los trabalhar dia e noite, chicoteá-los, não alimentá-los... afinal, eles não têm pais.",
  [1130369089377792] = "Tormento?",
  [1130369089377536] = "Suspiro, devem ser crianças trabalhadoras que não aguentaram o tormento e saíram correndo, apenas para serem pegas pelo capataz para voltar ao trabalho. Não podemos administrar isso.",
  [1130369089377024] = "Não é esta a criança que procuro?",
  [1130369089376768] = "Nenhum de vocês está fugindo hoje, especialmente você. Se não fosse você liderando o caminho, eu precisaria de tantos problemas?",
  [1130369089376512] = "Ministro da Administração! Correr!",
  [1130369089376000] = "Estarei morto se voltar!",
  [1130369089375744] = "Seu bastardo, fugindo antes do contrato expirar, você é um câncer para a sociedade!",
  [1130369089375232] = "Que estranho, não há nenhuma pista, apenas conheci algumas crianças que se chamavam de Ministros.",
  [1130369089374976] = "Minhas pernas vão quebrar!",
  [1130369089374720] = "Haverá derramamento de sangue!",
  [1130369089374464] = "Correr! Seremos colocados em uma jaula!",
  [1130369089374208] = "Talvez a polícia queira ler um jornal ou engraxar os sapatos.",
  [1130369089373952] = "Ministro da Administração Interna, Ministro da Administração, você errou, {{Sr.|Sra.}} não quer engraxate nem jornal. {{Sr.|Sra.}} quer comprar uma caixa de fósforos, certo {{Sr.|Sra.}}?",
  [1130369089373696] = "<P_Heart> (Parece que eles estão nisso juntos...) </>",
  [1130369089373440] = "Ministro da Administração Interna, você ouviu, {{Sr.|Sra.}} não quer engraxar os sapatos, você pode ir agora. {{Sr.|Sra.}}, quer ler um jornal?",
  [1130369089373184] = "...Sem brilho, obrigado.",
  [1130369089372928] = "Você quer engraxar os sapatos?",
  [1130369089372672] = "O que faz o Ministro da Administração Interna?",
  [1130369089372416] = "{{Sr.|Sra.}}, não sou o Ministro das Finanças, não estou implorando, sou o Ministro da Administração Interna.",
  [1130369089372160] = "Está aqui para pedir dinheiro de novo?",
  [1130369089371392] = "Eles se chamam de \"Ministros\"? Que tipo de jogo essas crianças estão jogando?",
  [1130369089371136] = "Ministro da Inteligência Militar! Espere por mim!",
  [1130369089370880] = "<P_Heart> (Pops sai) </> Ministro das Finanças! Correr! O Ministro das Relações Exteriores teve seu trabalho roubado pela Hat Gang!",
  [1130369089370624] = "Senhor, não é suficiente...",
  [1130369089370368] = "Muitas crianças? Hmm... então vou te dar um pouco mais.",
  [1130369089370112] = "Gentil {{Sr.|Sra.}}, por favor, dê um pouco mais... há muitas outras crianças que não comeram...",
  [1130369089369856] = "...O que está acontecendo. Mas aconteceu de eu trazer alguns trocos, pegue.",
  [1130369089369600] = "Nobre {{Sr.|Sra.}}, tenha piedade, não como há dias.",
  [1130369089369344] = "Ele está no beco à direita!",
  [1130369089369088] = "Desistir de pegar o ladrão? Vamos encontrar aquela criança primeiro.",
  [1130369089368576] = "Ele roubou suas coisas também? Na verdade... suspiro, é só um presunto, esqueça, esqueça.",
  [1130369089368320] = "Um ladrão? Não se preocupe, eu também estou procurando por ele.",
  [1130369089368064] = "Esse garoto roubou meu presunto!",
  [1130369089367552] = "Pegue aquele pequeno ladrão!",
  [1130369089366784] = "Pare de perseguir, você vai jogar fora!",
  [1130369089366272] = "Seu pirralho, pare aí, batedor de carteira!",
  [1130369089366016] = "Essa base é dessa criança?",
  [1130369089365504] = "Siga o resultado Adivinhação e siga em frente.",
  [1130369089365248] = "Bom.",
  [1130369089364992] = "Deixe isso comigo. Tenho uma maneira de encontrar os rastros do dono desta casa.",
  [1130369089364736] = "Hmm... nós realmente precisamos verificar as pessoas que estiveram ativas por aqui recentemente. Já rastreamos os movimentos das pessoas na área adjacente, mas ainda não tivemos tempo de investigar este lado.",
  [1130369089364480] = "Parece que essas são apenas necessidades diárias comuns e são bastante arrumadas e limpas. O proprietário deve ter saído há pouco tempo.",
  [813709740219136] = "Você quer dizer Liz? Ah, essa é minha irmã. O anjinho mais fofo do mundo.",
  [813709740517888] = "Sempre tão sujo, esfarrapado e cinza...",
  [1130298758777088] = "Quebre violentamente a fechadura!",
  [1130369089185024] = "Se ao menos Leonard pudesse aparecer com mais frequência. Ouvi da pequena Rozanne que suas habilidades com cartas são muito boas.",
  [1130369089184768] = "Não quero jogar cartas com Eustace. Ele é péssimo nisso e pode adormecer a qualquer momento.",
  [1130369089184512] = "Não há outro oficial de serviço lá fora?",
  [1130369089184256] = "Obrigado pelo lembrete.",
  [1130369089184000] = "Você também deve ter cuidado; chegar muito perto dele trará azar para você.",
  [1130369089183744] = "Haha, não precisa se preocupar muito. Existem pelo menos dois guardas internos da igreja, além de inúmeras armadilhas.",
  [1130369089183488] = "Isso parece impressionante e também muito perigoso.",
  [1130369089183232] = "Raramente. Agradeço que Chanis Gate não goste de conversar como eu. Mas conheço casos em que alguém encontrou um Artefato Selado que escapou de dentro para dizer olá.",
  [1130369089182976] = "Você já encontrou isso?",
  [1130369089182720] = "É fácil ouvir coisas que não deveria, ou até mesmo ver coisas que não deveria.",
  [1130369089182464] = "Afinal, há tudo por trás do Portão Chanis...",
  [1130369089181952] = "Embora eu possa ocasionalmente tocar a campainha e observar a pequena Rozanne correndo, é melhor para as pessoas comuns não chegarem muito perto daqui.",
  [1130369089181696] = "Pois é, você não tem ideia de como é chato estar de plantão. Eu tenho que ficar aqui guardando o Portão Chanis o tempo todo...",
  [1130369089181184] = "É você! Finalmente alguém pode vir conversar comigo!",
  [1130369089180928] = "Então vou dar uma olhada, obrigado capitão.",
  [1130369089180672] = "...O desenho é medíocre.",
  [1130369089180416] = "Ao lado da mesa.",
  [1130369089180160] = "Posso ver seu trabalho?",
  [1130369089179392] = "Capitão, você tem algum hobby?",
  [1130369089179136] = "Isso é muito útil, obrigado pela sua preocupação, capitão.",
  [1130369089178880] = "Além disso, se for uma emergência, ore imediatamente para a existência em que você acredita. Você deve confiar em seus parceiros e também deve confiar no papel da Grande Existência.",
  [1130369089178624] = "Ok, vou me lembrar disso.",
  [1130369089178368] = "Se você encontrar incidentes envolvendo o sobrenatural, preste atenção para proteger sua própria segurança. Você pode procurar ajuda em qualquer igreja próxima.",
  [1130369089178112] = "Ocasionalmente aceitamos algumas comissões extras, seja para encontrar pessoas ou atuar como guarda-costas, também é possível que envolvam poderes sobrenaturais.",
  [1130369089177856] = "Somos um esquadrão Vigia Noturno disfarçado de empresa de segurança, especializado em lidar com eventos sobrenaturais. Isso é algo que você já sabe.",
  [598342094653440] = "Verifique os bolsos",
  [1130369089177600] = "Como você não assinou um acordo de confidencialidade, não posso lhe contar muito.",
  [1130369089177344] = "Você está aqui.",
  [1130369089177088] = "Faz muito tempo que não tenho medo. Depois de me formar na faculdade de administração, vim trabalhar aqui. Estou muito feliz por ter conhecido um grupo de pessoas assim.",
  [1130369089176832] = "Desculpe, fiz você se lembrar de coisas ruins.",
  [1130369089176320] = "Aquele foi um maldito açougueiro que matou cinco meninas seguidas...",
  [1130369089176064] = "Não sei se você já ouviu falar do serial killer que chocou toda a cidade de Tingen há vinte e um anos.",
  [1130369089175808] = "Como você ingressou na Blackthorn Security Company?",
  [1130369089175552] = "Claro, trabalho aqui há mais de vinte anos.",
  [1130369089175296] = "Sra. Orianna, você conhece este lugar?",
  [1130369089175040] = "Suspiro, de repente me lembrei de um velho amigo que sempre quis usar fundos extras para reembolsar o café.",
  [1130369089174784] = "Os lanches do chá da tarde também são comprados com esse dinheiro.",
  [1130369089174528] = "Temos algumas tradições que continuam por muitos anos, como quando um novo membro oficial se junta, iremos ao restaurante do Old Will para uma refeição juntos...",
  [1130369089174272] = "Para que serve esse dinheiro?",
  [1130369089174016] = "De acordo com a regra tácita de longa data, metade da remuneração das comissões recebidas pela empresa de segurança é entregue a mim como fundos extras do esquadrão.",
  [1130369089173760] = "Fundos extras?",
  [1130369089173504] = "A sinalização da nossa empresa é muito especial e ocasionalmente há fundos extras.",
  [1130369089173248] = "À medida que a antiguidade aumenta, o salário aumentará gradualmente.",
  [1130369089172992] = "Além do salário base semanal, temos também subsídios de confidencialidade e de risco.",
  [1130369089172480] = "Gostaria de saber sobre os benefícios da empresa.",
  [1130369089172224] = "Aprendi bastante com isso.",
  [1130369089171968] = "Obrigado, obrigado pela revista que a pequena Rozanne trouxe.",
  [1130369089171712] = "Seu penteado hoje está muito lindo.",
  [1130369089171456] = "Sobre o que você gostaria de falar?",
  [1130369089171200] = "Mas os que estão no fundo não são, são para lembrarmos de velhos amigos.",
  [1130369089170944] = "Trimestralmente, organizo essas contas e as entrego ao capitão Frye. Ele os levará à Santa Catedral para serem reembolsados ​​e solicitarem os fundos do próximo trimestre.",
  [1130369089170688] = "Você está falando daqueles formulários de reembolso em cima da mesa?",
  [1130369089170432] = "Olá, pequeno {{PlayerName}}.",
  [1130369089170176] = "Certa vez, tivemos dois colegas com habilidades especiais de reembolso. É uma pena que você não os conheça, caso contrário eles poderiam ter lhe ensinado bastante.",
  [1130369089169664] = "Sim, mas comparado com antes, o número não é tão alto.",
  [1130369089169408] = "Existem alguns formulários de reembolso lá.",
  [1130369089169152] = "Exceto a Sra. Orianna, você é a segunda pessoa a apreciar esta revista! Muito bom gosto!",
  [1130369089168896] = "Se você estiver interessado, posso trazer mais alguns para lhe emprestar.",
  [1130369089168640] = "Esta é apenas uma revista que trouxe de casa.",
  [1130369089168384] = "Revista 《Lady's Aesthetics》?",
  [1130369089168128] = "Sim, ouvi dizer que esse era o sonho dele uma vez. Gostaria de saber se existe um Beyonder Caminho para pintores? Definitivamente serviria ao capitão Frye.",
  [1130369089167872] = "Esse é o hobby do Capitão?",
  [1130369089167616] = "Os esboços do Capitão são muito bons. Sugeri que ele pendurasse os quadros no Hall, mas ele era muito tímido.",
  [1130369089167360] = "Hehe, sugiro que você vá primeiro ao Gabinete do Capitão!",
  [1130369089167104] = "Você pode me dar algumas dicas?",
  [1130369089166848] = "Na verdade, existem algumas coisas interessantes aqui.",
  [1130369089166592] = "Você olhou para eles com atenção? Se não, você pode dar uma olhada primeiro.",
  [1130369089166336] = "Mas o que mais gosto são aquelas pequenas coisas com um significado especial.",
  [1130369089166080] = "Eu também acho, adoro cada design aqui!",
  [1130369089165824] = "O ambiente da empresa é realmente muito bom.",
  [1130369089165568] = "Mas se realmente não conseguirmos reunir pessoas suficientes, ele ainda virá.",
  [1130369089165312] = "Ele prefere ficar sozinho, nem sai se você chamá-lo para jogar cartas.",
  [1130369089165056] = "Sempre?",
  [1130369089164800] = "Exceto por estar de plantão e sair para cuidar de incidentes, o Capitão Frye estará sempre no Escritório.",
  [1130369089164544] = "Quero encontrar o Capitão.",
  [1130369089164288] = "Olá, {{PlayerName}}.",
  [1130369089164032] = "Ei! Ei! Por que você está começando de novo!",
  [1130369089163520] = "<P_Heart> Não parece nada de especial, é melhor ir embora. </>",
  [813709740519680] = "Os pirralhos que me seguem me chamam de “Rei Mendigo”, mas seria mais correto dizer que sou a madrinha de todos.",
  [1130369089163008] = "<P_Heart> Tem um corvo como animal de estimação? Isso não é exatamente raro em Loen. </>",
  [1130369089162752] = "Caso contrário não poderei te levar para casa!",
  [1130369089162496] = "Fique quieto!",
  [1130369089162240] = "...Não vou incomodar você, até a próxima.",
  [813713767028736] = "Quem é Jensen?",
  [1130369089161984] = "Cento e vinte centavos.",
  [1130369089161728] = "Coo coo coo coo coo coo coo coo coo coo coo coo-",
  [1130369089161472] = "Sessenta centavos.",
  [1130298758779136] = "Cadáver?",
  [813709740220928] = "Oi... Hm? O que... o que... o que? ... <P_Heart> (Nem levantou a cabeça.) </>",
  [1130369089159168] = "Por que você está com raiva...",
  [813713766533120] = "Alguma recomendação?",
  [1130369089158912] = "Droga, vamos terminar se isso continuar!",
  [1130369089158656] = "Lindo, lindo! É mais vermelho que minha gravata borboleta!",
  [813709740737024] = "A lança de Longinus passa a ter 6 tiros. Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813716450983936] = "Aproveite suas férias!",
  [813709740605952] = "Você não sabe? O pessoal da igreja arrastou o aleijado que anteontem pescava com agulha de costura, e a pessoa que pescava com guarda-chuva da última vez ainda está deitada no hospital contando raios!",
  [813709740640768] = "Bolo de limão com chá gelado doce, sentar na rua observando a multidão que passa – o que poderia ser melhor do que uma tarde como esta?",
  [813709740474880] = "Ele me deixa aqui quando vai trabalhar. Papai diz que os irmãos e irmãs daqui são todos muito gentis e que este é o lugar mais seguro.",
  [813709740509696] = "Para onde ele foi?",
  [813709740343808] = "Hehe, serei uma boa menina e quando papai voltar ele não ficará triste.",
  [813709740393984] = "O louco aventureiro Gehrman Sparrow! Ele é o caçador de recompensas, almirante pirata e rei dos exterminadores que usa os Cinco Mares como terreno de caça! O pesadelo e o doce sonho que atravessa o oceano!",
  [813709740212736] = "Diz-se que eles têm esse hábito desde que ainda se chamava “Restaurante do Will”.",
  [813709740247552] = "Verifique seu estado mental.",
  [813709740081664] = "Que a Tempestade te proteja!",
  [813709740116480] = "<P_Heart> (Alguém está discutindo?) </>",
  [813709739951616] = "Por que você está atrasado hoje?",
  [813709739985408] = "Estou feliz em ver Linda vencer. O velho Wade sofreu uma grande perda; ele pode estar escondido no banheiro chorando agora.",
  [813709740050944] = "O estilo também é diferente; as pernas cônicas das calças são populares para calças, que são mais convenientes para os movimentos.",
  [1130369089085440] = "E acredito que nos reuniremos no Reino da Meia Noite...",
  [1130369089085184] = "Eu não tenho medo. Mamãe uma vez me disse que se tornaria uma estrela para me proteger.",
  [1139301010194944] = "Você?",
  [1130369089084672] = "Não se preocupe, também sou um velho amigo de Blackthorn.",
  [1130369089084416] = "...Oh meu Deus, esqueci que você ainda estava aqui.",
  [1130369089084160] = "Vou terminar a universidade corretamente. Após a formatura, pretendo começar a trabalhar duro como escriturário na Blackthorn Security Company e eventualmente me tornar um Vigia Noturno que pode proteger Tingen.",
  [1130369089083904] = "Mas pensei nisso por muito, muito tempo e ainda quero me tornar alguém como você, trilhando o caminho que você já percorreu.",
  [1130369089083648] = "Sou uma criança muito, muito boa? Hehe.",
  [1130369089083392] = "...Tio Dunn, irmã Daly, finalmente entrei na Hoy University, honestamente, não foi fácil.",
  [1130369089083136] = "Por favor, espere um momento, vou colocar as flores.",
  [1130369089082880] = "Sim, eles disseram que você é uma criança muito boa.",
  [1130369089082624] = "Ei, você sabe meu nome. Tio Dunn e os outros me mencionaram para você?",
  [1130369089082368] = "Minha mãe era colega do tio Dunn e dos outros, e agora estão todos descansando aqui juntos.",
  [1130369089082112] = "Sim, você está aqui para visitá-los também?",
  [1130369089081856] = "Olá, você é amigo do tio Dunn e da irmã Daly?",
  [1130369089081600] = "Vocês dois acabaram juntos?",
  [1130369089081344] = "Muitas histórias devem ter acontecido depois disso, certo? Lady Daly disse essas palavras, o Sr. Dunn sempre foi tão estranho...",
  [1130369089081088] = "Embora seja tarde demais, finalmente foi entregue ao Sr. Dunn.",
  [1130369089080832] = "Sim, meu pai, o capitão Dunn e Lady Daly estão todos lá.",
  [1130369089080576] = "Lembro que você mencionou... Dunn e os outros estão dormindo no Cemitério Raphael, certo?",
  [1130369089080320] = "...Mas você parece um pouco triste.",
  [1130369089080064] = "Você Beyonders é sempre assim, falando coisas que eu não entendo.",
  [1130369089079808] = "Só posso conhecê-los por meio de histórias passadas e só consigo ver suas vívidas aparências em sonhos. É uma pena.",
  [1130369089079552] = "Ei, você sabe como eles são? Mas você nunca deveria ter se conhecido, certo?",
  [1130369089079296] = "Senhor Dunn, Lady Daly...",
  [1130369089079040] = "Está tudo bem, isso é o suficiente.",
  [1130369089078784] = "Não entendo do que você está falando, mas esta é apenas uma caixa vazia. Por favor, leve-o embora. Aliás, em relação ao pagamento, pretendo colocar na conta do Capitão Frye, hehe.",
  [1130369089078528] = "Pretendo ser entregador e devolvê-lo ao seu legítimo proprietário.",
  [1130369089078272] = "Esta caixa... Onde você a encontrou? O que você vai fazer com isso?",
  [1130369089078016] = "Posso levar essa caixa embora?",
  [1130369089077760] = "Ufa – finalmente terminei! Muito obrigado pela sua ajuda, {{PlayerName}}.",
  [1130369089077504] = "Imediatamente, imediatamente!",
  [1130369089077248] = "{{PlayerName}}! Você terminou de limpar?",
  [1130369089076992] = "Mas esse presente parece nunca ter chegado às mãos daquela pessoa...",
  [1130369089076736] = "Esta caixa é o presente de aniversário que ela preparou para Dunn?",
  [1130369089076480] = "A atuação acabou... Parece que foi por causa do mensageiro da Sra. Daly que consegui reviver o passado deles.",
  [1130369089076224] = "Dunn... Feliz aniversário... Na verdade, eu...",
  [1130369089075968] = "De agora em diante, deixo isso para você.",
  [1130369089075712] = "Este é o significado de tudo pelo que sacrificamos e persistimos até agora.",
  [1130369089075456] = "Vá rir livremente, ame o quanto quiser, viva feliz e então tenha um bom sonho.",
  [1130369089075200] = "Não fiquem tristes, meus filhos. Morri há cinco anos; minha história terminou há muito tempo.",
  [1130369089074944] = "Que tal eu te dar um presente como compensação? Que tal um doce sonho... Desejo que você tenha bons sonhos se tornando realidade...",
  [1130369089074688] = "Além disso, parece que arruinámos o aniversário do Dunn. Ainda tenho um pouco de força...",
  [1130369089074432] = "Haha, pequeno Daly, você não deve se arrepender como eu.",
  [1130369089074176] = "Não, eu entendo... eu quero fazer isso sozinho.",
  [1130369089073920] = "Não precisa, eu já disse tudo. Porém... eu poderia possuir você para fazer outra coisa, por exemplo, aquela coisa sobre a qual você tem hesitado?",
  [1130369089073664] = "Capitão Caryl, você precisa me possuir para ver Arnold mais uma vez? Você deve ter muito mais coisas para dizer a ele.",
  [1130369089073408] = "Você protegeu Tingen muito bem e salvou o pequeno Arnold. Obrigado.",
  [1130369089073152] = "Você não precisa se comparar comigo. Você é Dunn Smith, um capitão de esquadrão qualificado Vigia Noturno.",
  [1130369089072896] = "Eu... me saí tão bem quanto você?",
  [1130369089072640] = "Estou muito feliz em ver você tão maduro e confiável.",
  [1130369089072384] = "Oh meu Deus, Capitão Dunn, não fique tão nervoso. Você não está feliz em me ver de novo?",
  [1130369089072128] = "Capitão, Capitão Carol, essa aparição... Você esteve dentro do Artefato Selado todo esse tempo?",
  [1130369089071872] = "Tosse, tosse, Dunn, Daly, obrigado pelo seu trabalho duro.",
  [1130369089070592] = "Aquela pessoa, aquele homem disse, contanto que eu fizesse isso, poderíamos ir para casa juntos... Para casa, eu quero ir para casa...",
  [1130369089070336] = "É assim mesmo? Entendo... Sua família veio te buscar... Fiz algo errado, certo? Não sei, ninguém nunca me contou...",
  [1130369089069824] = "Mesmo que você ainda seja apenas uma criança...",
  [1130369089069568] = "Yodora, um destino doloroso não pode ser uma desculpa para você matar outras crianças.",
  [1130369089069312] = "Arnold, não somos iguais? Viver sozinho sem família...",
  [1130369089069056] = "Tão triste, tão doloroso, tão solitário...",
  [1130369089068288] = "Mas primeiro precisamos resolver o problema que temos diante de nós. Este pequenino que perdeu o controle não parece que nos deixará ir atrás de Lanevus facilmente.",
  [1130369089068032] = "Lembro-me do nome dele e de todos os seus crimes, não vou deixá-lo ir.",
  [1130369089067776] = "Eu vi o rosto dele, eu o vi em um cartaz de procurado: Lanevus.",
  [1130369089067520] = "Essa estranha energia provavelmente é causada por ele.",
  [1130369089067264] = "Alguém saiu de dentro e foi descoberto por mim. Eu queria detê-lo, mas ele escapou no caos.",
  [1130369089067008] = "Vamos resolver a crise antes de me dar um sermão, capitão.",
  [1130369089066752] = "Tosse, tosse... Isso é muito perigoso!",
  [1130369089066496] = "Há uma energia estranha transbordando na realidade e suas habilidades surgiram junto com ela. Fiquei preocupado que algo tivesse acontecido no sonho, então entrei para verificar.",
  [1130369089066240] = "O que está acontecendo, Daly, por que você entrou nesse sonho também?",
  [1130369089065984] = "Eventualmente nos encontraremos no Reino da Deusa da Noite Eterna.",
  [1130369089065728] = "Mamãe disse que mesmo que um dia ela vá embora, ela se tornará uma estrela e ficará comigo para sempre.",
  [1130369089065472] = "O sonho está desmoronando!",
  [1130369089065216] = "Não me abandone, Arnaldo!!!",
  [1130369089064960] = "Não vá! Não me deixe! Não fuja! Não me repreenda! Não me bata!",
  [1130369089064704] = "Quem está falando?!",
  [1130369089064448] = "Como era de se esperar, você não merece ter família, não merece ter casa própria.",
  [1130369089064192] = "Não, não me abandone... Tio...",
  [1130369089063936] = "...Você me decepciona...",
  [1130369089063680] = "Arnold, sua mãe...",
  [1130369089063424] = "Mas estou com muito sono agora, por que os pássaros não vieram me acordar? Por que não posso sonhar com a mãe, aconteça o que acontecer?",
  [1130369089063168] = "O canto dos pássaros é muito parecido com a canção de ninar da mamãe. Mamãe deve ter ensinado eles; Mamãe quer me conhecer em meus sonhos.",
  [1130369089062912] = "Recentemente, ouço frequentemente sons estranhos, como uma flauta... tocada muito mal, e depois sinto muito sono... mas no final sou acordado pelos pássaros.",
  [1130369089062656] = "Por que você acha isso?",
  [1130369089062400] = "Mamãe voltou para me ver.",
  [1130369089062144] = "Como você sabia? Hehe, como esperado do tio Dunn. Deixe-me contar-lhe secretamente, eu acho...",
  [1130369089061888] = "Você notou algo estranho recentemente?",
  [1130369089061632] = "Ela é órfã como eu. Acho que ela quer ser minha amiga. Ela é muito gentil e aprenderá sinceramente a canção da minha mãe comigo...",
  [1130369089061376] = "Yodora é minha amiga. Ela é um pouco tímida e sempre se esconde em um canto para me observar secretamente.",
  [1130369089061120] = "Ah, mamãe é tão chata! Volte rápido, vou esquecer a letra.",
  [1130369089060864] = "Estou esperando ela terminar de cantar aquela canção de ninar para mim. Essa música é muito linda, mas é uma pena que ela tenha fugido no meio.",
  [1130369089060608] = "Tio Dunn, você viu minha mãe?",
  [1130369089060096] = "Boa noite, tio Dunn!",
  [1130369089059584] = "Nós iremos... para casa... juntos...",
  [1130369089059328] = "...Aprendi a música do Arnold, e o Arnold também gosta de mim... Família, venham comigo...",
  [1130369089059072] = "Mas ele não gritou de medo, ele estava disposto a falar comigo...",
  [1130369089058816] = "...A flauta de osso não tem efeito sobre ele... Os pássaros estão seguindo Arnold...",
  [1130369089058560] = "Uma criança que é querida? O que isso significa?",
  [1130369089058304] = "Ele... é muito bom... É uma criança que o Verdadeiro Criador gosta... Eu também gosto dele, ele é minha família...",
  [1130369089058048] = "Por que você mirou em Arnold?",
  [1130369089057792] = "Verdadeiro Criador...",
  [1130369089057536] = "...Ele disse... os órfãos precisam de salvação... contanto que você siga o Verdadeiro Criador... todos nós podemos retornar... para nossa própria casa...",
  [1130369089057280] = "Nome... não sei...",
  [1130369089057024] = "Qual é o nome do seu tio?",
  [1130369089056768] = "<P_Heart> (Esta criança parece estar sendo usada por alguém.) </>",
  [1130369089056512] = "...Flauta? Foi dada a Yodora pelo tio... A flauta pode fazer os familiares ouvirem... Venha para casa comigo...",
  [1130369089056256] = "Onde você conseguiu sua flauta? O que isso faz?",
  [1130369089056000] = "Em breve, muito em breve poderei ir para casa também...",
  [1130369089055744] = "Yodora se saiu bem... Ele me elogiou... Ele é a primeira pessoa a me elogiar...",
  [1130369089055488] = "...Este mundo me odeia... Yodora não é um monstro...",
  [1130369089055232] = "...Yodora... está esperando... Arnold... voltar para casa...",
  [1130369089054976] = "Olá, acho que já nos conhecemos, Yodora.",
  [1130369089054720] = "Dunn está certo, me chupe!",
  [1130369089054464] = "Está tudo bem, o Capitão Caryl vai me ajudar.",
  [1130369089054208] = "Mas a entrada do seu sonho foi interrompida à força antes, e ainda há corrupção no sonho. Isso é muito perigoso.",
  [1130369089053952] = "Independentemente disso, entrarei no sonho para investigar primeiro.",
  [1130369089053696] = "Mas por causa do meu despertar, minha influência subconsciente desapareceu... Isso deu uma oportunidade à outra parte.",
  [1130369089053440] = "Arnold mencionou que os pássaros viriam brincar com ele. Talvez seja porque o Silver Nightingale Whistle está afetando os pássaros em Tingen, fazendo-os proteger Arnold.",
  [1130369089053184] = "Capitão Caryl...",
  [1139094851703296] = "Princípio da igualdade?",
  [1130369089052672] = "Arnold não foi afetado pela flauta antes, mas desta vez ele foi atraído...",
  [1130369089052416] = "Sua capacidade de atrair crianças deve ser liberada através daquela flauta.",
  [1130369089052160] = "Yodora provavelmente está por volta de Sequência 9, mas há risco de perda de controle. Devemos ter um cuidado especial com essa flauta.",
  [1130369089050368] = "Suspiro... Parece que esse pai ansioso não ama seu filho tanto quanto afirmava.",
  [1130369089048576] = "<P_Heart> (Patrulha) </>",
  [1130369089048320] = "Sonhos fragmentados, com cheiro de corrupção...",
  [1130369089048064] = "Ufa, que sonho bizarro.",
  [1130369089047808] = "É uma longa história. Vamos encontrar Arnold primeiro.",
  [1130369089047552] = "É a relíquia da Capitã Carol. Como poderia estar aqui... Este é o seu missão ?",
  [1130369089047040] = "Por favor, leve-nos para encontrar Arnold, Silver Nightingale Whistle.",
  [1130369089046784] = "Ah, tudo bem! Então vou deixar isso para vocês dois.",
  [1130369089046528] = "Daly virá comigo. Não se preocupe, vou trazer Arnold de volta.",
  [1130369089046272] = "Capitão, eu irei com você! Afinal, fui eu quem perdeu Arnold...",
  [1130369089046016] = "Kenley, volte para a empresa e notifique a todos sobre este Beyonder incidente.",
  [1130369089045760] = "Tudo bem, não tem problema, você mostra o caminho.",
  [1130369089045504] = "Acredite em mim, explicarei isso a você mais tarde.",
  [1130369089045248] = "Mas, como...",
  [1130369089044992] = "Siga-me, tenho uma maneira de rastrear a localização atual de Arnold.",
  [1130369089044736] = "Me siga.",
  [1130369089044480] = "Provavelmente não é esse o motivo, mas nada disso importa agora.",
  [1130369089044224] = "Por que... conexão mãe-filho ou algo assim?",
  [1130369089043968] = "Posso sentir a localização geral de Arnold agora. Não sei por que, mas posso sentir isso vagamente!",
  [1130369089043456] = "Pequeno Daly, pequeno Daly, você pode me ouvir?",
  [1130369089043200] = "Não se preocupe, deixe-me perguntar aos espíritos próximos...",
  [1130369089042688] = "Oh não! E o pequeno Arnold? Ele estava apenas comigo!",
  [1130369089042432] = "Eu ouvi... o som de uma flauta, uma música muito estranha, e então...!!!",
  [1130369089042176] = "No beco? Inconsciente? Oh, o pequeno Arnold queria ir para casa, então eu o levei de volta...",
  [1130369089041920] = "O que aconteceu agora? Por que você estava inconsciente no beco?",
  [1130369089041664] = "...Capitão, Sra. Daly?",
  [1130369089041408] = "Vamos dar uma olhada.",
  [1130369089041152] = "Mas por que... está aqui? Essa música... e é tão estranha...",
  [1130369089040896] = "Pequeno Daly, esta é a música que escrevi para Arnold. Esta é minha canção de ninar!",
  [1130369089040640] = "Eu reconheço essa música!",
  [1130369089040384] = "É o som da flauta! Eu ouvi isso no sonho de Arnold. Yodora pode estar por perto!",
  [1130369089040128] = "Dunn, você ouviu isso?",
  [1130369089039872] = "Tudo bem, as pistas são em sua maioria coletadas. É hora de voltar para Blackthorn e perguntar ao pequeno Arnold sobre seu “amigo”.",
  [1130369089039616] = "Daly, você...",
  [1130369089039360] = "Pequeno Daly...",
  [1130369089039104] = "Eu sei, é claro. Não se preocupe. Não muito depois, conheci o Capitão Cara e você... Se ao menos pudesse ter sido antes.",
  [1130369089038848] = "Você sabe, eu não sou bom nisso...",
  [1130369089038592] = "Hehe, você realmente não sabe como confortar as pessoas. Um verdadeiro cavalheiro deveria me tomar em seus braços agora e dizer algumas palavras doces.",
  [1130369089038336] = "Você não é um monstro. Você é um verdadeiro gênio, uma pessoa muito boa e gentil.",
  [1130369089038080] = "Gostava do frio e da sensação de estar perto de cadáveres, sempre vagando pelos cemitérios e dormindo em frente aos túmulos. Naquela época, eles me temiam, tinham nojo de mim...",
  [1130369089037824] = "Eu também fui chamado de aberração uma vez, depois que perdi minha família e acidentalmente consumi uma poção para me tornar um Colecionador de Cadáveres.",
  [1130369089037568] = "Você também estava...",
  [1130369089037312] = "Lembrei-me de algumas coisas do passado. Heh, este mundo não é amigável para órfãos.",
  [1130369089037056] = "Desculpe, eu estava distraído.",
  [1130369089036288] = "Yodora pode ouvir sussurros estranhos; ela pode ser uma Beyonder nata, mas que tipo de habilidade é esse som estranho de flauta...",
  [1130369089035776] = "Eu realmente ouvi, os arredores estavam cheios de sons estranhos. Alguém me salve, por favor me salve... Professor... todos foram para casa, onde é minha casa?",
  [1130369089035264] = "Ela é uma louca que muitas vezes murmura coisas assustadoras pelos cantos e grita sem motivo. Mesmo a oração da Deusa da Noite Eterna não consegue mantê-la quieta nem por dez minutos.",
  [1130369089035008] = "Mas Yodora é uma criança seduzida por um demônio, além de ser salva. Ou melhor, ela é um monstro em pele humana, que não merece piedade.",
  [1130369089034752] = "Oficial, nosso asilo sempre insistiu em tratar todos os órfãos pobres de maneira igual e gentil até os 12 anos de idade.",
  [1130369089034496] = "Yodora... Oh, aquela criança má.",
  [1130369089034240] = "Somos policiais. Uma vez uma órfã chamada Yodora ficou aqui, certo?",
  [1130369089033984] = "Com licença, o que vocês dois estão fazendo aqui?",
  [1130369089033728] = "Uma flauta? Que flauta? Nunca vi Yodora tocar flauta.",
  [1130369089033472] = "Que idade? Deixa eu pensar... uns 12 anos, mas ela é muito magra, talvez seja mais velha mesmo.",
  [1130369089033216] = "Mas ela não aparece há alguns dias. Aconteceu alguma coisa?",
  [1130369089032960] = "Não diga que não tenho coração. Nesta era terrível, não é fácil para nós sobrevivermos, então como podemos ter coragem de ter pena dos outros?",
  [1130369089032704] = "Ela é como um gato de rua, sujo e perigoso. Quem sabe quando ela apodrecerá nos esgotos.",
  [1130369089032448] = "Oficial, ela é uma louca, uma órfã. Honestamente, vivendo como ela, seria melhor morrer rapidamente.",
  [813709740519424] = "Deixe-me dizer, definitivamente há algo estranho nele. Desde que ele chegou ao Distrito Leste, tem havido constantes incidentes sangrentos lá – nenhum corpo, apenas poças de sangue.",
  [1130369089031936] = "Oh, com licença, o que você está investigando? Eu sei tudo o que acontece na Rua Cruz de Ferro!",
  [1130369089031680] = "Ahem, somos policiais, estamos aqui para investigar um caso. Por favor, coopere.",
  [1130369089031424] = "Hehe, parecemos uma combinação perfeita, não é?",
  [1130369089031168] = "Ei, senhor, quer comprar um buquê de flores? Combina perfeitamente com sua linda esposa.",
  [1130369089030912] = "De acordo com a investigação, Yodora costuma passear pela Tingen Poorhouse e pela Iron Cross Street. Talvez você possa encontrar mais pistas lá.",
  [1130369089030656] = "Órfão, hein...",
  [1130369089030400] = "Um órfão sem sobrenome, vagando pelas favelas de Tingen.",
  [1130369089030144] = "...Não há muita informação, eles já deram o seu melhor.",
  [1130298758778880] = "Obsessão?",
  [813709740220672] = "Com licença... você é da barraca de carne...",
  [1130369089028096] = "Todos eles têm, até certo ponto, pensamentos de querer fugir das suas famílias.",
  [1130369089027840] = "Essas crianças têm uma coisa em comum...",
  [1130369089027584] = "Oficial, você deve ajudar a família Aine.",
  [1130369089027328] = "Antes do desaparecimento da pequena Aine, eu os ouvia discutir todos os dias em casa, era muito acirrado. Talvez seja por causa disso... suspiro...",
  [1130369089027072] = "Mas, sério, honestamente, o casal Aine é muito rígido com a pequena Aine. Uma criança nesta idade deveria apenas brincar alegremente.",
  [1130369089026816] = "Suspiro... a pequena Aine é fofa e inteligente, muito mais comportada que aquela minha filha. Suas notas na escola são as melhores todos os anos.",
  [1130369089026304] = "Quem é você e o que está fazendo aqui?",
  [1130369089026048] = "Parece que não há ninguém em casa...",
  [1130369089025792] = "Que homem mal-humorado. A seguir, devemos...",
  [1130369089025536] = "Vocês, ladrões de impostos! Eu já respondi isso, por que você está perguntando de novo!",
  [1130369089025280] = "Desculpe senhor, ainda estamos investigando e precisamos de sua cooperação.",
  [1130369089025024] = "Oficial, oficial! Como está meu filho? Quando ele volta para casa?",
  [1130369089024768] = "Iodora? Tudo bem, aqui estão os arquivos das crianças desaparecidas; talvez eles sejam úteis para você.",
  [1130369089024512] = "Por favor, investigue uma pessoa chamada Yodora; pode estar relacionado ao caso.",
  [1130369089024256] = "O culpado é muito astuto. Além do estranho som da flauta, eles não deixaram nenhuma pista.",
  [1130369089024000] = "Há alguma novidade na delegacia?",
  [1130369089023744] = "Sr. Dunn, recebemos notícias de que o caso de sequestro de criança foi transferido para um incidente Beyonder. Cooperaremos com todas as suas ações aqui.",
  [1130369089023488] = "Eu entendo. Afinal, você até esqueceria meu aniversário. Se você pudesse se lembrar do seu aniversário, todos precisaríamos estar em alerta máximo.",
  [1130369089023232] = "Você recebeu um convite? Na verdade, eu até esqueci disso; era o Velho Neil e os outros...",
  [1130369089022720] = "E... talvez ainda possamos ir à sua festa de aniversário hoje à noite.",
  [1130369089022464] = "Investigar juntos será mais rápido. Afinal, as crianças não podem esperar muito.",
  [1130369089022208] = "Você quer investigar comigo? E o seu missão ?",
  [1130369089021952] = "Vamos partir agora. Você tem alguma outra pista sobre o caso de sequestro?",
  [1130369089021440] = "Se precisar de mim, me chupe com força.",
  [1130369089021184] = "Essas crianças desaparecidas e meu pequeno Arnold, vou deixá-los com você. Afinal, no meu estado atual, não pareço ser capaz de fazer muita coisa.",
  [1130369089020928] = "Mas, por enquanto, você deve ter coisas mais importantes para fazer.",
  [1130369089020672] = "Capitã Cara, se quiser falar com Dunn, posso tentar alguns métodos. Por exemplo... deixá-lo perceber sua consciência?",
  [1130369089020416] = "Espere um momento.",
  [1130369089020160] = "<P_Heart> (Tão barulhento...) </>",
  [1130369089019904] = "Aqueles traficantes de seres humanos – bip – se eu ainda estivesse vivo – bip –",
  [1130369089019648] = "Contanto que peguemos aquele cara escondido nas sombras o mais rápido possível, não haverá nada com que nos preocupar.",
  [1130369089019392] = "Eles estão de olho em Arnold, o que me deixa um pouco preocupado.",
  [1130369089019136] = "Ainda não tenho certeza...",
  [1130369089018880] = "Sim, você tem alguma pista?",
  [1130369089018624] = "Você mencionou anteriormente que em seu sonho viu bandos de pássaros voando e cantando músicas estranhas?",
  [1130369089018368] = "Uau, pequeno Daly, seus comentários estão se tornando cada vez mais... individualistas.",
  [1130369089018112] = "Seguidores do Verdadeiro Criador? Esses loucos são capazes de tudo. Hmph, eles realmente deveriam ser jogados em uma tumba e ter todos os poros cheios de carne podre.",
  [1130369089017856] = "Já encontrei esse tipo de aura caída e corrompida antes, no sonho de Haines Vincent. E de acordo com a nossa investigação, o seu sonho apontava para um deus maligno – o Verdadeiro Criador.",
  [1130369089017600] = "Não é tão simples. Senti o cheiro de corrupção em meu sonho.",
  [1130369089017344] = "...Então você suspeita que o “amigo” de Arnold – Yodora – é o culpado por trás do caso de sequestro de criança?",
  [1130369089017088] = "É assim...",
  [1130369089016832] = "Pensando bem, o que você está fazendo aqui?",
  [1130369089016576] = "Dunn não consegue ouvir minha voz? Isso é uma pena.",
  [1130369089016320] = "Por enquanto não, também não tenho nenhuma pista.",
  [1130369089016064] = "Então foi um missão... Precisa de ajuda?",
  [1130369089015808] = "Atualmente estou em missão e precisei vir para Tingen.",
  [1130369089015552] = "Pequeno Dunn————!",
  [1130369089015296] = "Aqui tão cedo? Parece que aqueles caras da Diocese de Backlund não são tão rígidos, afinal.",
  [1130369089015040] = "Eu entendo...",
  [1130369089014784] = "Hehe, pequeno Daly, algumas coisas precisam ser ditas o mais rápido possível.",
  [1130369089014528] = "Essa é uma desculpa que você inventou na hora? Se esta é a razão pela qual você não se dissipou, então, por favor, descanse em paz, Capitão Cara.",
  [1130369089014272] = "Que tal ir a um encontro primeiro? Posso ver seu casamento antes que minha obsessão se dissipe?",
  [1130369089014016] = "De repente me lembrei! Minha obsessão é ver todos alcançarem a verdadeira felicidade, por exemplo, você e Dunn felizes juntos.",
  [1130369089013760] = "...Isso não é algo que precisa ser negado.",
  [1130369089013504] = "Pensando bem, desde o momento em que você entrou para a equipe, vocês dois eram muito próximos e mencionaram Dunn com tanta frequência que não pude deixar de querer...",
  [1130369089013248] = "Não é? Ele parece muito mais maduro...",
  [1130369089012992] = "Daly, por que você está aqui?",
  [1130369089012736] = "Parece inofensivo. Que artefato selado gentil; como esperado de mim.",
  [1130369089012480] = "Nem mesmo um médium espírita consegue isolar completamente essa influência?",
  [1130369089012224] = "Lembro-me que o efeito colateral do Nightingale Silver Whistle é fazer com que o portador se sinta cansado e é particularmente atraente para os pássaros.",
  [1130369089011968] = "O pássaro pousou...",
  [1130369089011712] = "Você parece muito despreocupado, nada parecido com um espírito persistente.",
  [1139165182672384] = "Empate.",
  [1130369089011200] = "Também somos pobres coitados, vendo nossos companheiros de equipe se sacrificarem até que finalmente caminhemos para a escuridão.",
  [1139165182393856] = "Tudo bem.",
  [1130369089010688] = "Nos últimos cinco anos, Beyonder os incidentes tornaram-se mais frequentes, mas graças a todos, os cidadãos de Tingen ainda podem dormir tranquilamente todas as noites.",
  [1130369089010432] = "Hehe, você vai gostar deles.",
  [1130369089010176] = "Todos parecem boas pessoas. Eu realmente quero conhecê-los...",
  [1130369089009920] = "E Klein, que recentemente se juntou ao time Vigias Noturnos. Sua aparência tímida e ingênua é cativante, mas ele está sempre se envolvendo em Beyonder incidentes. Ele é um garotinho azarado.",
  [1130369089009664] = "Por exemplo, Leonard, um Poeta da Meia-Noite que não age como um poeta. Suas habilidades poéticas são ainda piores que as de Dunn, o que faz com que nos preocupemos sobre como ele avançará de Poeta da Meia-Noite.",
  [1130369089009408] = "Muitas pessoas nos deixaram e muitas se juntaram.",
  [1130369089009152] = "...Eu entendo, a taxa de mortalidade de Vigias Noturnos sempre foi muito alta.",
  [1130369089008896] = "Dawn... Dawn também se sacrificou. Enterramos ela no Cemitério Rafael, bem perto de você, em um lugar onde o sol pode brilhar.",
  [1130369089008640] = "Sua filha, Rozanne, agora é funcionária civil da Blackthorn Security Company. Hehe, ela é uma garota que fala muito; tanto Dunn quanto eu ficamos com um pouco de dor de cabeça por causa dela.",
  [1130369089008384] = "Adelaide se sacrificou durante um missão , logo depois que você morreu.",
  [1130369089008128] = "Acho que esse pode não ser um assunto que vai te deixar feliz.",
  [1130369089007872] = "Estou com saudades daqueles velhinhos... Como está Adelaide? Esse cara ainda é tão barulhento quando ri?",
  [1130369089007616] = "...Ainda não consigo me lembrar.",
  [1130369089007360] = "Há algum outro lugar que você queira ir? Foi você quem lutou tanto para retornar a Tingen.",
  [1130369089007104] = "De repente, sinto como se minha alma tivesse sido esvaziada pelo trabalho...",
  [1130369089006848] = "Local de trabalho número um e local de trabalho número dois. Mesmo na morte, não se pode escapar ao destino de ser um escravo assalariado.",
  [1130369089006592] = "Lugares que o capitão conhecia... Blackthorn Security Company ou Catedral de Santa Selena?",
  [1130369089006336] = "Obrigado pela sua gentileza, mas isso não será necessário.",
  [1130369089006080] = "Se você não se importa, posso enfiar uma torta quente para você embrulhar em sua comida favorita.",
  [1130369089005824] = "Ugh, droga!",
  [1130369089005568] = "Embora não seja um pedido excessivo, com o que você vai comê-lo agora?",
  [1130369089005312] = "Coisas que sinto falta... Quero comer uma torta Deisi, quero muito.",
  [1130369089005056] = "Para onde devemos ir primeiro... Há alguma coisa que você sente falta em particular?",
  [1130369089004800] = "Então ele vai entender... eu acredito que ele vai entender.",
  [1130369089004544] = "Sim, 27 pessoas.",
  [1130369089004288] = "Na minha final missão , se eu fosse o único que se sacrificou... salvamos 27 pessoas.",
  [1130369089004032] = "Ele tinha apenas 7 anos quando você se sacrificou. Essa confiança não é muito pesada?",
  [1130369089003776] = "Além disso, meu pequeno Arnold é muito parecido comigo. Eu acredito nele.",
  [1130369089003520] = "Muitas vezes acomodei as famílias dos meus colegas. A Igreja da Deusa da Noite Eterna fará o máximo para tratar bem nossas famílias.",
  [1130369089003264] = "Eu sei que ele vai ficar bem, em alguns aspectos...",
  [1130369089003008] = "Pelo que entendi, ele está indo muito bem.",
  [1130369089002752] = "...Como tem estado o pequeno Arnold nos últimos anos?",
  [1130369089002496] = "Ninguém em casa? Que pena.",
  [1130369089002240] = "Pequeno Arnold, meu pequeno Arnold...",
  [1130369089001984] = "Talvez devêssemos visitar o pequeno Arnold primeiro?",
  [1130369089001728] = "Então, você, sem dormir, não consegue nem escapar da sua terrível memória após a morte?",
  [1130369089001472] = "Hmm, não me lembro direito...",
  [1130369089001216] = "Voltando ao ponto principal, o que você precisa que eu faça por você? Quanto à sua obsessão, o Capitão tem alguma outra pista?",
  [1130369089000960] = "Hehe, acho que o jeito que você está agora só vai fazer com que ele se sinta mais culpado e o deixe com novos traumas psicológicos.",
  [1130369089000704] = "Que cara estranho, deixe-me ir e dar-lhe uma boa lição!",
  [1130369089000448] = "Eu disse a Dunn a mesma coisa, mas ele parece não ouvir.",
  [1130369089000192] = "Deixar o esquadrão Vigias Noturnos para Dunn é muito mais reconfortante para mim do que deixá-lo para algum velho enviado pela Igreja.",
  [1130369088999936] = "Como ele pôde pensar isso?",
  [1130369088999680] = "Mas ele sempre acreditou que foi por causa do seu sacrifício, e pelo fato de termos descoberto a Lei da Característica de Beyonder Indestrutibilidade a partir da sua morte, que chamou a atenção da Santa Catedral, que ele conseguiu se tornar esse Capitão.",
  [1130369088999424] = "Sim, ele sempre foi.",
  [1130369088999168] = "Ele é confiável e meticuloso; ele será um bom capitão. É muito difícil para ele!",
  [1130369088998912] = "Então Dunn assumiu essa bagunça de capitania, então posso ficar tranquilo!",
  [1130369088998656] = "Preciso fazer melhor, ser mais estável... para poder substituir Cara e fazer tão bem quanto ela.",
  [1130369088998400] = "Você nunca fez nada de errado; você sempre se saiu bem.",
  [1130369088998144] = "Suspiro, você não precisa assumir a responsabilidade por Arnold ou Cara... Essa sua personalidade estranha, quando exatamente você vai mudar isso?",
  [1130369088997888] = "...Eu não percebi, realmente não lidei direito.",
  [1130369088997632] = "Será porque o pequeno Arnold esteve envolvido neste incidente?",
  [1130369088997376] = "Relaxar. Você parece muito ansioso, e a ansiedade muitas vezes piora as coisas.",
  [1130369088997120] = "Acho que posso lidar com esse assunto sozinho.",
  [1130369088996864] = "Eu conheci isso Beyonder . A aura deles é sinistra e estranha, mas seu Sequência não parece alto - provavelmente em torno de Sequência 9 ou 8.",
  [1130369088996608] = "Você precisa da ajuda de outras pessoas?",
  [1130369088996352] = "Suspeito que este caso de rapto de criança esteja relacionado a Beyonder e estou me preparando para investigar.",
  [1130369088996096] = "Eh? Capitão? Velho Neil? Eu realmente não sou bom em cuidar de crianças...",
  [1130369088995840] = "Tudo bem, vou deixar esse pequeno para o pequeno Klein.",
  [1130369088995584] = "Velho Neil, por favor, venha aqui por um momento.",
  [1130369088995328] = "Está tudo bem, descanse bem.",
  [1130369088995072] = "...Não há como continuar questionando.",
  [1130369088994816] = "Minha cabeça dói tanto... wuwuwu...",
  [1130369088994560] = "Arnold, isso é muito importante. Você deve tentar o seu melhor para lembrar.",
  [1130369088994304] = "Hum, minha cabeça dói tanto...",
  [1130369088994048] = "Yodora é minha amiga... Estranho, como nos conhecemos?",
  [1130369088993792] = "Dunn, seu tom é muito parecido com um interrogatório.",
  [1130369088993536] = "Yodora é sua amiga? Quem é ela? Como vocês se conheceram?",
  [1130369088993280] = "Eles foram assustados pelo tio Dunn?",
  [1130369088993024] = "Lindos pássaros virão me cantar lindas canções e me acordar... Eu tinha um compromisso hoje para apresentar Yodora a eles, mas os pássaros não vieram.",
  [1130369088992768] = "Os pássaros não vieram hoje...",
  [1130369088992512] = "A aura perigosa do sonho não era poderosa, mas era um tanto estranha.",
  [1130369088992256] = "Este caso de rapto de crianças pode não ser tão simples.",
  [1130369088992000] = "Falando nisso, no sonho de agora, parece que ouvi um som estranho também...",
  [1130369088991744] = "As pessoas próximas ao local do desaparecimento parecem ter ouvido uma melodia estranha, semelhante a uma flauta.",
  [1130369088991488] = "...Não há muitas pistas úteis, apenas uma coisa a observar.",
  [1130369088991232] = "Eh? Capitão? Não sou bom em cuidar de crianças...",
  [1130369088990976] = "Vou deixar Arnold com você. Preciso investigar o caso o mais rápido possível.",
  [1130369088990720] = "Ela se sacrificou durante um missão , assim como o pai de Arnold, e como muitos outros Vigias Noturnos .",
  [1130369088990464] = "Lembre-se do nome dela - Carol Bishop, uma grande Vigia Noturno capitã.",
  [1130369088990208] = "Também foi um Vigia Noturno uma vez? Você quer dizer...",
  [1130369088989952] = "A mãe de Arnold também foi Vigia Noturno uma vez. Ele está muito familiarizado com este lugar, então não fique nervoso.",
  [1130369088989696] = "Olá, pequenino.",
  [1130369088989440] = "Olá, tio estranho!",
  [1130369088989184] = "Já foi entregue no escritório.",
  [1130369088988928] = "Preciso investigar este caso agora. Para onde fica o boletim de ocorrência enviado pela delegacia?",
  [1130369088988672] = "Este é Arnaldo Bishop. Ele pode ter estado envolvido nos recentes casos de rapto de crianças.",
  [1130369088988416] = "Huh, quem é essa criança?",
  [1130369088988160] = "O Capitão está de volta, mas ainda não terminamos de montar a empresa...",
  [1130369088987904] = "Sim, não se preocupe. Descanse bem.",
  [1130369088987648] = "Empresa de segurança Blackthorn? O lugar onde mamãe trabalhava...",
  [1130369088987392] = "Você precisa descansar agora. Vou levá-lo de volta para Blackthorn primeiro.",
  [1130369088987136] = "Você foi afetado pela destruição do sonho? Eu fui muito imprudente agora...",
  [1130369088986880] = "Minha cabeça... dói...",
  [1130369088986624] = "Meu amigo... nós...",
  [1130369088986368] = "Você parece ter um novo amigo interessante. O que vocês dois estavam fazendo agora?",
  [1130369088986112] = "Agora mesmo...? Para onde Yodora foi?",
  [1130369088985856] = "Hum... Tio Dunn?",
  [1130369088985600] = "Pássaros estranhos, o que estão fazendo aqui reunidos?",
  [1130369088985344] = "Considere-o um presente de saudação para este novo amigo, embora seja um pouco incomum.",
  [1130369088985088] = "Algo não está certo. Não os alerte ainda.",
  [1130369088984832] = "Espere, minha inspiração está me avisando que há perigo aqui... é muito estranho.",
  [1130369088984576] = "<P_Heart> (A inspiração se agita) </>",
  [1130369088984320] = "Pesquisar separadamente pode ser mais rápido. Desculpe incomodá-lo.",
  [1130369088984064] = "Nossa, isso é realmente assustador... Ele saiu há pouco tempo, menos de dez minutos. Eu irei com você procurá-lo.",
  [1130369088983808] = "Vou dar uma olhada nas proximidades.",
  [1130369088983552] = "Não há necessidade. Houve recentemente vários casos de rapto de crianças em Tingen. Tente não deixar Arnold sair sozinho hoje em dia.",
  [1130369088983296] = "Talvez você possa entrar e tomar uma xícara de chá. Ele deveria estar em casa logo.",
  [1130369088983040] = "Ele disse que estava com amigos. Ah, você sabe como é: os meninos dessa idade sempre têm segredinhos que não querem que os adultos saibam.",
  [1130369088982784] = "Ele disse para onde estava indo?",
  [1130369088982528] = "Mas é realmente lamentável hoje; ele acabou de sair.",
  [1130369088982272] = "Além do mais, a Igreja da Noite Eterna nos dá uma grande quantia em dinheiro para sua educação todos os meses. Honestamente, todos nós achamos que é um pouco demais criar um filho...",
  [1130369088982016] = "Por favor, não diga isso. Arnold é sensato e inteligente. Há muito que o tratamos como nosso próprio filho para criar.",
  [1130369088981760] = "Sim, o garotinho está bem? Obrigado por cuidar dele todo esse tempo.",
  [1130369088981504] = "Sr. Dunn, você está aqui para visitar Arnold?",
  [1130369088981248] = "Ok, obrigado pela sua preocupação. Vou considerar isso.",
  [519177257361921] = "Feliz aniversário!",
  [1130369088980992] = "Então é assim. Mas você já... bem, quero dizer, você deveria ter considerado casamento e família há muito tempo. Embora o trabalho policial seja intenso e perigoso, há muitas garotas que gostariam de um cavalheiro gentil e confiável como você.",
  [1130369088980736] = "Não, não, é um presente que pretendo dar a um amigo.",
  [519177257485313] = "Outro lote de mercadorias chegou ao cais; quanto tempo mais tenho que trabalhar hoje antes de poder sair do trabalho?",
  [1130369088980480] = "O filho do Sr. Dunn gosta deste bolo? Mas eu lembro que você ainda está solteiro?",
  [519177257526785] = "Isso é terrível. Devo manter as crianças longe daqui.",
  [1130369088980224] = "Sim, é isso. Por favor, me dê um.",
  [1130369088979968] = "Acho que você quer dizer bolo de limão. Todas as crianças gostam deste tipo de bolo.",
  [519177257630209] = "Senhora, por favor espere um pouco mais.",
  [1130369088979712] = "Você vende algum, uh... pão que as crianças gostariam?",
  [519177257723393] = "Sinto muita falta dos dias em que era estagiário no Backlund Bank.",
  [1130369088979456] = "Não se preocupe, este é o nosso dever.",
  [1130369088979200] = "Hehe, você ainda é tão gentil como sempre. Espero que o caso anterior não tenha causado muitos problemas.",
  [1130369088978944] = "Parece que você está de bom humor, Sra. Slin.",
  [1130369088978688] = "Sr. Dunn, faz muito tempo que não nos vemos.",
  [1130369088978432] = "Certo, antes de partir, Lord Anthony me deu um 'Réquiem da Noite', dizendo que usar esta poção poderia despertar a consciência persistente da Capitã Carol.",
  [1130369088978176] = "Ainda não consigo me comunicar...",
  [1130369088977664] = "Capitão Carol?",
  [1130369088977408] = "Há outra caixa no canto. O que é aquilo?",
  [1130369088977152] = "É sobre isso...",
  [1130369088976128] = "Mesmo agora, Dunn sempre foi muito grato e... culpado por você.",
  [470936453122816] = "Espectador",
  [1130369088975872] = "...Naquela época, Dunn e eu estávamos muito tristes.",
  [1130369088975616] = "Ah, é claro que espero que todos Vigias Noturnos vivam vidas longas e saudáveis. Que a Deusa da Noite Eterna os proteja.",
  [1130369088975360] = "Já vi muitas mortes e continuarei lutando até morrer em alguma missão. Todo capitão Vigia Noturno não pode escapar de tal destino.",
  [1130369088975104] = "Você não parece sentir arrependimento ou dor por sua própria morte.",
  [1130369088974848] = "Nada mal, minha morte não foi em vão.",
  [1130369088974592] = "Está tudo bem, completamos essa missão com sucesso e salvamos muitas pessoas... você foi o único sacrifício.",
  [1130369088974336] = "Não tenho nenhuma impressão do dia em que morri. Tudo correu bem?",
  [1130369088974080] = "Meu Mensageiro Espiritual pode manter seu estado estável por um curto período de tempo. As pessoas comuns não podem ver você, mas você não deve se afastar muito de mim.",
  [1130369088973824] = "Muito bom, me sinto um pouco mais claro agora.",
  [1130369088973568] = "Por favor, tenha paciência por um momento.",
  [1130369088973312] = "Eu farei com que o Mensageiro Espiritual envolva o Artefato Selado 3-116. Pode isolar os efeitos do artefato e também permitir que você me siga livremente.",
  [1130369088973056] = "Que taxa de crescimento exagerada. Você é um verdadeiro gênio... Você já é muito mais forte do que eu era naquela época.",
  [1130369088972800] = "Sequência 6 \"Necromante\", mas ainda prefiro ser chamado de \"Médium Espiritual\".",
  [1130369088972544] = "Mensageiro do Mundo Espiritual? O que Sequência é o pequeno Daly agora?",
  [1130369088972288] = "Pequeno Daly, você continua tão gentil como sempre.",
  [1130369088972032] = "Mas antes disso, preciso usar alguns meios para isolar os efeitos negativos do Artefato Selado 3-116.",
  [1130369088971776] = "Capitã Carol, a Igreja da Noite Eterna me despachou com essa intenção em mente desde o início.",
  [1130369088971520] = "Ajude-me, pequeno Daly.",
  [1130369088971008] = "Mas sinto vagamente que não me resta muito tempo.",
  [1130369088970752] = "Não me lembro, hehe, minha mente está uma bagunça.",
  [1130369088970496] = "Posso te ajudar. O que é?",
  [1130369088970240] = "Lembro-me vagamente que há algo que devo fazer, então tenho que fazer. Caso contrário, não poderei descansar em paz nem na morte... Hmm, de certa forma, já sou incapaz de descansar em paz mesmo na morte.",
  [1130369088969984] = "Dormi muito tempo, mas esse traço de consciência não deveria existir apenas para dormir.",
  [1130369088969728] = "Ha, eu não quero.",
  [1130369088969472] = "E seu estado não é estável. Preciso levá-lo de volta à Igreja Backlund o mais rápido possível para ser selado novamente.",
  [1130369088969216] = "Embora o Nightingale Silver Whistle seja basicamente inofensivo, ele ainda terá um impacto no ambiente.",
  [1130369088968960] = "Mas você está aqui para me recuperar, para recuperar este Artefato Selado, certo?",
  [1130369088968704] = "Embora meu cérebro de pássaro não seja muito flexível agora, e até mesmo minhas memórias estejam fragmentadas e dispersas...",
  [1130369088968448] = "Sua compreensão e aceitação são excelentes como sempre.",
  [1130369088968192] = "Eu entendo. Na verdade, já estou morto. O eu atual é apenas um fio de consciência obsessiva, um corpo espiritual quebrado.",
  [1130369088967424] = "Capitão, acalme-se...",
  [1130369088967168] = "Ah?! E o que eu sou?!",
  [1130369088966912] = "24? O que aconteceu com aquela pequena Daly, jovem, bonita e inocente de 19 anos?",
  [1130369088966656] = "...Capitão, tenho apenas 24 anos, longe de ser chamado de velho.",
  [1130369088966400] = "Huh? Pequeno Daly, por que você ficou tão velho de repente!",
  [1130369088966144] = "Sinto que tive um sonho muito, muito longo...",
  [1130369088965888] = "Heh, Capitã Carol, você realmente dormiu muito tempo.",
  [1130369088965632] = "...Pequeno Daly, é Daly?",
  [1130369088965376] = "Esta poção é realmente eficaz? Talvez eu precise preparar alguma ração para pássaros para cobrir a distância primeiro...",
  [1130369088965120] = "...Chilro...",
  [1130369088964864] = "Como você está se sentindo? Você ainda se lembra de quem você é?",
  [1130369088964608] = "Não se preocupe, só quero levá-la para casa.",
  [1130369088964352] = "Não a machuque, não a assuste. O Rouxinol é um bom pássaro, o canto do Rouxinol é lindo!",
  [1130369088964096] = "Nas profundezas do mausoléu, acima do sino do cemitério, o rouxinol canta, o rouxinol vagueia.",
  [1130369088963840] = "Você está procurando o Rouxinol?",
  [1130369088963584] = "Que espírito barulhento... quero dizer, uma aura poderosa e incomum?",
  [1130369088963328] = "Estranho? Auras estranhas aparecem todos os dias. Isso é um cemitério, idiota, que humano estúpido!",
  [1130369088963072] = "Você sentiu alguma aura estranha por perto ultimamente?",
  [1130369088962816] = "Eh? Você pode me ver? Os humanos podem me ver?",
  [1130369088962560] = "Não tenha tanta pressa de fugir, ou talvez eu tenha que usar métodos menos gentis, heh.",
  [1130369088962304] = "Eek! Assustador, um humano tão assustador!",
  [1130369088962048] = "Desaparecido...",
  [1130369088961792] = "Com tanto sono... tão cansado... vou descansar...",
  [1130369088961536] = "Cantoria? Pensando bem, a Capitã Carro também era dos Sleepless Caminho e cantava bem.",
  [1130369088961280] = "...Cantando... linda cantando... Mãe...",
  [1130369088961024] = "Pequena, você tem visto algum estranho ultimamente?",
  [1130369088960768] = "Eu também não teria conhecido Dunn e os outros. Ufa... ainda é mais honesto e relaxante conversar com os mortos.",
  [1130369088960512] = "Se você não tivesse me arrastado rudemente para o esquadrão Tingen Vigias Noturnos, eu deveria estar dormindo no cemitério há muito tempo.",
  [1130369088960256] = "Durante todo esse tempo, fiquei muito grato pela sua ajuda... e pela sua salvação.",
  [1130369088960000] = "Há muito tempo que não nos vemos, Capitã Carol.",
  [1130369088959744] = "O último lugar onde o Artefato Selado 3-116 foi descoberto... é perto do Cemitério Raphael?",
  [1130369088959488] = "A festa é à noite, dá tempo. Independentemente disso, preciso completar a missão primeiro.",
  [1130369088959232] = "Parece que estou ausente há muito tempo... embora só tenha sido transferido para a Diocese de Backlund há pouco tempo.",
  [1130369088958976] = "Quanto ao presente de aniversário...",
  [1130369088958720] = "Depois que a missão terminar, dê uma olhada no caminho. Talvez eu possa até acompanhá-lo para um baile de abertura, hehe.",
  [1130369088958464] = "Ainda tendo tempo para fazer uma festa de aniversário; parece que eles devem estar bem.",
  [1130369088957952] = "Tingen, o lugar com o qual você está mais familiarizado.",
  [1130369088957696] = "Onde 3-116 foi visto pela última vez?",
  [1130369088957440] = "Tentamos muito, mas não conseguimos salvá-la, nem suportamos destruí-la. Vá e acompanhe-a em sua jornada final; ela merece dormir no Reino da Noite.",
  [1130369088957184] = "Você deveria ter me dito há muito tempo que os pensamentos persistentes do Capitão Carro permaneceram no Artefato Selado... Eu sou um \"Médium Espiritual\", talvez eu tenha um jeito.",
  [1130369088956928] = "A capitã Carol Bishop era uma grande e altruísta Vigia Noturno.",
  [1130369088956672] = "Afinal, 3-116 é a \"relíquia\" do ex-capitão do Tingen Vigias Noturnos, Carro Bishop. É a melhor escolha para mim, um membro da equipe que uma vez a seguiu, recuperá-la.",
  [1130369088956416] = "Heh, você sabe, isso é algo que só eu posso fazer.",
  [1130369088956160] = "Daly Simone, você está disposto a aceitar esta missão?",
  [1130369088955904] = "O desaparecido Artefato Selado 3-116, ele nunca demonstrou qualquer intenção de escapar por conta própria, por que de repente...",
  [1130369088955648] = "Saia e limpe sua cabeça; o tempo está bastante bom hoje. Ficarei de olho nesses pequeninos e não deixarei que explodam Blackthorn.",
  [1130369088955136] = "Ela agora pertence à Diocese de Backlund. Vigias Noturnos não pode deixar sua jurisdição à vontade; você deveria saber disso.",
  [1130369088954880] = "Tudo bem, tudo bem, eu sei quem é o seu convidado desejado. Claro, enviei um convite a ela, mas ainda não recebi resposta.",
  [1130369088954624] = "Em quem você espera? Esse bando de pirralhos barulhentos? Minha velha cara que você olha há mais de uma década, ou espera ver o Bispo da Catedral de Santa Selena na festa?",
  [1130369088954368] = "Uh... mais alguém vem a esta festa?",
  [1130369088954112] = "O que você esqueceu de novo, balançando por aqui e irritando as pessoas?",
  [1130369088953856] = "Arnold... <P_Yellow> Carol </> Filho do capitão, não vou esquecer disso.",
  [1130369088953600] = "O quê, você esqueceu o caminho para a casa do Arnold?",
  [1130369088953344] = "Se você realmente não consegue ficar parado, a delegacia acaba de enviar um relatório sobre os recentes casos de desaparecimento de crianças em Tingen. Você pode lembrar aos pais adotivos do pequeno Arnold que prestem atenção à segurança da criança.",
  [1130369088953088] = "Minha saúde está muito boa e não tenho problemas. Você, por outro lado, está agindo um pouco estranho hoje.",
  [1130369088952832] = "Hmm, Velho Neil... como está sua saúde? Você pode discutir quaisquer problemas comigo.",
  [1130369088952576] = "Por que você ainda não está indo embora? Ocasionalmente, você precisa aprender a relaxar.",
  [1130369088952320] = "<P_Heart> (Leonard Mitchell, um Sequência 8 \"Poeta da Meia-Noite\"... ele parece muito relaxado, terei que fazê-lo memorizar mais algumas coleções de poesia.) </>",
  [1130369088952064] = "Capitão? Fique tranquilo, não há missões urgentes hoje.",
  [1130369088951808] = "Obrigado, capitão.",
  [1130369088951552] = "Você não precisa desanimar. Um Sequência 7 Beyonder não é tão fácil de capturar e você já se saiu muito bem.",
  [1130369088951296] = "Mas sinto muito. Se eu tivesse percebido antes que adivinhação não é onipotente, talvez Trissy não tivesse escapado...",
  [1130369088951040] = "Estou bem, muito saudável! Não se preocupe, capitão.",
  [1130369088950784] = "Praticamente nada. Tudo tem corrido bem ultimamente?",
  [1130369088950528] = "Capitão, aconteceu alguma coisa?",
  [1130369088950272] = "<P_Heart> (Klein Moretti, nosso recém-ingressado \"Seer\", um novo membro inteligente da equipe.) </>",
  [1130369088950016] = "Que desmancha-prazeres. Como não há missões hoje, é melhor você sair e clarear a cabeça. Volte antes do jantar.",
  [1130369088949760] = "Hoje é meu aniversário? Não me lembrava, mas você não precisava fazer tudo isso.",
  [1130369088949248] = "Esses pequeninos estavam fazendo barulho por dar uma festa de aniversário para você. A propósito, também aposto que você esqueceria seu próprio aniversário. Obrigado por cooperar. Vamos, Klein, dez centavos.",
  [1130369088948992] = "Não, não é um problema com o adivinhação ; é que superestimei a memória do Capitão...",
  [1130369088948736] = "Ganhei a aposta, dez centavos. Até mesmo o Sr. Seer tem momentos em que seu adivinhação falha.",
  [1130369088948480] = "Por que vocês estão todos reunidos no corredor?",
  [1130369088948224] = "<P_Heart> (Parece que esqueci algo de novo...) </>",
  [818107786477056] = "Molly, vamos pensar de novo...",
  [1130369088947968] = "<P_Heart> (Eu sou... Dunn Smith, capitão do time Tingen Vigias Noturnos.) </>",
  [1130369088947712] = "Por que você está se distanciando? Então você realmente esqueceu que dia é hoje, não foi?",
  [1130369088947456] = "Capitão, há algo errado... seus olhos são assustadores.",
  [1130369088947200] = "Capitão, sinto muito por acordá-lo... Devíamos ter sido mais cuidadosos.",
  [1130369088946688] = "Heh, esses dois se dão muito bem. É bom ser jovem, não é, Dunn?",
  [1130369088946432] = "Não tão esperto, Sr. Vidente, esta prateleira está claramente mais perto de mim. Se não fosse você bloqueando o caminho...",
  [1130369088946176] = "Se Leonard não tivesse se lançado repentinamente, eu teria tido tempo de firmar a prateleira e certamente não teria acordado o capitão.",
  [1130369088945920] = "Ei! Você acordou o capitão! Deveríamos fazer uma surpresa para ele!",
  [1130504917095168] = "Leonard também tirou a luva vermelha e entoou um poema de sono para o falecido - \n 'Ele recebeu um convite da noite escura e desde então encontrou o sono eterno.'\n",
  [1130504917093120] = "Após o término do recital, todos saíram um após o outro. Potter parecia ainda estar gostando e permaneceu onde estava.",
  [1130369088945152] = "Ufa, que sono... O que está acontecendo?",
  [1169958755263233] = "No dia seguinte...",
  [1130369088944640] = "Concedo-lhe autoridade para entrar neste pedaço da história. Por favor, ajude-me a testemunhar a história deles através de seus próprios olhos.",
  [1130369088944384] = "Eles já foram meus guias e serão seus também...",
  [1130369088944128] = "...Esse pequenino, eu lembro, ainda lembro, lembro deles...",
  [1130369088943872] = "Ah... então é assim...",
  [1130369088943616] = "Esta lacuna na história... por que foi iluminada? Eu nunca...",
  [1130369088943360] = "O que é aquilo?! O que aconteceu?",
  [1130369088943104] = "Às vezes sinto falta deles... sinto muita falta deles...",
  [1130369088942848] = "Não me olhe assim. Não se preocupe, estou bem, estou muito bem. Devíamos ter nos acostumado a nos separar há muito tempo.",
  [1130369088942592] = "Muitas pessoas nesta foto já se sacrificaram. Encontramos esta foto por acaso, e isso já é uma sorte.",
  [1130369088942336] = "Quão lamentável é o cavalheiro com a cabeça queimada; talvez você possa pegar um novo.",
  [1130369088942080] = "Por que pendurar uma foto queimada em um lugar tão visível?",
  [1130369088941824] = "Talvez, da próxima vez que eu visitar o Capitão Dunn e os outros no Cemitério Raphael, eu me lembre de trazer esses grãos de café para ele.",
  [1130369088941568] = "Ah, por favor, deixe-os aí por enquanto...",
  [1130369088941312] = "Mas olhando a data da embalagem, esses grãos de café já estão vencidos há muito tempo... como devemos manuseá-los?",
  [1130369088941056] = "Porém, Sleepless precisa mesmo tomar café?",
  [1130369088940800] = "Mais tarde percebi que não havia nada a temer; ele estava apenas cuidando de nós à sua maneira.",
  [1130369088940544] = "Sim, ele era muito gentil, parecia um pai para mim, mas não sei por que, eu tinha um pouco de medo dele.",
  [1130369088940288] = "Capitão Dunn... já ouvi falar dele, um homem muito confiável.",
  [1130369088940032] = "Ele deixou muitos grãos de café, considerados de muito boa qualidade, mas ninguém está disposto a beber todos.",
  [1130369088939776] = "Esses são do Capitão Dunn. Talvez você já tenha ouvido falar dele; ele era um homem muito bom.",
  [1130369088939520] = "Tem muitos grãos de café no armário, não sei se ainda são bebíveis... têm um cheiro estranho.",
  [1130369088939264] = "E esse baralho já é usado há muitos anos, acho que eles estão mais acostumados com esses “velhos amigos”.",
  [1130369088939008] = "Aqueles Vigias Noturnos que não precisam dormir costumam jogar cartas a noite toda; mesmo as placas de aço não suportavam esse tipo de uso.",
  [1130369088938752] = "Talvez você devesse comprar um novo baralho, pois os naipes dessas cartas já são difíceis de ver.",
  [1130369088938496] = "Luo Yao e os outros trouxeram as cartas do Combatente ao Mal da sala de recreação novamente!",
  [1130369088938240] = "Cartas de baralho desgastadas, já um pouco antigas.",
  [1130369088937984] = "{{PlayerName}}, você é uma pessoa realmente boa! Não se preocupe, você receberá uma recompensa, apenas considere isso uma comissão!",
  [1130369088937728] = "Uh, tudo bem. O Sr. Leonard e o Capitão Frye me ajudaram, então eu ajudarei.",
  [813709740220416] = "Oi... <P_Heart> (Bêbado) </>",
  [813709740519168] = "Eles costumavam ser, mas recentemente alguém chamado <P_Yellow> Caleb </> veio ao Distrito Leste e roubou a outra metade.",
  [1130298758778624] = "Esquecer?",
  [1130369088793600] = "Você não teve um bom desempenho agora, por favor, execute novamente",
  [1130369088793344] = "Você tem boas habilidades, jovem",
  [1130369088793088] = "Nós investigamos e descobrimos que um criminoso pode estar escondido aqui",
  [1130369088792832] = "De jeito nenhum, é só que meus amigos me dão cara",
  [1130369088792576] = "Ouvi dizer que você está indo bem aqui?",
  [1130369088792320] = "Bem-vindo ao meu território!",
  [1130369088792064] = "Vou me despedir de Jenny.",
  [1130369088791808] = "Sr.",
  [1130369088791552] = "Gentil {{Sr.|Sra.}}, obrigado por ouvir minhas divagações. Saber que ainda existe alguém neste mundo que se lembra de Jenny é o suficiente para me confortar.",
  [1130369088791296] = "A pequena e sensata Jenny deve ter ficado com medo de que eu ficasse triste se a visse, então ela arrastou seu corpo fraco para tão longe...",
  [48586280666624] = "Deixar",
  [1130369088791040] = "Mas quando acordei ontem de manhã, Jenny havia sumido. Quando a encontrei, ela já estava...",
  [1130369088790784] = "Lucas me disse que o asilo distribuiria comida de graça em poucos dias e nos daria moradia. Incentivei Jenny a aguentar mais alguns dias.",
  [1130369088790528] = "Pobre Jenny, agarrando esta caixa de fósforos todos os dias. Mas a fábrica está com os salários atrasados ​​há tanto tempo que mal conseguimos encher o estômago e muito menos comprar fósforos...",
  [1130369088790272] = "Este é o último contracheque dela, contém as palavras que ela deixou para mim e para a pequena Jenny. Você pode abri-lo e olhar – se quiser.",
  [1130369088790016] = "É uma pena que a mãe dela tivesse doença pulmonar. Esvaziamos a fortuna de nossa família para tratamento, mas ainda não conseguimos curá-la, suspiro...",
  [1130369088789760] = "Sim, {{Sr.|Sra.}}, veja bem, esta é a caixa de fósforos que sua mãe deu a ela. Originalmente, sua mãe usava esta caixa de fósforos para guardar seus recibos de pagamento.",
  [1130369088789504] = "Sr. Lawis, eu quero saber, os jogos são muito especiais para Jenny?",
  [1130369088789248] = "Oh, graças a Deus há alguém no mundo que se lembra dela.",
  [1130369088788992] = "Sim, eu tinha algum conhecimento com ela.",
  [1130369088788736] = "<P_Heart> (Surpreso) </> Isso mesmo, Jenny... essa {{Sr.|Sra.}}, você conhece a pequena Jenny?",
  [1130369088788480] = "Olá, você é o Sr. Lawis? Você tem uma filha chamada Jenny?",
  [1130369088788224] = "Desculpe incomodá-lo, vou dar uma olhada lá.",
  [1130369088787968] = "Pobre Lawis, seu cabelo ficou branco durante a noite. Não sei por quanto tempo ele aguentará nesse estado...",
  [1130369088787712] = "O maldito gerente da fábrica está retendo salários há um mês. Sua esposa morreu de doença há pouco tempo, e sua filha morreu de fome porque eles não tinham dinheiro para comer.",
  [1130369088787200] = "Você pegou a pessoa errada, Lawis é aquele homem ali; ele tem estado muito triste ultimamente.",
  [1130369088786944] = "Olá, você é o Sr. Lawis?",
  [1130369088786688] = "Eles não viram Jenny?!",
  [1130369088786432] = "Falando sozinhos...?",
  [1130369088786176] = "Essa pessoa é tão estranha, por que ela está falando sozinha ali desde agora?",
  [1130369088785664] = "Uma garotinha tão lamentável, ela é tão magra quanto um talo de palha prestes a ser quebrado pelo vento.",
  [1130369088785408] = "Gentil senhora, você pode me dar um fósforo, só um serve...",
  [1130369088785152] = "Gentil senhor, você pode me dar um fósforo...",
  [1130369088784896] = "<P_Heart> (A voz parece vir de lá.) </>",
  [1130369088782848] = "Eu não esperava usar apenas dois.",
  [1130369088782592] = "A propósito, aquela caixa de fósforos... originalmente eu queria dar tudo para Jenny...",
  [1130369088782336] = "<P_Heart> (Franze a testa) </> ... Agora, as vozes que perturbam você... desapareceram para sempre.",
  [1130369088782080] = "Ah, eu realmente espero que essas pessoas nunca apareçam perto de mim. Só de passar por eles já me preocupo em sujar minha saia com lama... Vamos sair rapidamente.",
  [1130369088781824] = "Mesmo sem esses rumores, Lower Street já é ruim o suficiente. Roubo, roubo, briga – nenhum momento de paz.",
  [1130369088781568] = "Ei, George, pare de mencionar essas coisas chatas! Você vai me matar de susto!",
  [1130369088781312] = "O que há de interessante nisso?!",
  [1130369088781056] = "Haha, não é interessante? É como um enredo de teatro!",
  [1130369088780800] = "Morreu de fome...",
  [1130369088780544] = "Dizem que quando ela morreu de fome na rua, ela segurava com força uma caixa de fósforos vazia na mão...",
  [1130369088780288] = "Relaxar! A propósito, falando em fósforos, deixe-me contar um novo boato: ouvi dizer que um estivador chamado Lawis, ali perto, acabou de perder sua filha pequena.",
  [1130369088780032] = "Lina, você não está aqui há muito tempo? Você está se sentindo muito tenso?",
  [1130369088779776] = "Pensando bem, acabei de ouvir uma voz de criança dizendo “combina, combina” ou algo assim, você ouviu?",
  [1130369088779520] = "Que garota? Você não está sozinho aí? Riscar partidas, bater palmas e tudo mais – as pessoas da Lower Street são realmente interessantes.",
  [1130369088779264] = "Você não viu aquela garota?",
  [1130369088773376] = "Eu ficaria muito feliz.",
  [1130369088773120] = "Este generoso e gentil {{Sr.|Sra.}}, Jenny espera compartilhar essa alegria com você. Você estaria disposto a me ajudar a acender um fósforo?",
  [1130369088772864] = "<P_Heart> (Alegremente) </> Jenny nunca conheceu alguém tão generoso quanto você!",
  [1130369088772608] = "Se quiser, você pode usar todos eles.",
  [1130369088772352] = "Um, três, cinco... uma caixa cheia! Jenny, Jenny nunca viu tantas partidas!",
  [1130369088772096] = "Você é realmente uma senhora gentil. Obrigado pela sua gentileza, que seu dia corra bem.",
  [1130369088771840] = "Ah, talvez seja a mesma garotinha. Por favor, {{Sr.|Sra.}}, não seja educado, estou disposto a lhe dar uma caixa de fósforos de graça.",
  [1130369088771584] = "Uma garotinha? Na verdade, estou comprando fósforos para uma menina.",
  [1130369088771328] = "Eu me pergunto como ela está agora...",
  [1130369088771072] = "Desculpe, acabei de me lembrar de uma garotinha pedindo fósforos a outros donos de barracas há alguns dias, mas quando fui atrás dela, ela já tinha ido embora...",
  [1130369088770816] = "Uma única partida...",
  [1130369088770560] = "Ah, desculpe, quase esqueci, os fósforos no supermercado devem ser comprados em caixa.",
  [1130369088770304] = "Um?",
  [813709740518912] = "Todos os mendigos de Tingen estão sob seu controle?",
  [1130369088769792] = "O que você gostaria?",
  [1130369088769536] = "Lenços, velas, sabonetes, utensílios domésticos, venha dar uma olhada na Heda's!",
  [1130369088769280] = "Jenny, espere aqui, vou ajudá-la a encontrar um par.",
  [1130369088769024] = "<P_Heart> (Talvez um fósforo possa trazer mais conforto para ela do que comida ou água.) </>",
  [1130369088768768] = "A mãe deu uma caixa de fósforos para Jenny, mas não havia fósforos. Jenny quer acender um fósforo...",
  [1130369088768512] = "Seu nome é Jenny? Por que você precisa de um fósforo?",
  [1130369088768256] = "Jenny não está com sede nem com fome, Jenny só quer um fósforo.",
  [1130369088768000] = "Menina, você precisa de água ou comida?",
  [1130298758778368] = "Como ajudar?",
  [813709740220160] = "Sim, definitivamente haverá um dia assim.",
  [1130369088765952] = "É delicioso! Sr. Velho Will, da próxima vez que pedirmos comida, com certeza pediremos isto.",
  [1130369088765696] = "{{PlayerName}}, parece que você também tem talento para ser crítico gastronômico.",
  [1130369088765440] = "{{PlayerName}}, devo dizer que seu estilo de análise é único...",
  [1130369088765184] = "Compartilhando um pedaço de carne grelhada depois de misturar dez quilos de concreto de ervas com um castor que correu para o banheiro!",
  [1130369088764928] = "Carne grelhada ao luar na chama de uma vela de ervas; não é excessivamente doce ou gorduroso, proporcionando uma noite fresca e bonita.",
  [1130369088764672] = "Carne grelhada com ervas recém colhidas em uma floresta densa; o aroma oleoso é preenchido com o hálito natural do Continente Sul.",
  [1130369088764416] = "Um aroma herbáceo muito rico. Seguindo o estilo da crítica gastronômica, é como...",
  [1130298758791936] = "\"Perda de controle\"",
  [1130298758664960] = "Um médium espiritual disfarçado?",
  [1130369088764160] = "Esta carne grelhada cheira tão bem, tem um aroma nostálgico... talvez sejam as ervas. Vamos tentar!",
  [1130369088763904] = "Capitão Dunn e Klein... isso foi há anos, não esperava que ainda se lembrassem.",
  [1130369088763648] = "Klein... bem, ele não desgosta de nada, mas prefere comidas doces.",
  [1130369088763392] = "Frye nos lembrará de usar menos alface, Leonard não gosta de brócolis e o molho de pimenta preta para Dunn deveria ser mais rico.",
  [1130369088763136] = "Quantas vezes sua empresa de segurança fez pedidos em nossa loja? Claro que me lembro das suas preferências.",
  [1130369088762880] = "Sr. Velho Will, você se lembra que eu gosto de ervas?",
  [1130369088762624] = "Aliás, você gosta do sabor das ervas, certo? Esta Carne Tostada com Molho Branco de Ervas pode agradar ao seu gosto.",
  [1130369088762368] = "Sim, os restaurantes em Tingen estão desenvolvendo novos pratos ultimamente e não podemos ficar para trás.",
  [1130369088762112] = "Sr. Velho Will, <P_Heart> (Um pouco estranho) </> Eu não esperava que você participasse deste evento também.",
  [1130369088761856] = "Rozanne, muito tempo sem nos ver. Obrigado pelo patrocínio da sua empresa de segurança. Venha experimentar nosso novo prato.",
  [1130369088761600] = "Oi!",
  [1130369088761088] = "<P_Heart> (Ajudar a loja nas entregas... talvez seja uma oportunidade de negócio?) </>",
  [1130369088760832] = "<P_Heart> (Sussurrando) </> Se o orçamento permitir.",
  [48451257635840] = "Fim da Observação",
  [1130369088760576] = "Entendo... então não pode ser ajudado. Se tivermos tempo, iremos jantar na loja.",
  [1130369088760320] = "Entrega? Desculpe... nossa loja costuma ficar muito movimentada durante o horário das refeições e não temos mão de obra suficiente para fornecer serviços de entrega.",
  [1130369088760064] = "Esta sopa de rabada com manjericão pode ser encomendada para entrega na nossa empresa? Na Rua Zoutland, 36, 2º andar.",
  [1130369088759808] = "Este prato pode ser adicionado ao nosso plano de melhoria de refeições.",
  [1130369088759552] = "Haha, acabei de ler as colunas de comida nos jornais com um pouco mais de frequência.",
  [1130369088759296] = "Rozanne, não sabia que você tinha talento para ser crítica gastronômica.",
  [1130369088759040] = "Mhm, a rabada também é cozida com muita ternura.",
  [1130369088758784] = "Hmm... o caldo é refrescante e o aroma rico do manjericão combina perfeitamente com o sabor da carne, como abrir uma janela na primavera e ver gado e ovelhas no pasto.",
  [1130369088758528] = "Vamos tentar.",
  [1130369088758272] = "Restaurante Silver Crown, sopa de rabada com manjericão? Isso soa bem.",
  [1130369088758016] = "Vamos tentar algo mais comum...",
  [1130369088757760] = "É um sabor muito complexo, como comer lama misturada com xisto. Combinado com esta apresentação única, como devo dizer... sinto que a minha experiência de vida aumentou.",
  [1130369088757504] = "Ugh... um fedor tão forte.",
  [1130369088757248] = "Uh... isso é mesmo peixe?",
  [1130369088756992] = "<P_Heart> (Sussurrando) </> Se isso incomodar nosso estômago, ainda podemos ser reembolsados.",
  [1130369088756736] = "O Imperador Roselle tem um ditado famoso: já estamos aqui.",
  [1130369088756480] = "Rozanne, você tem certeza?",
  [1130369088756224] = "Dê-me uma fatia, obrigado.",
  [1130369088755968] = "Uh... isso é...",
  [1130369088755712] = "Que tal, convidados? Você gostaria de experimentar alguns?",
  [1130369088755456] = "Uh, como devo colocar isso? Em vez de olhar para a lua vermelha, parece mais que eles morreram com os olhos bem abertos...",
  [1130369088755200] = "Huh? Sete cabeças de peixe presas numa torta?",
  [1130369088754944] = "Por favor, dê uma olhada—",
  [1130369088754688] = "Isto foi inspirado na história da pesca em uma noite de tempestade no porto de Enmat. Diz-se que os cardumes de peixes saltam da tempestade para o ar, como se quisessem sair do mar em direção à distante lua vermelha.",
  [1130369088754432] = "\"Olhando para a Escola da Lua Carmesim\"? Parece bastante romântico.",
  [1130369088754176] = "Torta recém-assada \"Olhando para a Lua Carmesim\"! Veja esta cor atraente e formato único... gostaria de experimentar, convidado?",
  [1130369088753920] = "Vamos dar uma olhada.",
  [1130369088753664] = "A placa ali diz “Torta da Lua Carmesim”; parece um prato especial.",
