  [1130298758697728] = "Jogue a carta emocional",
  [1130298758697472] = "Tem outras coisas para fazer, saindo agora.",
  [1130298758697216] = "Outra pessoa de plantão",
  [1130298758696960] = "Bater papo?",
  [1130298758696192] = "Introdução da empresa de segurança",
  [1130298758695936] = "Obrigado, vamos conversar na próxima vez.",
  [1130298758695680] = "Sobre a empresa de segurança",
  [1130298758695424] = "Benefícios",
  [1130298758694144] = "Obrigado, vou dar uma olhada sozinho.",
  [1130298758693376] = "Dê uma dica",
  [1130298758693120] = "Não, vou dar uma olhada",
  [1130298758692864] = "Vi",
  [1130298758692352] = "Ambiente da empresa",
  [1130298758692096] = "Encontre o capitão",
  [1130298758691840] = "Realmente?",
  [1130298758691584] = "O verdadeiro lojista?",
  [1130298758691328] = "Experimente?",
  [1130298758691072] = "Vários alunos compareceram ao quadro de avisos...",
  [1130298758690816] = "Eu posso te entender.",
  [1130298758690560] = "Mas isso ainda é injusto.",
  [1130298758690048] = "Pesquisar?",
  [1130298758689792] = "Então por que você está correndo?",
  [1130298758689536] = "Eu também tenho um amigo",
  [1130298758689280] = "Desistir?",
  [1130298758689024] = "Vá perguntar claramente",
  [1130298758688768] = "Vá ao hospital para verificar",
  [1130298758688512] = "Você está procurando alguém?",
  [1130298758688256] = "Mostre a ela o distintivo da polícia",
  [1130298758687744] = "Ele já se tornou um monstro",
  [1130298758686976] = "Prazer em conhecê-lo, Arnold",
  [1130298758686720] = "É uma pena",
  [1130298758686208] = "Anomalias recentes",
  [1130298758685952] = "Quem é Yodora?",
  [1130298758685440] = "Ir para casa?",
  [1130298758685184] = "Garoto mau?",
  [1130298758684928] = "Pergunte sobre a flauta",
  [1130298758684672] = "Pergunte sobre a idade",
  [1130298758684416] = "Sobre Yodora",
  [1130298758683648] = "Pergunte novamente à Carol",
  [1130298758683392] = "Velho amigo",
  [822513080824832] = "Eu tenho outras coisas para fazer, saindo agora",
  [1130298758683136] = "Lugar antigo",
  [1130298758682880] = "Itens antigos",
  [1130298758682624] = "Desista por enquanto",
  [1130298758682368] = "Continuar perguntando",
  [1130298758682112] = "Pássaro?",
  [1130298758681856] = "Canto",
  [1130298758681600] = "Quero dizer...",
  [1130298758681344] = "Não, definitivamente não",
  [1130298758681088] = "Pequeno Arnaldo...",
  [822510396486656] = "Para onde todos eles se mudaram?",
  [1130298758680832] = "Poderia ser...",
  [1130298758680576] = "Velho Neil?",
  [1130298758680320] = "Leonardo?",
  [1130298758679808] = "Desculpe",
  [1130298758679552] = "Capitão Dunn...",
  [1130298758679296] = "Claro",
  [804913646950144] = "É um acordo!",
  [1130298758678784] = "Termina em [50199999]",
  [1130298758676992] = "Levante o troféu",
  [1130298758676480] = "Expressar compreensão",
  [1130298758675968] = "Fale sobre espinafre",
  [1130298758675712] = "Fale por Linda",
  [822505833146880] = "Sujeitos, a situação é muito urgente dessa vez, e preciso da ajuda de todos. Ministro da Inteligência Militar, você explica primeiro a situação.",
  [1130298758675456] = "Linda, vá em frente!",
  [1130298758674688] = "Dê uma olhada mais de perto",
  [822505833055744] = "Outra rodada? Ou voltar para cuidar do bebê?",
  [822505833092608] = "Desculpe... esse não está à venda; é uma peça personalizada para um cavalheiro.",
  [360778595254016] = "Cuidadoso!",
  [1130298758674432] = "Ajude a encobrir",
  [1130298758674176] = "Diga a verdade",
  [1130298758673920] = "Adeus, Potter!",
  [1130298758673664] = "Obstáculo para cantar?",
  [1130298758672640] = "Entrando no Clube do Tarô .",
  [1130298758672384] = "Olhe para a estátua do Louco.",
  [1130298758672128] = "Torne-se você mesmo?",
  [1130298758671616] = "Um grupo de transmigradores?",
  [1130298758670080] = "Pergunte sobre partidas",
  [1130298758669824] = "Você tem fósforos",
  [1130298758668032] = "Mas você sabe, isso não é um sonho.",
  [813709740559616] = "Mas eu, por exemplo, não consigo curar minha própria dor no joelho... que patético.",
  [1130298758667008] = "Acabou?",
  [1130298758665984] = "Não me lembro",
  [813709740257280] = "Sim, sim, sim, desde que você entenda. Ah, vocês, jovens de hoje, um por um, vocês estão impetuosos, pensando em praticar sem entender a teoria!",
  [813709739962624] = "Ansiosa pela próxima exploração.",
  [813709740559360] = "Sim, sim, hmm, isso mesmo. Uma cidade é feita de pessoas. Posso curar pessoas, então é claro que posso curar uma cidade. Isso é fácil de entender, certo?",
  [862024900820992] = "Observar",
  [813709739962880] = "Você quer treinar com outro Beyonders ?",
  [813709740275712] = "Desculpe, não estou vendendo ingressos hoje. Vá encontrar Lettis do outro lado da rua.",
  [813709740271104] = "Ah, claro, claro! Com certeza você ganhará muito.",
  [813709740413952] = "O Apple Punch está pronto. Ouvi dizer que esta bebida é muito popular em Trier, que tentativa interessante.",
  [813709740144640] = "Você gostaria de um jornal?",
  [862018190028032] = "Formulário de reembolso",
  [813709740004864] = "Apenas uma tarde de lazer, encontrando um lugar tranquilo para sentar um pouco e esvaziar minha mente.",
  [813709740152832] = "Você está aqui para orar também? Ainda há um lugar ao meu lado.",
  [813709740151040] = "O peixe Tussock é macio e tem poucas espinhas, perfeito para fritar. Polvilhe um pouco de cominho e alecrim e fica crocante por fora, macio por dentro e dourado - absolutamente delicioso!",
  [813709740154624] = "Você sabe, trabalhar uma semana inteira é sempre cansativo. Sábado e domingo, receio...",
  [822505833149440] = "Tudo bem, então esta reunião de emergência acabou. Aguardaremos as suas boas notícias, Rei, Ministro dos Negócios Estrangeiros.",
  [822505833148928] = "Eh... não, Lange, você os conhece?",
  [822505833148672] = "Sim, eles usam nomes relacionados a têxteis, e apenas seu líder tem um nome decente, chamado Hunter.",
  [822505833148416] = "A Gangue do Chapéu... aquela Agulha de Ferro e Fio de Seda e os outros?",
  [822505833148160] = "Reportando-se ao Rei, existe aqui outra força chamada “Gangue do Chapéu”, que também é composta por um grupo de moleques de rua como nós. Talvez possamos pedir ajuda a eles!",
  [822505833147904] = "A coisa mais urgente agora é encontrar um lugar para ficarmos esta noite. Ministro das Relações Exteriores, o senhor conhece esta área do mercado de Tingen. Você tem alguma boa ideia?",
  [822505833147648] = "Calma, todos se acalmem. Sei que este assunto é muito repentino, mas devemos pensar em uma contramedida.",
  [822505833147392] = "Como isso pôde acontecer! Em alguns dias, será a festa de aniversário do nosso reino—",
  [813709740150528] = "Escolha-me um quilo de ervilhas tenras, quatro batatas e uma cebola. Vou voltar hoje à noite para fazer um tenro ensopado de ervilha e cordeiro para comemorar a aprovação da pequena Geórgia no exame de funcionário do governo.",
  [822505833093888] = "Entendo muito bem os sentimentos deles e os invejo por ainda conseguirem encontrar lembranças de alguém importante.",
  [822505833093632] = "Os vivos muitas vezes precisam de algo para comemorar aqueles que já faleceram.",
  [822505833092864] = "O material é na verdade... cabelo?",
  [813709740149504] = "9 a K, vou vencer isso! A propósito, você conhece aquela comissão em Pritz Harbor?",
  [822505833086464] = "É justamente por isso que a Madame tem investido em muitas joalherias como Miss Alice.",
  [822505833086208] = "Somente ficando mais barato poderá ser comprado por mais pessoas. Desde que um número suficiente de pessoas compre, poderemos definir o que está na moda – que é muito mais valioso do que as matérias-primas.",
  [822505833085952] = "De jeito nenhum, minha querida, as joias precisam ser mais baratas.",
  [822505833085696] = "A acumulação de riqueza está ultrapassada; eles deveriam ficar em segurança em um cofre. De agora em diante, o artesanato é a tendência popular, e Miss Alice sempre teve um faro apurado para isso.",
  [822505833085440] = "No passado, apenas a nobreza poderia definir um design excelente, mesmo que fosse muito pesado e monótono – um empilhamento manual de grandes quantidades de ouro, pérolas, corais... materiais caros.",
  [822505833085184] = "Embora eles não parecessem felizes quando se mudaram... Acho que todos que saem da Rua Daffodil sentem uma certa relutância.",
  [822505833084928] = "Isso sempre me lembra a família Moretti – eles eram meus vizinhos naquela época. O irmão mais velho fez o primeiro exame para funcionário público daquele ano e agora eles se mudaram para Backlund.",
  [822505833084416] = "...Vamos esquecer completamente essa guerra, Anna.",
  [822505833083904] = "Este é um lugar aconchegante, mas a maioria dos meus vizinhos da época se mudaram, é uma pena...",
  [822505833058560] = "Lutar contra o mal é muito divertido.",
  [822505833058304] = "Quantas vezes perdido? Quantas vezes ganhou? Ninguém se lembra. Você parece ter lutado até o fim do mundo, o fim do universo.",
  [822505833058048] = "A barulhenta mesa de jogo ficou em silêncio por um momento antes de entrar em erupção novamente. Você usou a mesma força de vontade que tinha quando se libertou do casulo vermelho para lançar suas cartas ferozmente.",
  [822505833057792] = "Deixe-me fazer isso.",
  [822505833057536] = "<P_Heart> (Alerta) </> O que você está tentando fazer?",
  [822505833057024] = "O jogo de cartas é longo, tão longo quanto a tristeza que emana daquele homem que perdeu quinze mãos seguidas.",
  [822505833056768] = "Você se senta ao lado do cachorrinho. Ele olha para você confuso, fica educadamente ao seu lado e vocês dois ficam sentados em silêncio, de frente para a barulhenta mesa de jogo.",
  [822505833056256] = "Ei, seu garoto fedorento aí, fique quieto quando brincar com o cachorro! Não posso mais perder!",
  [813709740149760] = "Tem havido cada vez mais fantasmas aquáticos perto do rio ultimamente, até mesmo muitos cidadãos comuns os viram com seus próprios olhos...",
  [822505833055232] = "Ei, Hunter, mantenha seu cachorro sob controle! É tão barulhento quanto um bebê recém-nascido!",
  [813709740290048] = "Não posso culpá-lo inteiramente. Mais tarde, nosso filho nasceu e tivemos que comprar comida, necessidades básicas, brinquedos e pagar seus estudos.",
  [813715108741632] = "Vou dar outra olhada.",
  [813709740433920] = "Senhora, embora eu não saiba o que você passou... mas as coisas vendidas neste mercado não são completamente inúteis.",
  [813709740749568] = "Eu tenho algumas poções especiais aqui que podem deixar você racional ou louco... quer experimentar uma?",
  [813709740749312] = "Entre, amigo. Espero que, daqui a pouco, quando eu te ver, você esteja andando sozinho.",
  [813709740749056] = "Que o poder da Deusa nos ajude a salvar Tingen da crise atual, e que aqueles que não puderam ser poupados do sofrimento encontrem sono no Reino de Deus.",
  [813709740748800] = "Tenha cuidado com tudo, {{PlayerName}}.",
  [813709740748544] = "Obrigado, pequeno {{PlayerName}}. Por favor, tenha cuidado também; perder qualquer companheiro é um golpe igualmente doloroso para nós.",
  [813709740748288] = "Sra. Orianna, com certeza trarei Rozanne de volta.",
  [813709740748032] = "Pequena Rozanne... que a Deusa a abençoe. Ela sempre foi tímida, principalmente depois do acidente envolvendo seu pai...",
  [813709740747776] = "Se não fosse por me ajudar a comprar material de escritório, talvez ela não tivesse sido apanhada neste desastre.",
  [813709740747520] = "Estou bem, só que a pequena Rozanne também ainda não voltou...",
  [813709740747264] = "Sra. Orianna, você está bem?",
  [813709740747008] = "Pequeno {{PlayerName}}, você veio.",
  [813709740746752] = "Não tem nada a ver com a recompensa; trata-se apenas de fé – a fé de um Guardião.",
  [813709740746496] = "Trabalho mais importante? Ah, eu entendo. Não se preocupe, querido Bright, a recompensa nunca é um problema e posso pagar um preço significativo.",
  [813709740746240] = "Desculpe, temos um trabalho mais importante agora. Por favor, me perdoe, eu realmente não posso participar de sua aventura.",
  [813709740745984] = "Mas decidi convidá-lo repetidamente. Ex-mercenário, venha conosco e aventure-se em busca do rico tesouro!",
  [813709740745728] = "Senhor, já recusei repetidamente.",
  [813709740745472] = "Amigo, a partitura musical continua incompleta. Por favor, vá a três locais no Castelo de Lamud, encontre o “Bard” e ajude-o a rastrear os ecos do passado.",
  [813709740744704] = "Amigo, a partitura musical continua incompleta. Vá a três locais no Mar de Flores de Hornacis, encontre o “Bardo” e ajude-o a rastrear os ecos do passado.",
  [813709740744192] = "Obrigado, amigo! Você coletou todas as notas musicais para mim.",
  [813709740743680] = "Qual nível você quer desafiar?",
  [813709740743168] = "Que pergunta você quer fazer?",
  [813709740742912] = "Tudo bem, volte para mim se mudar de ideia.",
  [813709740742656] = "Se você não se importa, compartilhe alguns comigo? Isso me ajudaria a deixar este lugar fantasma perigoso mais cedo. Não se preocupe, tenho coisas boas para você; você definitivamente não vai perder ~",
  [813709740742400] = "Este lugar está cheio de Marionetes enlouquecidos. É realmente assustador, mas este também é o único lugar onde você pode obter a maior e melhor Marionete essência. Ei, olhando para seus bolsos abarrotados, você deve ter pegado bastante pelo caminho, certo?",
  [813709740742144] = "Ah, uma criatura que não perdeu o controle... isso é realmente raro aqui.",
  [813709740741632] = "Sim, mas você precisa fornecer o material Beyonder correspondente.",
  [813709740741376] = "Hum? Beyonder ... há algum problema?",
  [813709740740608] = "Qual carruagem você quer pegar?",
  [813709740740352] = "Não há mais nada por enquanto. Você poderia tentar negociar com outro Beyonders .",
  [813709740740096] = "Haverá alguns novos materiais amanhã; você pode voltar e dar uma olhada então.",
  [813709740739840] = "Ei, um novo lote de Beyonder materiais chegou hoje. Quer dar uma olhada?",
  [813709740739072] = "Qual progresso você deseja verificar?",
  [813709740738816] = "Caro convidado, olá, precisa de alguma coisa?",
  [813709740738560] = "Entre rapidamente, acho que Rozanne deve estar pronta.",
  [813709740738304] = "Olá, Sra.",
  [813709740738048] = "Recém-chegado? Sou Luo Yao Laiting, prazer em conhecê-lo.",
  [813709740737792] = "Hmm, ouvi de Xiga que você se saiu muito bem na investigação do mercado negro. Acontece que há outro caso urgente que preciso confiar a você.",
  [813709740737536] = "A Refração da Luz também dispara uma lança. Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813709740430848] = "Dizem que o marido dela perdeu todo o dinheiro nos negócios.",
  [813709740736256] = "Ganhe Escudo após liberar Knowledge Pursuit. Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813709740736000] = "Restaure 30% da saúde máxima após liberar Refração da Luz. Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813709740735744] = "Acione Starry Dome Judgment após lançar Star Sand. Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813709740735488] = "Reduza a Busca do Conhecimento recarga em três segundos. Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813709740735232] = "Acione manualmente a Lança de Longinus para reduzir o Gambito dos Séculos recarga em 1 segundo. Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813709740734464] = "Dispare um tiro a cada 5 segundos em combate. Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813709740733440] = "Desdobre o Tesouro do Rei. Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813709740730112] = "Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813709740729856] = "Utilize o Guia de Viagem; nos levará ao lugar onde caiu a primeira chuva dourada.",
  [813709740729600] = "Não tem problema, Capitão Frye, vamos partir agora!",
  [813709740729344] = "Este assunto precisa ser resolvido o mais rápido possível. Eu irei acompanhá-lo desta vez.",
  [813709740729088] = "Após verificação, essas moedas de ouro vieram de um capitalista chamado Locke e contêm Beyonder poder. Não podemos permitir que cheguem aos cidadãos comuns, pois trarão perigos imprevisíveis.",
  [813709740728832] = "A chuva dourada caiu na Praça Central de Tingen. Alguns dizem que é um presente dos deuses, enquanto outros dizem que é uma isca do diabo.",
  [813709740728320] = "Hmm, há um caso urgente que preciso confiar a você.",
  [813709740728064] = "Toda guerra tem suas origens, e sou eu quem abre a porta para você alcançá-las.",
  [813709740727808] = "O destino que desceu com você, o destino que o trouxe até aqui.",
  [813709740727552] = "Que destino? Eu quero entender isso agora.",
  [813709740727296] = "Revelações, presságios e segredos indescritíveis – você eventualmente compreenderá o destino que o aguarda.",
  [1139094851695360] = "Sim",
  [813709740726528] = "Gatinho, deixe-me acariciar você.",
  [813709740726272] = "Hmm, obrigado pelo lembrete, terei mais cuidado!",
  [813709740726016] = "Está tudo bem, não há mais ninguém por aqui, não será ouvido.",
  [813709740725760] = "Minha voz estava muito alta agora? Desculpe, eu estava um pouco animado demais, hehe.",
  [813709740725504] = "Ah, é você! Eu pensei...",
  [813709740724992] = "Tenha cuidado, a gangue Dragon Hunter está próxima.",
  [813709740724736] = "No entanto, seu cabelo estava penteado com muito cuidado. Parece que mesmo na pobreza ela tinha uma família que a amava profundamente.",
  [813709740724480] = "Ela era muito magra, suas roupas estavam esfarrapadas e velhas e ela nem usava sapatos. Há muitas crianças assim na Rua Cruz de Ferro. Eu estava com pressa para vender meus produtos na época, então não olhei com atenção.",
  [813709740724224] = "Você ainda se lembra das características dela?",
  [813709740723712] = "Uau!",
  [813709740723456] = "Bom cachorro!",
  [813709740723200] = "Miau miau...",
  [813709740722944] = "O que é isso, gatinha? Deixe-me acariciar você.",
  [813709740722688] = "Cale a boca, Arlo, nós dois usamos o mesmo fornecedor de sorvete.",
  [813709740722176] = "Pigmentos, aromatizantes, adoçantes, uma mordida pode envenenar você até a morte!",
  [813709740721920] = "...Limão, baunilha, chocolate, delicioso, refrescante e comovente!",
  [813709740721664] = "Leite vencido mais açúcar branco! Desliza em seu estômago e te dá arrepios!",
  [813709740721408] = "O melhor sorvete de Tingen! Excelente sabor, delicado e suave!",
  [813709740721152] = "Aja com cuidado e preste atenção à segurança.",
  [813709740720896] = "Não tem problema, deixe comigo.",
  [813709740720640] = "Atualmente, as pistas conhecidas são poucas e precisamos ir ao local relatado para investigar.",
  [813709740720384] = "Perto de algumas ruínas nos subúrbios. Alguém relatou ter visto rituais de culto aqui várias vezes.",
  [813709740720128] = "Não muito tempo atrás, várias testemunhas detectaram vestígios do que se suspeita ser um zumbi à noite.",
  [813709740719872] = "Capitão, qual é a comissão desta vez?",
  [813709740719616] = "Tenha cuidado com tudo.",
  [813709740719360] = "Não tem problema, deixe comigo.",
  [813709740719104] = "Blackthorn é a equipe Vigia Noturno mais próxima, então estamos enviando pessoas para ajudar.",
  [813709740718848] = "Não faz muito tempo, alguém descobriu seus rastros em Backlund. O diocesano Vigia Noturno Borgia imediatamente levou as pessoas a persegui-lo, até as proximidades de Tingen, e solicitou o apoio da Santa Catedral.",
  [813709740718592] = "Caçando um Beyonder que perdeu o controle. O alvo se chama Karl Edgar, um Sequência 7 Mystery Pryer. Depois de perder o controle, ele vagou e machucou muitas pessoas.",
  [813709740718336] = "Que caso?",
  [813709740713984] = "(Um diálogo a ser empacotado)",
  [813709740713728] = "(Um diálogo a ser empacotado) O progresso de qual história você deseja verificar?",
  [813709740712960] = "(Um diálogo a ser empacotado) Qual história você quer vivenciar?",
  [813709740712704] = "Amigo, a partitura musical ainda está incompleta. Por favor, vá a três locais em Tingen, encontre o 'Bard' e ajude-o a perseguir os ecos do passado.",
  [813709740712448] = "Por favor, siga-me e curtam essa música maravilhosa juntos.",
  [813709740712192] = "Obrigado, amigo! Você coletou todas as notas musicais para mim.",
  [813709740711936] = "Você quer que eu ajude a te teletransportar de volta para Tingen? Tudo bem... mas não tenho muita confiança, pode doer um pouco...",
  [813709740711680] = "Passageiros que pegam a balsa para Tingen, comprem seus ingressos aqui!",
  [813709740711424] = "Respeitado {{Sr.|Sra.}}, você pode pegar uma carruagem de longa distância para Tingen aqui!",
  [813709740711168] = "O quê, você quer ir para o Clube do Tarô ? Sem problemas! Sou um Aprendiz maduro e minha taxa de sucesso no teletransporte é de trinta por cento!",
  [813709740710912] = "Passageiros que pegam a balsa para o Star Plateau no Southern Continent, comprem seus ingressos aqui!",
  [813709740710656] = "Respeitado {{Sr.|Sra.}}, você pode pegar uma carruagem de longa distância para Backlund aqui!",
  [813709740710400] = "Respeitado {{Sr.|Sra.}}, você pode pegar uma carruagem de longa distância para a Cidade dos Nenúfares aqui!",
  [813709740710144] = "Respeitado {{Sr.|Sra.}}, você pode pegar uma carruagem de longa distância para o Lago Tingen aqui!",
  [813709740709888] = "Respeitado {{Sr.|Sra.}}, você pode pegar uma carruagem de longa distância para o Mar de Flores de Hornacis aqui!",
  [813709740709632] = "Respeitado {{Sr.|Sra.}}, você pode pegar uma carruagem de longa distância para o Castelo Lamud aqui!",
  [813709740709376] = "Respeitado {{Sr.|Sra.}}, você pode pegar uma carruagem de longa distância para o Lago Golden Autumn aqui!",
  [813709740702976] = "O progresso de qual líder você deseja verificar?",
  [813709740702720] = "Conheço bem a mansão e posso te levar para onde você quiser...",
  [813709740702208] = "Tenho a sensação de que algo terrível está acontecendo na mansão...",
  [813709740701952] = "Diga-me quando estiver pronto e partiremos imediatamente.",
  [813709740700928] = "Volte à juventude e sinta-se novo! Que tal? Você pode comprar alguns, quer precise ou não.",
  [813709740700672] = "Não conte a ninguém, mas esse puro pó de múmia do Continente Sul é suficiente para deixar velhos que nem conseguem ficar em pé...",
  [813709740700416] = "É claro que também estamos progredindo. Todos os mestres de Backlund vêm até mim para estocar!",
  [813709740700160] = "Mas os negócios têm piorado nos últimos anos; as pessoas confiam mais nos médicos que estão sempre prontos para puxar uma faca.",
  [813709740699904] = "Nossa cidade natal também realiza pesquisas sobre ervas tradicionais.",
  [813709740699648] = "Flores para dormir profundamente e ervas perfumadas à noite têm efeitos milagrosos sobre a insônia. Bergamota com um pouco de hortelã pode manter os trabalhadores mais esforçados por mais meio dia!",
  [813709740699392] = "Você perguntou à pessoa certa. Minha família está na indústria tradicional de ervas há gerações. Estejam doentes ou não, as pessoas que bebem algumas misturas de ervas são sempre boas.",
  [813709740699136] = "Não, estou muito interessado em ervas tradicionais, você pode me falar sobre elas?",
  [813709740698880] = "Bem-vindo ao Julgamento do Tarô. Você está pronto?",
  [813709740691456] = "O tempo voa tão rápido; num piscar de olhos, já são 1358. Parece que a guerra acabou de terminar.",
  [813709740690944] = "Está tudo bem, você é muito trabalhadora, garota forte. Que a Deusa te abençoe.",
  [813709740690688] = "Nossa, isso foi há muito tempo; Estou sendo muito prolixo.",
  [813709740690432] = "Mas mais tarde, quando pensei em ser capaz de reduzir o fardo da minha família, essas dificuldades não contaram para nada.",
  [813709740690176] = "Mas eu tinha que ir vender flores mesmo com o estômago vazio, senão ninguém da família teria comida.",
  [813709740689920] = "Foi muito difícil no começo; Eu tinha que acordar muito cedo todos os dias e o pior era não ter o que comer.",
  [813709740689664] = "Isso deve ser muito difícil, certo?",
  [813709740689152] = "É tão bom ver alguém interessado em peixe salgado!",
  [813709740688896] = "Claro, lembre-se de adicionar a quantidade certa de água de cada vez e garantir que a temperatura da água fique quente o suficiente.",
  [813709740688640] = "Acredite, apenas uma mordida vale mil. Compre uma porção de sopa concentrada de peixe salgado e ela pode durar uma semana inteira para uma família se você levar para casa.",
  [813709740688384] = "Que tipo de gosto Loen é esse...",
  [813709740688128] = "Um convidado que passava me ajudou a chamá-lo de 'Looking Up at the Stars' antes. Porém, mudei para 'Looking Up at the Crimson Moon', que se adapta melhor à minha fé, haha.",
  [813709740687872] = "Depois da minha pesquisa, combinada com as preferências alimentares do povo Loen, inventei este prato – colocar cabeças de peixe salgadas numa tarte e assá-las por ordem!",
  [813709740687616] = "São ricos em óleo, por isso costumo sugerir que todos fritem novamente quando chegarem em casa, mas isso depende da preferência pessoal!",
  [813709740687360] = "Quando eles estavam vivos, eles podiam nadar pela capital real até as águas rasas do Mar Sônia para procriar e sobreviver... Claro, esses amigos definitivamente não estão tão enérgicos agora, haha.",
  [813709740687104] = "Dá para perceber de relance que você entende o charme do peixe salgado, haha. Você quer peixe salgado, torta de peixe salgado ou sopa concentrada com sabor de peixe salgado?",
  [813709740686848] = "Quando se trata de peixe salgado, ninguém sabe mais do que Hoffman Paulson, a menos que você também seja um Paulson!",
  [813709740686592] = "Claro! Meu avô era Intisiano e só veio para Loen por amor. A família Polson sempre lidou com peixes.",
  [813709740686336] = "Além disso, \"um peixe salgado virando\" é uma metáfora que o Imperador usou para descrever alguém da base da sociedade que de repente teve um golpe de sorte e se tornou um figurão.",
  [813709740686080] = "Por exemplo, “Sem anseio por uma vida futura, um cidadão não é diferente de um peixe salgado” e “Qual a diferença entre uma pessoa que não lê e um peixe salgado?”",
  [813709740685824] = "Segundo pessoas próximas ao Imperador Roselle, o Imperador apreciava muito a delicadeza do peixe salgado e tinha muitas citações famosas sobre o assunto.",
  [813709740685568] = "{{Sr.|Sra.}}, você gostaria de um peixe salgado? Ou talvez uma iguaria de peixe salgado recentemente desenvolvida? Ou talvez uma sopa concentrada com sabor de peixe salgado?",
  [813709740685312] = "Peixe salgado delicioso, peixe salgado barato, o peixe salgado favorito de Roselle, novo peixe salgado melhorado ao estilo Loen, peixe salgado da família Hoffman!",
  [813709740684544] = "Uma estela deixada aqui por alguém desconhecido, registrando vários locais regionais com Beyonder poderes.",
  [813709740684288] = "Muito obrigado, vou tentar mais tarde!",
  [813709740684032] = "Talvez isso possa lhe trazer algumas surpresas inesperadas.",
  [813709740683776] = "É um hábito do pessoal de Tingen tentar adivinhação quando encontram problemas.",
  [813709740683264] = "Então talvez você possa tentar adivinhação ; isso pode lhe trazer uma nova solução.",
  [813709740683008] = "Suponho que tenho um pouco de dificuldade.",
  [813709740682752] = "E você? Você tem algum problema?",
  [813709740682496] = "Nada, apenas pensando em algumas coisas de antes.",
  [813709740681984] = "<P_Heart> (Falando consigo mesma) </> Os dias passados ​​com Melissa e Elizabeth são tão claros como se fossem ontem.",
  [813709740681728] = "De jeito nenhum, estou apenas olhando a paisagem de Tingen.",
  [813709740681472] = "Obrigado por suas bênçãos!",
  [813709740681216] = "Então feliz aniversário antecipadamente!",
  [813709740680960] = "Então devo escrever uma carta para convidá-la, como antes!",
  [813709740680704] = "Talvez ela já tenha decidido voltar para lhe fazer uma surpresa?",
  [813709740680448] = "Quero convidar Melissa para minha festa de aniversário, mas não sei se ela está livre.",
  [813709740680192] = "Há alguma coisa que você queira contar a ela?",
  [813709740679936] = "Estou pensando em escrever uma carta para meu bom amigo.",
  [813709740679680] = "Que a Deusa os abençoe!",
  [813709740679424] = "<P_Heart> (Suspiros) </> Sim, espero que eles possam se reunir com suas famílias e amigos no reino da Deusa.",
  [813709740679168] = "Pelo menos agora temos paz.",
  [813709740678912] = "Nós, em Tingen, tivemos sorte de termos escapado de tudo isso.",
  [813709740678656] = "Felizmente, Melissa e os outros não foram afetados...",
  [813709740678400] = "Muitas pessoas não puderam voltar e permaneceram para sempre na frente de Midseashire, nas montanhas de Minminsk.",
  [813709740678144] = "Há quatro anos, foram eles que lançaram um ataque surpresa em Backlund e iniciaram a guerra!",
  [813709740677888] = "Eles são ladrões! Homens loucos!",
  [813709740677632] = "Eu nem quero pensar no passado; é tudo culpa daqueles malditos Feysacs!",
  [813709740677376] = "Sim, parece que foi ontem.",
  [813709740677120] = "O tempo realmente voa; num piscar de olhos, é 1358. Parece que a guerra acabou de terminar.",
  [813709740676608] = "Há mais alguma coisa que você precisa?",
  [813709740676352] = "O que você gostaria de saber?",
  [813709740676096] = "Gostaria...",
  [813709740675840] = "A escolha tradicional é o café das terras altas de Feynapot, mas esta loja vende chá gelado doce do sul, que também é uma tendência recente.",
  [813709740675584] = "Você pode experimentar o bolo de limão e os muffins pequenos; Acho que você vai se apaixonar por eles, desde que goste de sobremesas.",
  [813709740675328] = "O que você gostaria?",
  [813709740675072] = "Bem vindo, criança!",
  [813709740674816] = "<P_Heart> (Pobre Imperador Roselle, sendo usado por comerciantes inescrupulosos para inventar histórias novamente...) </>",
  [813709740674560] = "Tudo bem, então 12 soli... 10 soli está bem, ei, não tenha tanta pressa de sair!",
  [813709740674304] = "Não há necessidade...",
  [813709740674048] = "Vou vendê-lo para você por apenas 15 soli. Garanto que você ficará ansioso pela chegada da noite todos os dias. Que tal?",
  [813709740673792] = "Hehe, este é o óleo essencial vegetal de East Balam. Pode te transformar em um trem a vapor na cama, em um canhão de tiro rápido no meio da noite, sabe, hehe.",
  [813709740673536] = "O que é isso?",
  [813709740673280] = "<P_Heart> (Tirando um pequeno pote de algum lugar) </> Deixe-me dizer calmamente, é tudo graças a essa coisa que o Imperador Roselle teve o capital para o romance.",
  [813709740673024] = "...Por que?",
  [813709740672768] = "Quando ele era apenas um oficial de baixa patente, ele teve muitas amantes nobres e inúmeras belezas estavam apaixonadas por ele. Você sabe por quê?",
  [813709740672512] = "Ei, amigo, você já ouviu falar dos casos românticos do Imperador Roselle?",
  [813709740672256] = "Não sei se Charlie é o nome dele ou o nome do proprietário; Vou prestar mais atenção a isso no futuro.",
  [813709740672000] = "Será que ele se perdeu e foi vendido aqui como cachorro de rua? Que pena.",
  [813709740671744] = "Hum? Este cachorro tem uma etiqueta pendurada no pescoço, gravada com... Charlie?",
  [813709740671488] = "<P_Heart> (Carinhosamente) </> Uau! Uau, au!",
  [813709740671232] = "Que cachorro fofo.",
  [813709740670976] = "Parece que alguém está discutindo... vamos ouvir o que está acontecendo.",
  [813709740670720] = "Você me lisonjeia! No trabalho acadêmico, é preciso ter um olhar atento.",
  [813709740670464] = "Este ângulo é verdadeiramente refrescante. Se você pudesse fazer anotações sobre os burros no mercado, temo que você poderia produzir uma monografia espessa.",
  [813709740670208] = "Estou planejando escrever um artigo usando essa teoria para analisar a obsessão da Rainha das Fadas pela cabeça de burro – essa é a parte mais brilhante da peça – que na verdade é uma acusação à alienação da humanidade pela civilização industrial.",
  [813709740669952] = "<P_Heart> (Animadamente) </> Isso é natural! Desconstruir o texto através dos sentidos é um sistema de discurso totalmente novo que criei. Não olhe para esta peça chamada “Sonho de uma noite de verão”; na verdade, metaforiza exatamente o conteúdo oposto!",
  [813709740669696] = "Feysac? Frígido? A compreensão deste cavalheiro do drama clássico de Loen é verdadeiramente... muito única.",
  [813709740669440] = "Oh, desculpe, na verdade comecei a gostar de relembrar o passado.",
  [813709740669184] = "Claro, isso também graças ao apoio do pequeno Klein – ele foi um dos primeiros convidados a provar o doce chá gelado. Infelizmente, a morte o levou muito cedo. A família Moretti também se mudou para Backlund logo cedo.",
  [813709740668928] = "Nos últimos dias, mais e mais pessoas adoram chá gelado doce. <P_Heart> (Orgulhoso) </> Acho que contribuí bastante para a divulgação da culinária sulista.",
  [813709740668672] = "Pequenos muffins fofos e macios - se você quiser entreter os convidados, esses pequeninos são perfeitos.",
  [813709740668416] = "No entanto, posso dizer com ousadia que você não ficará desapontado se comprar uma peça inteira.",
  [813709740668160] = "Bolo de limão recém-assado é o mais saboroso; você pode comprar um pequeno pedaço para experimentar primeiro.",
  [813709740667904] = "Cada pão pesa cerca de 0,5 quilo, mas haverá alguns erros inevitáveis, então você pode comprar conforme necessário.",
  [813709740667648] = "No café da manhã, o pão de centeio é a escolha mais acessível.",
  [813709740667392] = "Embora o chá gelado doce seja uma bebida do sul, ele também agrada aos gostos dos habitantes locais de Tingen.",
  [813709740667136] = "Para o chá da tarde, você pode experimentar bolo de limão e muffins pequenos, que podem ser combinados com o café das terras altas de Feynapot ou o chá gelado doce da minha cidade natal.",
  [813709740666880] = "Se quiser comprar o café da manhã, recomendo pão de centeio, que enche muito.",
  [813709740666624] = "Obrigado. Se tivermos a sorte de nos encontrarmos em Backlund no futuro, pintarei um retrato perfeito para você com as cores mais vibrantes.",
  [813709740665856] = "É uma pena, ouvi dizer que é a cidade mais próspera do continente; você pode passear quando tiver tempo no futuro.",
  [813709740665600] = "Aqui ninguém nunca elogiou minhas pinturas. Talvez os críticos de arte de Backlund apreciem o meu estilo.",
  [813709740665344] = "Para ser honesto, estou partindo para Backlund amanhã – ganhei uma passagem de barco enquanto lutava contra o mal, talvez esta seja a orientação da Deusa.",
  [813709740665088] = "Como esperado, você parece uma pessoa perspicaz.",
  [813709740664832] = "{{Sr.|Sra.}}, você já esteve em Backlund?",
  [813709740664576] = "<P_Heart> (Esta é uma escolha tão difícil?) </>",
  [813709740664320] = "Suspiro, como quiser, continue escolhendo, meu chefe de cozinha.",
  [813709740664064] = "Acho que não, isso vai estragar o sabor deles...",
  [813709740663808] = "Veja, até mesmo {{Sr.|Sra.}} que está passando por aqui concorda com minha sugestão.",
  [813709740663552] = "Então vamos dividi-los ao meio.",
  [813709740663296] = "Essa sugestão é muito extravagante.",
  [813709740663040] = "Minha sugestão é que você compre esses dois pães.",
  [813709740662272] = "Ah, todo mundo diz isso sobre ele. Na verdade, o Sr. Sparrow parece apenas frio... Ele é um verdadeiro cavalheiro, um cavalheiro com um pouco de domínio, e dentro desse domínio, um pouco de ternura...",
  [813709740661248] = "Ei, eu ouvi isso!",
  [813709740660992] = "Não quero mais brincar com Janny, ele sempre corre muito devagar.",
  [813709740660736] = "<P_Heart> (Eles parecem estar jogando o jogo mais popular entre as crianças nos últimos anos, 'O Grande Aventureiro Gehrman'.) </>",
  [813709740660480] = "Venha comigo, conheço um lugar tranquilo no beco, é muito mais confortável que isso!",
  [813709740660224] = "Querido, está muito barulhento aqui, meus ouvidos estão zumbindo.",
  [813709740659968] = "Grant, as pessoas podem morrer em qualquer lugar. Aprendemos isso quando estávamos no Continente Sul.",
  [813709740659712] = "Os soldados deveriam morrer no campo de batalha!",
  [813709740659456] = "Aquele relógio de bolso, aposto que foi enterrado com ele.",
  [813709740659200] = "Ouvi dizer que após o tiro seu vizinho chegou imediatamente ao local; Philip realmente cometeu suicídio atirando.",
  [813709740658944] = "Impossível, Philip é um covarde, como ele ousaria puxar o gatilho.",
  [813709740658688] = "Mas só posso ajudar Bert a aplaudir aqui...",
  [813709740658432] = "Eu claramente tenho o livro de contos de fadas favorito dela em casa, e biscoitos doces também...",
  [813709740658176] = "Quero dizer Comia, a linda mocinha ao seu lado.",
  [813709740657920] = "{{Sr.|Sra.}}, diga-me, por que ela sempre olha para Bert?",
  [813709740657664] = "Claro, aquele que está mais ativo na sua frente: Bert, meu marido ideal.",
  [813709740657408] = "A quem você está se referindo?",
  [813709740657152] = "Você sabe, quando eu crescer, vou me casar com o garoto que dança melhor nesta rua!",
  [813709740656896] = "Se você tiver outros requisitos de tamanho, poderá se registrar ao lado. Quando a mercadoria estiver pronta, avisarei você para vir buscá-la.",
  [813709740656640] = "Para que seja conveniente apreciar estas estátuas em diferentes ocasiões. Tamanho da palma da mão, tamanho da mesa e tamanho da vitrine estão disponíveis para você escolher.",
  [813709740656384] = "Existem muitas estátuas de tamanhos diferentes aqui.",
  [813709740656128] = "Eu não vou!",
  [813709740655872] = "Tosse, tosse, tudo bem, vou fingir que não ouvi isso, levante-se primeiro, vamos parar de competir!",
  [813709740655616] = "Shh, fale baixo. Você está arruinando minha reputação!",
  [813709740655360] = "Eu me importo com o meu? Quem cuida de você quando você chora de dor à noite? Para lhe dar uma compressa quente nos joelhos, a chaleira está quase em greve!",
  [813709740655104] = "Negócios adultos, você cuida dos seus!",
  [813709740654848] = "Pai! Por que você ainda está competindo com o tio Freyr para ver quem consegue agachar por mais tempo! E lendo o jornal, você consegue focar nisso!",
  [813709740653056] = "Não importa onde você esteja, a vida de um plebeu é normal. Quanto a saber se você pode transformar a vida em um bom vinho, meu jovem, isso depende de suas próprias habilidades.",
  [813709740652800] = "...Espero que sim. Mas não quero que ela sofra comigo e não quero que ela fique presa aqui, como nós, sem nunca ver o mundo lá fora.",
  [813709740652544] = "O que há de errado com o distrito fabril? Enquanto duas pessoas estiverem juntas, a vida sempre poderá ter algum sabor.",
  [813709740652288] = "Jovem, não pense assim. A vida é amarga, mas sempre há algo pelo qual ansiar.",
  [813709740652032] = "Deixá-la se casar com alguém como eu e viver uma vida repetitiva no distrito fabril para sempre, esse tipo de coisa... não é nada para comemorar.",
  [813709740651776] = "Flores? Suspiro... Já é injusto com ela namorar alguém como eu.",
  [813709740651520] = "Oh! Então, por favor, compre um buquê de flores lindamente embrulhado para dar a ela, para comemorar seu grande dia!",
  [813709740651264] = "Eu... vou sair com Leslie mais tarde, você tem alguma recomendação?",
  [813709740651008] = "Ei, meu jovem, compre algumas maçãs, elas estão frescas! Ou compre algumas uvas – colhidas da videira esta manhã!",
  [813709740650496] = "Shh – fale baixo, seja discreto, discreto. ...Sou um grande fã de teatro!",
  [813709740650240] = "Você é um cambista?",
  [813709740649984] = "Olá, você está aqui para comprar ingressos? Posso esperar na fila por você.",
  [813709740649728] = "Vou esperar aqui até mamãe me encontrar; ela deveria estar a caminho.",
  [813709740649472] = "Olhe para aquele restaurante; o proprietário, Old Will, costuma dividir um pouco de comida comigo.",
  [813709740649216] = "Ah, obrigado, está tudo bem!",
  [813709740648960] = "Há algo que eu possa fazer para ajudá-lo?",
  [813709740648704] = "Chiu-Chiu era um passarinho tão lindo, azul como o céu... Era a melhor boneca.",
  [813709740648448] = "Voltei sorrateiramente uma vez, mas tudo se foi. O copo d'água da mamãe, as roupas dela e meu Chiu-Chiu...",
  [813709740648192] = "Não sei, mamãe não vem para casa há dias. Eu não tinha acordado esta manhã quando alguém de repente invadiu a casa e me expulsou.",
  [813709740647936] = "Por que você está dormindo aqui? O que você tem?",
  [813709740647680] = "Olá...?",
  [813709740647424] = "É um pouco mais lento; um dia, dois dias, as notícias sempre passarão.",
  [813709740647168] = "As pessoas nesta rua são pobres, mas o seu desejo de compreender o mundo não é diferente do de qualquer outra pessoa.",
  [813709740646912] = "Estes são todos jornais de segunda mão que encontrei. Varandas de casas ricas, latas de lixo na rua Zolat, espreguiçadeiras em jardins – todos os tipos de lugares.",
  [813709740646656] = "Jornais vencidos? Por que você não vende o de hoje?",
  [813709740646400] = "Todos estes jornais expiraram; você pode trocá-los por itens ou apenas dar alguns centavos.",
  [813709740646144] = "Cada vez que Loro termina uma apresentação, ele vomita até meio da noite, dizendo enquanto vomita: 'Vou comer mais da próxima vez.'",
  [519041160596480] = "Carne de vaca, carneiro, carne fresca...",
  [519041160608768] = "Louvado seja a Deusa!",
  [813709740645888] = "Um dia, Loro disse de repente que pensou em uma boa maneira de ficar satisfeito e ganhar dinheiro.",
  [813709740645632] = "Conhece ele? Crescemos juntos, sempre com fome.",
  [519041160729088] = "Alguma notícia do mar?",
  [519041160713728] = "É ridículo que esses idiotas ainda divulguem cartazes de procurados com retratos.",
  [813709740645376] = "Você conhece o 'Grande Comedor' Loro?",
  [813709740645120] = "<P_Heart> (Sussurrando) </> Se Loro continuar comendo assim, algo vai acontecer mais cedo ou mais tarde.",
  [519041160814592] = "{{Buddy|friend}}, você tem algum rato vivo em mãos?",
  [519041160844288] = "Miau!",
  [813709740644864] = "Eu irei te encontrar se precisar de alguma coisa.",
  [519041160958976] = "Próximo paciente, não corra!",
  [519041160997888] = "Que a Deusa proteja você!",
  [519041160983552] = "Miau!",
  [813709740644608] = "Concluirei meu trabalho com o maior entusiasmo!",
  [813709740644352] = "Desde limpar o banheiro até preparar as refeições, qualquer tarefa da sua vida pode ser entregue a mim!",
  [813709740644096] = "O que é uma empregada geral?",
  [519041161107968] = "Hum...",
  [813709740643840] = "Olá, você está procurando uma empregada geral? Sou ágil, entusiasmado e garanto que se você me contratar terá bom humor todos os dias!",
  [813709740643584] = "Uma empregada muito esperta terá suas próprias ideias e sempre tentará passar por cima do mordomo e do patrão.",
  [519041161201664] = "...Suspirar.",
  [813709740643328] = "Não é bom ter uma empregada inteligente?",
  [813709740643072] = "<P_Heart> (Sussurrando) </> A empregada encontrada para a Sra. Cyril não pode ser muito esperta, caso contrário, ela será muito difícil de administrar.",
  [813709740642816] = "Poder viajar por aí e fazer o que você ama é muito legal, não é mesmo?",
  [813709740642560] = "Não estou no clube há muito tempo, mas ouvi dizer que ela está viajando pelo mundo em busca de novas inspirações para sobremesas!",
  [813709740642304] = "Você poderia me contar sobre isso, Sra. Cuthbert?",
  [813709740642048] = "Que tipo de sobremesa nova a Sra. Cuthbert fará quando voltar na próxima vez?",
  [813709740641792] = "Se não se importa, experimente esta peça; Eu estava planejando originalmente levá-lo para casa!",
  [813709740641536] = "Ouvi dizer que ela foi para Intis e Feynapot para estudar confecção de sobremesas e só voltou para Loen até aquela guerra.",
  [813709740641280] = "Oh! Este é um bolo de limão fornecido especialmente pelo Cuthbert Dessert Club, é uma receita exclusiva da Sra. Cuthbert!",
  [813709740430080] = "As pessoas estão indo e vindo aqui o dia todo, não sei de quem você está falando.",
  [813709740640000] = "Você também está aqui para ver as novidades desta temporada?",
  [813709740639744] = "Aconselho você a não me virar as costas, ou vou chutar sua bunda com força!",
  [813709740639488] = "Besteira! O que senhora Intis!",
  [813709740639232] = "Você tem razão! Eu deveria ter viajado com amigos e deixar você ir ao Dixi com sua querida senhora Intis comer paella e beber cerveja!",
  [813709740638976] = "Escolha, escolha, escolha! A tempestade está acima, eu já te disse, não viaje comigo!",
  [813709740638720] = "Você me pergunta com o que estou insatisfeito? Estou insatisfeito com tudo!",
  [813709740638464] = "Volte e verifique suas contas de café com seu livro de taxas de impostos! Os cartazes contra o trabalho infantil não foram feitos para você olhar!",
  [813709740638208] = "Você! Oh, que pessoa vulgar; Eu não deveria ter falado com você!",
  [1143492898212608] = "Compre os materiais",
  [813709740637696] = "Senhorita, essas alterações grosseiras são realmente uma monstruosidade para a cidade...",
  [813709740637440] = "Aham... você está certo! Na verdade, isso é apenas... apenas ervas calmantes do Continente Sul.",
  [813709740637184] = "De acordo com o artigo 17 da Portaria de Saúde Pública—",
  [813709740636928] = "O sinal? Você quer dizer aquele pedaço de sucata onde você nem consegue ler as palavras?",
  [813709740636672] = "Senhor, é proibido fumar na praça – você não viu a placa?",
  [813709740636416] = "Apenas espere! Se eles não me deixam cultivar vegetais, eu os cultivarei de qualquer maneira!",
  [813709740636160] = "Qual é a utilidade de ser impressionante? Uma única ordem de cima, e as pessoas de baixo limpam tudo por uma questão de “estética”! Os senhores da Prefeitura querem até controlar a sujeira!",
  [813709740635904] = "Isso é impressionante.",
  [813709740635648] = "Você poderia dizer isso. Era um canteiro de ervas daninhas que capinei cuidadosamente e plantei junto com um círculo de repolhos viçosos.",
  [813709740635392] = "Antes isso era uma horta?",
  [813709740635136] = "Um pássaro é um pássaro! Um pássaro é ele mesmo!",
  [813709740634880] = "{{Sr.|Sra.}}, se você ver meu pássaro, por favor, saia em silêncio e não o perturbe.",
  [813709740634624] = "Um ex azarado. Você entende, certo? Um ex decente deve agir como se não existisse, e não aparecer de repente enquanto alguém está fazendo compras feliz!",
  [813709740634368] = "Quem é ele?",
  [813709740634112] = "Deusa, realmente encontrá-lo em um lugar como esse é muito azar.",
  [813709740633856] = "A garota mais linda do mundo. Se eu não tivesse dado em cima de outras garotas na rua naquela época, ela não teria me deixado, e eu não estaria tão arrependido...",
  [813709740633600] = "Quem é ela?",
  [813709740633344] = "Deusa, realmente encontrá-la em um lugar como este, isso é um sinal de Deus, me dizendo para segurá-la firmemente desta vez e nunca mais soltá-la?",
  [813709740633088] = "Então vamos ver quem ganha!",
  [813709740632832] = "Minha Bola de Neve não é um coelho comum!",
  [813709740632576] = "O pequeno Toby é um descendente genuíno de cães pastores; sempre que ele vê um coelho, ele... ele só quer competir.",
  [813709740632320] = "Heh, minha Debbie ara campos há dez anos; sua resistência é incomparável.",
  [813709740632064] = "Meu velho John pode ser gordo, mas é rápido quando corre! Da última vez que ele roubou aveia, eu nem consegui pegá-lo!",
  [813709740631808] = "Eu... não posso... perder... para... um... velho... homem...",
  [813709740631552] = "Mas você parece muito cansado.",
  [813709740631296] = "Isto... é... uma... forma... de... cultivo...",
  [813709740631040] = "Olá, há um banco próximo onde você pode se sentar.",
  [813709740630784] = "<P_Heart> (Lutando para suprimir o tremor) </> Uh... Eu digo, velho amigo, nós realmente temos que competir dessa maneira?",
  [813709740630528] = "Você está certo sobre isso. Estamos consecutivos há tantos anos e nunca vi suas pernas tremerem!",
  [813709740630272] = "Na nossa idade, temos que aprender a ser bons conosco mesmos. Não tente ser durão sempre, a saúde é o mais importante, entendeu?",
  [813709740630016] = "Não mencione isso! Meus joelhos têm doído como se tivessem sido esmagados por uma carruagem nos últimos dias, e meu filho insistiu para que eu ficasse na cama. É por isso que só estou saindo agora que posso andar.",
  [813709740629760] = "Velho amigo, por que não te vi nesses últimos dias? Não me diga que você foi atormentado por aquele maldito reumatismo de novo?",
  [813709740629504] = "Suficiente! Vocês dois perdedores! Vou voltar para a casa da minha mãe em Midseashire!",
  [813709740629248] = "<P_Heart> (Furioso) </> Besteira! Semana passada ela até me elogiou por ter o cheiro forte de quem trabalha!",
  [813709740628992] = "Calma, velho Fitch! Foi a Sra. Melini quem disse que você sempre deixa as roupas com cheiro de fumaça de carvão...",
  [813709740628736] = "Abrir a porta! Sua maldita doninha, se você tem coragem de roubar minha esposa, você tem coragem de abrir a porta! Diga-me! Por que a anágua da minha esposa está na sua tábua de passar?",
  [813709740628480] = "Você está apenas tratando a queda de cabelo! Por que se importar tanto?",
  [813709740628224] = "Mas você viu aqueles morcegos secos na porta? E aqueles potes de pós estranhos...",
  [813709740627968] = "Dê um descanso! Você não estava dizendo isso ontem à noite quando estava chorando enquanto olhava para seu reflexo em uma poça. Não é só comprar algumas ervas?",
  [813709740627712] = "Eu digo, vamos voltar. Ouvi dizer que o dono desta loja lançará maldições sobre as pessoas...",
  [813709740627456] = "<P_Heart> (Sussurrando) </> Preciso ter cuidado com minhas palavras da próxima vez...",
  [813709740626944] = "Lixo... chegar mais perto da cozinha do restaurante permite que você pegue esses vegetais!",
  [813709740626688] = "Cesto de lixo?",
  [813709740626432] = "Yeah, yeah! A lixeira da cozinha do restaurante tem muitos desses vegetais todos os dias, é uma pena jogar fora... ah!",
  [813709740626176] = "Um preço bastante razoável, deve ser bom para fazer sopa.",
  [813709740625920] = "Ah, esses são todos... ah, especialmente selecionados no restaurante, muitas variedades e o preço é barato! Apenas 1 centavo por libra!",
  [813709740625664] = "Você tem uma grande variedade de vegetais aqui.",
  [813709740623360] = "A família Moretti...",
  [813709740623104] = "Mas tinha mesmo uma família aqui que já foi para a cidade grande antes... ah, era a família Moretti.",
  [813709740620288] = "Apenas estar vivo já é bom o suficiente!",
  [813709740620032] = "Mas isso é demais...",
  [813709740619776] = "Não pode comer? Ferva, refogue, ainda vai encher seu estômago! Como vocês, jovens mestres e senhoras decentes, conheceriam a vida das pessoas da Lower Street?",
  [813709740619520] = "Mas essa carne não dá mais para comer, né?",
  [813709740619264] = "Acha que fede? Se você acha que fede, vá até a Upper Street comprar produtos frescos! A carne lá é cheirosa, mas olha o preço!",
  [813709740619008] = "Essa carne já está podre, ainda pode ser vendida? Você não tem medo de causar problemas de saúde?",
  [813709740618752] = "{{Sr.|Sra.}}, isso é apenas um treino, estou apenas praticando a postura... o vencedor só precisa jogar cartas com a boca.",
  [813709740618496] = "Por que você está jogando cartas sozinho?",
  [813709740618240] = "Copas ou Espadas?",
  [813709740617984] = "Se você se manifestar agora para me ajudar, prometo ir ao cais todos os dias para ajudar gatos vadios a afugentar cães selvagens! Simples assim... aventureiro louco debaixo do seu assento!",
  [813709740617728] = "Ainda tenho três rebuçados cremosos na minha mochila! Eles são todos para você! Na verdade, quando minha irmã quebrou o vaso... fui eu! E o cachorrinho Querida, não roubou as batatas...",
  [813709740617472] = "\"Sr. Tolo\"... isto é, aquele alto e poderoso! O jornal diz que você adora piadas— <P_Heart> (soluçando de repente) </> Se eu... se eu for esmagado em um hambúrguer de carne... não sobrará ninguém para contar a história embaraçosa do Lame Tom, vizinho, sendo perseguido por um ganso!",
  [813709740617216] = "É mais assim! Vamos trabalhar duro juntos, definitivamente não é tarde hoje... amanhã!",
  [813709740616960] = "Oh, meu anjinho, você é sempre mais forte que eu. Tudo bem, para você e esta família, vou tentar.",
  [813709740616704] = "Se você não for hoje, não conseguirá explicar amanhã! Além disso, ainda temos que pagar o aluguel. Se você não for trabalhar, não teremos nem dinheiro para comprar pão.",
  [813709740616448] = "Isso foi só para te confortar, minha querida. O chefe não pensará assim. Ele só vai pensar que sou um vagabundo preguiçoso e posso até perder esse emprego.",
  [813709740616192] = "Pai, não diga isso! Você não me disse muitas vezes que antes tarde do que nunca? Você mesmo disse isso!",
  [813709740615936] = "Estando tão atrasado hoje, vou levar uma bronca se for. Talvez eu devesse ir para casa, deitar no sofá e fingir que nada disso aconteceu.",
  [813709740615680] = "Não, não, não! Estou descendo! Sinceramente, nem mesmo um espectador irá cooperar!",
  [813709740615424] = "Que tal eu chamar um policial para você? Eles estão apenas ociosos de qualquer maneira.",
  [813709740615168] = "No limite da vida e da morte? Você nem saiu da varanda! Volte agora, ou irei te empurrar para baixo!",
  [813709740614912] = "Ei, por que você tem tanto sangue frio? Estou no limite da vida ou da morte!",
  [813709740614656] = "Ei, você aí em cima! Se for pular faça rápido, não perca o tempo de todo mundo! Eu ainda tenho que ir trabalhar!",
  [813709740614400] = "Dá um tempo, irmão! Você já realizou esse ato três vezes! Toda vez é só para me enganar e te oferecer bebidas! Apresse-se e volte aqui!",
  [813709740614144] = "Fique longe! Já estou farto desta maldita vida! Ninguém vai me parar hoje!",
  [813709740613888] = "Procure você mesmo!",
  [813709740613632] = "Por que você continua olhando para cima?",
  [813709740613376] = "Tempestades acima, não me assustem! Assuste-me e serei atingido por um raio!",
  [813709740613120] = "Você tem razão. Ouvi dizer que há alguns cultistas ativos no Distrito Oeste ultimamente, especificamente usando comida para atrair os pobres, e então... <P_Heart> (baixando a voz, quase sussurrando) </> fazendo coisas indescritíveis.",
  [813709740612864] = "Sim, também acho que isso é um pouco suspeito. A sopa tem um cheiro perfumado, mas... quem sabe se há algum truque nisso? Hoje em dia não existe almoço grátis!",
  [813709740612608] = "Este restaurante nunca ofereceu sopa de graça antes, por que de repente eles são tão generosos?",
  [813709740612352] = "Poupe-me disso, por que não comparamos o faturamento de ontem!",
  [813709740612096] = "Acho que seu cérebro pedante foi devorado por leitores ávidos, por isso você não sabe apreciar a beleza da natureza!",
  [813709740611840] = "Hmph, não importa quão boas sejam suas flores, elas podem ser tão práticas quanto meus livros? Eles não precisam de fertilizantes e são mais honestos do que os livros contábeis de algumas pessoas!",
  [813709740611584] = "Vejam as minhas flores, acabei de regá-las esta manhã com fertilizante comprado de um comerciante do Continente Sul, elas florescem com mais intensidade que os vitrais da igreja!",
  [813709740611328] = "Suspiro, que eles encontrem paz no reino da Deusa.",
  [813709740611072] = "Eles finalmente conseguiram sobreviver, e a criança tinha um emprego decente, quem diria... aquela maldita Grande Névoa...",
  [813709740610816] = "Os chapéus do casal Hunter são acessíveis e duráveis. Eles confiaram na costura de chapéus ponto por ponto para enviar seus filhos para a Escola Técnica Backlund.",
  [813709740610560] = "O que aconteceu com a loja de Hunt?",
  [813709740610304] = "Oh, você parece uma cara nova, talvez não conheça esta loja.",
  [813709740610048] = "O chapéu que usei no meu casamento, o primeiro chapéu para o meu filho, o último chapéu para o meu pai, foram todos comprados na loja da família Hunt...",
  [813709740609792] = "Se você pretende apenas olhar e não comprar, por favor não atrapalhe meus negócios.",
  [813709740609536] = "Mamãe e papai estão doentes, felizmente ainda posso ajudar a vender coisas.",
  [813709740609280] = "Estou imitando o papai.",
  [813709740608768] = "Sua falcoaria... é única.",
  [813709740608512] = "Apoie o negócio da menina.",
  [813709740608256] = "Você não consegue ouvir a voz da mamãe? Ela está claramente aqui, ela não mentiria para mim...",
  [813709740608000] = "Sua mãe...",
  [813709740607744] = "Afastarei qualquer um que te machuque, te suje ou até queira te cortar...",
  [813709740607488] = "Mãe, você sempre estará comigo né...",
  [813709740607232] = "Mãe... por que você não me abraça mais? Estou com tanto frio...",
  [813709740606976] = "Não me incomode... O Backlund Daily está esgotado, o Maritime News ainda não chegou... Se quiser comprar, vá buscar você mesmo, coloque o troco no pote...",
  [813709740606720] = "Com licença-",
  [813709740430336] = "<P_Heart> (abaixa a voz) </> Esse, é esse! Ela morava na Howls Street...",
  [813709740604928] = "Há uma vara de pescar em meu coração e ela está nadando na água.",
  [813709740604672] = "O que você está usando para pescar? Parece que não vejo uma vara de pescar.",
  [813709740604416] = "Pesca.",
  [813709740604160] = "O que você está fazendo?",
  [813709740603904] = "Está com medo? Estou com mais medo do que vocês dois!",
  [813709740603648] = "Tudo bem... mas você tem que ser rápido, parece bastante assustado.",
  [813709740603392] = "Ah! Olhar! Você quase caiu! Volte, eu imploro! Você precisa de uma escada!",
  [813709740603136] = "Uma escada? Quando a escada chegar, o gato já terá fugido! Está com muito medo de se mover agora, tenho que me apressar—",
  [813709740602880] = "Um pouco mais? Você está prestes a cair! Volte, vou procurar uma escada!",
  [813709740602624] = "Não importune! Estou quase alcançando... só mais um pouquinho!",
  [813709740602368] = "Deusa, tenha cuidado! Não se deixe matar por causa daquele gato!",
  [813709740602112] = "Tudo bem, eu vou com você. Se aquele dono da barraca de ervas se atrever a nos enganar, eu lhe darei uma lição com uma chave inglesa.",
  [813709740601856] = "Resistir? Se eu continuar resistindo, tenho medo que meu estômago vá realmente explodir. Esqueça, vou tentar a sorte, na pior das hipóteses vou pedir crédito.",
  [813709740601600] = "Ervas? Essas coisas são caras pra caramba, como nossos escassos salários podem permitir isso? É melhor apenas aguentar.",
  [813709740601344] = "Esta vida é realmente insuportável... Ouvi dizer que há uma loja de ervas aqui perto, devemos dar uma olhada?",
  [813709740601088] = "Não mencione isso, minha cabeça parece ter sido atingida por um martelo a vapor, zumbindo constantemente. Trabalhei horas extras até meia-noite ontem à noite e o capataz nem me deu uma gota de água quente.",
  [813709740600832] = "Ai, meu estômago dói muito. Receio que o pão preto da noite passada tenha estragado... E você?",
  [813709740600576] = "Não, obrigado. Você vê, eu tenho dinheiro para comprar comida de novo!",
  [813709740600320] = "Você precisa de ajuda?",
  [813709740600064] = "Tudo bem, Edward, dê mais algumas moedas ao pobre Bright para que ele possa se livrar do cheiro de mofo.",
  [813709740599808] = "Esconde-esconde? Mármores? Você chama esses jogos? Coitado, não tem gosto nenhum!",
  [813709740599552] = "Também brincamos de esconde-esconde e de bolinha de gude... essas brincadeiras também são bem divertidas.",
  [813709740599296] = "Como o que? Uma competição de coleta de lixo? Ou quem pode trabalhar mais na fábrica?",
  [1143563228452608] = "Antes?",
  [1143563228325632] = "Sua experiência anterior de aventura deve ser muito rica; você não está pensando em reviver uma vida emocionante?",
  [1143563228288768] = "Grande enterro acima do orçamento",
  [813709740598272] = "Ei, Bright, você já jogou croquet antes? Esse é o jogo mais popular do nosso West End... Acho que você provavelmente ainda nem viu, certo?",
  [813709740598016] = "Deusa? Este é o território do Senhor das Tempestades! Que tal, vou aumentar um pouco o preço, mas você tem que entender minhas dificuldades. Vamos ambos dar um passo para trás!",
  [813709740597760] = "Mas minhas flores são diferentes! São um presente da natureza, a beleza concedida pela Deusa! Você não pode compará-los com flores artificiais!",
  [813709740597504] = "Renée, os tempos mudaram. Os pobres não têm sequer dinheiro para comprar pão, então onde é que teriam dinheiro sobrando para comprar flores? O negócio é difícil!",
  [813709740597248] = "...Nesta época, no ano passado, você até elogiou minhas flores como as melhores do Distrito Leste.",
  [813709740596992] = "O preço das flores no mercado caiu drasticamente. Todas aquelas garotas da fábrica estão comprando flores artificiais; quem estaria disposto a gastar muito dinheiro em reais?",
  [813709740596736] = "Senhora, colhi estas flores do subúrbio esta manhã, estão muito frescas! O preço que você está oferecendo nem cobre o custo!",
  [1130504917095424] = "O corpo de Pete se dissipou gradualmente, deixando apenas uma flor de íris no lugar...",
  [1130504917093376] = "Voltei para o Clube do Tarô com Potter.",
  [813709740595968] = "Meu avô disse que quando o Senhor das Tempestades responder, começará a ventar, chover e trovejar no céu!",
  [813709740595712] = "Minha mãe disse que enquanto seu coração for sincero, o Senhor das Tempestades te ouvirá. Então, para curar a tosse da minha mãe, rezo todos os dias para a fonte!",
  [813709740595456] = "Você acha que o Senhor realmente responderá às nossas orações?",
  [813709740594944] = "{{Buddy|friend}}, quando você tiver ratos vivos em mãos, lembre-se de vir me encontrar!",
  [813709740594688] = "Você pode apostar em qual cachorro é o melhor ‘caçador’, ou até mesmo apostar em quantos eles conseguem pegar!",
  [813709740594432] = "Este é um evento exclusivo em todas as principais tabernas!",
  [813709740593920] = "Muitas outras coisas também podem ser gratuitas... quero dizer, reembolsadas.",
  [813709740593664] = "O Vigias Noturnos ao menos reembolsa você por atirar com balas de treino?",
  [813709740593408] = "O capitão Frye tem parecido muito estressado ultimamente, como se algo estivesse para acontecer, o que nos deixou muito nervosos.",
  [813709740593152] = "Tudo bem, eu esperava ter um match com você.",
  [813709740592896] = "Só de passagem hoje.",
  [813709740592640] = "Para onde foi meu formulário de reembolso, ah, {{PlayerName}}? Você está aqui para praticar tiro também?",
  [813709740592384] = "Haha, tem um gosto ótimo, certo? É a receita secreta da minha família. Você não encontrará uma bebida artesanal tão perfumada nem mesmo em Intis.",
  [813709740592128] = "Sibilo... obrigado.",
  [813709740591872] = "(Você sente uma sensação picante na boca e o líquido frio queima até o estômago.)",
  [813709740591616] = "Está aqui para tomar uma bebida? Ainda não abrimos para negócios, mas você pode provar primeiro.",
  [813709740591360] = "Mas nunca consigo me lembrar deles! Talvez se eu levar um buquê para casa eu consiga lembrar!",
  [813709740591104] = "Mamãe sempre me arrasta até aqui para ver as flores e me ensina seus nomes.",
  [813709740590848] = "Olá, posso perguntar se você poderia me dar um buquê de flores?",
  [813709740590592] = "Se você estiver organizando uma festa de chá ou um salão de beleza, também poderá obter preços com desconto.",
  [813709740590336] = "Claro, você deve ser um entusiasta do chá da tarde. Temos os melhores bolos de natas e biscoitos requintados de vários sabores.",
  [813709740590080] = "O vinho tinto de alta qualidade é o cartão de visita gourmet da Intis. Combinado com molho rico e carne suave, certamente proporcionará o máximo prazer sensorial.",
  [813709740589824] = "Recomendo que você saboreie o mais delicioso guisado de vinho tinto Intis, acompanhado de uma garrafa de champanhe.",
  [813709740589312] = "Houve alguns episódios menores, mas isso é assunto meu. Para o futuro do Reino Errante, como Ministro das Relações Exteriores, irei com você para negociar com eles.",
  [813709740586752] = "...Enfim, depois a família perdeu a renda, mas felizmente encontrei esse emprego, vendendo ingressos para o jovem mestre rico de lá.",
  [813709740586496] = "<P_Heart> (Sussurrando) </> Meu pai foi lá. No início, ainda podíamos receber suas cartas...",
  [813709740586240] = "Gaste tudo e jogue novamente até não sobrar nada. Bayam preparou tantas armadilhas que ninguém voltou.",
  [813709740585984] = "E mesmo que você tenha a sorte de ganhar uma grande fortuna, você rapidamente se tornará um verme que permanece no 'Teatro Vermelho' o dia todo - ah, 'Teatro Vermelho' é o nome do maior bordel de lá.",
  [813709740585728] = "É mais do que isso, {{Sr.|Sra.}}. Bayam é famosa do outro lado do mar por suas especiarias, bordéis e cassinos. Depois de começar a jogar, é difícil sair.",
  [813709740585472] = "Cassinos? Bayam não é um lugar que produz temperos?",
  [813709740585216] = "Quando seria a vez de ficar rico ser a vez de plebeus como nós? Tenho visto muitos que queriam ir aos cassinos de Bayam, desejando ficar ricos da noite para o dia, mas nenhum deles jamais voltou.",
  [813709740584960] = "Bayam parece um lugar onde se pode enriquecer, mas muito poucas pessoas vêm embarcar no navio.",
  [813709740584704] = "Backlund, Bayam, Bansy Harbor... mas hoje só há um voo para Bayam.",
  [813709740584448] = "...Vamos procurar em outro lugar.",
  [813709740584192] = "Dou um beijo de despedida em você na noite escura... Meu coração chora ao acolher a tristeza...",
  [813709740583936] = "Dou-te um beijo de despedida no porto deserto...deixo o vento zombar de mim por não saber reescrever...",
  [813709740583680] = "Não desanime, meu querido. Você se lembra da coleção de poesias de Roselle que eu estava lendo quando nos conhecemos? Venha, enxugue suas lágrimas e vamos recitar juntos aquele poema daquela época.",
  [813709740583424] = "Dale... meu querido Dale, também odeio me separar de você, mas só indo para o mar poderei possuir riqueza — riqueza suficiente para que seu pai permita esse casamento.",
  [813709740583168] = "Minha Dinit, não sei como enfrentar os dias que virão sem você. Sentirei sua falta a cada momento, rezando à Deusa dia e noite, implorando a Ela que proteja sua viagem.",
  [813709740582912] = "Minha querida, vamos nos despedir aqui. Quando nos encontrarmos novamente, voltarei do mar com o nosso futuro cheio de esperança.",
  [813709740582656] = "<P_Heart> (Parece uma despedida, devo ouvir?) </>",
  [813709740582400] = "Obrigado, gentil {{Sr.|Sra.}}, que a Deusa cuide de você.",
  [813709740582144] = "{{Sr.|Sra.}}, não importa o que você compre, esta loja doará cinco por cento dos lucros para o asilo para ajudar os necessitados.",
  [813709740581888] = "Se preferir uma textura quebradiça, também temos biscoitos amanteigados.",
  [813709740581632] = "Se prefere sobremesas suaves e delicadas, não perca o nosso recém-lançado crème brûlée.",
  [813709740581376] = "Fermentado naturalmente, feito à mão, gostaria de um pouco de pão, {{Sr.|Sra.}}?",
  [813709740581120] = "As especiarias vão trazer mais sabor à sua vida. Bem-vindo de volta na próxima vez, {{Sr.|Sra.}}.",
  [813709740580864] = "Então, você gostaria de alguns temperos deliciosos?",
  [813709740580608] = "{{Sr.|Sra.}}, você parece o tipo de pessoa que consegue entender seu próprio destino.",
  [813709740580352] = "Estando na encruzilhada do destino, ninguém sabe se as escolhas que fazem estão corretas.",
  [813709740580096] = "Eles são todos pessoas lamentáveis, repetidamente enganadas pelo destino inconstante. Costumo dizer ao meu marido que se tivéssemos investido em antracite naquela época, não estaríamos vendendo especiarias aqui agora.",
  [813709740579840] = "Desde que a Lei Antipoluição foi aprovada, o antracite tornou-se a nova tendência e acabou por falir.",
  [813709740579584] = "Na verdade, o carvão já trouxe glória. Há alguns anos, possuir carvão equivalia a ter uma onda gigantesca de libras de ouro.",
  [813709740579328] = "Ela já foi a queridinha da alta sociedade, mas desde que seu marido faliu... suspiro, nossa casinha miserável agora se tornou seu lar.",
  [813709740579072] = "Você está falando de Lia? Ela é uma mulher lamentável.",
  [813709740578816] = "Parece bom, vou dar outra olhada.",
  [813709740578560] = "Claro, tostado! A pele do peixe é crocante, a carne é branca como a neve e, depois de tostada, rega-se com um pouco de suco de limão – é o prato de assinatura do restaurante ribeirinho, e você pode replicar até em casa!",
  [813709740578304] = "As pessoas hoje em dia farão qualquer coisa contra a sua consciência por lucro. Que a Mãe Terra abençoe você com saúde, {{Sr.|Sra.}}.",
  [813709740578048] = "Pelo que eu sei, há um dono de barraca que compra produtos de segunda mão de vendedores de verduras, e outro que comprou um terreno por um preço baixo para ser sua própria fazenda, e o preço baixo foi justamente porque o antecessor do terreno era uma unidade industrial!",
  [813709740577792] = "Eu sabia, {{Sr.|Sra.}}, você parece o tipo de pessoa que se preocupa com a saúde, então naturalmente você se importaria com aqueles vegetais regados com águas residuais industriais.",
  [813709740577536] = "Não tem problema, volte se quiser!",
  [813709740577280] = "Nós administramos nossa própria fazenda, ao contrário daquele dono de barraca ao lado que finge acreditar na Mãe Terra, mas está cheio de mentiras! Você deve ter cuidado, {{Sr.|Sra.}}.",
  [813709740577024] = "Batatas, ervilhas, rabanetes brancos, alface... Garanto que minha barraca tem todas as variedades de vegetais encontradas em todas as mesas de jantar de toda Tingen – não, de todo o condado de Ahoava!",
  [813709740576768] = "<P_Heart> (Falando consigo mesma) </> Obrigada, fonte de vida! Louvado seja você, mãe de todas as coisas!",
  [813709740576512] = "Então vou dar outra olhada.",
  [813709740576256] = "<P_Heart> (Se ela realmente acredita na Mãe Terra, este é um juramento mortal...) </>",
  [813709740576000] = "Mãe Terra... Juro, se meus vegetais fossem comprados de outros vendedores, quando minha vida murchar, não cairei na terra e jamais poderei voltar ao abraço da Mãe.",
  [813709740575744] = "Alguns dizem que você vende vegetais de segunda mão, comprados a preços baixos de outros vendedores.",
  [813709740575488] = "Bem-vindo, sinta-se à vontade para escolher, {{Sr.|Sra.}}.",
  [813709740575232] = "Haha, obrigado pelo seu elogio generoso! Esses são princípios que aprendi quando era jovem, mas só os compreendi verdadeiramente depois que fiquei mais velho.",
  [813709740574976] = "Você tem razão; mesmo os rumores não conseguem esconder a verdade. Senhor, você é muito experiente.",
  [813709740574720] = "E acredito que todo cliente tem olhos brilhantes.",
  [813709740574464] = "Sim, {{Sr.|Sra.}}. Sempre há pessoas que, por ciúme ou outra coisa, caluniam outros concorrentes. É muito comum.",
  [813709740574208] = "É óbvio; este é o mercado de alface e carne mais famoso de toda Tingen! No entanto, com tantas barracas, é provável que haja alguma concorrência desleal.",
  [813709740573952] = "{{Sr.|Sra.}}, você pode olhar em volta e perguntar o que quiser. Garanto que não há bife melhor no Mercado de Alface e Carne do que o meu.",
  [813709740573696] = "Como está o cordeiro? É muito delicioso, muito adequado para fazer o prato de ervilha tenra estufada com borrego!",
  [813709740573440] = "Vá embora, vá embora! Não me deixe ser encontrado!",
  [813709740573184] = "Ah, não é {{Olo|Lillia}}... por que você é uma pessoa tão estranha! Por que você está falando com um barril!",
  [813709740572672] = "Uau, uau, uau! Você me pegou?",
  [813709740572416] = "Mas o brilho da tecnologia nunca se extinguirá.",
  [813709740572160] = "Depois da guerra, muitas figuras importantes da igreja partiram e não podemos mais pregar como costumávamos fazer.",
  [813709740571904] = "Steam acima, essa também é uma forma de difundir tecnologia.",
  [813709740571648] = "Espere um momento, deixe-me consertar isso primeiro...",
  [813709740571392] = "Suspiro, mas a eficiência realmente precisa ser melhorada. Veja como aqueles cidadãos na fila estão reclamando...",
  [813709740571136] = "Foi apenas um conflito entre a polícia e os criminosos que aconteceu depois!",
  [813709740570880] = "Dennis quer evitar riscos maiores ao renunciar; que covarde.",
  [813709740570624] = "Sob o meu governo, Tingen está em perfeita ordem.",
  [813709740569344] = "Varrendo o chão. Minha esposa não quer que eu faça tarefas em casa, então só posso sair para fazer trabalho voluntário.",
  [813709740568832] = "Quanto a este senhor... não se preocupe, providenciaremos as coisas de acordo com o regulamento da delegacia.",
  [813709740568320] = "Malditos ladrões de impostos! Agora mesmo! Ele ainda estava me perseguindo!",
  [813709740568064] = "Não houve nenhum caso de roubo, fraude ou sequestro nos últimos meses, então você pode ir normalmente.",
  [813709740567808] = "{{Sr.|Sra.}}, não se preocupe, nós investigamos essa área. É muito seguro e não há nada de anormal.",
  [813709740567552] = "Se você precisar ir, aguarde até que a delegacia termine de liberá-la. <P_Heart> (Olha para Daksy) </> Vocês vão exorcizar aquele fantasma, certo?",
  [813709740567296] = "Vá rápido! Uh... não, não vá, é realmente assustador lá!",
  [813709740567040] = "Como isso pode ser...",
  [813709740566784] = "Uh... não, é muito tranquilo lá. Os transeuntes estão sãos e salvos e as crianças brincam de fingir que são lojistas.",
  [813709740566528] = "Diga-me, {{Sr.|Sra.}}, você também viu, o fantasma que está matando pessoas em todos os lugares!",
  [813709740566272] = "Bem no quarteirão à frente, em frente à porta vermelha! Tem um fantasma me perseguindo!",
  [813709740566016] = "{{Sr.|Sra.}}! Acredite, realmente existem fantasmas!",
  [813709740565504] = "Então, por favor... deixe-me ir.",
  [813709740565248] = "Tudo bem, eu entendo, mas... senhor, nunca fiz nada que pudesse ser chamado de ruim.",
  [813709740564736] = "Claro. Já que você pode aparecer aqui de uma forma tão incrível, posso te ver e te pegar de uma forma incrível.",
  [813709740564480] = "Você... você pode me ver?",
  [813709740564224] = "Espero que você possa ser sempre tão feliz...",
  [813709740563968] = "A vida aqui é tão boa...",
  [813709740563200] = "Shh, espere até terminarmos de louvar a Deusa da Noite Eterna, que é mais sublime que o céu estrelado e mais eterna que a própria eternidade.",
  [813709740562944] = "...É muito animado aqui.",
  [813709740562688] = "Pontos de acupuntura? O que são pontos de acupuntura? Tempestade acima, minhas costas têm muitos buracos?",
  [813709740562432] = "Ah, por favor, confie em nós; essas agulhas de prata podem ajudá-lo a limpar seus pontos de acupuntura.",
  [813709740562176] = "Você está dizendo que vai cobrir minhas costas com agulhas de prata?",
  [813709740561664] = "Doutor! Por que minhas costas estão cobertas de hematomas que parecem biscoitos!",
  [813709740561408] = "Ajuda! Ah! Ahhhhh... ah, parece que não dói mais tanto.",
  [813709740561152] = "Ah, é incrível! Aquelas decocções medicinais negras e amargas realmente curaram minha dor no joelho...",
  [1130298758796288] = "Ah, insetos!",
  [1130298758667264] = "Torne-se um Vigia Noturno?",
  [1130298758663168] = "Alguém os matou?",
  [813709740559104] = "……Cidade?",
  [813709740558848] = "Também trato algumas doenças urbanas.",
  [813709740558336] = "E doenças especializadas relacionadas com a aparência e o cheiro de senhoras e senhores...",
  [813709740557824] = "Trato principalmente dos vários problemas que as crianças encontram durante o seu crescimento e desenvolvimento...",
  [813709740557568] = "Ah, acho que deveria reunir coragem e entrar!",
  [813709740557312] = "O que mais? Bom ou ruim, tenho que tentar. Não quero ficar de joelhos e chamar minha mãe mesmo quando estiver no túmulo.",
  [813709740557056] = "Então... você quer tentar?",
  [813709740556800] = "Parece tão estranho, senhor. Um grande número de agulhas inseridas na pele pode aliviar dores lombares – que lógica é essa!",
  [813709740556544] = "Certa vez, tentei me tratar, mas não surtiu efeito. No entanto, meus pacientes dizem que chegou aqui um novo médico que usa agulhas de prata para aliviar a dor lombar.",
  [813709740556288] = "Isso vem acontecendo há pelo menos dez anos, senhor. Sempre que é um dia nublado ou chuvoso, meus joelhos doem terrivelmente e Tingen fica nublado e chuvoso na maior parte do tempo!",
  [813709740556032] = "Oh, sou um velho médico e um velho paciente. O Imperador Roselle disse uma vez que um médico não pode curar a si mesmo.",
  [813709740555776] = "Então, você está aqui para ver um médico.",
  [813709740555520] = "Sou médico há quarenta anos, tenho clínica e pacientes próprios, mas também preciso de ajuda.",
  [813709740555264] = "Obviamente, meu lugar não é aqui! Ninguém teria medo de um lugar com o qual está familiarizado.",
  [813709740555008] = "Ouça os sons lá dentro! É ruim! Muito ruim!",
  [813709740554752] = "Por que o médico está do lado de fora da clínica?",
  [813709740551424] = "Hahahaha! Perdedor, perdedor, o mundo inteiro está cheio de perdedores!",
  [813709740551168] = "Vou perguntar mais uma vez - por que você está cuspindo em mim?",
  [813709740550656] = "Ptooey, ptooey, ptooey - haha, um perdedor ainda mais azarado do que eu!",
  [813709740550400] = "Hahahaha! Perdedor! Grande perdedor!",
  [813709740550144] = "É você? Por que você está cuspindo em mim?",
  [813709740549888] = "Suspiro, como isso poderia ser possível? Concentre-se apenas na revisão para o exame.",
  [813709740549632] = "Se ao menos existisse uma universidade dedicada ao estudo do misticismo onde tanto alunos quanto professores estivessem Beyonders, eu enviaria meu pedido de transferência agora mesmo.",
  [813709740549376] = "Ontem vi uma reportagem sobre fenômenos psíquicos no Jornal Honesto. A magia deve existir!",
  [813709740549120] = "Você está procurando por aqueles livros de magia rebuscados novamente. Ainda temos um exame sobre os princípios das máquinas a vapor para revisar na próxima semana.",
  [813709740548864] = "Por que não posso pegar emprestado o 'Livro da Necromancia' da biblioteca?",
  [813709740548096] = "Aqueles malditos Beyonders , pensando que podem escapar de sanções legais apenas conhecendo alguns truques? Desta vez nunca deixarei que tenham sucesso e não permitirei que nenhum acidente aconteça!",
  [813709740547840] = "Naquela época, o membro do Novo Partido, Sr. Maynard, foi brutalmente assassinado antes da eleição para prefeito. Graças ao Capitão Dunn e sua equipe de Vigias Noturnos , o assunto foi resolvido.",
  [813709740547584] = "Sim, sim, senhor!",
  [813709740547328] = "As eleições para a Câmara Municipal estão prestes a começar, por isso fique alerta!",
  [813709740546560] = "Porque minha carteira está nela.",
  [813709740546048] = "Eu realmente gostaria que tivéssemos trazido nossa própria mesa de centro.",
  [813709740545792] = "Irmão, é melhor você guardar o seu “café da tarde” para você. Vou só tomar meu chá da tarde.",
  [813709740545536] = "Minha querida irmã, isso só mostra que você ainda não experimentou um café realmente bom. O café Filmer do Continente Sul tem um sabor doce após o amargor. Você gostaria de uma xícara?",
  [813709740545280] = "Sério, Eric, eu realmente não consigo entender vocês, amantes do café. O chá é a alma do Reino Loen.",
  [813709740545024] = "Isso é uma pena. Laura acabou de se formar na melhor escola de etiqueta de Backlund, e sua etiqueta gastronômica é melhor do que a de alguns novos ricos do continente sulista.",
  [813709740544768] = "Lamento, senhora, mas para manter o ambiente de jantar, não são permitidos animais de estimação na loja.",
  [813709740544512] = "Posso deixar minha Laura vir jantar comigo?",
  [813709740544256] = "<P_Heart> (Parece que tenho que usar ' Visão Espiritual ' com mais frequência; não posso deixar o primeiro ou o segundo andar de lado.) </>",
  [813709740544000] = "Hmm... Eu prometo que nunca vou deixá-los escapar dos <P_Yellow> Arquivos </> . Se você não consegue encontrá-los no primeiro andar, talvez você possa considerar dar uma olhada no <P_Yellow> segundo andar </> ? Claro, não se esqueça de '<P_Yellow> Visão Espiritual </> ', essas coisinhas são muito boas para se esconder.",
  [813709740543744] = "Para ser sincero... nem sei onde eles estão escondidos.",
  [813709740542976] = "...... Não importa, obrigado.",
  [813709740542720] = "Hmm, falando conservadoramente, um mês?",
  [813709740542464] = "Quanto tempo terei que esperar pela minha vez?",
  [813709740542208] = "No início, vendi apenas alguns itens defeituosos que o Tingen Grand Theatre não gostou, mas eles se tornaram inesperadamente populares.",
  [813709740541952] = "Por que vender as fantasias?",
  [813709740541696] = "Você está aqui para comprar fantasias também? Por favor, marque uma consulta primeiro.",
  [813709740541440] = "Naquela patética pausa para o almoço, este é o único local onde o serviço é rápido o suficiente para voltar a tempo.",
  [813709740541184] = "Eu costumava vir aqui quase todos os dias.",
  [813709740540928] = "Pior e pior? Você é regular aqui?",
  [813709740540672] = "Suspiro, o trabalho acabou e as coisas que compro estão cada vez piores.",
  [813709740540416] = "As ervilhas provavelmente estão ali há dias; eles estão enrugados e velhos. É horrível.",
  [813709740540160] = "Só tem um ou dois pedaços de cordeiro! Isso não é apenas uma farsa?",
  [813709740539904] = "Quão ruim é isso?",
  [813709740539648] = "Este ensopado de borrego com ervilhas tenras está cada vez pior!",
  [813709740539392] = "Sou uma boa criança, quero ajudar minha irmã para que ela coma pão fresquinho!",
  [813709740539136] = "Eu sou diferente; eles são todos idiotas!",
  [813709740538880] = "Outras crianças só querem brincar, por que você quer tanto trabalhar?",
  [813709740538624] = "Não se preocupe comigo! Já sou adulta!",
  [813709740538368] = "Você ainda não tem idade para trabalhar, não é?",
  [813709740538112] = "Nove! E daí!",
  [813709740537856] = "Quantos anos você tem?",
  [813709740537600] = "Você está aqui para me convencer a desistir também?",
  [813709740537344] = "Oh! Pare de falar comigo! Não poderei deixar de te responder!",
  [813709740537088] = "Claro! Já me escondi aqui muitas vezes!",
  [813709740536832] = "Você conseguirá sair daqui a pouco?",
  [813709740536576] = "Sim! Se eu me esconder aqui, eles não conseguirão me encontrar. Não sou inteligente?",
  [813709740536320] = "Você está na caixa?",
  [813709740536064] = "Não precisa, você bebe. Eu realmente não gosto de beber de qualquer maneira.",
  [813709740535808] = "<P_Heart> (Envergonhado) </> Esta garrafa na minha mão é a última, se você não se importa.",
  [813709740535552] = "Vou te pagar uma bebida! Ah...",
  [813709740535296] = "Obrigado! Você é realmente uma boa pessoa!",
  [813709740535040] = "Agora não, mas ficarei de olho em você.",
  [813709740534784] = "Eu realmente sinto muito.",
  [813709740534528] = "Trabalho de curto prazo está bem! Biscates também são bons! Por favor... não tenho cara de ir para casa.",
  [813709740534272] = "Eu sou realmente muito capaz! Olhe para minhas mãos! Eles estão cheios de calos por causa da movimentação de carga!",
  [813709740534016] = "Sinto muito, não tenho nenhum trabalho para apresentar a você.",
  [813709740533760] = "Não me olhe assim; Na verdade, sou muito capaz! Posso colocar azulejos e construir paredes, e posso arar campos e plantar flores!",
  [813709740533504] = "Ah, {{Sr.|Sra.}}! Você tem algum trabalho para me apresentar?",
  [813709740533248] = "Eles parecem um pouco perigosos; é melhor não puxar conversa.",
  [813709740532992] = "Se você tiver problemas que precisam ser resolvidos, você também pode nos procurar.",
  [813709740532736] = "Valorizamos a integridade acima de tudo – mais do que irmãos, dinheiro ou a bebida em nossas mãos.",
  [813709740532480] = "Na verdade, nossa linha de trabalho é um pouco específica, mas somos todos pessoas decentes.",
  [813709740532224] = "Algum tolo cego reteve o pagamento que nos era devido.",
  [813709740531968] = "Você teve algo roubado?",
  [813709740531712] = "Não se preocupem, rapazes, ninguém pode tirar o que nos pertence.",
  [813709740531456] = "Isso me deu olheiras!",
  [813709740531200] = "Como resultado, comecei a ter pesadelos todos os dias, uma semana depois, sendo esmagado por tijolos, enterrado pela areia e assim por diante.",
  [813709740530944] = "Um prédio em que investi desabou; Achei que isso já era bastante azar.",
  [813709740530432] = "Por que tem que ser eu quem encontra esse tipo de coisa? Eu sou realmente tão azarado?",
  [813709740530176] = "Você também pode encontrar aquele grupo sentado no canto. Eles não conhecem uma única letra, mas fazem as coisas com eficiência.",
  [813709740529920] = "Isso depende de quantas bebidas você pede.",
  [813709740529664] = "Ouvi dizer que você está muito bem informado, chefe .",
  [813709740529408] = "Ha! Não acabe de bruços no chão ao sair.",
  [813709740529152] = "Apenas me dê algo bom.",
  [813709740528896] = "O que você gostaria de beber?",
  [813709740528640] = "Esqueça! Quando eu a convencer a me acompanhar na administração de um clube de teatro, você poderá vir e fazer alguns cursos avançados!",
  [813709740528128] = "“Ela e ele, ele e ela, ela e ela, ele e ele, histórias de amor prolongadas e sentimentais”?",
  [813709740527872] = "Nunca ouvi falar dela...",
  [813709740527616] = "Winifred! O dramaturgo que ganhou o Prêmio Literário Roselle e manteve inúmeros teatros em funcionamento!",
  [813709740527360] = "Quem é Winfr?",
  [813709740527104] = "Suspiro, eu ainda estava pensando que os elogios do público deveriam ser capazes de tirá-la do vórtice da autodepreciação por um tempo.",
  [813709740526848] = "Não, não estou.",
  [813709740526592] = "Você é fã do Winfr?",
  [813709740526336] = "Se eu tivesse o talento de Miss Fors, meu novo trabalho poderia ter sido apresentado no Backlund Grand Theatre por muito tempo...",
  [813709740526080] = "Esses clichês só são populares por causa da boa sorte.",
  [813709740525824] = "Olha isso ao seu lado! O pôster da sua peça! Isso não é prova de que você foi reconhecido?",
  [813709740525568] = "Mas você é um dramaturgo que ganhou o Prêmio Literário Roselle!",
  [813709740525312] = "Não consigo mais escrever. Eu sinto que cada frase simplesmente não está certa.",
  [813709740525056] = "É uma pena que alguém já tenha pesquisado isso hoje!",
  [813709740524800] = "Quando você tiver sorte, poderá encontrar pão que só foi mordido uma vez! E há muitas roupas e pratos velhos que eles não querem, que podem ser vendidos por alguns centavos!",
  [813709740524544] = "As latas de lixo nesta rua Zoutland contêm o maior número de tesouros de todo o Distrito Oeste!",
  [813709740524288] = "Por que você está vasculhando a lata de lixo?",
  [813709740524032] = "Oh! Você me assustou! ...Olá?",
  [813709740523776] = "Na verdade, gosto bastante de Tingen. É tranquilo e bonito, e o ar é muito fresco.",
  [813709740523520] = "Sim, temos alguns negócios sobre antracite para discutir.",
  [813709740523264] = "Você é de Backlund?",
  [813709740523008] = "Você é de Tingen? Desculpe, meu irmão é muito indelicado.",
  [813709740522752] = "Sinto muita falta do Cragg Club em Backlund, é decorado com flores de bom gosto.",
  [813709740522496] = "Se não fosse pelo trabalho, eu não viria para este lugar pequeno; as ruas são tão estreitas e sujas.",
  [813709740522240] = "Se você está procurando por Vigias Noturnos , entre no beco atrás dele, fica do lado esquerdo. A Sra. Luo Yao costuma bater na porta para tomar um pouco de ar.",
  [813709740521984] = "Não, sou responsável por alguns trabalhos de aquisição e inteligência.",
  [813709740521728] = "(Você sente a expressão dele ficar séria instantaneamente, e ele olha para você com um olhar examinador.)",
  [813709740521472] = "Há um símbolo do Blackthorn no seu carrinho. Você é um Vigia Noturno?",
  [1130369090080768] = "Não é apenas o local; ele também fornece abrigo aqui.",
  [1130369089957888] = "Esta noite, você não entrará para comer ou dormir. Você fica aqui e arranca todas as ervas daninhas do quintal com a mão!",
  [1130369089832960] = "Tenha um bom sonho, dona Amanda.",
  [1130369089810432] = "[Atuação] Monterey está morto. Algumas coisas brilhantes (Característica de Beyonder da Porta) são extraídas de seu corpo. Dê uma olhada nas placas de máscaras espalhadas nas proximidades.",
  [813643705274112] = "Falar",
  [813709740520192] = "Quer comprar um chapéu? É o mesmo estilo do Gehrman!",
  [813709740519936] = "Perder brigas, roubar coisas, passar fome – todo dia é puro caos.",
  [1130369089163264] = "Eh? Está quieto...",
  [1130369089032192] = "Você está investigando Yodora? Aquela pobre coisinha...",
  [1130369088935936] = "Esta é a segunda frase.",
  [1130369088770048] = "Você tem alguma correspondência? Apenas um bastará.",
  [1130369088751616] = "Livre?!",
  [1130369089558528] = "<P_Heart> (Pequena Daisy? Senhorita Daisy? A julgar pelo tom, elas não são a mesma pessoa?) </>",
  [1130369089425408] = "Outro? Se não for comprar flores, saia rapidamente ou chamarei o policial.",
  [1130369089363968] = "Talvez, mas este lugar parece poder acomodar muitas pessoas. Estou prestes a inspecioná-lo.",
  [813709740517632] = "Nunca serei como aquelas moças, morando em casas grandes, usando roupas brilhantes, comendo sobremesas chiques, certo?",
  [813709740517376] = "Nós perseguimos aquela coisa até aqui, e Katie e os outros estão lá dentro limpando.",
  [813709740517120] = "Eles tentaram fazer contato com um item Beyonder. Aquela coisa possuía características vivas e no final... nem uma única pessoa sobreviveu.",
  [813709740516864] = "Suspiro, há uma reunião selvagem Beyonder.",
  [813709740516608] = "O que aconteceu?",
  [813709740516352] = "Por favor, mantenha distância—ah, {{PlayerName}}.",
  [813709740516096] = "A rua está cheia de gente de novo, é ótimo, não acham?",
  [813709740515840] = "Qual é o sentido de ficar de frente para uma mesa e uma parede?",
  [813709740515584] = "Por que você não entra e toma um café?",
  [813709740515328] = "É uma pena que ele tenha sido explodido pelos bastardos de Feynapotter quando foi para Backlund para cursar a universidade, caso contrário eu poderia ter apresentado você.",
  [813709740515072] = "Não é de admirar! Você tem exatamente o mesmo temperamento do meu primo!",
  [813709740514816] = "Mm... estou estudando em algum lugar.",
  [813709740514560] = "Ei, você parece muito jovem! Você ainda está na escola?",
  [813709740512768] = "Nunca subestime o apetite desses pequeninos, meus queridos, precisamos pegá-los o mais rápido possível!",
  [813709740512512] = "<P_Heart> (cauda se levanta e estufa) </> Gulu gulu!",
  [813709740512256] = "<P_Heart> (Esfrega-se em você) </> Ronronar, ronronar, ronronar—",
  [813709740512000] = "Ronronar-",
  [813709740510464] = "......É melhor que ele esteja morto.",
  [813709740510208] = "Mas você não só não pode ganhar dinheiro, como também tem que pagar a ele todos os meses.",
  [813709740429568] = "Eu não pensava assim antes, mas agora acho que o que ele diz realmente faz algum sentido.",
  [813709740508928] = "Deveria... não ser?",
  [813709740508672] = "Não, não, não, não foi isso que eu quis dizer. Eu estava apenas perguntando sobre sua condição de rotina. Desejo-lhe boa saúde!",
  [813709740508160] = "Você está doente?",
  [813709740507904] = "<P_Heart> (Abaixa a voz) </> Entendido, por favor, espere um momento, vou pegar para você.",
  [813709740507648] = "<P_Heart> (Abaixa a voz) </> Aquele que faz o cabelo crescer.",
  [813709740507392] = "Ah, você sabe, aquela coisa, aquela verde, aquela cheirosa...",
  [813709740507136] = "Que?",
  [813709740506880] = "Chefe , eu quero um pouco disso.",
  [813709740506624] = "Não. Não comi pão nem ensopado, só tomei leite e comi um pedaço de banana!",
  [813709740506368] = "Nenhum efeito? Esse pacote de ervas precisa ser tomado com o estômago vazio. Você não comeu nada antes de usar, certo?",
  [813709740506112] = "Chefe , as ervas para dormir que você me deu da última vez não pareceram ter nenhum efeito?",
  [813709740505856] = "Você é um turista? Não entende a língua Loen? Eu disse - eu, sou, um, imploro, gar.",
  [813709740505344] = "Você não ouviu claramente? Eu disse, sou um mendigo.",
  [813709740504832] = "Olá, sou um mendigo.",
  [813709740504576] = "Ir para casa...",
  [813709740504320] = "Tudo bem. Se você sente falta da sua mãe, vá para casa e visite-a.",
  [813709740504064] = "Carregar tijolos todos os dias, roer pão de centeio... Ei! Por que estou dizendo isso, {{Sr.|Sra.}}, obrigado por ouvir minhas reclamações.",
  [813709740503808] = "Já se passaram cinco anos. Desde que as “Leis dos Milho” foram revogadas, trabalho em Tingen há cinco anos.",
  [813709740503552] = "Quando eu era criança, minha mãe fazia a mesma coisa, arrastando-me dos campos de trigo para casa depois de eu ter corrido o dia todo e colocando uma tigela de sopa de batata quente em minhas mãos.",
  [813709740503296] = "{{Sr.|Sra.}}, você viu aquela senhora? Uma mãe chamando o filho para jantar em casa, que cena linda.",
  [813709740503040] = "Só estou dizendo. Para quem só pode pagar por refeições grátis, um par de pernas que andem é o suficiente!",
  [813709740502784] = "Vamos comprar um também? Mas onde conseguiríamos o dinheiro?",
  [813709740502528] = "Você já ouviu falar? O velho Ryan, vizinho, comprou uma bicicleta; é muito mais conveniente de usar do que uma carruagem.",
  [813709740502272] = "É difícil que as coisas voltem ao silêncio aqui antes da chegada da polícia. Se você quiser comprar flores, é melhor ir a outro lugar.",
  [813709740502016] = "Por que você está me perguntando por que estou sentado na parede?",
  [813709740501760] = "Por que você está sentado na parede?",
  [813709740501504] = "Esperando, esperando que a próxima senhora olhasse para trás.",
  [813709740501248] = "......Tudo bem, então o que você está fazendo aqui?",
  [813709740500992] = "Felizmente, eles também responderam ao meu amor, um após o outro.",
  [813709740500736] = "Apresento a cada uma delas um narciso amarelo da Intis, rezando pelo favor daquelas lindas damas.",
  [813709740500224] = "Adoro criar e por isso fiz amizade com muitas jovens que amam humanidades e artes.",
  [813709740499712] = "Cosete! Pare de ler, sua mãe vai ficar preocupada!",
  [813709740499456] = "Com tanta fome... Cindy, irei para casa depois de terminar de assistir a parte em que 'Flame' Danitz se junta ao time e se torna parceiro de Gehrman!",
  [813709740499200] = "Quem te perguntou sobre isso?",
  [813709740498944] = "Veja este poema de amor: “Quando você for velho e tiver cabelos grisalhos...” Que romântico! É digno de ser escrito pelo Imperador!",
  [813709740498688] = "Por favor, não fique com raiva, este é um livro de amostra. Embora “O Grande Aventureiro” esteja esgotado, esta “Coleção de Poesias de Roselle” em minhas mãos também é muito popular entre todos.",
  [813709740498432] = "E aquela criança ali não está segurando “O Grande Aventureiro”?",
  [813709740498176] = "O último volume de “O Grande Aventureiro” esgotou ontem à noite? Não chegou anteontem?",
  [813709740497920] = "Deixe-me pensar... quando a guerra estourou em 1350, ele era três anos mais velho que eu. Este ano, sou um ano mais velho que ele...",
  [813709740497664] = "Quantos anos Jensen tem este ano?",
  [813709740497408] = "Meu irmão, um jovem animado, alegre e amante dos esportes.",
  [813709740496896] = "Obrigado! Obrigado por se disponibilizar a desejar um feliz aniversário ao Jensen. Você é uma boa criança, assim como a pequena Liddy.",
  [813709740496384] = "<P_Heart> (Cantarolando) </> Parabéns para você, parabéns para você, parabéns para o querido Jensen.",
  [813709740496128] = "Oh, oh, oh, o gato preto usando óculos de aros dourados!",
  [813709740495872] = "<P_Heart> (Mostra o brinquedo de pelúcia na mão deles.) </>",
  [813709740495616] = "Não diga esse nome! Estou comendo essas coisas há meio mês direto. Até meu hálito tem sabor de Gehrman, ao mesmo tempo doce e picante... Olha! O brinde pelo qual finalmente consegui trocar.",
  [813709740495360] = "Você gostaria de um bolo de creme picante Gehrman?",
  [813709740494848] = "O pudim de limão parece estar à esquerda.",
  [813709740494592] = "Por que não há pudim de limão Danitz? Pudim de limão Danitz... Pudim de limão Danitz...",
  [813709740494336] = "Ha! Quero expulsar todos que tentarem me abrir!",
  [813709740494080] = "Por que uma lata de peixe-lobo?",
  [813709740493824] = "Meu? Prefiro ser uma lata de peixe-lobo.",
  [813709740493312] = "Já falei, procure meu colega Fries para alugar uma casa! Ele é apaixonado, ele é proativo!",
  [813709740492800] = "Calma? Não consigo me acalmar! Quero dormir! Quero dormir!",
  [813709740492544] = "Acalmar.",
  [813709740492288] = "Porque hoje era para ser o turno dele, mas ele não apareceu! E fui acordado pelo supervisor para trabalhar para ele!",
  [813709740492032] = "Não funciona... Haha! Você viu meu colega Walk? Você não fez isso!",
  [813709740491776] = "Você não trabalha?",
  [813709740491520] = "<P_Heart> (Preguiçoso) </> Não estou aqui. Se você tiver alguma coisa, procure meu colega.",
  [813709740491264] = "Minhas condolências...",
  [813709740491008] = "Os narcisos murcharam e ele foi embora sem se despedir. Nunca nos conhecemos, mas nossas almas já se fundiram...",
  [813709740490752] = "Meu amigo por correspondência e também meu amante.",
  [813709740490240] = "Este narciso amarelo, como ele, vem do Intis. Esse é um país romântico, verdadeiramente saudoso.",
  [813709740489984] = "Enterre este narciso amarelo; simboliza meu amor morto.",
  [813709740489472] = "Sr. Leonard, você proferiu a frase \"Isso é educação\" tão bem hoje!",
  [813709740489216] = "Esqueça, vou comprar a passagem primeiro. Quanto a permanecer vivo, pensarei em outra maneira.",
  [813709740488960] = "<P_Heart> (Por que seu olhar de repente ficou tão firme...) </>",
  [813709740488704] = "Mas este é o show final! Você não sabe o quão emocionante é o show final. O ator que interpreta Gehrman conduzirá o público no local...",
  [813709740488448] = "O desempenho é precioso, mas a saúde é mais valiosa. Você deve economizar esse dinheiro para comprar comida.",
  [813709740488192] = "Não importa, compre primeiro. Pular uma refeição não vai me matar, mas se eu não assistir ao show final, morrerei de arrependimento!",
  [813709740487936] = "Então você deve comer primeiro?",
  [813709740487680] = "Você tem razão! Mas, mas sou tão pobre que mal posso comprar pão... vou desmaiar de fome antes do show começar?",
  [813709740487424] = "Como a turnê 'The Great Adventurer' raramente chega a Tingen, eu deveria comprar um ingresso.",
  [813709740487168] = "Na verdade, os ingressos para o show final da minha amada apresentação, \"O Grande Aventureiro\", estão prestes a ser colocados à venda, mas meu salário restante deste mês... Devo comprar esse ingresso ou não?",
  [813709740486912] = "Ah! Você me assustou.",
  [813709740486656] = "Olá, você está vagando por aqui há muito tempo, precisa de ajuda?",
  [813709740486400] = "...... Não há necessidade, obrigado.",
  [813709740486144] = "Sim, sim, sim! Esse é o trabalho com um enredo primorosamente estruturado e uma representação meticulosa dos personagens! Se você quiser, entre na fila atrás de mim.",
  [813709740485888] = "Você nem conhece o romance mais popular dos últimos anos? Não tenho nada a dizer para você. Vá, vá, faça fila lá atrás, não me incomode.",
  [813709740485632] = "No último show de 'O Grande Aventureiro' em Tingen desta rodada, os primeiros cinquenta membros do público podem receber um pôster autografado da autora original, Srta. Fors Wall!",
  [813709740485376] = "Obviamente, na fila!",
  [813709740485120] = "O que você está fazendo?",
  [813709740484864] = "Qual deles?",
  [813709740484608] = "Transeunte esperto, que machado você deixou cair?",
  [813709740484352] = "O cheiro dentro da carruagem é realmente terrível.",
  [813709740483328] = "A carruagem ainda não chegou... este tempo está realmente insuportável.",
  [813709740483072] = "Temos vários roteiros para você escolher. Você pode dar uma olhada cuidadosa.",
  [813709740482816] = "Venha conferir o tour de um dia da nossa agência de viagens! Levaremos você para conhecer o cenário da Cidade das Universidades no menor tempo possível!",
  [813709740482560] = "{{Sr.|Sra.}}, você também está aqui para visitar Tingen?",
  [813709740482304] = "Quem odiaria uma lareira?",
  [813709740481536] = "Aqueles mestres e amantes... provavelmente nunca sofreram assim em toda a sua vida.",
  [813709740481280] = "Leah não precisa de chapéu! Ela passa cada vez mais tempo deitada na cama... Ela não precisa mais de chapéu.",
  [813709740480768] = "Você garoto! Você economizou muito dinheiro tão jovem... Tudo bem, saia deste lugar mais cedo.",
  [813709740480512] = "Na próxima semana também não trabalharei na Fábrica Têxtil Sophie. Estou me concentrando em arrumar nossa nova casa na Rua Vlad.",
  [813709740480000] = "Felizmente, já comuniquei ao supervisor que vou pedir demissão. Poderei sair deste lixão em breve.",
  [813709740479744] = "É tão miserável todos os dias. A fumaça da queima do carvão já manchou nossa pele e nossos dentes de amarelo. Não sei em que mais isso os manchará.",
  [813709740479232] = "Deixá-la se casar com alguém como eu e depois viver uma vida repetitiva na área da fábrica e na área portuária para sempre – esse tipo de coisa não precisa ser comemorado.",
  [813709740478976] = "Por que? Coisas boas devem ser comemoradas!",
  [813709740478720] = "Não há necessidade.",
  [813709740478464] = "Você finalmente não quer mais sair de Tingen, isso é bom! Compre um buquê de flores para Leslie; garotas gostam disso.",
  [813709740478208] = "Talvez futuramente nos casemos e moremos na região das Docas, sendo seus vizinhos.",
  [813709740477952] = "Como você está se dando com Lesley?",
  [813709740477440] = "Numa boate tão grande, só o café da Angélica tem sabor familiar.",
  [813709740477184] = "Deixa para lá.",
  [813709740476928] = "Bem-vindo ao Clube Adivinhação!",
  [813709740476672] = "Ah, é mesmo? Isso é uma pena. Mas enquanto não houver recesso escolar e o rio não estiver congelado, estaremos treinando aqui. Você está convidado a vir e assistir!",
  [813709740476416] = "<P_Heart> (Uma família vindo nos visitar.) </>",
  [813709740476160] = "Você não acha isso lindo?",
  [813709740475904] = "A vida, e até mesmo todas as possibilidades do mundo, estão contidas em poucos números!",
  [813709740475648] = "Você também quer praticar numerologia adivinhação ?",
  [813709740475392] = "Às vezes, eu realmente invejo esses irmãos e irmãs. Eles podem ficar com seus pais por muito tempo.",
  [813709740429824] = "Você já ouviu falar? Aquela nova mulher na Iron Cross Street recentemente.",
  [813709740474112] = "A propósito, ouvi dizer que há um gramado no bairro universitário perfeito para um piquenique. Você pode ir lá e aproveitar aos poucos.",
  [813709740473856] = "Leve todos eles! Posso sair do trabalho depois de distribuir esses bolos!",
  [813709740473600] = "Livre? Por favor, me dê um pedaço.",
  [813709740473344] = "Gostaria de experimentar o novo bolo? Fresco e delicioso, tudo grátis!",
  [813709740473088] = "Mas quando me olhei no espelho, descobri que ainda era meu próprio rosto. Ainda tenho que trabalhar hoje, é assustador!",
  [813709740472832] = "Sonhei ontem à noite que me tornei filho da família Hall em Backlund.",
  [813709740472576] = "Sra. Amanda, por favor, me dê uma...",
  [813709740460800] = "Não importa, agora é tudo a mesma coisa. Os vivos são muito mais problemáticos do que os mortos. Voltar ao abraço da Deusa pode ser a melhor escolha.",
  [813709740460544] = "Parece que você tem sorte. O velho Trelle já está morto. É melhor encontrar um lugar seguro à noite, para sua própria segurança.",
  [813709740460288] = "Que horas são agora? Parece que bebi demais de novo. Eu vi o Velho Trelle ontem. Aquele maldito bastardo realmente queria roubar meu vinho.",
  [813709740459776] = "Claro, se você tiver alguma informação importante, também pode me avisar.",
  [813709740459520] = "Não há necessidade, é apenas uma questão pequena. Vamos apenas esperar por perto; espiritualidade irá guiá-lo de volta aqui.",
  [813709740459264] = "Você precisa da minha ajuda?",
  [813709740459008] = "O velho Trelle saiu do cemitério. Droga, Little Kohler vendeu esse terreno para outra pessoa novamente.",
  [813709740458752] = "As pessoas sempre morrem e tudo perde o sentido após a morte. Olha, o Velho Trelle acabou de sair do cemitério e o Pequeno Kohler já vendeu este terreno para outra pessoa.",
  [813709740458496] = "Você é bastante despreocupado.",
  [813709740458240] = "Nós, coveiros, somos hereditários, então é claro que sabemos dessas coisas. O que há para ter medo? De qualquer forma, todos nós acabaremos em um túmulo, mais cedo ou mais tarde.",
  [813709740457984] = "Você não está com medo?",
  [813709740457728] = "O velho Trelle era um velho bastardo quando estava vivo e não deixa as pessoas descansarem depois de morto. Ele rastejou para fora depois de morrer e ainda não foi encontrado.",
  [813709740457472] = "Quem é o Velho Trelle?",
  [813709740457216] = "Se você quiser comprar um terreno para cemitério, vá até a entrada e pergunte ao Pequeno Kohler.",
  [813709740456960] = "Claro. Com minhas roupas esfarrapadas, como eu poderia ir até a seção rica para cavar sepulturas? Não seria adequado.",
  [813709740456704] = "Existem tantas maneiras de fazer as coisas?",
  [813709740456448] = "Um coveiro, claro, é alguém que cava sepulturas. No entanto, sou responsável apenas pelo pobre cemitério. Você precisa encontrar as pessoas correspondentes para os outros dois cemitérios; eles moram na aldeia vizinha.",
  [813709740456192] = "Eu sou o coveiro aqui. Você precisa cavar uma sepultura ou está aqui para investigar a Velha Trelle?",
  [813709740455936] = "Você está aqui para comprar um cemitério? Os cemitérios estão em falta ultimamente, então compre um com antecedência se precisar!",
  [813709740455680] = "Obrigado pela sua orientação.",
  [813709740455424] = "Se você está procurando um cemitério, não vá para Little Kohler; apenas venha até mim.",
  [813709740455168] = "No lado noroeste fica o local de descanso do passado de Tingen Vigias Noturnos . Espero não ver você lá no futuro.",
  [813709740454912] = "O cemitério está dividido em três áreas: o lado sudoeste é para os ricos, a área do meio é para aqueles que estão relativamente abastados e a direção nordeste é a área do cemitério pobre.",
  [813709740454656] = "Sua história não é mais curta do que a existência de Loen.",
  [813709740454400] = "O Cemitério Rafael é nosso parque exclusivo, e os enterrados aqui são todos crentes que adoram a Deusa.",
  [813709740454144] = "Espero que sim; O Velho Teller está rastejando para fora do cemitério há muito tempo desta vez.",
  [813709740453888] = "Não se preocupe, ele será encontrado em breve.",
  [813709740453632] = "Também tenho que esperar até que o Velho Teller seja encontrado antes de poder retornar à Catedral de Santa Selena.",
  [813709740453376] = "Afinal, esta é uma área chave de preocupação para o nosso Tingen Vigias Noturnos .",
  [813709740453120] = "Claro, isso não é grande coisa; isso tem acontecido de vez em quando desde que o Cemitério Rafael foi fundado.",
  [813709740452864] = "Uma pessoa morta escapou. Droga, é o Velho Trelle, um bastardo que não consegue nem descansar em paz após a morte.",
  [813709740452608] = "A qual você está se referindo?",
  [813709740452352] = "Você também está aqui para cuidar desse assunto?",
  [598342094559488] = "Ativar Visão Espiritual",
  [813709740451584] = "<P_Heart> (Essas pessoas parecem um pouco perturbadas?) </>",
  [813709740451328] = "Eu sempre pensei assim também. Faça o que quiser enquanto estiver vivo e não se arrependa antes de morrer!",
  [813709740451072] = "Você também não pode dar nenhuma resposta, então as pessoas devem valorizar a vida enquanto ainda estão vivas.",
  [813709740450816] = "Você provavelmente pode ver o que acontece depois que você morre no cemitério. Outros podem sentir sua falta ou ser amaldiçoado, mas é claro, a maioria é esquecida.",
  [813709740450560] = "Que tipo de sentimento?",
  [598343705239808] = "Cheire com cuidado",
  [813709740450304] = "Esta é a parada final da vida. Cada vez que saio daqui de carruagem, sempre me dá uma sensação diferente.",
  [813709740450048] = "Obrigado pelo seu conselho. Normalmente amarro uma corda em mim mesmo quando pratico.",
  [813709740449792] = "Você certamente se tornará um excelente acrobata de alta altitude no futuro, mas ainda espero que preste atenção à segurança.",
  [813709740449536] = "Eu andei nesta prancha de madeira. Esta é a minha área de atuação.",
  [813709740449280] = "Huh? Como você chegou até aqui?",
  [813709740449024] = "Eu também espero. Também quero me tornar um acrobata de grande altitude e ir ao Circo dos Reis para que meu pai possa me ver.",
  [813709740448768] = "A vida está sempre cheia de vários infortúnios. Espero que ele possa se levantar novamente e não ser abatido pelo sofrimento.",
  [813709740448512] = "Porque ele caiu da corda e não conseguiu dançar e pular entre as cordas como antes. Mais tarde voltamos para cá e ele também começou a beber durante o dia.",
  [813709740448256] = "Então por que ele se tornou alcoólatra?",
  [813709740448000] = "Ele não era assim antes. Ele era um incrível acrobata de alta altitude no Circo Reis.",
  [813709740447744] = "Ele é alcoólatra? Que pai terrível.",
  [813709740447488] = "Meu pai ficou bêbado de novo, tive medo que ele me batesse, então me escondi aqui.",
  [813709740447232] = "Por que você está aqui? É perigoso aqui.",
  [813709740446976] = "Ele deveria estar por aqui, você pode encontrá-lo se olhar ao redor.",
  [813709740446720] = "{{Sr.|Sra.}}, você viu uma criança mais nova que nós?",
  [813709740446464] = "Eu acredito que você pode fazer isso.",
  [813709740446208] = "Trabalharei duro para me tornar a pessoa mais rica de Tingen e depois construirei esta vila para ser muito luxuosa também.",
  [813709740445952] = "Isso exigirá algum esforço, só pessoas ricas vivem lá.",
  [813709740445696] = "Não a catedral, estou falando da torre do Distrito Norte. Devo viver em cima disso no futuro para poder ignorar toda Tingen!",
  [813709740445440] = "Catedral de Santa Selena ou a torre do Distrito Norte?",
  [813709740445184] = "Fique um pouco aqui, sabe qual é a casa mais alta do outro lado da margem?",
  [813709740444672] = "<P_Heart> (Por que há uma sensação de estranheza? Melhor não perguntar.) </>",
  [813709740444416] = "Velho Tuller, nada a dizer, ele é apenas um bastardo, morava nesta aldeia.",
  [813709740444160] = "Você está sendo bastante vago.",
  [813709740443904] = "O velho Tuller é só um bastardo que morava na aldeia, morreu há poucos dias.",
  [813709740443648] = "Você pode ser mais específico?",
  [813709740443392] = "Apenas um louco bastardo vivendo nesta aldeia.",
  [813709740443136] = "Velho Tuller? Ele parece bastante famoso.",
  [813709740442880] = "Claro, isso também não é novidade.",
  [813709740442624] = "Sim, aquele bastardo do Velho Tuller nem teve paz depois que morreu, ele rastejou para fora do cemitério novamente.",
  [813709740442368] = "Houve alguma novidade recentemente?",
  [813709740442112] = "Você gostaria de ter alguma coisa?",
  [813709740441856] = "O Sr. Neil definitivamente ficaria muito grato a você.",
  [813709740441600] = "Sim, moro no Distrito Leste e venho nos finais de semana para cuidar do jardim.",
  [813709740441344] = "Você não mora mais por aqui?",
  [813709740441088] = "O Sr. Neil era uma pessoa muito boa. Eu costumava ser vizinho dele. Este é o jardim que ele construiu para sua amada Celeste. Ela descansa aqui. O Sr. Neil deve tê-la amado muito.",
  [813709740440832] = "Hahaha, o que você disse é um fato. Como você pode ver, não sou bom em cuidar de jardins, só não quero que o jardim do Sr. Neil seja abandonado assim.",
  [813709740440576] = "Tem a sensação de estar sendo cuidado, mas não meticulosamente o suficiente! Desculpe, eu não deveria ter dito isso!",
  [813709740440320] = "Negligenciado, certo?",
  [813709740440064] = "Não admira, parece um pouco...",
  [813709740439808] = "Parece que você entendeu mal, este é o jardim do Sr. Neil, ele já faleceu.",
  [813709740439552] = "Este é o seu jardim? É muito bonito.",
  [813709740438016] = "(Um diálogo a ser empacotado) O progresso de qual líder você deseja verificar?",
  [813709740435712] = "Olha, não estão todos ocupados comprando coisas?",
  [813709740435456] = "Mas para os residentes locais, é muito rentável...",
  [813709740435200] = "Ah, eu sabia que você era uma pessoa de bom gosto.",
  [813709740434944] = "Você está certo, a qualidade das coisas aqui não é realmente muito boa.",
  [813709740434688] = "<P_Heart> (Interrompe abruptamente) </> Pare! Não diga mais nada... você não entende nada... vá embora!",
  [813709740434432] = "Se você quiser encontrar temperos de melhor qualidade, pode ir à Daffodil Street, ou à Wendel Street e Howls Street no Distrito Norte...",
  [813713767032064] = "Muitos?",
  [813709740433664] = "Antigamente essas coisas não podiam nem ser usadas para desodorizar no banheiro ou nos sapatos... A tempestade está lá em cima, isso é realmente atormentador... <P_Heart> (aperta o peito) </>",
  [813709740433408] = "Estou tão cansado disso! Olha, o que essas sobras estão sendo vendidas? Sem fragrância, sem aparência...",
  [813709740433152] = "<P_Heart> (Olha você de cima a baixo) </> Você parece a primeira pessoa civilizada que vi nesses dias.",
  [813709740432896] = "Ah, senhora, você está querendo comprar alguma coisa?",
  [813709740432384] = "Esta senhora...",
  [813709740432128] = "<P_Heart> (Parece estar xingando baixinho, não consigo ouvir o que ela está dizendo.) </>",
  [813709740431872] = "É verdade, o dinheiro que ela usou para comprar um cão de caça provavelmente poderia comprar uma casa aqui.",
  [813709740431616] = "Ela lançou uma frase, dizendo “Que tipo de folhas podres são essas!”, e saiu com o coração orgulhoso.",
  [813709740431360] = "Não acho que valha a pena simpatizar com ela. Eu a vi fazendo compras há alguns dias, escolhendo e escolhendo mais de oitocentas vezes, e então adivinhe?",
  [813709740431104] = "Na verdade, sinto um pouco de simpatia por ela agora.",
  [813709740737280] = "Gambit of the Ages concede 1 lança. Confirmar esta habilidade? Escolhê-lo fará com que os outros 2 desapareçam.",
  [813709740430592] = "Deusa... esse não é o bairro rico de Tingen... como ela acabou morando aqui?",
  [813709740606208] = "Sinceramente, só não quero ir buscar meu filho na escola, haha.",
  [813709740641024] = "O bolo de limão no seu prato parece único; em qual loja você comprou?",
  [813709740475136] = "Mas não posso vê-lo o dia todo...",
  [813709740509952] = "<P_Heart> (vigilante) </> Por que você está perguntando isso? Embora seja preguiçoso e misterioso, ele é uma boa pessoa...",
  [813709740344064] = "Quer comer alguma coisa? Nosso chef é de Dixi Bay e sua especialidade é arroz de frutos do mar.",
  [813709740378880] = "Se você quiser entender o verdadeiro mundo interior do grande aventureiro Gehrman, leia 'Coisas entre mim e Gehrman Sparrow'. Tem tudo que você quer saber!",
  [813709740212992] = "Este pequeno bar de mergulho não tem caçadores de recompensas nem oferece entretenimento, então fique à vontade para tomar um copo de cerveja de centeio ou Tei-Lang-Chi como quiser.",
  [813709740247808] = "Meu estado mental é muito bom.",
  [813709740081920] = "Como posso fazer com que Anna me dê mais mesada!",
  [813709740116736] = "<P_Heart> (Não se envolva em problemas novamente) </>",
  [813709739951872] = "Tudo bem, só não se atrase da próxima vez.",
  [813709739985664] = "Acredito que depois dessa luta de boxe, mais pessoas irão frequentar o Evil Dragon Bar por causa de Linda. É realmente um problema feliz.",
  [813709740051200] = "A alfaiataria também está mais rigorosa e requintada do que antes, mais, mais...",
  [813709740429312] = "Thea, você está parecendo cada vez mais com aquele seu patrão idoso.",
  [813709740429056] = "Sim, suponho que as pessoas sempre tenham que encontrar uma maneira de sobreviver. Depender de nos reunirmos assim para viver muito também é uma saída.",
  [813709740428800] = "Oh... eles são todos crianças sem-teto? Isso não é fácil.",
  [813709740428544] = "Olha a lateral da estação, quem ajuda as pessoas a carregar bagagens para ganhar um dinheirinho também são eles. E guiando o caminho, entregando mensagens, sabendo algumas novidades locais.",
  [813709740428288] = "Tosse, esse é um nome que inventei. Mas todos eles se autodenominam membros de algum \"Reino Errante\" ou \"Gangue do Chapéu\".",
  [813709740428032] = "“Gangue de Órfãos”?",
  [813709740427776] = "Ah, eu sei, deve ser um membro daquela “Gangue de Órfãos”.",
  [813709740427520] = "Agora mesmo, depois de terminar as compras, um pequenino disse que me ajudaria a carregar a sacola por apenas 1 centavo. As crianças hoje em dia são tão espertas?",
  [813709740427264] = "Bem-vindo à joalheria, fique à vontade para dar uma olhada.",
  [813709740427008] = "<P_Heart> (Ela aperta os olhos, os cantos da boca se levantam e ela sorri muito feliz.) </>",
  [813709740426752] = "Acho que é porque você ama essas massas gordinhas, ama sua vida e ama os vizinhos ao seu redor, então seu pão é excepcionalmente delicioso.",
  [813709740426496] = "Sim, você não precisa de nenhuma receita secreta. Contar com quarenta anos de hábito, além de um pouco de ternura, é o suficiente para fazer uma boa padaria.",
  [813709740426240] = "Ele disse, então a receita secreta deve ser “amor”! Ouça isso, como poderia ser tão exagerado? Sinceramente, amasso a massa, fermento e coloco no forno.",
  [813709740425984] = "Haha, não há nada de especial nesse artesanato... Um escritor veio reunir material há alguns dias e me perguntou qual é a receita secreta para assar, e não consegui responder.",
  [813709740425728] = "Se fosse eu, com certeza também sentiria falta do seu trabalho caloroso.",
  [813709740425472] = "Às vezes, as crianças que ganharam dinheiro saem da Rua Cruz de Ferro, mas ainda assim voltam à padaria para comer um pedaço de bolo de limão.",
  [813709740425216] = "<P_Heart> (Tão delicioso...) </>",
  [813709740424960] = "Que tal um pequeno copo de chá gelado doce? Muitos jovens gostam deste sabor.",
  [813709740424704] = "Há alguns anos, tentei recriá-los aos poucos a partir de minhas memórias. Não esperava que os vizinhos próximos também gostassem deles, então coloquei-os na loja para venderem juntos.",
  [813709740424448] = "Você acertou, {{jovem | mocinha}}. Morei no sul quando era jovem, para mim essas são as comidas da minha cidade natal.",
  [813709740424192] = "<P_Heart> (Que tópico que causa fome, estou com água na boca.) </>",
  [813709740423936] = "Chá gelado doce, panquecas, pão de batata... hein, esse parece ser um estilo de comida sulista? Faz lembrar legumes fritos e carne assada, ou salsichas de porco...",
  [813709740423680] = "Haha, os antigos vizinhos estão acostumados a comê-los. Dê outra olhada; esse menu é um pouco diferente.",
  [813709740423424] = "Pão de centeio, biscoitos Tingen, bolo de limão... hmm, todos parecem ser comida tradicional de Tingen. Ouvi dizer que seus biscoitos Tingen são os melhores da vizinhança.",
  [813709740423168] = "Sim, olhe para este.",
  [813709740422912] = "Vejo que você parece ter dois menus aqui. Estas são as iguarias exclusivas da sua loja?",
  [813709740422656] = "Devo dizer que conhecer uma senhora animada e bem-humorada como você, e uma padaria dessas, é realmente uma alegria.",
  [813709740422400] = "E então eles podem dizer: “Ei, esse é o sabor que sua mãe mais gostava há vinte anos!” “Papai também cresceu comendo esses bolinhos!”",
  [813709740422144] = "Não é verdade? E aí os jovens que cresceram trazem seus companheiros, e seus filhos voltam à minha padaria.",
  [813709740421888] = "Isso parece muito bom.",
  [813709740421632] = "<P_Heart> (Um sorriso orgulhoso floresce em seu rosto.) </>",
  [813709740421376] = "Se fazer pão nesta rua há mais de quarenta anos conta como “sempre”, então é realmente esse o caso. Muitas crianças por aqui cresceram comendo o pão que eu fazia.",
  [813709740421120] = "Você sempre vendeu pães e doces aqui?",
  [813709740420864] = "É tão bom ver um jovem excelente como você. A Rua Cruz de Ferro pode ser um pouco caótica... mas está sempre cheia de vitalidade, não é?",
  [813709740420608] = "<P_Heart> (Vamos conversar um pouco com esta gentil senhora.) </>",
  [813709740420352] = "<P_Heart> (Dê uma olhada primeiro; aqui tem pão de centeio comum, biscoitos Tingen, bolo de limão...) </>",
  [813709740420096] = "Olá, {{jovem Sr.|jovem Sra.}}. O aroma do pão é sempre agradável; é realmente maravilhoso.",
  [813709740419584] = "Acredite, esta bebida fará com que você seja expulso de todos os bares de Trier.",
  [813709740419328] = "Meia xícara de suco de maçã, meia xícara de licor forte Feysac, 2 colheres de chá de bala de menta, alguns cubos de gelo. Em seguida, dê uma sacudida...",
  [813709740419072] = "Adicione 2 colheres de chá de doce de menta. Hum, uma combinação única.",
  [813709740418560] = "Uau, combinação clássica, é o sabor que minha avó gostava quando era criança.",
  [813709740418304] = "Meia xícara de suco de maçã doce, meia xícara de suco de laranja, 2 colheres de chá de bala de menta e um pouco de raspas de limão. Em seguida, dê uma sacudida...",
  [813709740417536] = "Garanto que isso definitivamente causará uma tempestade no seu estômago.",
  [813709740417280] = "Meia xícara de suco de limão, meia xícara de suco de laranja, 2 colheres de chá de gengibre fresco... em seguida, agite.",
  [813709740417024] = "Adicione 2 colheres de chá de gengibre fresco.",
  [813709740416512] = "Que tentativa terrível, parece que o Apple Punch estragou.",
  [813709740416256] = "Meia xícara de suco de limão doce, meia xícara de licor forte Feysac, 2 colheres de chá de gengibre fresco, alguns cubos de gelo. Em seguida, dê uma sacudida...",
  [813709740415744] = "Suco de maçã doce, uma ótima escolha. Vamos continuar adicionando algo a isso.",
  [813709740415488] = "No entanto, cada bebida aqui vem do presente do dragão. Aproveite a delícia, {{Sr.|Sra.}}.",
  [813709740415232] = "Hmm... uma combinação medíocre e um pouco estranha.",
  [813709740414976] = "Meia xícara de suco de maçã, meia xícara de licor forte Feysac, 2 colheres de chá de gengibre fresco... vamos dar uma sacudida.",
  [813709740414464] = "Adicione meia xícara de licor forte Feysac. Hmm... parece bom. Vamos continuar.",
  [879891427886850] = "Notas",
  [813709740413696] = "Meia xícara de suco de maçã doce, meia xícara de suco de laranja, 2 colheres de chá de gengibre fresco, alguns cubos de gelo. Em seguida, dê uma sacudida.",
  [813709740413440] = "Adicione 2 colheres de chá de gengibre fresco. Hum, uma combinação única.",
  [813709740413184] = "Adicione meia xícara de suco de laranja. Uau, parece muito bom. Vamos continuar.",
  [813709740412928] = "Cada bebida aqui vem do presente do dragão. Aproveite a delícia, {{Sr.|Sra.}}.",
  [813709740412672] = "O coquetel de limão doce está pronto. Tempestade acima, isso me lembra daqueles dias na Ilha Oravi.",
  [813709740412416] = "Meia xícara de licor forte Feysac, meia xícara de suco de limão, 2 colheres de chá de bala de menta e um pouco de raspas de limão. Em seguida, dê uma sacudida...",
  [813709740412160] = "Adicione 2 colheres de chá de doce de menta. Hum, uma combinação única.",
  [813709740411904] = "Cada bebida aqui vem do presente do dragão... se a bebida que você pediu contar como uma bebida. Aproveite a delícia, {{Sr.|Sra.}}.",
  [813709740411648] = "O suco de laranja com limão Bili-Bala está pronto. Uau, ouso dizer que isso é gosto de criança.",
  [813709740411392] = "Meia xícara de suco de limão, meia xícara de suco de laranja, 2 colheres de chá de bala de menta... em seguida, agite.",
  [813709740411136] = "Adicione 2 colheres de chá de doce de menta.",
  [813709740410880] = "Adicione meia xícara de suco de laranja. Hmm... parece bom. Vamos continuar.",
  [813709740410624] = "Adicione meia xícara de licor forte Feysac. Uau, parece muito bom. Vamos continuar.",
  [813709740410368] = "Suco de limão azedo, uma ótima escolha. Vamos continuar adicionando algo a isso.",
  [813709740410112] = "Primeiro, escolha uma base.",
  [813709740409856] = "Dragon's Special, esse tipo de bebida personalizada, você com certeza vai gostar.",
  [813709740409600] = "Você tem alguma recomendação especial?",
  [813709740409344] = "A cerveja Rye custa 25 centavos o copo, a cerveja Enmat custa 50 centavos, a cerveja Southwell custa 100 centavos, ou você gostaria de algo diferente?",
  [813709740408832] = "(Um diálogo a ser empacotado) Se não quiser, esqueça, toda a equipe será exterminada.",
  [813709740408576] = "(Um diálogo a ser empacotado) Cuide-se, Beyonder .",
  [813709740408064] = "(Um diálogo a ser empacotado) Bravo aventureiro, quer uma habilidade extra?",
  [813709740407552] = "(Um diálogo a ser empacotado) Você pode se teletransportar e verificar o progresso dos membros líderes da equipe aqui.",
  [813709740407296] = "Olá! Hoy University Rowing Club, gostaria de saber mais sobre isso? Os melhores membros da equipe de Tingen estão aqui!",
  [813709740407040] = "Ah, tudo bem, você pode voltar na próxima vez.",
  [813709740406784] = "Caso contrário, por que você acha que tenho meio saco aqui?",
  [813709740406528] = "Bem dito, mas como você pode presumir que definitivamente não vou terminar?",
  [813709740406272] = "Mas ainda é barato. De qualquer forma, você não vai terminar nem meio saco nem um saco inteiro, então por que não comprar o mais barato?",
  [813709740406016] = "Não é quase o preço de um saco inteiro de farinha?",
  [813709740405760] = "7 centavos.",
  [813709740405504] = "Quanto custa isso?",
  [813709740405248] = "Uh... era algo que um aluno que se formou no ano passado não poderia levar consigo quando se mudasse. Encontrei-o em uma caixa de embalagem. Seria um desperdício jogá-lo fora, não acha?",
  [813709740404992] = "Isso está realmente bem...",
  [813709740404736] = "São mercadorias que você não pode comprar em Loen; 3 libras é uma pechincha para você.",
  [813709740404480] = "Não é de segunda mão? Por que ainda é tão caro?",
  [813709740404224] = "Bom olho, uma camisa estilo Intis, ainda nova. Vou dar a você por 3 libras de ouro.",
  [813709740403968] = "Esta peça de roupa parece muito boa.",
  [813709740403712] = "Olá. São todos bens de segunda mão que circulam entre os estudantes, fique à vontade para dar uma olhada.",
  [813709740403456] = "Um garçom passando. Você vai pedir ou não?",
  [813709740403200] = "Quem é você? Como você sabe disso?",
  [813709740402944] = "Parem de discutir, pessoal. A massa desviada é um gás inerte.",
  [813709740402688] = "Mas como você pode provar que isso não é produto de uma nova reação?",
  [813709740402432] = "O desvio de massa no experimento com gás é devido às impurezas misturadas!",
  [813709740402176] = "Huh, em que número eu estava agora? Não importa, vamos começar de trezentos de novo...",
  [813709740401920] = "Você precisa de um bom conjunto de músculos para usar roupas com equilíbrio.",
  [813709740401664] = "Olá amigo, você está disposto a ingressar no clube e fazer exercícios juntos?",
  [813709740401408] = "Hmm, de qualquer forma, você pode vir e aprender mais!",
  [813709740401152] = "Isso é uma grande soma de dinheiro. Talvez eu possa até enviar alguns para minha mãe e meu pai.",
  [813709740400896] = "A razão pela qual entrei no clube? Hmm... se meus resultados no remo forem excelentes, também posso me candidatar a uma bolsa de estudos.",
  [813709740400640] = "Ei, garoto, que problema? Eu não entendo. Sou apenas um pobre vendedor de jornais! Vá embora, vá embora!",
  [813709740400384] = "Não, não, ainda não fizemos um acordo! Sinto muito, não ouso fazer isso de novo!",
  [813709740400128] = "Parece que acabei de ouvir algo sobre uma tese, algo sobre ghostwriting. Talvez eu devesse considerar denunciar isso...",
  [813709740399872] = "Certo, estou aqui para comprar revistas acadêmicas.",
  [813709740399616] = "Nada, esse garoto está aqui para comprar revistas acadêmicas.",
  [813709740399360] = "Huh? Uh, eu estou, uh... o que estou fazendo?",
  [813709740399104] = "O que você está fazendo?",
  [813709740398848] = "Hehe, viva e aprenda – foi o que o Imperador Roselle disse!",
  [813709740398592] = "Seguirei seu espírito de aprendizado!",
  [813709740398336] = "Ocasionalmente, posso até assistir a palestras nas quais estou interessado. Estou muito satisfeito com este trabalho.",
  [813709740398080] = "Eu entendo. Ficar com esse grupo de crianças me faz sentir muito mais jovem.",
  [813709740397824] = "Sim, estou aqui para visitar. O ambiente aqui é bastante agradável.",
  [813709740397568] = "Olá! Olhando para o seu traje, você não é estudante, é?",
  [813709740397312] = "Estudantes como eu nas artes liberais estão vivendo uma vida onde não podemos ver o fim e estamos desempregados no momento em que nos formamos!",
  [813709740397056] = "Deusa, ouça o que está sendo dito?",
  [813709740396800] = "Mas não estou nada feliz. Esse tipo de vida onde você pode ver o fim de relance é muito chato.",
  [813709740396544] = "Eu realmente invejo você por ter feito tal negócio; você pode conseguir um emprego logo após se formar na faculdade técnica.",
  [1139094851687424] = "Nenhum",
  [813709740396032] = "Aqui estão as flores que comprei do velho necrófago para você! Se eu passar hoje, compro todas as flores dela...",
  [813709740395776] = "Oh, ótimo... uh, veterano da escola! Por favor, conceda-me a sorte de passar no exame!",
  [813709740395520] = "Que vulgaridade! Mas é uma boa ideia. Darei a você uma cópia assim que terminar de escrevê-la.",
  [813709740395264] = "Ah, ah, ah, ah, ah! Apenas escreva assim. Quando eu terminar de escrevê-lo, enviarei uma cópia para você.",
  [813709740395008] = "Então terei que pensar sobre isso com cuidado. Quando eu terminar de escrevê-lo, enviarei uma cópia para você. Obrigado!",
  [813709740394752] = "Espere um segundo... esse capítulo é muito emocionante, preciso lê-lo mais algumas vezes.",
  [813709740394496] = "Você tem razão! Amigo, então sobre quais feitos de Gehrman devo escrever...",
  [813709740394240] = "Noventa mil libras em recompensa, deve ser um sonho doce... suspiro, às vezes, também quero escrever sobre os feitos de Gehrman.",
  [813709740393472] = "\"Em meio às camadas de cerco do Almirante Pirata, Gehrman era como um rápido arco de luz, desaparecendo instantaneamente na fumaça e na poeira. Os arredores de repente ficaram assustadoramente silenciosos...\"",
  [813709740391680] = "Fique longe de mim, não tente arrancar informações de mim!",
  [813709740391424] = "Espere... um novo rosto?",
  [813709740391168] = "Que tesouro?",
  [813709740390912] = "Se não fosse por esse tesouro, ninguém poderia ter se levantado após o ataque final do Exterminador do Futuro.",
  [813709740390656] = "A Senhora está acima, esse é James! O 'Exterminador do Futuro'!",
  [813709740390400] = "Parece que James não é páreo para Anthony.",
  [813709740390144] = "Ei, essa rodada pode fazer algumas pessoas perderem as calças.",
  [813709740389888] = "Ok, combinado!",
  [813709740389632] = "Isso... 10 libras, é o valor mais baixo!",
  [813709740389376] = "<P_Heart> (Por que essa garota não pechincha...) </> Muito caro! Afinal, parece que ainda está muito longe de ser um verdadeiro amuleto.",
  [813709740389120] = "Ok, então eu aceito!",
  [813709740388864] = "12 libras.",
  [813709740388608] = "Quanto custa esse amuleto?",
  [813709740388352] = "Este amuleto de prata gravado com penas de anjo não é ruim; é o suficiente para evitar o azar.",
  [813709740388096] = "<P_Heart> (Após uma inspeção cuidadosa, parece que apenas este amuleto é bastante especial.) </>",
  [813709740387840] = "Muito obrigado. Parece que tenho encontrado algumas coisas de azar ultimamente, e um amigo recomendou que eu escolhesse um amuleto.",
  [813709740387584] = "Precisa que eu lhe forneça alguma ajuda, senhora?",
  [813709740387328] = "Alguém pode me dizer como escolher um amuleto adequado?",
  [813709740387072] = "Aguardamos a sua próxima visita.",
  [813709740386816] = "Da próxima vez com certeza...",
  [813709740386560] = "Uh... é por isso que são bens raros. Gastei muito esforço para coletá-los! Por apenas 5 libras, você terá dificuldade em encontrar um preço mais barato.",
  [813709740386304] = "Mas ouvi dizer que são difíceis de encontrar.",
  [813709740386048] = "Isso mesmo! Ele registra as misteriosas runas criadas pelo Imperador Roselle, que contêm um poder misterioso!",
  [813709740385792] = "Notas do Imperador Roselle?",
  [813709740385536] = "Ei, você perguntou à pessoa certa. Também tenho aqui duas páginas de anotações do Imperador Roselle. São bens raros!",
  [813709740385280] = "Portanto, é melhor não tentar de ânimo leve. Melhor conseguir uma cópia de 'Os Dez Mistérios Não Resolvidos da Segunda Época'. Esta é a última obra-prima do autor de 'Things Between Me and Gehrman Sparrow'!",
  [813709740385024] = "Isso é assustador.",
  [813709740384768] = "Este senhor prescreveu preparações de beladona aos aldeões para tratar a dor, mas os pacientes que tomaram uma overdose alegaram que se transformaram em lobos. Quando o Vigias Noturnos chegou, metade da aldeia sofria de 'licantropia clínica'.",
  [813709740384512] = "O que aconteceu?",
  [813709740384256] = "Este é um livro que apresenta bruxas e magia negra. No entanto, o anterior dono deste livro preparou poções mágicas de acordo com ele, e diz-se que quase destruiu a vida pacífica de uma aldeia.",
  [813709740384000] = "'Livro das Bruxas', 'Dez Mistérios Não Resolvidos da Segunda Época' – sempre há pessoas dedicadas a dissipar a névoa do misticismo. Há algo em que você esteja interessado?",
  [813709740383744] = "Você eventualmente retornará.",
  [813709740383488] = "Lembre-se de que a comunicação com certas existências misteriosas e perigosas tem um preço alto.",
  [813709740383232] = "Sombras e presságios turvos, você se aprofundou demais em certos rituais.",
  [813709740382976] = "Já foi embora.",
  [813709740382720] = "Atrás de mim?",
  [813709740382464] = "Os espíritos ilusórios que vagam atrás de você e estão prestes a se dissipar.",
  [813709740382208] = "Espíritos?",
  [813709740381952] = "Pode fazer com que sua mente não fique mais tensa e entre em um estado entre o sono e a vigília. Este estado é o mais fácil para a comunicação com os espíritos penetrantes.",
  [813709740381696] = "Para que é usado?",
  [813709740381440] = "Esta é uma água floral destilada de uma mistura de grama com aroma noturno, flores de sono profundo e camomila. Uma senhora chamou-o de 'Amantha', que significa tranquilidade em Hermes.",
  [813709740381184] = "Vejo que você está vagando há muito tempo. Você precisa de uma garrafa de água floral 'Amanda'?",
  [813709740380928] = "Louvado seja a Senhora! Você é realmente uma pessoa gentil; toda a nossa família vai agradecer!",
  [813709740380672] = "Mesmo assim, ainda não temos condições de pagar o aluguel e estamos prestes a ser expulsos pelo proprietário... Deusa, rezo para que você me deixe encontrar trabalho logo!",
  [813709740380416] = "Pobre criança.",
  [813709740380160] = "Wendy é uma criança sensata. Depois que perdi o emprego, ela tomou a iniciativa de ajudar minha esposa a fazer caixas de fósforos em casa e não frequentou mais a catequese, mas sei que aquela criança adora ler...",
  [813709740379904] = "Um médico? Não, não é tão sério. Além disso, como eu teria dinheiro para ir a um hospital?",
  [813709740379648] = "Você deveria ir ver um médico.",
  [813709740379392] = "Ultimamente só estou com um pouco de aperto no peito e não consigo recuperar o fôlego, mas isso não afeta em nada meu trabalho! Mas o supervisor disse que mais cedo ou mais tarde eu lhe causaria problemas...",
  [813709740379136] = "{{Sr.|Sra.}}, você precisa de um trabalhador temporário? Perdi meu emprego na semana passada e a pobre Wendy ainda está me esperando em casa com o estômago vazio...",
  [813709740377856] = "Você está perguntando como eu conheço o Sr. Sparrow? Você está questionando meu trabalho?",
  [813709740377600] = "'Things Between Me and Gehrman Sparrow' já foi reimpresso para a quinta edição, mas as vendas de 'The Ten Unsolved Mysteries of the Third Epoch' ainda estão muito lentas. Tenho que pedir ao Gielshido para promovê-lo.",
  [813709740377344] = "Obrigado pela sua recomendação.",
  [813709740377088] = "Que tal um copo de cerveja Southwell moderadamente alcoólica? Esta é a melhor cerveja produzida em toda Loen.",
  [813709740376832] = "Cara nova? Então sugiro que seja melhor não tocar em Langzi. Diante disso, muitas cervejas só podem ser consideradas bebidas.",
  [813709740376576] = "A cerveja Rye custa 25 centavos o copo, a cerveja Enmat custa 50 centavos, a cerveja Southwell custa 100 centavos, ou você gostaria de um copo de Langzi puro malte?",
  [813709740376320] = "Seu maldito vigarista!",
  [813709740376064] = "Os juros que ele cobra são muito altos...",
  [813709740375808] = "Se você não tiver dinheiro suficiente, pode pedir emprestado a Swain.",
  [813709740375552] = "Hmph, falta vontade de melhorar!",
  [813709740375296] = "Como controlá-lo? Adicione fogo quando estiver frio, adicione gelo quando estiver quente - é simples assim... no entanto, o tempo e o tempo são muito importantes.",
  [813709740375040] = "Isso não é algo que você possa controlar casualmente. Não recomendo para alunos que acabaram de ingressar no Clube do Tarô ; afinal, é necessário controlar bem os poderes do gelo e do fogo.",
  [813709740374784] = "Você quer usar esse forno?",
  [813709740374528] = "Então não sonhe acordado. Mesmo que haja boa sorte, ela não cairá sobre nossas cabeças.",
  [813709740374272] = "Ah, não.",
  [813709740373760] = "Claro, isso significa tirar 20!",
  [813709740373504] = "O que você quer dizer com sorte explosiva?",
  [813709740373248] = "Ouvi dizer que pessoas com sorte explosiva podem obter recompensas extraordinárias desta fonte!",
  [813709740372992] = "Ah... sobre qual você quer saber?",
  [813709740372736] = "Posso perguntar quais são os efeitos que 'aquelas' poções de Joe têm?",
  [813709740372480] = "Com licença.",
  [813709740372224] = "No passado, eu só pensava nisso como um jogo de quebra-cabeça inventado pelo meu pai. Agora parece mais uma guerra de mesa em miniatura. Um jogo muito charmoso, não é? <P_Heart> (sorri) </>",
  [813709740371968] = "“Implantando tropas e formações, manobrando em todos os sentidos.” — esta é a “linguagem Roselle” que um certo aluno me ensinou; pode não parecer estranho para você.",
  [813709740371712] = "Talvez você possa tentar assistir.",
  [813709740371456] = "Agora, toda vez que venho para a escola, encontro alguém para aprimorar minhas habilidades no xadrez. Se eu puder jogar contra meu pai novamente no futuro, eu definitivamente irei – como você diz – deixá-lo sem uma única peça sobrando.",
  [813709740371200] = "Só depois de jogar alguns jogos com outros alunos percebi que meu entendimento das regras desse tipo de jogo ainda precisa ser melhorado.",
  [813709740370944] = "Isso é ótimo.",
  [813709740370688] = "……Nenhum? Parece que nós dois deveríamos descansar hoje. Hmm, esta é uma revelação que se pode obter sem espiritualidade intuição.",
  [813709740370432] = "Hmm, parece que sua intuição espiritual forneceu uma orientação muito boa. Hoje é um dia propício para descansar!",
  [813709740370176] = "Vou treinar muito, senhorita Justiça.",
  [813709740369920] = "Hehe, não precisa ficar nervoso, é apenas um sparring amistoso. Não vou forçá-lo até que você esteja totalmente preparado mentalmente.",
  [813709740369664] = "Eu me esforçarei para corresponder às suas expectativas, Srta. Justiça.",
  [813709740369408] = "<P_Heart> (Sorrisos) </> Posso dizer que você definitivamente dará tudo de si. E sua força também deve ser suficiente para fundamentar minhas palavras.",
  [813709740369152] = "Mas, felizmente, a salvação chegou. Por favor, acreditem que certamente entraremos em uma era sem trevas sob a liderança do Sr. Tolo.",
  [813709740368896] = "Os residentes da Cidade de Prata mantiveram sua posição por mil anos na noite eterna da Terra Abandonada dos Deuses. Dissipamos a escuridão com a nossa fé e confiamos uns nos outros para sobreviver à longa noite.",
  [813709740368640] = "Encorajar companheiros e trazer luz às trevas é o dever de um Bardo em equipe.",
  [813709740368384] = "Se você encontrar dificuldades, não tenha medo de pedir ajuda aos amigos. É zelando e ajudando uns aos outros que podemos superar desafios difíceis de enfrentar sozinhos.",
  [813709740368128] = "Estou muito feliz que você tenha se juntado ao Clube do Tarô ; todos aqui são seus parceiros.",
  [813709740367872] = "Heh, digerir sua poção o mais rápido possível e melhorar sua força. Só então você será capaz de enfrentar o destino pesado que está por vir.",
  [813709740367616] = "Parece que você gosta de manter seu destino em suas próprias mãos. Embora falte alguma emoção, é uma escolha segura.",
  [813709740367360] = "É assim mesmo? Você pode se preparar para pagar um preço equivalente no futuro... hehe, só estou brincando.",
  [813709740367104] = "Manter um desejo não realizado às vezes é uma forma de sorte. Se eu prometesse realizar o seu maior desejo, você escolheria aceitar ou recusar esse presente inesperado?",
  [813709740366848] = "Todos os presentes do destino já estão marcados com um preço no escuro.",
  [813709740366592] = "Espero que você não se esqueça de agir com cautela fora do clube; a malícia de certas Existências Desconhecidas pode ser muito mais intensa do que você imagina.",
  [813709740366336] = "Hehe, eu posso entender isso. Porém, a curiosidade vem sempre acompanhada de certos perigos.",
  [813709740366080] = "O Clube do Tarô é sem dúvida um milagre, e os nossos alunos demonstram sempre um grande interesse em explorar as suas origens.",
  [813709740365824] = "Alguém disse uma vez que a ressurreição é um milagre. O que você acha que é um verdadeiro milagre?",
  [813709740365568] = "Obrigado pela ajuda. Da próxima vez que eu voltar de New Silver City, trarei para você um saco de doces de leite feitos com cogumelos de leite.",
  [813709740365056] = "Ele pode vir até mim a qualquer momento, então tenho que esperar aqui.",
  [813709740364800] = "Você vê aquele aluno ao meu lado? Ele sempre fica lá e não sai. Talvez ele tenha alguns problemas que queira confiar a alguém.",
  [813709740364544] = "Por que você mesmo não dá a ele?",
  [813709740364288] = "Conduzir a Cidade de Prata em direção à luz, mesmo que isso signifique sacrificar tudo... esse é o significado deste título que o Chefe me ensinou.",
  [813709740364032] = "Chefe... esse era o título na Terra Abandonada dos Deuses. Embora eu tenha assumido o cargo de Chefe na Nova Cidade Prateada em Bayam agora, ainda não consigo quebrar o velho hábito.",
  [813709740363776] = "Ah, esse é o mentor do “Guerreiro” da escola Caminho.",
  [813709740363520] = "Esta é uma especialidade de New Silver City, Black-Faced Wine. Você pode me ajudar a levá-lo ao chefe?",
  [813709740363008] = "{{PlayerName}}, você tem tempo agora?",
  [813709740362752] = "Você joga xadrez? Estou precisando de um oponente.",
  [813709740362496] = "Sim. <P_Heart> (Sorrisos) </> Talvez seja por isso que meu pai sempre me disse para não me enfiar no meu próprio mundo e passar mais tempo com os outros.",
  [813709740362240] = "Podemos ajudar um figurão como você?",
  [813709740361984] = "Dos alunos do Clube do Tarô , ou seja, de todos vocês, ganhei muita ajuda que uma vez lutei para obter, e também desvendei muitos mistérios que não consegui resolver.",
  [813709740361728] = "Agora parece que esta decisão foi correta.",
  [813709740361472] = "O Clube do Tarô é uma tentativa. Meus companheiros e eu descobrimos acidentalmente essa nova possibilidade durante uma viagem.",
  [813709740361216] = "É claro que força suficiente é a base do prazer. Quer você queira percorrer o céu estrelado ou viajar pelos continentes, isso é difícil de conseguir em sequências baixas.",
  [813709740360960] = "Hehe, honestamente, acho que alguns “Aprendizes” buscam o avanço com o propósito de viajar. Hmm, aproveitar a vida é o verdadeiro sentido da vida, afinal.",
  [813709740360704] = "Compartilhei algumas taças de vinho Oulmier com os amigos que encontrei por acaso, e alguns dos pequenos mensageiros que passavam estavam tão bêbados que mal conseguiam distinguir a frente e a traseira.",
  [813709740360448] = "Sim, os hábitos das criaturas do Mundo Espiritual variam. O que passei foi exatamente um aglomerado de criaturas que amam vinho.",
  [813709740360192] = "Amigos de bebida?",
  [813709740359936] = "Ah, você pode imaginar? Até conheci amigos para beber durante minhas viagens!",
  [813709740359680] = "Você pode fazer o que quiser, andando e parando, provocando criaturas estranhas e inofensivas e observando-as girar em círculos.",
  [813709740359424] = "Se não fosse pelas cartas de acompanhamento me incitando a terminar meu manuscrito, não haveria nada mais perfeito no mundo.",
  [813709740359168] = "Ao vagar pelo Mundo Espiritual, sempre não consigo deixar de suspirar. Para um escritor como eu, reunir material é realmente a mais agradável de todas as missões.",
  [813709740358912] = "Você sente isso?",
  [813709740358656] = "Você diz que há algumas coisas que você não vê onde estão? Ah, isso é simples; pegue seu pingente, bola de cristal ou espelho mágico mais acessível e espere pela revelação do destino.",
  [813709740358400] = "Gastamos muito esforço para transformar a escola no lugar confortável e agradável que é agora. Adega, sofás, lareira, livros, camas macias: tudo está disponível e ao seu alcance...",
  [813709740358144] = "Todas as regras estão em constante processo de melhoria e revisão. Este processo requer a participação de todos e não pouparei esforços para ajudar a todos.",
  [813709740357888] = "Mas manter a ordem não significa conformidade e obediência rígidas. Se tiver alguma dificuldade ou insatisfação, pode sempre vir até mim.",
  [813709740357632] = "Como Semideus do \"Árbitro\" Caminho , tenho uma percepção mais apurada da ordem. Manter as regras existentes é tanto uma necessidade de ação como um hábito formado ao longo de muitos anos.",
  [813709740357376] = "Claro, isso também ocorre porque nossa escala é suficientemente simplificada e temos requisitos rígidos para os membros que aderem. Afinal, cada membro entra na escola sob o olhar do Sr. Tolo.",
  [813709740357120] = "Quanto mais próximo o apocalipse, mais se pode sentir que o caos e o conflito estão se tornando a tônica desta era. Lugares tão organizados como a escola quase podem ser contados nas duas mãos.",
  [813709740356864] = "Ocasionalmente penso que se meu neto mais velho não tivesse morrido, provavelmente teria a mesma idade dele...",
  [813709740356608] = "Ficarei feliz em poder atendê-lo.",
  [813709740356352] = "Talvez você esteja certo. Mas desta vez... por favor, transmita-me isso. Considere este o pedido de um velho que tem muito pouco tempo para ficar com seus entes queridos.",
  [813709740356096] = "<P_Heart> (Na verdade atordoado) </> ...Desculpe, nunca pensei nisso.",
  [813709740355840] = "Por que você mesmo não conta a ele?",
  [813709740355584] = "Ele está ficando cada vez mais ocupado agora; com grande poder vem uma grande responsabilidade, mas ainda espero que ele cuide de sua saúde.",
  [813709740355328] = "Falando nisso, espero que você possa lembrar Derrick para mim quando pensar nisso e dizer a ele para organizar sua dieta e dormir razoavelmente.",
  [813709740355072] = "Muitas pessoas que escolheram caminhos que favorecem o fortalecimento do corpo para ingressar no Mundo Extraordinário perderam a vida por causa disso. Você também deve ter cuidado.",
  [813709740354816] = "No entanto, a melhoria das capacidades físicas não significa que você se tornou um homem de ferro indestrutível.",
  [813709740354560] = "Beyonders do Guerreiro Caminho possui uma Defesa que quase ninguém abaixo do alto Sequência pode quebrar; mesmo as balas de rifle dificilmente podem nos prejudicar.",
  [813709740354304] = "<P_Heart> (Sorrindo) </> Minha escolha é igual à sua. Esta é também a razão pela qual me tornei mentor no Clube do Tarô .",
  [813709740354048] = "Farei o meu melhor para proteger esta luz.",
  [813709740353792] = "Agora, a luz está bem na minha frente; pode ser extinto ou pode queimar – isso depende das escolhas de todos nós.",
  [813709740353536] = "Para os ex-cidadãos de Silver City, a graça ocasionalmente dada pelos deuses poderia ser retirada a qualquer momento.",
  [813709740353280] = "Acho que você deveria saber que a Terra Abandonada dos Deuses foi capaz de encerrar seu sofrimento milenar sob a proteção do \"Tolo\".",
  [813709740353024] = "Caso contrário, a projeção de uma alma morta não poderia permanecer na realidade por tanto tempo.",
  [813709740352768] = "A escola é um lugar muito especial. Até certo ponto, você pode considerar este um canto do reino divino do Sr. Louco.",
  [813709740352512] = "Talvez da próxima vez eu deva convidar você para praticar comigo no Campo de Treinamento?",
  [813709740352256] = "Na verdade, este Caminho também ganhará habilidades de ataque e defesa não menos que outras nos estágios posteriores. Mas nem todo mundo acredita nisso.",
  [813709740352000] = "Muitas vezes ouço estudantes reclamarem que os “Espectadores” não têm habilidade de combate direto em sequências baixas e só podem servir como suporte.",
  [813709740351744] = "Não se preocupe, você terá uma conversa agradável.",
  [813709740351488] = "Se você realmente não tem coragem de dar o primeiro passo, posso lhe dar um leve empurrão.",
  [813709740351232] = "Hmm, talvez você devesse tentar interagir com mais alunos.",
  [813709740350976] = "Não importa de onde você venha, lembre-se sempre que você pode voltar para cá.",
  [813709740350720] = "Sempre esperamos que, além de ensinar habilidades extraordinárias, a escola também se tornasse um lar permanente para todos neste mundo.",
  [813709740350464] = "Fico feliz em ouvir você dizer isso.",
  [813709740350208] = "Oh, por favor, perdoe minha preocupação um pouco excessiva. Afinal, quando eu trouxe você aqui pela primeira vez, sua cabeça estava cheia de perguntas e você não sabia onde encontrar as respostas.",
  [813709740349952] = "Você está se acostumando a ficar na escola?",
  [813709740349696] = "Você não sofrerá de insônia se passar mais algumas noites inteiras.",
  [813709740349440] = "Isso, isso é chá com leite! Você não deveria me ensinar como preparar uma poção para dormir?",
  [813709740348928] = "Deixe ferver... adicione 150 mililitros de leite integral... mexa...",
  [813709740348672] = "12 folhas frescas da árvore do chá Snowy Mountain...",
  [813709740348416] = "8 gramas de canela em pó... 100 mililitros de água pura...",
  [813709740347904] = "No dia em que eu subir no palco, vou convidá-lo para assistir à apresentação, você deve vir!",
  [813709740347648] = "Entenda o que...",
  [813709740347392] = "Tudo bem, eu entendo.",
  [813709740346880] = "Você já arriscou sua vida para realizar seu sonho?",
  [813709740346624] = "Você tem um sonho? Qual é o seu sonho?",
  [813709740346368] = "Senhorita Pombo... haha! Sou um louco que fala com pombos...",
  [813709740346112] = "Haha... Covarde... Você está certo! *hic*, eu sou... eu sou um covarde... Um covarde desavergonhado, vil e desprezado...",
  [813709740345856] = "<P_Heart> (Ele parecia não ouvir suas palavras, murmurando para si mesmo, imerso em tristeza novamente.) </>",
  [813709740345600] = "Hic... Senhorita Pombo, você acha que eu não sou tão bom quanto um Babuíno de Cabelo Encaracolado?",
  [813709740345344] = "Eu sou apenas um pedaço de lixo... *hic*...",
  [813709740345088] = "Mas como enfrentá-la... Passei dez anos no mar e tive um olho cegado por piratas. Quando ganhei libras de ouro suficientes e voltei, descobri que minha amante estava gravemente doente... Não ousei contar à pequena Liddy que a mãe dela já tinha...",
  [813709740344832] = "Passo o dia todo... *hic*, bebendo aqui. Deixando minha filha na loja... Ela ainda é tão pequena, mas eu... *hic*, falhei em cumprir minha responsabilidade como pai...",
  [813709740344576] = "Eu sou terrível? Você, você me diz... *hic*... Wuwu, minha filha, minha sensata e pobre Liddy...",
  [813709740344320] = "Mas por enquanto não fornecemos sobremesas, porque minha mãe foi para Backlund para continuar os estudos e ela é a melhor confeiteira!",
  [813709740343040] = "Mesmo que mamãe e papai não estejam aqui, posso cuidar bem dos convidados.",
  [813709740342784] = "Seus pais não estão aqui? Por que você foi deixado aqui sozinho?",
  [813709740342528] = "<P_Heart> (Fungando) </> Uh, está um pouco frio, isso é uma revelação de Deus?",
  [813709740342272] = "A Igreja não manda alguém para cuidar disso!",
  [813709740342016] = "De fato.",
  [813709740341760] = "Há realmente cada vez mais loucos!",
  [813709740341504] = "Oh, Tempestades acima, enviem rapidamente o castigo divino e afastem este louco!",
  [813709740341248] = "Senhor, grande tempestade, por favor, tenha piedade de minha alma ardente e lave a sujeira do meu coração!",
  [813709740340992] = "Uma piada? Aqueles que não são piedosos o suficiente são a piada!",
  [813709740340736] = "Cale-se! Olha, todo mundo ao redor está rindo de você!",
  [813709740340480] = "A Tempestade está acima, a água é o lar eterno dos seguidores da Tempestade! Como voltar ao momento do nascimento, banhar-se na água azul do mar...",
  [813709740340224] = "Droga, você tem que ficar na água?",
  [813709740339968] = "Estou com muito medo, você estaria disposto a ajudar?",
  [813709740339712] = "Por que ninguém chamou a polícia... Minhas pernas, minhas pernas ficaram fracas...",
  [813709740339456] = "Ah, ah! Você está certo, não entre na diversão, não entre na diversão.",
  [813709740339200] = "Shh, fale baixo, não deixe o doente mental ouvir você!",
  [813709740338944] = "Mãe, por que aquele homem ali está mergulhado na água... tão estranho.",
  [813709740338688] = "Chame a polícia... chame a polícia primeiro...",
  [813709740338432] = "Fiquei em Backlund por tanto tempo e nunca vi uma situação em que a polícia não viesse manter a ordem após a ocorrência de um caso!",
  [813709740338176] = "Assassinato! Só existe uma verdade! Alguém deve ter sido morto aqui!",
  [813709740337920] = "O que aconteceu?",
  [813709740337664] = "O que você está olhando? Esta estrada está bloqueada! Você não consegue ver!",
  [813709740337408] = "Quão incivilizado! Um canteiro de flores perfeitamente bom foi corrompido!",
  [813709740337152] = "Fui espancado por um gato... dói.",
  [813709740336384] = "<P_Heart> (Você aproveitou a desatenção do lojista para acariciar secretamente o gatinho) </>",
  [813709740336128] = "<P_Heart> (O gatinho soltou um leve ronco) </>",
  [813709740335872] = "Bem-vindo! Não há necessidade de olhar em volta, sou o dono desta loja.",
  [813709740335616] = "Mas eu realmente preciso desse trabalho...",
  [813709740335360] = "Sir Dervill é um bom homem, não posso evitar isso amanhã... preciso ir... trabalhar...",
  [813709740335104] = "Se a Deusa não está disposta a me dar uma torta, por que ela me deixou cheirar a torta?",
  [813709740334848] = "Obrigado, agradeço em nome deles.",
  [813709740334592] = "Eu farei isso e contarei aos outros alunos também.",
  [813709740334336] = "Ei, quando você pegar emprestado Artefatos Selados, tente ser legal com eles... não deixe chover sobre eles.",
  [813709740334080] = "Aquele cara, Spring, tem um temperamento estranho, mas trata meus amigos com certo carinho, então deixe-o em paz.",
  [813709740333824] = "Hehe... é que todos eles se tornaram Artefatos Selados agora.",
  [813709740333568] = "...... Não me olhe assim, eu não tenho aquele hobby especial de Spring. Gosto de ficar aqui porque meus amigos estão todos aqui.",
  [813709740333312] = "Não, foi você quem tocou no assunto primeiro... Certo, tosse, qual é o seu propósito ao dizer isso? Qual é o motivo? Quem te instigou? Você foi enfeitiçado por alguma entidade perigosa? Venha comigo!",
  [813709740333056] = "<P_Yellow> Tosse tosse tosse tosse tosse não, eu não disse nada! Por favor, esqueça! </>",
  [813709740332800] = "Além de fazer as pessoas crescerem com chifres e rabos, se tornarem fortes e trabalhadoras, e serem capazes de mugir... <P_Heart> (Sentindo-se gradualmente culpado) </> , há algum outro benefício em cruzar humanos e vacas?",
  [813709740332544] = "Tosse, tosse... Meu Deus, o que você está pensando? Eu não pensei, não pensei em uma coisa tão bizarra!",
  [813709740332288] = "Ah, isso mesmo, você realmente me entende! Este seria um avanço que marcou época!",
  [813709740332032] = "Se eu pudesse aprender as etapas operacionais detalhadas, então teria uma ideia ousada...",
  [813709740331776] = "Ouvi dizer que um grande biólogo certa vez cruzou trigo com miudezas bovinas. Este é um enorme salto evolutivo na genética das espécies! Sempre fiquei curioso para saber por que não há documentos relacionados em lugar nenhum.",
  [813709740331008] = "Pretendo fazer uma placa clássica, da-da-da-da! “O vento que sente sua falta soprou para Clube do Tarô”, que tal?",
  [813709740330752] = "“Dá uma sensação de lar.”",
  [813709740330496] = "Ah, alguém recentemente fez uma sugestão na caixa de correio do Presidente, na esperança de adicionar algumas decorações dentro da escola...",
  [813709740330240] = "Do que vocês estão falando?",
  [813709740329728] = "Isso é algo sobre o qual podemos conversar? Oh meu Deus, você não disse nada! Eu não ouvi nada! Vamos encerrar esse assunto rapidamente...",
  [813709740329472] = "Essa é uma história não oficial. De acordo com a tese, só pode ser comprovado que Ele e a Presidente Bernadette mantêm uma relação de cooperação, inferindo-se assim o Seu significativo papel no processo de fundação... <P_Heart> (Divagando) </>",
  [813709740329216] = "Claro! Esta é a pedra angular da escola de Clube do Tarô. Temos razões suficientes para acreditar que o Sr. Tolo é o patrocinador do Clube do Tarô ... <P_Heart> (Falando incessantemente) </>",
  [813709740328960] = "Há algum sentido em discutir isso...",
  [813709740328704] = "Aterrorizante... ser capaz de abrir um mundo no Mundo Espiritual e construir uma estrutura tão magnífica, admiro cada vez mais o figurão por trás dela.",
  [813709740328448] = "Este é um verdadeiro milagre! Não esperava que algo de tão alto nível fosse colocado no lugar mais visível.",
  [813709740328192] = "Hehe... Se você está curioso sobre essa poção, sugiro que vá direto ao salão e peça um copo de vodca para a dona Amanda. No entanto, seu sabor é provavelmente um pouco melhor que o da vodca...",
  [813709740327936] = "Ele pode mantê-lo atualizado a noite toda e você definitivamente não adormecerá nos arquivos. O efeito é provavelmente dez vezes maior que o do café.",
  [813709740327680] = "Oh, esta é minha poção favorita! Fará você sonhar continuamente a noite toda e funciona melhor quando usado na Sala de Astrologia.",
  [813709740327424] = "Ouvi passos, por favor me deixe em paz, deixe-me dormir... não vou incomodar ninguém. Quanto mais perto estou do Mundo Espiritual, mais informações posso capturar... incluindo os sonhos dos que partiram...",
  [813709740327168] = "Uh, embora ele já tenha se tornado um crente na Fonte da Purificação...",
  [813709740326912] = "Você pode acusar o antigo eu de ser um mentiroso, mas agora sou um verdadeiro Vidente; até o materialista mais teimoso se curvou diante do meu astrolábio!",
  [813709740326656] = "Estou esperando a chegada de um certo pianista.",
  [813709740326400] = "No entanto, eles parecem estar realizando missões importantes. É isso que querem dizer com “pesada é a cabeça que usa a coroa”...",
  [813709740326144] = "Suspiro, se eu pudesse ser como os mentores. Quero fazer 100 projeções históricas de mim mesmo e viajar por todos os continentes sem sair de casa.",
  [813709740325888] = "Onde está o próprio Sr. Merlin agora?",
  [813709740325632] = "Não entende o que quero dizer? Isso é bom. Desculpe, não vou acompanhá-lo em conversas fúteis. Eu tenho coisas para fazer.",
  [813709740325376] = "Se sua intenção é proferir algumas palavras indelicadas, por favor, desista.",
  [813709740325120] = "Ah, desculpe, eu não estava falando com você. Você não parece ser meu amigo.",
  [813709740324864] = "Deixe-me pensar, você deveria encontrar na escola a pessoa que mais gosta de dormir; ela lhe dará uma avaliação honesta do produto.",
  [813709740324608] = "Ei, não posso dizer. Se você realmente quer saber, por que não perguntar a quem os comprou sobre sua experiência.",
  [813709740324352] = "Quais são os seus efeitos?",
  [813709740324096] = "Que tipo de poção você quer comprar? Atualmente tenho \"Dream of Angerwade\", \"Night-Visiting Witch\" e \"Fire-Bathed Ouroboros\".",
  [813709740323840] = "Tudo bem... os jovens de hoje em dia realmente carecem de espírito empreendedor. Suspiro, o que acontecerá com o apocalipse...",
  [813709740323584] = "Eu me recuso a responder.",
  [813709740323328] = "Mas você sabe quando, onde e em que circunstâncias o Imperador Roselle disse isso? Você não sabe disso, certo? Naquele dia, Roselle estava andando na estrada... <P_Heart> (Divagando) </>",
  [813709740323072] = "Resposta correta, parece que você se adaptou bem.",
  [813709740322816] = "É o Imperador Roselle.",
  [813709740322560] = "“Os livros são a escada do progresso humano”... deixe-me testar você, quem disse isso?",
  [813709740322304] = "De qualquer forma, primeiro tenho que encontrar um lugar para me esconder... seria ruim se eu fosse pego estudando a noite toda, dependendo secretamente de poções.",
  [813709740322048] = "Aqueles dois idiotas lá embaixo, não sabem ficar quietos na biblioteca?",
  [813709740321792] = "V-você, você é simplesmente desprezível demais!",
  [813709740321536] = "Espere, por que você não vem comigo?",
  [813709740321024] = "Hum-hmm, vá em frente.",
  [813709740320768] = "Deixe-me pensar, Ken adora relaxar, ele provavelmente está na sala e Sarah deveria estar ajudando a limpar o escritório do presidente...",
  [813709740320512] = "Hum-hmm.",
  [813709740320256] = "Você tem razão! Eu irei agora.",
  [813709740320000] = "Não fique nervoso, ninguém está culpando você. Por que você não chama todo mundo? Nosso objetivo futuro não é sermos colegas de universidade?",
  [813709740319744] = "O-o que você está dizendo! Eu não traí nosso grupo de estudos!",
  [813709740319488] = "Você não está aqui também? Se você não tivesse me encontrado, você planejava ficar acordado a noite toda se preparando para o vestibular nas nossas costas?",
  [813709740319232] = "Vamos, meu amigo, se você não tiver educação, você só pode ser um pirata. Você não quer entrar na Backlund University?",
  [813709740318976] = "Estudando em segredo novamente. Hmph, como pode haver uma pessoa tão tortuosa como você no mundo?",
  [813709740318720] = "Esqueça, vou perguntar à Bessie mais tarde...",
  [813709740318464] = "Torta Dixi? Ensopado de ervilha com cordeiro? ...Ou talvez costelinha de vaca Dagya refogada?",
  [813709740318208] = "O que comer esta noite...",
  [813709740317952] = "Decidi ignorar Peter o dia todo hoje. Na verdade, ele disse que minha roupa era estranha, quando eu estava claramente imitando a Presidente, e ela é sem dúvida a líder de toda a tendência de moda da escola!",
  [813709740317696] = "Hum... interessante. A Grande Civilização Antiga já pereceu, mas depois que a humanidade sobreviveu, eles reconstruíram uma sociedade próspera. A ordem é um sinal de estabilidade da civilização? Obrigado pela sua resposta.",
  [813709740317440] = "A verdadeira natureza do mundo é a ordem, o retorno ao estado original é inevitável.",
  [813709740317184] = "Hum... Interessante. Construir a ordem com base no que se considera “correção” também é uma forma de desordem? Obrigado pela sua resposta.",
  [813709740316928] = "A verdadeira natureza do mundo é a desordem, por que não fazer o que bem entendemos?",
  [813709740316672] = "Estamos tentando estabelecer a ordem num mundo caótico, como andar sobre um cabo de aço no ar. O que a humanidade está fazendo agora é uma mudança necessária ou um autocontrole sem sentido?",
  [813709740316416] = "A ordem poderosa é incrivelmente perigosa. Isso fará com que você lute contra a dor, mas você só pode duvidar de si mesmo: fiz algo errado? Você não conseguirá perceber o erro do pedido em si.",
  [813709740316160] = "Ela escreve regras, usa regras, aprisiona seus inimigos e os força a um beco sem saída.",
  [813709740315904] = "Você já ouviu falar do Livro de Bronze Trunsoest?",
  [813709740315648] = "Eu só quero ficar com meu amigo boneco de madeira para sempre.",
  [813709740315392] = "Uh, desculpe, se você está procurando um parceiro de treino, você deveria perguntar a Sodoma, ou encontrar um boneco de madeira como eu fiz.",
  [813709740315136] = "Se um dia você se cansar da vida como ele, lembre-se de procurar um 'psiquiatra'.",
  [813709740314880] = "Não olhe para Haze desse jeito; ele costumava ser um capitão muito bom também.",
  [813709740314624] = "Às vezes ele olha para a multidão rindo com uma expressão atordoada, soltando um longo suspiro...",
  [813709740314368] = "O mentor Colin parece ser o mais especial de todos os mentores.",
  [813709740314112] = "Hehe... Você vai entender quando acabar como eu.",
  [813709740313856] = "Não vire as costas para ninguém, mesmo para um companheiro com quem você já treinou.",
  [813709740313600] = "Vou esperar por ele aqui.",
  [813709740313344] = "Acho que Martin está lá fora. Se você o vir, ajude-me a passar uma mensagem: se você quer progredir, deve enfrentar o seu medo.",
  [813709740313088] = "Eu era um Guerreiro que evitava treinar, até...",
  [813709740312832] = "Ótimo, então vamos para o salão dançar!",
  [813709740312576] = "......Tudo bem, onde você quer ir? Vou acompanhá-lo daqui a pouco.",
  [813709740312320] = "Esqueça, prefiro admirar mais essas obras.",
  [813709740312064] = "Não necessariamente... Poderíamos também explorar os mistérios não resolvidos escondidos na escola?",
  [813709740311808] = "Você quer dizer que deveríamos ir para o campo de treinamento e bater uns nos outros agora?",
  [813709740311552] = "Ei, nós realmente temos que ser tão improdutivos?",
  [813709740311296] = "Além disso, não tente forçá-lo, caso contrário, terei que considerar levá-lo a tribunal!",
  [813709740311040] = "É um mensageiro contratado por um amigo meu, que atualmente entrega algumas... cartas insignificantes. Não, é um diário que trocamos para testemunhar a nossa amizade, não deve ser perdido.",
  [813709740310784] = "Observe que ele manca levemente e pode cheirar a álcool.",
  [813709740310528] = "Se acontecer de você encontrar uma criatura segura feita de ossos brancos empilhados no Mundo Espiritual, certifique-se de dar uma carona.",
  [813709740310272] = "Estou preparado para enfrentar tudo. Ah, louvado seja o Louco!",
  [813709740310016] = "Oh, você precisa da minha força também? Não tem problema, esta é minha boa sorte, minha honra e uma responsabilidade que devo assumir.",
  [813709740309760] = "No momento em que penso em amizade e vínculos, sinto-me cheio de força!",
  [813709740309504] = "Você não está curioso? Quer dizer, as pessoas sempre ficam cansadas, até mesmo os santos da Igreja.",
  [813709740309248] = "Não se preocupe comigo, não farei nada. Eu só quero assistir.",
  [813709740308992] = "Estou esperando, Mentor Derrick, pelo momento em que você se sentir exausto.",
  [813709740308736] = "Se tiver tempo, você pode entrar e ajudar o Sr. Scharf.",
  [813709740308480] = "Cansado? Você ouviu errado, eu quis dizer que esse cinto está um pouco apertado. Tenho a sorte de poder tocar em máquinas tão precisas e perfeitas.",
  [813709740308224] = "Eu não quero brigar! Não posso vencer de jeito nenhum...",
  [813709740307968] = "Shh! Shh... fale baixo, você pode me devolver primeiro? O tempo que combinei com a Sra. Fors está quase acabando...",
  [813709740307712] = "Ah, você está falando do romance “Little Naughty in the Spirit World” que você escreveu? Eu gosto mais da parte em que o fantasma travesso irrita mais a Duquesa do Castelo, é...",
  [813709740307456] = "Não! <P_Heart> (Sussurrando) </> 'Aquele' manuscrito... como está? Você terminou de ler?",
  [813709740307200] = "Por que você me chamou? Você finalmente está interessado em 'Fundamentos da Fabricação Mecânica'?",
  [813709740306944] = "<P_Heart> (Resmungando) </> Não, eu nem perguntei ainda, por que você me bateu, wuwuwu...",
  [813709740306688] = "Uau! Aaaaaah, sinto muito, Lorde Arrodes! Não tive a intenção de dificultar as coisas para você, ah, não, não tive a intenção de incomodá-lo com questões tão triviais!",
  [813709740306432] = "<P_Heart> (Uau... Um raio de repente atingiu o topo da cabeça de Taelon, queimando seu cabelo!) </>",
  [813709740306176] = "Vou perguntar assim: Espelho, espelho, quem é a pessoa mais linda da escola? —Que tal isso?",
  [813709740305920] = "Então, o que você vai perguntar mais tarde? ...Eh, o olho atrás do espelho parece estar olhando para você?",
  [813709740305664] = "Claro, compilei um 'Guia completo para perguntas e respostas de Arrodes', que foi testado várias vezes. Os dados provam que o espelho mágico não tornará as coisas muito difíceis para os alunos.",
  [813709740305152] = "Pretendo fazer algumas perguntas difíceis a Arrodes.",
  [813709740304896] = "Vá para casa, vá para casa... Suspiro, se fosse assim tão fácil ir para casa, eu já teria voltado há muito tempo.",
  [813709740304640] = "O que é ainda mais ridículo é que alguns dizem que se você acertar três vezes seguidas, você pode ir para casa...",
  [813709740304384] = "Não sei de onde veio a notícia, dizendo que se você virar as costas para a Fonte da Purificação, segurar uma moeda na mão direita e jogá-la na água, por cima do ombro esquerdo, poderá realizar seu desejo.",
  [813709740303872] = "Não dê ouvidos a boatos... Como isso se espalhou até agora?",
  [813709740303616] = "Acho que você é pior que um peixe salgado; pelo menos um peixe salgado é comestível! O que você pode fazer além de aumentar minha carga de trabalho!",
  [813709740303360] = "Uh, não, ainda estou tentando... Uma pessoa deve ter sonhos; caso contrário, qual a diferença entre eles e um peixe salgado?",
  [813709740303104] = "...... Você já lançou isso?",
  [813709740302848] = "Rolou 20! Sucesso crítico!",
  [813709740302592] = "Transbordando sorte?",
  [813709740302336] = "Não fique com raiva... Ouvi dizer que jogar uma moeda aumenta a sorte, e pessoas com muita sorte podem obter recompensas extraordinárias na Fonte da Purificação!",
  [813709740302080] = "Mas não há necessidade de ficar muito nervoso. Como 'psiquiatra' sênior, posso responder à maioria das suas perguntas relacionadas.",
  [813709740301824] = "Independentemente de você ter ouvido este aviso, devo lembrá-lo novamente: “Cuidado com os espectadores”.",
  [813709740301568] = "Se aparecerem muitas coincidências ao seu redor, não as ignore; eles podem ser o trabalho de um alto Sequência \"Espectador\".",
  [813709740301312] = "O destino lhe deu um caminho difícil, mas não tema o futuro; o \"Tolo\" cuidará de você.",
  [813709740301056] = "A sala de literatura acolhe todos que anseiam por conhecimento.",
  [813709740300800] = "Não há necessidade de ser reservado. O título de Presidente não significa que haja uma diferença de status entre você e eu; Aceitei-o apenas porque aceitei as responsabilidades e obrigações que o acompanham.",
  [813709740300544] = "Olá, {{PlayerName}}.",
  [813709740300288] = "Qualquer má conduta dentro da escola pode ser denunciada para mim, fique tranquilo, a fonte da informação será mantida estritamente confidencial.",
  [813709740300032] = "Olá, você está aqui para orar ou há alguma corrupção problemática que precisa ser dissipada pela luz?",
  [813709740299776] = "Ele sempre trabalha tanto que isso me preocupa... Se você conhecer o Porter, lembre-se de dizer a ele para vir ao lounge para relaxar quando tiver tempo, e não se pressione muito.",
  [813709740299520] = "Como amigo dele, realmente sou um pouco negligente em meu dever. Veja, não consigo encontrá-lo novamente agora.",
  [813709740299264] = "Porter sempre gosta de se esconder para cantar.",
  [813709740299008] = "Se possível, espero que você mantenha isso em segredo dos outros.",
  [813709740298752] = "Para falar a verdade, quero ganhar a surpresa e os aplausos de todos no próximo recital. Está muito quieto aqui, não é?",
  [813709740298496] = "Por que você está praticando aqui sozinho?",
  [813709740298240] = "Então o que você quer? Se não houver nada, não me incomode. O primeiro passo para se tornar um Aprendiz qualificado é aprender a usar o forno sozinho.",
  [813709740297984] = "Se você estiver interessado em todos os três itens acima, recuso-me a forjar armas para você.",
  [813709740297728] = "As coisas que mais odeio na minha vida são peixes e cogumelos, e aqueles malucos do Plantador Caminho !",
  [813709740297472] = "Para lutar lado a lado com as pessoas que você deseja proteger, você deve aprender muito mais conhecimento do que imagina e se tornar mais forte.",
  [813709740297216] = "Tudo o que você aprendeu sobre Beyonder conhecimento pode se tornar uma lâmina para derrotar inimigos.",
  [813709740296960] = "“Conhecimento é Poder” – esta não é uma afirmação simbólica.",
  [813709740296704] = "A cooperação moderada pode alcançar o dobro do resultado com metade do esforço, mas a confiança excessiva é uma fraqueza que, mais cedo ou mais tarde, se tornará uma falha fatal numa crise.",
  [813709740296448] = "Orar aos deuses e buscar ajuda na escola pode resolver algumas de suas dificuldades, mas não tenha preguiça de melhorar suas próprias forças.",
  [813709740296192] = "Ha! Não há necessidade de invejar os dons inatos dos vampiros. Contanto que você trabalhe duro, você também pode fazer isso. É claro que o produto final pode não ser tão bom quanto o de um especialista, mas já merece elogios.",
  [813709740295936] = "Ah, esqueci, você não é um vampiro. Então este missão pode ser bastante desafiador para você.",
  [813709740295680] = "<P_Heart> (Limpando a garganta) </> Preparar poções não depende muito de talento. Antes de procurar ajuda, tente primeiro fazer isso sozinho.",
  [813709740295424] = "Tocar uma senhora casualmente não é um comportamento educado. Se você se sentir deprimido, posso lhe fornecer aconselhamento psicológico profissional.",
  [813709740295168] = "<P_Heart> (Ela olha para você, e sob seus olhos claros e sábios, todos os seus pensamentos parecem não ter onde se esconder.) </>",
  [813709740294912] = "Portanto, passo a maior parte do meu tempo aqui orientando e ajudando os alunos a melhorar sua habilidade de combate, independente de você ter escolhido o “Guerreiro” Caminho .",
  [813709740294656] = "Depois de entrar no meio e alto Sequência , Beyonders do Guerreiro Caminho são muito hábeis em descobrir as fraquezas de diferentes monstros; até certo ponto, essas experiências também podem ser aplicadas aos humanos.",
  [813709740294400] = "Hehe, estou brincando. Tem muita gente séria na escola, acho que às vezes precisamos ajustar o clima.",
  [813709740294144] = "O ambiente aqui sempre deixa as pessoas com um pouco de sono, não acham? Se não se chamasse “escola” mas sim “salão”, com certeza seria muito mais interessante.",
  [813709740293888] = "Obrigado, aguardo seu voto quando chegar a hora.",
  [813709740293632] = "Mas espero que todos os cidadãos de Tingen possam sentir-se cuidados e respeitados; este é o ideal pelo qual quero lutar por toda a minha vida.",
  [813709740293376] = "Esta é, obviamente, uma das razões importantes pelas quais quero entrar na política. Esta era está mudando rapidamente, algumas pessoas conseguem acompanhar, outras podem ficar para trás.",
  [813709740293120] = "Exatamente, exatamente! E se Rina for eleita prefeita com sucesso, ela será a primeira mulher prefeita na história de Tingen!",
  [813709740292864] = "Ele é uma boa pessoa, mas sua perspectiva é sempre olhar de cima para baixo, e há muitas pessoas destinadas a não serem vistas.",
  [813709740292608] = "Sir Dervil fala bem, mas na realidade não é adequado para ser prefeito. Se você me perguntar, deveríamos deixar Reina ser a próxima prefeita.",
  [813709740292352] = "Senhora, sobre o que vocês estão conversando?",
  [813709740292096] = "Eu vou, obrigado.",
  [813709740291840] = "{{jovem Sr.|jovem Sra.}}, obrigado por estar disposto a me ouvir divagar tanto. Minha vida é muito simples, mas espero que você persista em fazer o que deseja, seja mais corajoso e não seja muito influenciado pelos outros.",
  [813709740291584] = "Pensando bem, não há como evitar nesta vida.",
  [813709740291328] = "Coisas que não ousei comprar durante décadas, posso comprar casualmente agora, mas não consigo mais mastigar comidas deliciosas, não consigo mais engolir bebidas saborosas e não tenho coração nem energia para as coisas que queria fazer.",
  [813709740291072] = "Agora finalmente ninguém me pede para esperar, mas parece que muitas coisas... já perdi.",
  [813709740290816] = "Sim, meu jovem, eu também penso assim. Quando eu era jovem, sempre me pediram para desistir de tudo de bom para meu irmão mais novo e, mais tarde, para meu filho.",
  [813709740290560] = "Não mencione isso, estou tão velho agora. Quando estou velho, não consigo mais dançar.",
  [813709740290304] = "Pensando bem, no início eu era o líder do Grupo de Dança Tingen, mas depois minha família me disse para priorizar o cuidado da criança e esperar até que ela crescesse para seguir meus hobbies.",
  [818107786466048] = "Oh? Então, de acordo com o princípio da reciprocidade, você está pronto para responder à Sua pergunta?",
  [813709740289792] = "Ah, ainda lembro que há mais de trinta anos ele disse que me ligaria, mas tive que esperar um pouco, e essa espera dura até hoje.",
  [813709740289536] = "<P_Heart> (Silencioso) </> Não é uma questão de bom ou ruim, é apenas viver a vida.",
  [813709740289280] = "<P_Heart> (Sorrindo amargamente) </> Mais tarde, entrei na fábrica, nunca mais fui à escola e me casei com um homem que meus pais arranjaram para mim.",
  [813709740289024] = "Quando eu era jovem, minhas notas eram muito boas, mas minha família disse: deixe-me esperar, espere até meu irmão mais novo terminar a escola.",
  [813709740288768] = "Suspiro, sim e não. Parece que me acostumei a ter meu destino arranjado por outras pessoas.",
  [813709740288512] = "Não, não é assim. Pelo contrário, a vida agora é muito melhor, recebi uma grande herança.",
  [813709740288256] = "É porque sua vida passada foi muito boa?",
  [813709740288000] = "Desculpe... por incomodar você. Eu simplesmente... simplesmente não consigo me adaptar à minha vida atual.",
  [1130504917095680] = "...... eu vi ...... foi realmente muito, muito bom -",
  [813709740287232] = "Tudo bem, mas eles estão todos dormindo hoje, outro dia, outro dia {{irmão mais velho | irmã mais velha}} vou levar você para conhecê-los!",
  [813709740286720] = "Tudo bem, mas eles estão todos dormindo hoje, outro dia, outro dia eu trarei {{irmão mais velho|irmã mais velha}} para conhecê-los!",
  [813709740286464] = "Que ótimo, também quero conhecer esses amigos!",
  [813709740286208] = "Sim, desde que conheci esses bons amigos, Fula nunca mais se sentiu sozinha!",
  [813709740285952] = "Sim, eles são tão bons para mim. Quando quero tomar sol, o Oceano me deixa ir para o lugar com melhor sol, e quando quero descansar, a Praia me deixa ir para a sombra.",
  [813709740285696] = "Então, você pode ouvi-los conversando?",
  [813709740285440] = "Eu não inventei isso! Eles mesmos me disseram, este cacho de flores na minha frente se chama Oceano, a árvore mais alta à esquerda se chama Praia e a árvore mais baixa à direita se chama Elfo.",
  [813709740285184] = "Tudo bem, vamos jurar, está combinado!",
  [813709740284928] = "Então {{irmão mais velho | irmã mais velha}}, venha me ver novamente quando tiver tempo, talvez até lá eu já tenha florescido.",
  [813709740284672] = "Claro que é verdade, quando tiver tempo irei aprender com você, também quero desabrochar lindas florzinhas.",
  [813709740284416] = "Sério, {{irmão mais velho | irmã mais velha}}, estou aqui há muito tempo, você é a primeira pessoa disposta a dizer isso para mim.",
  [813709740284160] = "Nenhum amigo quer brincar comigo... todos dizem que sou muito estranho, mas flores e plantas são diferentes; eles são todos meus bons amigos.",
  [813709740283904] = "É assim mesmo. Então pequena Fula, por que você quer virar flor?",
  [813709740283648] = "Sim, claro que tenho que absorver os nutrientes rapidamente para poder florescer minhas próprias flores em breve.",
  [813709740283392] = "Isso mesmo, sou uma florzinha que está crescendo.",
  [813709740283136] = "Pequena, você disse que é...",
  [813709740282880] = "Sim, não só temos romantismo mas também falamos das dificuldades da vida. Isso me faz sentir ainda mais que deveria ter a responsabilidade de um homem.",
  [813709740282624] = "{{Sr.|Sra.}}, você é a primeira pessoa a me abençoar, estou muito feliz!",
  [813709740282368] = "{{Sr.|Sra.}}, você não é a primeira pessoa a dizer isso para mim, mas vou persistir!",
  [813709740282112] = "Eu também fiz essa pergunta, ela disse que me sente muito especial, diferente dos homens que ela conheceu antes, dando-lhe uma sensação de distanciamento.",
  [813709740281856] = "<P_Heart> (Algo parece errado) </> Quer dizer, você a conheceu enquanto bebia? É possível que ela diga isso para todo mundo?",
  [813709740281600] = "Ah... isso, parece que realmente esqueci de perguntar. Vou perguntar a ela na próxima vez que for à taverna, ela trabalha lá.",
  [813709740281344] = "Pergunte, meu amor por ela está muito firme agora!",
  [813709740281088] = "Ela quer morar comigo e eu quero suportar as tempestades da vida com ela.",
  [813709740280832] = "Eh, você é tão inteligente, como você adivinhou isso? Ela tem um irmão mais novo na escola, suspiro, o fardo de uma família de quatro pessoas recai todo sobre ela.",
  [813709740280576] = "Suspiro, isso não é tudo, ela também tem um irmão mais novo na escola. O fardo de uma família de quatro pessoas recai todo sobre ela.",
  [813709740280320] = "Deixa eu continuar, ela também tem uma mãe acamada com doença, e agora os remédios estão muito caros, e o asilo também não tem vaga para ela.",
  [813709740280064] = "Ela tem um pai jogador que fez com que a família devesse muito dinheiro, então ela mesma teve que sair para trabalhar...",
  [813709740279808] = "Onde nos conhecemos não é importante, o importante é que ela confie em mim e me conte sobre sua história.",
  [813709740279552] = "Para falar a verdade, nos encontramos pela primeira vez hoje. Mas, eu já me apaixonei profundamente por ela.",
  [813709740279296] = "Ah... desculpe, ainda não somos casados.",
  [813709740279040] = "Amiga, me diga, se o filho que ela e eu tivermos no futuro for um menino, que tal chamá-lo de Tom, e se for uma menina, chamá-la de Jéssica?",
  [813709740278784] = "Assim que eu me tornar um romancista tão famoso quanto Fors Wall, deixarei você fazer esse curso.",
  [813709740278528] = "Não me despreze também; Serei um grande romancista no futuro, assim como o famoso Fors Wall!",
  [813709740278272] = "Todos os navios nesta doca ostentam a bandeira da minha família, então vá em frente e peça ao RH que me demita...",
  [813709740278016] = "Tudo bem, eu entendo, você simplesmente não quer trabalhar. É estranho, como você ainda não foi demitido?",
  [813709740277760] = "Talvez sejam todos eles.",
  [813709740277504] = "Não vendo ingressos, não quero vender; se não quero vender, como posso vender?",
  [813709740277248] = "Não vendo ingressos para assuntos não urgentes; se não for urgente, o que estou vendendo?",
  [813709740276992] = "Não vendo ingressos para assuntos urgentes; quando as pessoas estão com pressa, cometem erros facilmente.",
  [813709740276736] = "Não vendo passagens para novos passageiros; você nunca comprou de mim, como posso me atrever a vender para você?",
  [813709740276480] = "Não me interrompa. Ouça-me, não vendo passagens para passageiros antigos porque isso não gera nova demanda.",
  [813709740276224] = "O que isso tem a ver com “O Grande Aventureiro” de Fors?",
  [813709740275968] = "Vendendo ingressos, tenho cinco ‘não vou vender’.",
  [999388423920384] = "Uau!",
  [813709740275456] = "Na última série de \"O Grande Aventureiro\", {{Sr.|Sra.}}, estou estudando o estilo de expressão da famosa escritora Sra.",
  [813709740275200] = "O que você está olhando?",
  [813709740274944] = "Aquele aventureiro que parece gentil e educado, mas age como um louco, tem um nome que faz com que os Quatro Reis e os Sete Generais o temam – Gehrman! Isso mesmo, é ele, o grande aventureiro, o louco caçador de piratas, Gehrman Sparrow!",
  [813709740274688] = "<P_Heart> (Bem, pelo menos ele ainda não teve sua barraca derrubada, talvez sofismas de língua fluente e implorar por misericórdia também sejam uma forma de \"sabedoria\".) </>",
  [813709740274432] = "<P_Heart> (Se confiar em truques baratos para enganar as pessoas também pode ser chamado de sabedoria...) </>",
  [813709740274176] = "Ei, {{Sr.|Sra.}}, não diga isso! Você deve saber que a sabedoria também é uma das formas de ganhar dinheiro, claro, claro! Não é necessariamente moral.",
  [813709740273920] = "Não, ganhei uma barriga cheia de raiva.",
  [813709740273664] = "Claro, claro! Você pagou dinheiro, mas ganhou sabedoria!",
  [813709740273408] = "Você está certo, ganhei muito.",
  [813709740273152] = "{{Sr.|Sra.}}, agora você descobrirá que o número obtido é zero! Ah, deve ser zero! Claro, claro!",
  [813709740272896] = "Veja, este é um passo muito misterioso, considerando que você certamente não me disse sua idade.",
  [813709740272640] = "Então subtraia sua idade original!",
  [813709740272384] = "Adicione mais sete.",
  [813709740272128] = "Então subtraia vinte.",
  [813709740271872] = "Em seguida, adicione treze à sua idade.",
  [813709740271616] = "Excelente! Por favor, lembre-se silenciosamente da sua idade em seu coração, não há necessidade de me dizer, afinal, isso é privacidade pessoal.",
  [813709740271360] = "Acho que você estaria disposto a trocar um dinheirinho pela oportunidade de adquirir essa grande sabedoria, claro, claro!",
  [880023229696256] = "Revólver",
  [813709740270848] = "Uh, senhor, estou disposto a ouvir sua \"grande visão\".",
  [813709740270592] = "Ótima visão! Uma grande descoberta que vale a pena parar para ouvir! Uma filosofia de vida cheia de valor!",
  [813709740270336] = "Obrigado, terei cuidado.",
  [813709740270080] = "A propósito, {{Sr.|Sra.}}, tem um Louco que adora beber lá. Siga meu conselho e fique longe dele.",
  [813709740269824] = "Vire à direita novamente e continue andando, e você verá.",
  [813709740269568] = "Saia daqui, atravesse para outra rua e você verá aquela loja de especiarias.",
  [813709740269312] = "Para pessoas como nós, poder fumar um cigarro ao sol todos os dias é uma felicidade suficiente.",
  [813709740269056] = "Esta é a realidade. Além disso, os verdadeiramente pobres nunca aparecem no asilo.",
  [813709740268800] = "Quem sabe? Basta considerar isso uma boa ação e ouvir as reclamações de uma pessoa pobre como eu. Há tantos andarilhos que até o asilo tem fila só para conseguir um pedaço de pena pela fresta da porta.",
  [813709740268544] = "Suspiro, eles eram pintores errantes. Eu até vi a exposição de arte deles na semana passada... muitas pessoas assistiram, mas ninguém poderia gastar nenhum dinheiro extra com eles.",
  [813709740268288] = "Sim, {{Sr.|Sra.}}, aqui, alguns moradores de rua morrendo de fome não é novidade. É só...",
  [813709740268032] = "Oh... {{Sr.|Sra.}}, você sabe, dois moradores de rua morreram aqui.",
  [813709740267776] = "Você é tão gentil! Tenho um presente para você também, podemos trocar presentes depois, só de pensar nisso me deixa feliz!",
  [813709740267520] = "<P_Heart> (Acenando com a cabeça) </> Com certeza! Tenho muitas coisas interessantes que quero lhe contar. A propósito, também trouxe algumas especialidades locais de Backlund; Vou entregá-los a você quando comermos mais tarde!",
  [813709740267264] = "<P_Heart> (Tímido) </> Tudo bem então, depois de comermos, vou presentear você com uma boa cerveja Southwell. Ouvi dizer que o luar está lindo esta noite e podemos dar um passeio no cais e aproveitar a brisa. Você está em viagem de negócios há uma semana inteira; você deve ter muita coisa para me contar, certo?",
  [813709740267008] = "Já está reservado. Esta noite vamos ao restaurante Old Will's. Ouvi dizer que chefe está muito entusiasmado; ele é bem velho, mas ainda fica na porta para cumprimentar os convidados. Acabei de receber meu salário hoje, então esta refeição é por minha conta!",
  [813709740266752] = "Hehe, na verdade você tem se saído muito bem o tempo todo. Eu estava apenas brincando mais cedo, não precisa ser tão sério. A propósito, você já decidiu onde vamos comer mais tarde?",
  [813709740266496] = "<P_Heart> (Sério) </> Sanna, não se preocupe, eu sei. Um homem não deveria fazer promessas vazias. Farei tudo o que prometi a você.",
  [813709740266240] = "<P_Heart> (Fingindo estar falando sério) </> Tudo bem então, ouça, colega Powell. Em um relacionamento, quando você é necessário, você não aparece, e quando aparece, você não é mais necessário!",
  [813709740265984] = "<P_Heart> (Sério) </> Professora Sanna, por favor, ensine este meu colega simples, mas diligente!",
  [813709740265728] = "<P_Heart> (Ouvindo o que eles estão conversando) </>",
  [813709740265216] = "{{Sr.|Sra.}}, você me descobriu de novo. Não sei se a Deusa vai me perdoar... aquele meu amigo.",
  [813709740264960] = "Será que esse amigo de quem você está falando pode ser...",
  [813709740264704] = "Quer dizer, o que quero dizer é que tenho um amigo que sempre foi diligente e honesto, mas uma vez, num momento de fraqueza, ele cometeu um erro...",
  [813709740264448] = "Obrigado, eu entendo. Deixe-me pensar sobre isso novamente.",
  [813709740264192] = "Acho que depende da sinceridade do arrependimento.",
  [813709740263936] = "Um... um erro que não é grande nem pequeno.",
  [813709740263680] = "Hmm... a prata é um metal do domínio da Deusa, e a cerâmica também não é ruim. Qual devo escolher?",
  [813709740263424] = "Sim, costumava ser apenas uma escola dominical gratuita. Para encorajar mais mulheres crentes a trabalhar, a Igreja da Deusa da Noite Eterna abriu cursos de pintura, escrita, cerâmica e jóias de prata.",
  [813709740263168] = "A aula de treinamento da igreja?",
  [813709740262912] = "Suspiro, é melhor eu voltar para a aula de treinamento da igreja para estudar mais.",
  [813709740262656] = "Parece que sim, mas você já pintou muito bem.",
  [813709740262400] = "Gosto da atmosfera desta praça e gosto da igreja da Deusa; Eu simplesmente escolhi ser pintora aqui.",
  [813709740262144] = "Só faço isso para não precisar ficar em casa. A Deusa incentiva suas crentes a trabalharem fora e encontrarem mais autoestima.",
  [813709740261888] = "Pintar não é seu trabalho?",
  [813709740261632] = "Não fale nisso, não confio nisso para ganhar dinheiro.",
  [813709740261376] = "Obrigado pelo elogio. Se você gostar, posso te dar.",
  [813709740261120] = "Não, você pintou muito bem.",
  [813709740260864] = "Venha me ajudar a ver se meu quadro está torto.",
  [813709740260608] = "<P_Heart> (Sorri) </> Você está falando sobre a família dele? Isso não é importante; apenas consideramos Heywood um amigo que persegue sonhos conosco.",
  [813709740260352] = "Todos vocês sabem que Heywood é...",
  [813709740260096] = "Obrigado e continue apoiando meus amigos!",
  [813709740259840] = "Jovem, por que você continua me encarando?",
  [813709740259584] = "<P_Heart> (Sorrindo) </> Você está falando sobre a identidade dele? Isso não é importante; apenas tratamos Haywood como nosso companheiro de armas.",
  [813709740259328] = "Todos vocês sabem que ele é...",
  [813709740259072] = "Não sou eu, é a pessoa ao meu lado.",
  [813709740258816] = "Você está aqui para experimentar a vida?",
  [813709740258560] = "Juntos, eles apoiam os círculos religiosos da cidade de Tingen e das cidades e aldeias afiliadas.",
  [813709740258304] = "A Igreja da Deusa da Noite Eterna e a Igreja do Senhor das Tempestades têm suas próprias igrejas em Tingen.",
  [813709740258048] = "Suspiro, você é como Hera, sua base teórica ainda precisa de melhorias. Todo esse conhecimento que compartilhei foi em vão!",
  [813709740257792] = "Não há muitos jovens como você com um olhar tão aguçado! Você pode reconhecer a importância da oratória, compreender a urgência, persistir na consciência e mostrar iniciativa; isso já é ótimo!",
  [1130298758796544] = "Hmm... eles não são apenas alguns bichinhos?",
  [1130298758665472] = "Os pequenos?",
  [813709740257024] = "Sim, sim, quando falamos deste oratório não é palestra, nem recitação, então o que é? Ei, esse oratório em si precisa de atenção, ei, sério, deixe-me dizer, tenho os seguintes seis pontos a dizer...",
  [813709740256768] = "<P_Heart> (Sempre acha que algo está estranho) </> Senhor, parece que você também tem pesquisas sobre oratória?",
  [813709740256512] = "Sim, olha o orador ali que continua promovendo a Deusa; Fiquei muito feliz ao ouvir isso, nossa equipe está crescendo novamente!",
  [813709740256256] = "Suspiro, seu nível teórico precisa tanto de melhoria quanto o daqueles quatro poetas. Todo esse conhecimento que compartilhei foi em vão!",
  [813709740256000] = "Não há muitos jovens como você com um olhar tão aguçado! Você pode reconhecer a importância de escrever poesia, compreender a urgência, persistir na consciência e mostrar iniciativa; isso já é ótimo!",
  [813709740255744] = "Não há muitos jovens como você que estejam dispostos a aprender! Também estou muito feliz que você tenha sua compreensão única da poesia!",
  [813709740255488] = "Sim, sim, sim, desde que você entenda. Ah, vocês, jovens de hoje, sempre pensando nesse -ismo ou naquele -ismo, na verdade, a poesia em si é só poesia!",
  [813709740255232] = "Meu jovem, quando a gente fala dessa poesia, quer dizer, ah, nós, a poesia em si é muito... não é que a gente deva fazer alguma coisa com um poema, mas...",
  [813709740254976] = "<P_Heart> (Sempre acha que algo está estranho) </> Senhor, parece que você também gosta de poesia, me diga o que você acha sobre poesia?",
  [813709740254720] = "Sim, todos na praça estão discutindo poemas em louvor à Deusa, e fiquei muito emocionado ao ouvi-los.",
  [813709740254208] = "Obrigado, vou presenteá-lo com um pouco de vinho Ormier então!",
  [813709740253952] = "Na verdade, esta é a primeira vez que estou pescando, adoro jogar.",
  [813709740253696] = "Hoje, hoje devo orar com devoção e deixar a Deusa abençoar minha sorte com cartas amanhã!",
  [813709740253440] = "Com certeza, como você pode mudar as coisas sem jogar?",
  [813709740253184] = "Depois de amanhã, Stanny está me chamando para pescar! Apostamos que quem pega menos presenteia o outro com uma refeição!",
  [813709740252928] = "Amanhã, sinto que minha sorte nas cartas amanhã será especialmente boa!",
  [813709740252672] = "Que tal não ir hoje?",
  [813709740252416] = "Só não perca todo o seu capital.",
  [813709740252160] = "Obrigado por me apoiar! Quando eu ganhar e voltar, com certeza vou te oferecer uma refeição!",
  [813709740251904] = "Eu ouvi isso do lado!",
  [813709740251648] = "Ah... {{Sr.|Sra.}}, como você sabia que eu queria tanto ir?",
  [813709740251392] = "Eu realmente quero ir... então quando você acha que eu deveria ir?",
  [813709740251136] = "Suspiro, venha me ajudar, estou pensando se devo ir ao cassino?",
  [813709740250880] = "Senhor, com o que você está lutando?",
  [813709740250624] = "Vamos, Sr. Schneider!",
  [813709740250368] = "Meu estado mental é muito bom.",
  [813709740250112] = "Desejo que sua batalha corra bem.",
  [813709740249856] = "Meu estado mental é muito bom.",
  [813709740249600] = "Continue assim, você está prestes a alcançar a vitória!",
  [813709740249344] = "Meu estado mental é muito bom.",
  [813709740248576] = "<P_Heart> (Pensando por um momento) </> Eu também costumo enfiar agulhas nas rimas da vida.",
  [813709740248320] = "Um rapper? Talvez a vida tenha organizado as rimas de maneira muito densa para mim.",
  [813709740248064] = "Desejo-lhe sucesso!",
  [813709740246784] = "Poesia não é meu <P_Yellow> temperamento </> , porque acho que ainda tenho um pouco de <P_Yellow> sanidade </> .",
  [813709740246528] = "Hmm... você está certo, mas depois dos sonhos com cerveja Southwell, ela circulará na Howls Street <P_Yellow></> \n, passando a primavera, o verão <P_Yellow> e o outono </> com a lua negra.",
  [813709740246272] = "Eu vejo. Você não viu porque as flores da lua produzidas pela loja de departamentos Harland podem ser usadas na 33ª Expo Mundial da Universidade de Tingen depois de cozidas.",
  [813709740246016] = "Parece que não vejo ninguém?",
  [813709740245760] = "Shh, há um inimigo na minha frente.",
  [813709740245504] = "Com quem você está falando?",
  [813709740245248] = "<P_Heart> (Você sabe aproximadamente o que aconteceu, e olhando para a criança ingênua e inocente diante de você, você fica em silêncio por um momento.) </> Estou disposto.",
  [813709740244992] = "Claro! Minha tia e meu tio me disseram que enquanto eu rezar à Deusa por cem dias, ah, não, mil dias, a doença de Bruce vai melhorar. Você está disposto a orar comigo?",
  [813709740244736] = "<P_Heart> (Você provavelmente sabe o que aconteceu, e olhando para a criança jovem e inocente à sua frente, você permanece em silêncio por um tempo.) </> Sua tia e seu tio estão certos.",
  [813709740244480] = "Eu... eu não sei. Mas minha tia e meu tio me disseram que enquanto eu rezar à Deusa por cem dias, ah, não, mil dias, a doença de Bruce vai melhorar.",
  [813709740244224] = "Ele está doente. Os pais de Bruce disseram que é contagioso e não me deixam visitá-lo.",
  [813709740243968] = "Ele é meu melhor amigo.",
  [813709740243712] = "Quem é Bruce?",
  [813709740243456] = "Trabalhar é impossível, nunca trabalharei.",
  [813709740243200] = "Obrigado, estranho. Vou considerar isso.",
  [813709740242944] = "Para alguém como eu... rezar para que não haja infortúnios já é o maior desejo.",
  [813709740242688] = "Talvez eu devesse encontrar um emprego... talvez eu continue deitado aqui.",
  [813709740242432] = "Nome? Estou vagando há tanto tempo... que até esqueci meu próprio nome.",
  [813709740241920] = "Além disso, só na praça da igreja ninguém me afugenta.",
  [813709740241664] = "Para alguém como eu, que não tem casa, ficar deitado aqui é o ideal.",
  [813709740241408] = "Há cadeiras dos dois lados, por que você está deitado aqui sozinho?",
  [813709740241152] = "Você também acha que fiz algo errado, não é... {{Sr.|Sra.}}, quero lhe pedir um favor. Se você vir meu pai, Sr. Bellman, na Iron Cross Street, por favor me ajude a esconder isso dele. Obrigado.",
  [813709740240896] = "Obrigado, {{Sr.|Sra.}}. Que a Deusa te abençoe. Se você vir meu pai, Sr. Bellman, na Iron Cross Street, por favor, ajude-me a esconder isso dele; ele ainda está procurando pela pequena Irene...",
  [813709740240640] = "Eu... perdi minha filha, a pequena Irene. Pode me ajudar?",
  [813709740240384] = "Você está bem?",
  [813709740240128] = "Obrigada... Julie sempre diz isso para mim também.",
  [813709740239872] = "Obrigado, vou seguir o exemplo de Julie.",
  [813709740239616] = "Eu, eu não, eu só... a admiro.",
  [813709740239360] = "{{Sr.|Sra.}}, não mencione essas perguntas que você me fez para Julie...",
  [813709740239104] = "Não sei.",
  [813709740238848] = "Sem o incentivo de Julie, eu teria medo até de sair. Ela é muito boa para mim; Não sei como retribuir a ela...",
  [813709740238592] = "Eu... me desculpe, acabei de... chegar, minha fala está... um pouco desajeitada.",
  [813709740238336] = "Que a Deusa te abençoe.",
  [813709740238080] = "Que tipo de flores você quer comprar?",
  [813709740237824] = "{{Sr.|Sra.}}, olá.",
  [813709740237312] = "Você não lê muito, não te culpo.",
  [813709740237056] = "Você é ótimo, vou recompensá-lo escrevendo poesia comigo.",
  [813709740236544] = "Você deveria encontrar Hera e aprender a falar.",
  [813709740236288] = "Louvado seja a Deusa, louvado seja você.",
  [813709740236032] = "Não parece tão bom quanto Eufêmia.",
  [813709740235776] = "Parece que seu gosto nada mais é do que isso.",
  [813709740235520] = "Sim, as roupas que Mathilde está vestindo já são usadas há três anos. Quando foi a última vez que ela comprou roupas novas...",
  [813709740235264] = "Ela disse roupas para combinar?",
  [813709740235008] = "Mathilde está olhando para um colar que vale cinco anos do meu salário; não tenho como comprar...",
  [813709740234752] = "<P_Heart> (Sussurrando) </> Espere um pouco mais, economize para mais meio ano de salário e eu posso ficar com ele!",
  [813709740234496] = "Mas não tenho nenhuma roupa que combine com esse colar.",
  [813709740234240] = "Cinco anos? Dez anos?",
  [813709740233984] = "Quantos anos tenho que trabalhar para comprar um colar como este...",
  [813709740233728] = "Para aquele toque exótico primitivo e selvagem, preservámos especificamente os vestígios do artesanato.",
  [813709740233472] = "O Continente Sul gosta muito de produtos de ouro, por isso esta parte da coleção utiliza o ouro como material principal, combinado com diversas pedras preciosas nativas do Continente Sul.",
  [813709740233216] = "Definitivamente não foi desenterrado de alguma tumba real das Terras Altas, nem de nenhuma múmia!",
  [813709740232960] = "Afirmarei antecipadamente que nossas joias têm fontes legítimas.",
  [695031203655168] = "Sala de Alquimia",
  [813709740232704] = "Eles gostam especialmente de pérolas irregulares, o que confere muita personalidade às joias assim desenhadas.",
  [813709740232448] = "Esse estilo de joalheria usa muitas curvas e a combinação de materiais costuma ser linda, o que fez subir os preços das pedras preciosas coloridas.",
  [813709740232192] = "As joias Intis, assim como as pessoas de lá, são cheias de cores românticas.",
  [813709740231936] = "Usá-los, mesmo em ocasiões sociais em Backlund, você ficará bastante deslumbrante.",
  [813709740231680] = "Eles têm designs simples e materiais ricos. Você pode escolher com base nas categorias de cor, estilo e preço.",
  [813709740231424] = "Todas as joias estilo Loen são feitas à mão por mestres artesãos da capital.",
  [813709740231168] = "Gostaria de saber mais sobre as joias da loja?",
  [813709740230912] = "Quem você acha que escreve melhor entre nós quatro?",
  [813709740230656] = "Obrigado, John costuma dizer isso sobre mim também.",
  [813709740230400] = "<P_Heart> (Tímido) </> Este {{bonito Sr.|elegante Sra.}}, por favor, me perdoe, eu... ainda não pensei sobre essa questão.",
  [813709740230144] = "João é meu vizinho. Os pais dele não se importaram com ele desde que nasceu, então sempre cuidei dele, como... como um irmão mais novo.",
  [813709740229888] = "Já faz muito tempo, não consigo me lembrar com clareza. Comecei a trabalhar com minha família quando era muito jovem.",
  [813709740229632] = "Esta também é uma planta amada pela Deusa. Abençoe.",
  [813709740229376] = "Que tipo de flores você quer comprar?",
  [813709740229120] = "Olá, {{bonito Sr.|elegante Sra.}}.",
  [813709740228864] = "Você realmente sabe escolher! O salmão deve ser consumido frio; o salmão fresco é o mais gordo e macio. Você tem que comprar de mim.",
  [813709740228608] = "Ei, o peixe quilha aqui acabou de ser trazido por um navio que saiu para o mar. Frito, fica uma delícia!",
  [813709740228352] = "Você escolheu bem. Perto do rio Tussock, você não deveria comer peixe Tussock? Aposto que não há nenhum residente de Tingen que não goste.",
  [813709740228096] = "Dê uma olhada, tem algo que você gosta?",
  [813709740227840] = "Se você não encontrou nada desta vez, sempre haverá a próxima. Deixe-me saber se você quiser peixe fresco no futuro.",
  [813709740227584] = "{{Sr.|Senhorita}}, você tem um olhar aguçado para me encontrar! O peixe aqui é o mais fresco de toda Tingen, isso mesmo!",
  [813709740227328] = "<P_Heart> (Iron Cross Street é muito animada, vamos visitar outros lugares.) </>",
  [813709740227072] = "Você está realmente certo! Não sei dizer porquê, mas simplesmente gosto deste lugar.",
  [813709740226816] = "Por aqui é assim, muitos vigaristas e muitos ladrões. Mas ainda gosto deste lugar.",
  [813709740226560] = "Então ele provavelmente é um vigarista.",
  [813709740226304] = "Eu também diria isso, alguém com muita sabedoria não montaria uma barraca aqui.",
  [813709740226048] = "Não temos dinheiro extra. <P_Heart> (Ri baixinho) </> Que tipo de grande sabedoria? Manter a patroa de bom humor é o que importa.",
  [813709740225792] = "Você viu aquele cara? Ele é estranho, dizendo que pode lhe contar uma grande sabedoria se você lhe der algum dinheiro.",
  [813709740225536] = "Oh, você está falando bobagem de novo! Que tipo de poeta é uma empregada doméstica fazendo biscates?",
  [813709740225280] = "Tempestade acima! Lusha, você fala como um poeta.",
  [813709740225024] = "Sair para comprar mantimentos todos os dias e conversar com você é quando estou mais feliz.",
  [813709740224768] = "Eu adoro a agitação! O cheiro de ensopado no ar é maravilhoso e os sons do falcoeiro também são agradáveis. As folhas de alface estão pingando água e as batatas são tão redondas e fofas!",
  [813709740224512] = "Toda a área da Iron Cross Street é a mais animada aqui. Todos os donos das barracas se reúnem aqui.",
  [813709740224256] = "Recentemente, surgiram algumas novas barracas no mercado de alface e carne.",
  [813709740224000] = "<P_Heart> (Eles estão falando sobre...) </>",
  [813709740223744] = "<P_Heart> (Parecem que são duas empregadas que acabaram de fazer compras... querem ouvir as fofocas delas?) </>",
  [813709740223488] = "Este é o seu diário, um caderno de invenções que ele não consegue mais entender.",
  [813709740223232] = "O que há de errado com o almoço embalado?",
  [813709740222976] = "Olá, sou representante dos trabalhadores, gostaria que vocês dessem uma olhada na lancheira de hoje.",
  [1130369090081024] = "Que tipo de abrigo? Se você me perguntar, é mais como ficar de olho em todos.",
  [1130369089958144] = "Desculpe, eu incomodei você? A música que você tocou era linda demais!",
  [1130369089835264] = "Acredite, os arquivos são deliciosos demais. Se não pegarmos logo esses pequeninos em fuga, esse tesouro de conhecimento logo se tornará um denso ninho de insetos!",
  [1130369089810688] = "A razão... é um tanto complicada. Em seu coração, sempre fui eu quem tirou seu futuro.",
  [813709740221696] = "Para problemas de relacionamento, escolha 1; para ressentimentos pessoais, escolha 2; para encontrar objetos de valor, escolha 3. \n Para encontrar gatinhos e cachorrinhos, procure por Iris no Distrito Norte; esse é o nosso novo... novo funcionário.",
  [813709740221440] = "Olá, aqui é a Agência de Detetives Henry. \n Classificamos nossos serviços numericamente:",
  [813709740221184] = "<P_Heart> (Suspiro, é melhor ir embora. Não há como se comunicar.) </>",
  [1130369089159424] = "Os pombos também podem vender jornais?",
  [1130369089028352] = "Talvez seja essa a razão pela qual o culpado os atacou.",
  [1130369088936192] = "Esta é a terceira frase.",
  [1130369088766208] = "É uma honra para nossa loja ser sempre apreciada por você.",
  [1130369088751872] = "Então não posso perder isso!",
  [1130369089552640] = "Hmm... vamos ao salão <P_Yellow></> para discutir isso em detalhes - já ocupamos este lugar há tempo suficiente.",
  [1130369089421568] = "Não, meu documento foi roubado.",
  [1130369089364224] = "Também ajudarei a procurar pistas.",
  [813709740218880] = "Aquela garotinha, ela é sua...",
  [813709740218624] = "Olá, procurando algo? Um jornal? Uma revista?",
  [813709740218368] = "Sim... exatamente como você vê. \n Mas não fique muito triste, talvez um dia melhore, certo? Talvez um dia eu consiga correr.",
  [813709740218112] = "Sua perna... me desculpe, não percebi...",
  [1152495149661184] = "Depois de algum tempo...",
  [813709740217600] = "{{Sr.|Senhorita}} Olá, meu nome é Liz. Bem-vindo!",
  [813709740217344] = "Tirar um quarto de hora para fumar um cachimbo e deixar o cheiro de fumaça se dissipar no caminho para casa é o intervalo que me dou.",
  [813709740217088] = "E ela absolutamente não me deixa tocar em uma única folha de tabaco em casa, entendeu?",
  [813709740216832] = "Ha, você não entende. É o meu caminho do trabalho para casa agora. Daqui a um quarto de hora, tenho que voltar para ver minha esposa.",
  [813709740216576] = "Quer dizer, sinto que existem escolhas melhores.",
  [813709740216320] = "Senhor, você está... fumando na rua, na beira da estrada?",
  [813709740216064] = "Amigo, deixe-me terminar esse cachimbo, então você pode falar comigo.",
  [813709740215808] = "Eu descobri agora; basta deixar essas coisas de joelhos fracos e rosto pálido lá em cima para arejar por um tempo, e não deixá-las atrapalhar os projetos de construção pública.",
  [813709740215552] = "Assim que começo a trabalhar pela manhã, tenho que verificar se preciso salvar alguém.",
  [813709740215296] = "Sempre há alguns idiotas que sobem as escadas do andaime no meio da noite.",
  [813709740215040] = "<P_Heart> (Sussurrando) </> Ela só está brincando, ela não suportaria fazer isso, hee hee.",
  [813709740214784] = "Ei, volte para jantar, caso contrário, tia Mary confiscará todos os seus folhados e punirá você não deixando você comer arroz doce na próxima semana.",
  [813709740214528] = "Tia Mary mora bem ao nosso lado! Eu os vi crescer e agora sou uma criança crescida, então posso cuidar deles.",
  [813709740214272] = "Olha, esses dois pequeninos são fofos, não são? Esses são os filhos da tia Mary.",
  [813709740214016] = "Sinta-se à vontade para dar uma olhada. Embora não haja muitos clientes, não vou simplesmente abandonar minha barraca como aquele vagabundo preguiçoso ali.",
  [813709740213760] = "Espero que cada flor vendida possa ser apreciada por seu dono.",
  [813709740213504] = "Pelo menos posso passar meus dias com as coisas que amo; isso é uma espécie de sorte em si!",
  [813709740213248] = "Guardar a barraca de manhã à noite é um trabalho árduo, mas ver essas flores frescas melhora meu humor.",
  [813709740211968] = "É isso mesmo, este é um restaurante estabelecido há muito tempo em Tingen, e muitos vizinhos costumam vir aqui. É bastante conveniente caminhar por aqui.",
  [813709740211712] = "Então essa direção é a porta dos fundos do Restaurante Old Will's! Acabei de perceber.",
  [813709740211456] = "Mesmo que não haja nada de especial acontecendo, gosto de vir, sentar um pouco, pedir uma bebida e ler o jornal.",
  [813709740211200] = "Naquela época eu nem era tão alto quanto o balcão, haha...",
  [813709740210944] = "Quando este lugar ainda era o Restaurante Will, meus pais sempre me traziam aqui para comer.",
  [813709740210688] = "Embora eu não entenda a linguagem dos gatinhos, sinto que a atitude deste membro em relação à assembleia é muito inadequada.",
  [813709740210432] = "…… <P_Heart> (ronronar…) </>",
  [813709740209152] = "Miau! Miau, miau, miau! <P_Heart> (Gatos! Conte!) </>",
  [813709740208896] = "Miau... miau miau miau miau miau! <P_Heart> (Ah... é hora da palestra da turma dos gatos!) </>",
  [813709740208640] = "Miau, miau, miau, miau, miau. <P_Heart> (Você nem quer me chamar de Padrinho Gato.) </>",
  [813709740208384] = "Ei, {{jovem | mocinha}}! É melhor você ficar de lado, é perigoso perto das caixas de carga.",
  [813709740208128] = "<P_Heart> (Parece que um cliente continua experimentando e devolvendo roupas... que comportamento terrível.) </>",
  [813709740207872] = "Suspiro... se ele continuar comprando e devolvendo roupas assim, com certeza terei que colocá-lo na lista negra!",
  [813709740207616] = "Encomenda de terno Andis... encomendante Andis... encomendante... por que é tudo isso Andis?",
  [813709740207360] = "<P_Heart> (angustiado) </> A taxa de retorno tem estado chocantemente alta ultimamente, não sei o que está acontecendo...",
  [813709740207104] = "Livro razão? Houve algum problema com os negócios ultimamente?",
  [813709740206848] = "Bem-vindo! Desculpe, estou verificando o livro... Você pode sentar ou dar uma olhada, nossas roupas são feitas com os melhores materiais.",
  [813709740206592] = "Vou dar uma olhada sozinho primeiro.",
  [813709740206336] = "<P_Heart> (Não, não, não, uma vez que se torna um trabalho, comparado a andar alegremente e olhar as coisas, deve ser mais profissional.) </>",
  [813709740206080] = "Ah, acho que já ouvi falar desses dois designers... Reunião de inspiração para design? Parece um trabalho realmente interessante.",
  [813709740205824] = "Falando nisso, há dois dias, os designers Miss Elsa e Mr. Jacques vieram à nossa loja enquanto estavam em Tingen em busca de inspiração, e até disseram que queriam estabelecer uma parceria connosco se houvesse oportunidade. Eles vão criar uma nova marca; você já ouviu falar disso?",
  [813709740205568] = "Uma boa roupa deve evitar as desvantagens do cliente, ao mesmo tempo que destaca as vantagens e Unicidade de sua figura e temperamento. Nesse aspecto, nossa loja de roupas é a melhor de toda Tingen. <P_Heart> (Orgulhoso) </>",
  [813709740205312] = "Os dados relativos ao vestuário são muito complexos. Mesmo com o mesmo padrão, o efeito será completamente diferente dependendo do formato do corpo.",
  [813709740205056] = "Não entendo muito de roupas, podemos conversar sobre alfaiataria personalizada?",
  [813709740204800] = "Se você quiser roupas personalizadas, fique à vontade para me encontrar para tirar suas medidas.",
  [813709740204544] = "Bem-vindo à loja de roupas. Sinto muito, como você pode ver... Não estou muito livre agora, você pode dar uma olhada sozinho primeiro.",
  [813709740204288] = "Eu vejo. <P_Heart> (Eu me pergunto se minha doença ocupacional é querer conversar com alguém que eu vejo e que parece suspeito...) </>",
  [813709740204032] = "Eles costumavam trabalhar na profissão jurídica. Mesmo quando não estão no trabalho, estão acostumados a um tom de debate. \n Acho que é uma doença ocupacional, haha.",
  [813709740203776] = "Ah, você quer dizer eles.",
  [813709740203520] = "Aqueles dois senhores ali... parecem estar debatendo intensamente?",
  [813709740203264] = "Ah, olá, olá. Estou lendo o jornal, fique à vontade para perguntar qualquer coisa.",
  [813709740203008] = "Olá, convidado! Bem-vindo ao Rollins Bar. \n Se você tiver alguma dúvida, entre em contato comigo a qualquer momento.",
  [813709740202752] = "Eles partirão sozinhos em alguns dias.",
  [813709740202496] = "<P_Heart> (sorri) </> Hmm, eu sei. Não se preocupe com isso, coisas assim acontecem às vezes.",
  [813709740202240] = "Parece que há dois cavalheiros esperando por você na porta.",
  [813709740201984] = "Por favor, sente-se em qualquer lugar. As bebidas são servidas depois das oito da noite. \n Estou trabalhando em uma nova receita, você prefere ensopado de nabo ou batata?",
  [813709740201728] = "Aqueles que não conseguem aproveitar plenamente a aleatoriedade de um jogo não conseguem realmente gostar de “lutar contra o mal”.",
  [813709740201472] = "<P_Heart> (O número de cartas também está errado! Boa sorte...) </>",
  [813709740201216] = "Então devo trocá-lo por quatro 2s?",
  [813709740200960] = "Mas trocar um 3 por um pequeno Coringa não é uma jogada muito grande? É muito fácil ser pego.",
  [813709740200704] = "Tudo bem, não importa, não vou contar a ninguém.",
  [813709740200448] = "Olha esse tempo, está tão quente! Não é? <P_Heart> (Olhos vagando, evasivos.) </>",
  [813709740200192] = "Haha, sim, o reabastecimento das barracas e as entregas de grandes pedidos são de nossa responsabilidade. Cini e os outros foram ao banheiro; estávamos apenas jogando cartas na sombra.",
  [813709740199936] = "Ah, eu estava de passagem e queria ver as flores. Você é responsável pela entrega de flores?",
  [813709740199680] = "Ufa, não foi a Cini.",
  [813709740199424] = "Tenho uma carta pequena na mão, ah não, é um pequeno Coringa! Oh meu Deus, como eu poderia usar métodos tão baixos para vencer você...",
  [813709740199168] = "Ah, Cini, você está de volta! Hahaha, não, você viu errado, como eu pude ter trocado de cartão!",
  [813709740198912] = "Esse...",
  [813709740198656] = "Um 3... isso é muito pequeno... troque-o secretamente por...",
  [813709740198400] = "{{lindo senhor | linda senhorita}}, desejo-lhe um bom dia!",
  [813709740198144] = "Isso é tudo então, aqui está a mudança.",
  [813709740197888] = "Nada que eu queira comprar por enquanto.",
  [813709740197632] = "Que página de anúncio grande. A publicidade chegou até a Tingen; o alcance de vendas é bastante amplo.",
  [813709740197376] = "\"Ar fresco, começando por você e por mim. Fornecimento especial de carvão sem fumaça, compre enquanto durarem os estoques.\"",
  [813709740197120] = "Obtenha uma cópia do Backlund Daily.",
  [813709740196864] = "Tudo bem, então foi uma pessoa gentil ajudando uma senhora idosa a atravessar a rua. Obrigado pelo seu trabalho duro.",
  [813709740196608] = "“O gentil anjo anda pelas ruas, uma brisa fresca ajuda suavemente...” Anjo? Tingen despachou um figurão desse nível?",
  [813709740196352] = "Obtenha um exemplar do Jornal do Homem Honesto de Tingen.",
  [813709740196096] = "Oh, espere, então foi o esquadrão de gatos vadios invadindo novamente.",
  [813709740195840] = "“Departamento de polícia resolve um caso de assédio residencial, suspeita de misteriosa organização clandestina reaparecer…”",
  [813709740195584] = "Obtenha uma cópia do Tingen Morning Post.",
  [813709740195328] = "{{Sr.|Senhorita}} Olá, procurando alguma coisa?",
  [813709740195072] = "Se você me perguntar, esse cara é muito interessante... Ele não tem medo de que seus vegetais sejam roubados?",
  [813709740194816] = "Você vê isso? Há uma barraca de vegetais autônoma ali.",
  [813709740194560] = "Gulu gulu... <P_Heart> (Parece bastante dócil.) </>",
  [813709740194304] = "Melhor sair primeiro, não incomodar alguém focado em encontrar algo.",
  [813709740194048] = "Não, porque parece estar... enrolado bem atrás de você... \n <P_Heart> (Este nível é realmente adequado para ser um detetive particular?) </>",
  [813709740193792] = "<P_Heart> (chocado) </> Como você sabe? Você está me perseguindo, tentando roubar meu negócio?",
  [813709740193536] = "Iri... ah não, ótimo Sr. Iris, o demônio que você está procurando é todo marrom, coberto de padrões, mais ou menos deste tamanho? E tem padrões como este nas costas...",
  [813709740193280] = "<P_Heart> (Huh, parece haver um gatinho por perto.) </>",
  [813709740193024] = "<P_Heart> (Provavelmente... um detetive particular procurando um gatinho perdido por um empregador...) </>",
  [813709740192768] = "Hmph, se eu encontrar, certamente irei capturar esse demônio gentilmente, devolvê-lo ao santuário onde ele pertence e então obter a recompensa que mereço...",
  [813709740192512] = "Oh! Não perturbe a grande detetive Iris! A grande Iris está à procura do perverso demônio bola de pêlo, do quadrúpede covarde, do fugitivo indescritível...",
  [813709740192256] = "Senhor, posso perguntar...",
  [813709740192000] = "<P_Heart> (Este senhor está procurando alguma coisa? Devo dizer alguma coisa?) </>",
  [813709740191744] = "Onde você está... pequenino?",
  [813709740191488] = "<P_Heart> (Espero que depois que a Srta. Manisha partir corajosamente, esse lindo casal possa se reunir rapidamente.) </>",
  [813709740191232] = "Sephra, estou indo agora...! Oh, não, meu rosto fica quente só de pensar nisso. Eu, eu não consigo dar um passo...",
  [813709740190976] = "Realmente? Sim, parece que tenho uma vaga memória... Ele disse o nome daquele restaurante? Ele deve ter dito isso...!",
  [813709740190720] = "Senhorita Manisha, tenho um palpite ousado. Talvez você devesse ir ao restaurante Old Will e dar uma olhada. Acredito que se o Sr. Xavier não quebrou sua promessa, ele ainda deveria estar esperando lá tolamente.",
  [813709740190464] = "Entre os restaurantes em Tingen adequados para encontros, aquele que pode oferecer vinho tinto Southwell é... hmm, não é comida do sul, e as características do restaurante também são distintas... É isso!",
  [813709740190208] = "Já que o Sr. Xavier reuniu coragem para fazer seu primeiro convite formal, talvez ele escolhesse um lugar mais distinto...",
  [813709740189952] = "Hmm... embora o restaurante Silver Crown valha uma visita, o vinho não é sua especialidade.",
  [813709740189696] = "A senhorita Manisha está esperando aqui há muito tempo... A julgar pela descrição dela, o Sr. Xavier não seria tão rude a ponto de dormir depois do horário do encontro. Ele deve estar em outro lugar...",
  [813709740189440] = "Não, não seria o Restaurante Coastline. O Restaurante Coastline é famoso pela culinária do sul, enquanto o vinho Southwell é produzido no norte do Reino de Loen. Não é apropriado beber vinho tinto Southwell no Restaurante Coastline...",
  [813709740189184] = "Eu acho que ele está em...",
  [813709740188928] = "Não, talvez eu saiba. Você mencionou <P_Yellow> South Will Red Wine </> agora há pouco, certo?",
  [813709740188672] = "Esta {{Sr.|Senhorita}}, talvez você possa ajudar Manisha... Ah, mas você também não sabe!",
  [813709740188416] = "Ah, há tantos restaurantes em Tingen que devo ter esperado no lugar errado...",
  [813709740188160] = "Sefra, ouça! Um encontro...! Cada vez que Xavier diz essa palavra, meu coração bate descontroladamente. Não me lembro de nada, nem mesmo em que entrada do restaurante ele disse para me encontrar!",
  [813709740187904] = "Ele disse que poderia até me oferecer uma taça de <P_Yellow> South Will Red Wine </> !",
  [813709740187648] = "Não consigo me lembrar direito... <P_Heart> (resmungando) </> Ele, ele entrou no meu quintal ontem à noite e me disse pela janela que havia economizado algum dinheiro e queria me convidar formalmente para um encontro...",
  [813709740187392] = "<P_Heart> (Hmm... como eu saberia se está certo ou não... ah, não...) </>",
  [813709740187136] = "Hmm... talvez eu esteja esperando no lugar errado? Certo?",
  [813709740186880] = "Este {{Sr.|Senhorita}}, você vê, nossa Manisha está com muita pressa desde que saiu esta tarde.",
  [813709740186624] = "Não... não é assim, Xavier está apenas... <P_Heart> (Ela parece muito nervosa, ansiosa para defender seu namorado.) </>",
  [813709740186368] = "Deixar uma senhora elegante como você esperar ansiosamente na rua em vez de convidá-lo pessoalmente deve ser a grosseria desse cavalheiro.",
  [1152288991288320] = "Ofereça ajuda",
  [813709740185856] = "<P_Heart> (A garota parece estar esperando por alguém chamado Xavier.) </>",
  [813709740185600] = "Não, Xavier talvez esteja apenas... Sephra, espere um pouco mais comigo, ok...?",
  [813709740185344] = "Você está esperando há muito tempo... Ele realmente não vem?",
  [813709740185088] = "Um poema muito interessante. Parece que a garota tem o coração e o sangue em chamas.",
  [813709740184832] = "Tudo bem, vamos combinar. <P_Yellow> 'Um vestido verde rolando como ondas de jade; um coração mole; elogiando... aquela luz incessante do fogo!' </> Ufa, isso não é nada ruim.",
  [813709740184576] = "Um poema muito interessante. Use um coração mole para elogiar os jovens.",
  [813709740184320] = "Tudo bem, vamos combinar. <P_Yellow> 'Um vestido verde rolando como ondas de jade; um coração mole; elogiando... aquela fragrância fluente!' </> Ufa, isso não é nada ruim.",
  [813709740184064] = "Um poema muito interessante. Que tipo de luz a garota está cantando em sua música?",
  [813709740183808] = "Tudo bem, vamos combinar. <P_Yellow> 'Um vestido verde rolando como ondas de jade; um coração mole; cantando... aquela luz incessante do fogo!' </> Ufa, isso não é nada ruim.",
  [813709740183552] = "Um poema muito interessante. O coração de uma menina é a coisa mais linda. O canto deve ser muito agradável.",
  [813709740183296] = "Tudo bem, vamos combinar. <P_Yellow> 'Um vestido verde rolando como ondas de jade; um coração mole; cantando... aquela fragrância fluente!' </> Ufa, isso não é nada ruim.",
  [813709740183040] = "Versículos muito interessantes. É a garota de vestido verde elogiando o sol? É muito comovente.",
  [813709740182784] = "Tudo bem, vamos combinar. <P_Yellow> 'Um vestido verde rolando como ondas de jade; lábios e dentes doces; elogiando... aquela luz incessante do fogo!' </> Ufa, isso não é nada ruim.",
  [813709740182528] = "Um poema muito interessante. A juventude perfumada certamente merece elogios.",
  [813709740182272] = "Tudo bem, vamos combinar. <P_Yellow> 'Um vestido verde rolando como ondas de jade; lábios e dentes doces; elogiando... aquela fragrância fluente!' </> Ufa, isso não é nada ruim.",
  [813709740182016] = "Um poema muito interessante. A garota de vestido verde canta sobre o sol eterno.",
  [813709740181760] = "Tudo bem, vamos combinar. <P_Yellow> 'Um vestido verde rolando como ondas de jade; lábios e dentes doces; cantando... aquela luz incessante do fogo!' </> Ufa, isso não é nada ruim.",
  [813709740181504] = "Um poema muito interessante. A fragrância deve ser o florido da garota de vestido verde.",
  [813709740181248] = "Tudo bem, vamos combinar. <P_Yellow> 'Um vestido verde rolando como ondas de jade; lábios e dentes doces; cantando... aquela fragrância fluente!' </> Ufa, isso não é nada ruim.",
  [813709740180992] = "Um poema muito interessante. Elogiando o café quente junto à lareira? Parece quente em meu coração.",
  [813709740180736] = "Tudo bem, vamos combinar. <P_Yellow> 'O café amargo é tão profundo quanto a noite; um coração mole; elogiando... aquela luz incessante do fogo!' </> Ufa, isso não é nada ruim.",
  [813709740180480] = "Um poema muito interessante. Um coração mole elogia o café delicioso.",
  [813709740180224] = "Tudo bem, vamos combinar. <P_Yellow> 'O café amargo é tão profundo quanto a noite; um coração mole; elogiando... aquela fragrância fluente!' </> Ufa, isso não é nada ruim.",
  [813709740179968] = "Um poema muito interessante. Um coração mole ficaria agitado pela luz do fogo, não seria? O café também não é mais amargo.",
  [813709740179712] = "Tudo bem, vamos combinar. <P_Yellow> 'O café amargo é tão profundo quanto a noite; um coração mole; cantando... aquela luz incessante do fogo!' </> Ufa, isso não é nada ruim.",
  [813709740179456] = "Um poema muito interessante. O coração deve ter sentido a doçura do canto...",
  [813709740179200] = "Tudo bem, vamos combinar. <P_Yellow> 'O café amargo é tão profundo quanto a noite; um coração mole; cantando... aquela fragrância fluente!' </> Ufa, isso não é nada ruim.",
  [813709740178944] = "Um poema muito interessante. Mesmo que o café esteja amargo, a lareira continuará acesa...",
  [813709740178688] = "Tudo bem, vamos combinar. <P_Yellow> 'O café amargo é tão profundo quanto a noite; lábios e dentes doces; elogiando... aquela luz incessante do fogo!' </> Ufa, isso não é nada ruim.",
  [813709740178432] = "Versículos muito interessantes. Cantando louvores à fragrância do café, ele deveria ser postado na cafeteria.",
  [813709740178176] = "Tudo bem, vamos combinar. <P_Yellow> 'O café amargo é tão profundo quanto a noite; lábios e dentes doces; elogiando... aquela fragrância fluente!' </> Ufa, isso não é nada ruim.",
  [813709740177920] = "Versículos muito interessantes. A luz do fogo deve vir da lareira do café...",
  [813709740177664] = "Tudo bem, vamos combinar. <P_Yellow> 'O café amargo é tão profundo quanto a noite; lábios e dentes doces; cantando... aquela luz incessante do fogo!' </> Ufa, isso não é nada ruim.",
  [813709740177408] = "Um poema muito interessante. A fragrância do café, cantada pelos lábios e dentes, com amargor e doçura em contraste...",
  [813709740177152] = "Tudo bem, vamos combinar. <P_Yellow> 'O café amargo é tão profundo quanto a noite; lábios e dentes doces; cantando... aquela fragrância fluente!' </> Ufa, isso não é nada ruim.",
  [813709740175104] = "Hmm, esta é a última linha...",
  [813709740174080] = "Continue! Deveria ser...",
  [813709740173568] = "E então...",
  [813709740173312] = "Coisas lindas... Deixe-me tentar. A primeira coisa que vem à mente é...",
  [813709740173056] = "Ah, esse {{lindo senhor | linda senhora}}, como você pode ver, a inspiração de um poeta é fragmentada e você precisa conectá-los. Qualquer coisa bonita que você pensar pode ser transformada em poesia...",
  [813709740172800] = "Senhora, você está escrevendo poesia? Na verdade, também tenho algum interesse nisso... Você poderia me dar algumas dicas?",
  [813709740172544] = "Esqueça isso por enquanto.",
  [813709740172288] = "\"A lareira se apagará no verão? No entanto, eles são brilhantes...\"",
  [813709740172032] = "Talvez. Só espero que minha filha melhore logo.",
  [813709740171776] = "Senhor, não creio que a taxa seja a chave. Talvez este seja algum tipo de código de conduta para o Dr. Hosen.",
  [813709740171520] = "Será que a taxa de consulta não é suficiente?",
  [813709740171264] = "As habilidades médicas do Dr. Horsen são muito superiores às do meu médico particular em casa! Mas ele se dedica a atender pacientes e diz coisas como: 'Muitos pacientes que vêm aqui estão agarrados à sua última esperança... Não posso decepcioná-los.'",
  [813709740171008] = "Este {{Sr.|Sra.}}, diga-me, como um médico pode se recusar a fazer visitas domiciliares?",
  [813709740170752] = "Senhor, com licença, presumo que você tenha um médico de família contratado em casa? Ou você precisa de alguma ajuda adicional?",
  [813709740170496] = "Olhando todos os dias para a carruagem pela janela com uma cara triste... ela deve estar fantasiando sobre um passeio.",
  [813709740170240] = "Por que o Dr. Hosen não está disposto a fazer visitas domiciliares? Minha filha pegou tosse novamente recentemente...",
  [813709740169984] = "<P_Heart> (Você deve estar falando daquela senhora na esquina.) </>",
  [813709740169728] = "Que pessoa boa. Que a Deusa a proteja.",
  [813709740169472] = "Depois que seu marido se sacrificou, ela se dedicou a promover o bem-estar dos soldados aposentados e também se tornou um membro importante do clube...",
  [813709740169216] = "Ah, você deve estar falando da Sra. Bennett, do Clube dos Oficiais Aposentados.",
  [813709740168960] = "E ela parece bastante frágil. Talvez ela seja um membro da equipe civil?",
  [813709740168704] = "Aquela senhora poderia ser uma soldado aposentada? Mas mesmo entre os crentes da Deusa da Noite Eterna, há muito poucos casos de recrutamento para o exército...",
  [813709740168448] = "Hmm, embora as lojas de departamentos vendam muitas roupas, falta-lhes a estética da alfaiataria. Roupas personalizadas de alta qualidade devem ter características únicas do usuário...",
  [813709740168192] = "Na verdade, isso será uma grande ajuda para a nossa nova marca. As diferenças de moda entre as cidades também é um tema que vale a pena discutir.",
  [813709740167936] = "Isso faz muito sentido... O corpo humano é uma forma de arte tridimensional. Somente prestando atenção a todos os ângulos da roupa essa beleza pode ser perfeita.",
  [813709740167680] = "Sim, fazer com que os nobres se destaquem da multidão não é algo que se consegue simplesmente empilhando rendas... Requer um toque especial de inovação. Obrigado.",
  [813709740167424] = "Na sua opinião, qual é a característica mais importante a considerar numa peça de moda?",
  [813709740167168] = "Um bom designer nunca deve ficar limitado à sua própria oficina, enfrentando todos os dias uma régua e uma máquina de costura.",
  [813709740166912] = "Este {{Sr.|Sra.}}, você está vestido de maneira muito interessante. Senhorita Elsa e eu estamos fazendo pesquisas de design.",
  [813709740166656] = "Acho que esse tipo de pesquisa em qualquer cidade pode render muito...",
  [813709740166400] = "<P_Heart> (Ele parece estar conversando com a senhorita Elsa ao lado dele.) </>",
  [813709740166144] = "Obrigado, talvez um dia você veja meu último trabalho no jornal.",
  [813709740165888] = "Ah, não posso deixar de querer experimentar. O mundo da moda atual carece de coragem.",
  [813709740165632] = "Tenho algumas ideias ousadas. Por que não experimentar cores mais intensas?",
  [813709740165376] = "Então, que tipo de inspiração essa observação lhe deu?",
  [813709740165120] = "Comparado aos materiais acetinados macios e brilhantes, acho que o uso de bordados rígidos e rendas é mais comum aqui.",
  [813709740164864] = "Comparada a Backlund, Tingen, como uma “Cidade das Universidades”, parece ter algumas diferenças sutis nas tendências da moda.",
  [813709740164608] = "<P_Heart> (Como este poderia ser o menos confiável!) </>",
  [813709740164352] = "<P_Heart> (Bem, não é.) </>",
  [813709740164096] = "<P_Heart> (Não... também entendi ao contrário.) </>",
  [813709740163840] = "<P_Heart> (Olhe para cima... ufa, acertou.) </>",
  [813709740163584] = "<P_Heart> (Espere, também estou confuso, o que foi mesmo...) </>",
  [813709740163328] = "......Oh Deusa, eu não acho que eles vão contratar você.",
  [813709740163072] = "Lírio?",
  [813709740162560] = "Ganso?",
  [813709740162048] = "Andrô?",
  [813709740161792] = "É o Harrod.",
  [813709740161536] = "O que você acha de eu trabalhar como garçom na loja de departamentos Harold?",
  [813709740161280] = "Esta é a maior loja de departamentos de Tingen.",
  [813709740161024] = "Meu Deus... meus olhos estão deslumbrados!",
  [813709740160768] = "<P_Heart> (Parece que eles estão conversando sobre algum negócio de lanches... hmm, eu também quero comer.) </>",
  [813709740160512] = "<P_Heart> (mastigar mastigar mastigar) </> Talvez precise de algumas melhorias...",
  [813709740160256] = "Oh, hmm, eu acho <P_Heart> (mastigar mastigar mastigar) </> , é um pouco pegajoso?",
  [813709740160000] = "Adição de açúcar e outros aromas, muito adequados para mastigar...",
  [813709740159744] = "Senhor, por favor, olhe também para isto. A matéria-prima é a goma do Continente Sul, experimente.",
  [813709740159488] = "Um lanche com sabor único <P_Heart> (mastigar mastigar) </> , adequado para o chá da tarde...",
  [813709740159232] = "Claro, ainda precisa de avaliação <P_Heart> (mastigar mastigar mastigar) </> , mas <P_Heart> (mastigar mastigar mastigar) </> , é de fato...",
  [813709740158976] = "Extrair suco de frutas do Continente Sul e depois adicionar açúcar e leite para formar um sólido especial...",
  [813709740158720] = "Senhor, por favor, olhe essa comida, acho que vai vender como pão quente!",
  [813709740158464] = "<P_Heart> (Na verdade, ele ainda tem a capacidade de viver sozinho... Espero que ele consiga se recompor e não desistir de seu destino.) </>",
  [813709740158208] = "<P_Heart> (Mas coisas como essa acontecem com frequência aqui, e não tenho poder para ajudar. É um jogo de especulador; ganhe e você pode ficar rico da noite para o dia, perca e tudo vira de cabeça para baixo.) </>",
  [813709740157952] = "Que ações... é tudo... <P_Heart> (A voz fica cada vez mais baixa, não consigo ouvir com clareza.) </>",
  [813709740157696] = "Mentiroso... um completo mentiroso... perdi metade das minhas economias! ...Ah, Deusa...",
  [813709740157440] = "...... eu peguei todo o meu dinheiro para ...... investir ......",
  [813709740157184] = "<P_Heart> (Parece que há alguém aqui que acabou de encontrar um infortúnio. Vamos ouvir o que eles estão dizendo...) </>",
  [813709740156928] = "Não se preocupe, ainda tenho algum dinheiro sobrando.",
  [813709740156672] = "Ah, obrigado pelo seu incentivo. Eu também acho.",
  [813709740156416] = "Que a Deusa me proteja, quero tentar comprar aquele par de brincos de esmeralda... embora realmente custe um pouco de dinheiro.",
  [813709740156160] = "Este é o segredo para manter o amor fresco. Você ainda é muito jovem.",
  [813709740155904] = "Veja, Leon me ama muito.",
  [813709740155648] = "Tempestade acima! Meu marido acabou de me contar uma surpresa; ele vai me dar aquele colar de água-marinha como presente de aniversário!",
  [813709740155392] = "Afinal, nesta vida limitada, devemos primeiro desfrutar da liberdade da alma.",
  [813709740155136] = "Se quiser, pode deixar seu endereço, que irei visitá-lo quando tiver tempo livre.",
  [813709740154880] = "Então, quando devo ir até você para pedir um perfume?",
  [822510396496128] = "Uma história triste...",
  [813709740154368] = "Sinto muito, sempre sinto aperto no peito e dores de cabeça nos horários mais inconvenientes às quintas e sextas, e preciso ir ao campo para aliviá-los.",
  [813709740154112] = "Ah, sinto muito, vou dar um passeio à beira-mar na quarta-feira. Prometi trazer batatas fritas douradas para as gaivotas.",
  [813709740153856] = "Ah, que coincidência, o renascimento de “O Retorno do Conde” é na terça-feira, e me esforcei muito para comprar o ingresso.",
  [813709740153600] = "Olá, pedindo perfume? Sinto muito, hoje é segunda-feira e a perfumaria está fechada.",
  [813709740153088] = "<P_Heart> (Em conversa...) </>",
  [822511739042560] = "Sobre Tingen",
  [813709740152064] = "<P_Heart> (Beyonder comércio?) </>",
  [813709740151808] = "Tenho Beyonder material para vender. Eureka disse que você tem conexões aqui...",
  [804913646966784] = "Realmente?",
  [813709740151552] = "Aqui está um ramo de alecrim para você, volte de novo!",
  [813709740151296] = "Você realmente deveria ser um crítico gastronômico no Restaurante Bonaparte. Vou levar esse peixe também.",
  [822511738665728] = "Pode ser vendido por mais?",
  [1169951775789312] = "Acompanhado de chá gelado doce até tarde da noite",
  [822505833147136] = "É assim, quando saí em patrulha esta manhã, descobri que nosso reino havia sido bloqueado. Tentei encontrar uma brecha, mas ainda não consegui voltar à base.",
  [813709740150272] = "Ervilhas macias, batatas e cordeiro com desconto... hmm, será um jantar farto esta noite.",
  [813709740150016] = "<P_Heart> (Fantasmas de água?) </>",
  [822505833056000] = "Não fale em cuidar do bebê – rápido, rápido, tenho que ir para casa em cinco minutos, ainda dá tempo para mais uma rodada antes disso!",
  [822505833091840] = "São todos de estilo clássico e lindo, com ouro, pérolas e diamantes formando buquês, borboletas e o Ouroboros representando a eternidade. São joias decentes com um forte senso de presença.",
  [813709740149248] = "Uma sequência de 8 a Q, quer?",
  [813709740148992] = "<P_Heart> (Cão pegando corrida de rato?) </>",
  [813709740148736] = "Velho, você já decidiu em quem vai apostar para a próxima corrida \"Dog Catching Mouse\"?",
  [813709740148480] = "Lelange me lembra os dias em que as tempestades assolavam, mas agora sou apenas um cara velho.",
  [813709740148224] = "Caramba! Todos nós vamos morrer!",
  [813709740147968] = "Os olhos do diabo! Ele está olhando para mim! Olhando para mim! Eu vou morrer!",
  [813709740147712] = "Ele está pintando de sangue... Tenho que correr... Ahhh! Ele se virou e viu meu rosto! Ah, não!",
  [813709740147456] = "É o cheiro da morte...",
  [813709740147200] = "Sangue! Sangue! Tanto sangue!",
  [813709740146944] = "Este é um presente concedido pelo destino.",
  [813709740146688] = "Sim, é isto: cristal amarelo, uma profecia cristalina, um sinal não distorcido por forças externas. Muitos ouviram dele os sussurros de existências misteriosas.",
  [813709740146432] = "Não há necessidade de dizer mais nada. Deixe-me ver: mercúrio, ouro, rubi, pirita... não, nada disso corresponde ao seu destino acidentado.",
  [813709740146176] = "Corra para casa, Vina...",
  [813709740145920] = "Coloquei seu osso de carne preferido na tigela da Vina...",
  [813709740145664] = "Recebemos informações confiáveis ​​de que o autor dos assassinatos em série de Golden Elm está à espreita perto do Evil Dragon Bar. É imperativo examinar novamente todos dentro do bar.",
  [813709740145408] = "Só de pensar nisso me sinto feliz, não posso deixar de querer outra taça do bom vinho de sangue Soniath.",
  [813709740145152] = "Mesmo se eu estivesse bem na frente deles, eles nunca adivinhariam que sou a pessoa que procuram.",
  [862024900913408] = "Revista \"Estética da Senhora\"",
  [813709740144384] = "Senhora, acho que isso é tudo que existe.",
  [813709740144128] = "Ah, você está de volta. Por favor, me diga que você os encontrou.",
  [813709740142848] = "Apenas deixe-me ficar sozinho.",
  [813709740142592] = "Como eu poderia estar bêbado sem beber? Talvez fosse melhor se eu estivesse bêbado...",
  [813709740142336] = "Você está bêbado, isso é muito perigoso! Descer.",
  [813709740142080] = "Talvez eu pudesse faltar a esse exame, mas ainda teria que fazer o exame de reposição...",
  [813709740141824] = "Se eu fizer isso deliberadamente, posso quebrar um osso, mas qual seria o sentido?",
  [813709740141568] = "Estou muito calmo. Saltar daqui, desta altura, não passa de uma contusão de tecidos moles.",
  [813709740141312] = "Não seja impulsivo!",
  [813709740141056] = "Quanto mais você sabe, mais perigoso é.",
  [813709740140800] = "<P_Heart> (Suspiros) </> Eles são os Guardiões de Tingen...",
  [813709740140544] = "<P_Heart> (Os Vigias Noturnos parecem pertencer ao Sétimo Grupo do Departamento de Operações Especiais?) </>",
  [813709740140288] = "Novato, você acha que o Departamento de Operações Especiais só tem quatro grupos? A partir do quinto grupo, eles atuam nas sombras, lidando com fenômenos sobrenaturais pelas cidades do condado.",
  [813709740140032] = "Devo entregá-lo ao Grupo de Proteção VIP ou ao Grupo de Proteção de Sites Importantes?",
  [813709740139776] = "Tudo bem, entregue isso ao Departamento de Operações Especiais para cuidar.",
  [813709740139520] = "Definitivamente era uma mão humana saindo da pilha de destroços na cena do crime, e ainda estava em movimento!",
  [813709740139264] = "Suspiro, da próxima vez eu realmente deveria encontrar alguém com quem ir. Perder-se é apenas uma ocorrência normal para mim.",
  [813709740139008] = "Não tem problema {{Sr.|Sra.}}, obrigado pela sua gentileza.",
  [813709740138752] = "Desculpe, também não estou muito familiarizado com esta área.",
  [813709740138496] = "Mas... qual caminho é o norte e qual caminho é o leste? Vou estudar um pouco mais.",
  [813709740138240] = "Obrigado...",
  [813709740137984] = "Siga esta estrada para o norte e vire para o leste no cruzamento.",
  [813709740137728] = "A Sra. Connie me convidou para uma festa, mas... parece que me perdi. Que vergonha.",
  [813709740137472] = "{{Sr.|Sra.}} Olá, por acaso você sabe onde fica a casa da Sra. Connie?",
  [813709740137216] = "Senhora, precisa de ajuda?",
  [813709740136960] = "<P_Heart> (Melhor cortar minhas perdas agora...) </>",
  [813709740136448] = "Sol escaldante? Sombra?",
  [813709740136192] = "Você não sente isso? Esta é a chuva do céu! Sob a sombra do sol escaldante, a bênção de Deus...",
  [813709740135936] = "Parece... esse copo não tem nenhum sentimento especial?",
  [813709740135680] = "Tem mais uma xícara! Mais uma xícara! Quer experimentar?",
  [813709740135424] = "<P_Heart> (Não admira que o Sr. Tamang não o deixe se formar...) </>",
  [813709740135168] = "É o meu recém-desenvolvido café com pimenta preta! Ouvi dizer que o café com pimenta verde vende bem em outras regiões, então estou aprendendo com isso...",
  [813709740134912] = "Tosse tosse tosse! Um sabor tão picante... Água! Água!",
  [813709740134656] = "Não, obrigado, o material grátis é o mais caro.",
  [813709740134400] = "<P_Heart> (As duas senhoras parecem estar discutindo sobre algo, deixe-me ouvir primeiro...) </>",
  [813709740134144] = "Você gostaria de outra xícara?",
  [813709740133888] = "<P_Heart> (Uh...) </>",
  [813709740133632] = "É lama de sapato! A fragrância de couro e terra, que inebriante...",
  [813709740133376] = "Ptooey... o que você acrescentou a isso? É horrível, por que tem gosto de terra molhada?",
  [813709740133120] = "Como é grátis, vou experimentar!",
  [813709740132864] = "Algum interesse em experimentar um café novo? Eu mesmo desenvolvi, é grátis!",
  [813709740132608] = "OK! Vamos conversar outro dia!",
  [813709740132352] = "Desculpe, tenho que trabalhar, vamos conversar outro dia!",
  [813709740132096] = "Entrarei em contato com você na próxima vez que a vir. Deusa acima, não aumente mais minha carga de trabalho.",
  [813709740131840] = "Você precisa de ajuda para investigar?",
  [813709740131584] = "Uma senhora estranhamente vestida veio ao café procurar alguém mais cedo, parecendo furiosa. Não parecia nada de bom.",
  [813709740131328] = "Mas o Sr. Tamang não permite que um cachorro entre em seu café. Ele simplesmente não consegue aceitar esse tipo de coisa, suspiro.",
  [813709740131072] = "……Os danos causados ​​pela guerra ainda não diminuíram.",
  [813709740130816] = "O marido e o filho morreram na guerra há alguns anos. Agora são só ela e aquela cadela chamada Laura, e elas vão a todos os lugares juntas.",
  [813709740130560] = "Como assim?",
  [813709740130304] = "A senhora na porta parece irracional, mas posso entendê-la.",
  [813709740130048] = "Hmph, vestido como um humano! Ele não é nem tão leal quanto um cachorro, passando o dia todo com conversa fiada, enganando aquelas garotas ingênuas.",
  [813709740129536] = "Ele simplesmente parece decente. Andy, da loja de roupas, já reclamou várias vezes comigo, dizendo que vai à loja todos os dias para devolver peças por diversos motivos.",
  [813709740129280] = "A julgar pelo seu traje, aquele cavalheiro não parece estar com pouco dinheiro.",
  [813709740129024] = "É ele. Ele trouxe três mulheres diferentes para o nosso café em uma semana. O que é ainda mais exagerado é que as mulheres pagavam sempre.",
  [813709740128768] = "Eu o vejo.",
  [813709740128512] = "Ei! Vê aquele homem em um encontro lá dentro? Aquele sentado em frente a uma senhora.",
  [813709740128256] = "Eu o admiro muito! Mas sou aprendiz há tanto tempo que tenho um certo ressentimento, então só estou reclamando um pouco, só um pouquinho... só finjo que não falei nada.",
  [813709740128000] = "Não, não, não, o Sr. Tamang é o melhor e mais profissional barista de toda Tingen.",
  [813709740127744] = "Você está planejando seguir carreira solo então?",
  [813709740127488] = "Aprendo com ele há três anos! Em qualquer outro café eu teria sido um barista capaz de trabalhar sozinho, mas ainda sou um aprendiz...",
  [813709740127232] = "Hum?",
  [813709740126976] = "Sr. Tamang é ótimo em tudo, mas ele é muito antiquado em relação ao café, é uma dor de cabeça...",
  [813709740126720] = "{{Sr.|Sra.}} Olá, bem-vindo ao Corner Café.",
  [813709740126464] = "<P_Heart> (\"Escamas de tritão\" são claramente escamas de peixe comuns que foram tingidas, e aquelas \"pedras de sereia\" são ainda mais ridículas - são apenas vidro azul comum.) </>",
  [813709740126208] = "O que é uma escala de tritão? Minhas abotoaduras são Siren Stones compradas durante as férias em Midseashire. Ouvi dizer que você não consegue encontrar um segundo par em toda Loen!",
  [813709740125952] = "Esta bolsa é feita de escamas de tritão genuínas; cada um brilha com um brilho diferente. Meu tio o trouxe de uma longa viagem ao continente meridional.",
  [813709740125184] = "Suspirar! E gastou um dinheiro extra para alugar um smoking de segunda mão, meu tolo irmão!",
  [813709740124928] = "Custa dinheiro estar neste clube! Já basta ter um idiota na nossa família desperdiçando dinheiro!",
  [813709740124672] = "Por que não entrar no clube e encontrar Luther?",
  [813709740124416] = "Se você me perguntar, em vez de perder tempo com isso, seria melhor orar na igreja da Deusa!",
  [813709740124160] = "Meu irmão, ele corre para esse clube todos os dias! Ele diz que pode ver sua fortuna!",
  [813709740123904] = "Quem é esse Lutero de quem você está falando?",
  [813709740123648] = "<P_Heart> (Ele parece um pouco perturbado?) </>",
  [813709740123392] = "Quando aquele idiota do Luther finalmente vai sair!",
  [813709740123136] = "Existem apenas algumas universidades no lado leste de Tingen! ... Poderia estar lá?",
  [813709740122880] = "O “lado leste” soa como uma dica direcional?",
  [813709740122624] = "Algum tipo de renascimento? Deusa acima, não tenho ideia!",
  [813709740122368] = "A que você acha que o berço pode se referir?",
  [813709740122112] = "<P_Heart> (Adivinhos são sempre tão vagos.) </>",
  [813709740121856] = "Você não pode tornar a revelação mais clara! O que significa “época do berço na zona leste”?",
  [813709740121600] = "Uau au au au au! Uau!",
  [813709740121344] = "O que está errado? O que acabei de dizer foi tão ofensivo?",
  [813709740121088] = "......Uau?",
  [813709740120832] = "<P_Heart> (Ouvindo a risada de um cachorro, devo ter enlouquecido.) </>",
  [813709740120576] = "Uau-hee-hee-hee...",
  [813709740120320] = "O dono da barraca é um cachorro?",
  [813709740119808] = "Deixa para lá.",
  [813709740119552] = "Suas falas são sempre tão ruins?",
  [813709740119296] = "Meu nome é Olivia, e administro esta barraca e aquele restaurante do outro lado da rua que não tem negócios.",
  [813709740119040] = "Se você puder comprar todas as minhas flores agora mesmo, prometo sorrir mais do que aquele idiota jogando bolas do outro lado da rua.",
  [813709740118784] = "Sua atitude de serviço é terrível, senhorita.",
  [813709740118528] = "Se você está aqui para comprar flores, jogue o dinheiro naquela caixinha.",
  [813709740118272] = "Desculpe, estamos incomodando você?",
  [813709740118016] = "<P_Heart> (Vamos dar uma olhada um pouco mais.) </>",
  [813709740117760] = "<P_Heart> (Ela disse que está construindo um navio de guerra blindado?) </>",
  [813709740117504] = "Não me incomode! Não consigo memorizar tudo! Não consigo memorizar tudo!",
  [813709740117248] = "Eu sou definitivamente um gênio da pintura! Espere até eu ficar famoso!",
  [813709740116992] = "Quem pode me ajudar a escrever minha tese!",
  [813709740115712] = "Vamos conversar novamente na próxima vez!",
  [813709740115456] = "Cara nova? Olá!",
  [813709740115200] = "Talvez seja porque a luz do sol aqui é tão agradável, os livros têm um cheiro maravilhoso e o café que Angélica prepara é mais saboroso do que em qualquer outro lugar.",
  [813709740114944] = "Mas ainda gosto de vir aqui.",
  [813709740114688] = "Existem muitas maneiras de interpretar sinais adivinhação e eu conheço todas elas.",
  [1139094851708160] = "Mostrar distintivo da polícia",
  [813709740114176] = "Não posso confiar meu plano de investimento empresarial a alguém assim.",
  [813709740113920] = "Você é novo aqui? Não saia por aí pedindo às pessoas adivinhação ; a maioria deles não consegue nem calcular os números espirituais mais básicos!",
  [813709740113664] = "Eles estão conduzindo algum tipo de transação?",
  [813709740113408] = "De quem ela está se escondendo?",
  [813709740113152] = "Esta pessoa parece bêbada; eles confundiram este lugar com um banheiro?",
  [813709740112896] = "Nossa, parece que a comunicação é completamente impossível.",
  [813709740112640] = "Não tenho nada a dizer! Polícia inútil, vou registrar queixa contra você!",
  [813709740112128] = "Onde você quiser ir, eu te levarei na hora certa!",
  [813709740111872] = "Terminando em [90010000]",
  [813709740111616] = "Existem novos desenvolvimentos?",
  [813709740111360] = "{{Sr.|Sra.}}, gostaria de um jornal?",
  [813709740111104] = "Lierly me lembra dos dias em que as tempestades assolavam, mas agora sou um cara velho.",
  [813709740110848] = "Carter, quando você vai me devolver essas 200 libras? Ou jogar outra partida de bilhar?",
  [813709740110336] = "Eu pretendo...",
  [813709740110080] = "Com que fundamento...",
  [813709740109824] = "O lojista é um pombo?",
  [813709740109568] = "O que esse corvo está fazendo?",
  [813709740109312] = "Estou perguntando se parece bom!",
  [813709740109056] = "Está bem vermelho.",
  [813709740108800] = "Passei batom novo hoje, ficou bom?",
  [813709740108544] = "Mas quando pensei em ter muitos companheiros comigo, não tive medo nenhum.",
  [813709740108288] = "Eu costumava pensar que era um pouco estranho e frio aqui.",
  [813709740108032] = "{{Sr.|Sra.}}, gostaria de comprar pão ou bolo?",
  [813709740107776] = "Eles ainda contam comigo para limpar as lápides; eles não farão nada comigo.",
  [813709740107520] = "Quanto a mim, lido com parceiros clandestinos o dia todo, então estou acostumado.",
  [813709740107264] = "Saia mais cedo depois de terminar seu negócio, meu jovem; a noite aqui não pertencerá a você.",
  [813709740107008] = "Se você comprar duas estátuas de uma vez, posso lhe dar um certo desconto.",
  [813709740106752] = "O orgulho de Tingen, o guardião dos estudantes, objeto de culto das crianças!",
  [813709740106496] = "Este {{Sr.|Sra.}}, venha ver as lembranças da Escultura do Conhecimento!",
  [813709740106240] = "Você está interessado em aprender sobre a Escultura do Conhecimento de Tingen?",
  [813709740105984] = "Então papai doará um prédio para cada um deles para que meu tesouro tenha mais espaço para escolha.",
  [813709740105728] = "Por que você não está respondendo ao papai? Ou você quer que o papai te ajude a decidir?",
  [813709740105216] = "A Universidade Hoy de Tingen e a Universidade de Tingen são boas. Qual deles você deseja participar no futuro?",
  [813709740104960] = "Criança, você vê? Esta é a Escultura do Conhecimento de Tingen.",
  [813709740104704] = "Que a Mãe das Universidades seja testemunha de tudo isto! Jenny, veja minha sinceridade por você!",
  [813709740104448] = "Então decidi mudar minha abordagem; Vou derrotar o primeiro colocado Francesco!",
  [813709740104192] = "Tentei muitos métodos, mas não consegui chegar ao primeiro lugar.",
  [813709740103936] = "Espero que sim, se algum dia ele voltar a Tingen.",
  [813709740103680] = "Então parece que você ainda tem chance de continuar aprendendo suas fórmulas mágicas.",
  [813709740103424] = "Parece que você entendeu mal alguma coisa. Ele acabou de sair, saiu de Tingen, só isso. Droga, ainda tenho que entregar a maior parte da minha renda para ele todos os meses.",
  [813709740103168] = "Minhas condolências!",
  [813709740102912] = "Esta é uma loja de ervas que de repente assumi do meu mestre. Ele foi embora de repente, e há muitas receitas que ainda não aprendi – receitas mágicas.",
  [813709740102656] = "Esta não é uma loja de ervas muito famosa em Tingen?",
  [813709740102400] = "Adianto antecipadamente que aqui só vendo receitas com efeitos fixos; eles podem ser úteis ou inúteis.",
  [813709740102144] = "Você foi apresentado por um conhecido?",
  [813709740101888] = "Chega de conversa, vamos dar uma olhada nos vegetais. Pepinos frescos, tomates, que lindo!",
  [813709740101632] = "Os jovens não gostam de estar perto de um cemitério sem vida e todos foram para as grandes cidades em busca de oportunidades. Só restamos nós, ossos velhos, aqui...",
  [813709740101376] = "Esta costumava ser a praça mais animada de Tingen, mas agora diminuiu. Observe o ambiente circundante e saberá porque há cada vez menos pessoas aqui.",
  [813709740101120] = "Não há nada de errado em viver com os mortos. De certa forma, os mortos são muito menos problemáticos que os vivos!",
  [813709740100864] = "Hehe, não me olhe assim; mesmo que você more perto do cemitério, a vida ainda precisa continuar.",
  [813709740100608] = "Olhe para o porco – porco de orelhas encaracoladas e pêlo curto, ou o que quer que seja aquele porco de orelhas curtas e pêlo encaracolado, uma nova raça! Venha e dê uma olhada!",
  [813709740100352] = "Vende peixe na Riverside Street há 10 anos; todo mundo me conhece.",
  [813709740100096] = "Não se preocupe, o peixe aqui é absolutamente fresco.",
  [813709740099840] = "Você quer comprar peixe?",
  [813709740099328] = "O bolo de cenoura tem um sabor muito refrescante; encontro é raro, então vou te dar um pedaço para provar.",
  [813709740099072] = "Não posso ir para Tingen sem um missão ? Embora o café aqui não seja tão bom quanto em Backlund, as empregadas... aham, ainda são muito simpáticas.",
  [813709740098816] = "Você está aqui em Tingen para um missão de novo?",
  [813709740098560] = "...... O tempo voa tão rápido.",
  [813709740098304] = "Mas você me lembrou; é hora de ver alguns velhos amigos.",
  [813709740098048] = "Ferida? Você não se refere à lesão que sofreu em Tingen durante um missão , não é? Já faz tanto tempo que curou há muito tempo.",
  [813709740097792] = "Sua lesão está bem?",
  [813709740097536] = "Eu vejo. Ainda estou de férias; podemos conversar sobre trabalho mais tarde.",
  [813709740097280] = "Uh... eu sou um membro da equipe civil.",
  [813709740097024] = "Shh! Mantenha sua voz baixa; você não pode falar sobre isso aleatoriamente. Você é um Vigia Noturno? Por que não me lembro de você? Minha memória também piorou?",
  [813709740096768] = "Sim, sim, quando estávamos transportando aquele boneco, em Riel...",
  [813709740096512] = "Quem é você...? Nós nos conhecemos?",
  [813709740096000] = "Desculpe, tenho um compromisso.",
  [813709740095744] = "Senhora...",
  [813709740095488] = "Bem-vindo de volta na próxima vez; Estou ansioso para conhecê-lo novamente.",
  [813709740095232] = "Espere um momento, a deliciosa comida está sendo preparada.",
  [813709740094976] = "{{Sr.|Sra.}}, aqui está o menu. Espero que você encontre o que deseja aqui.",
  [813709740094720] = "A sobremesa recomendada de hoje é bolo de cenoura, doce mas não gorduroso, saudável e nutritivo.",
  [813709740094464] = "O chá preto Marquês tem fragrância duradoura, sabor suave e acidez moderada, mais adequado para um {{Sr.|Sra.}} com sabor excelente como você.",
  [813709740094208] = "O café Filmer é produzido próximo ao Star Plateau, no Vale da Paz. É denso e leve, com final de boca duradouro; é uma boa escolha.",
  [813709740093952] = "Temos todos os tipos de café, chá preto e chá gelado doce especialmente preparados para crianças, pequenos bolos, tortas de frutas e assim por diante, garantindo que todos os hóspedes tenham momentos maravilhosos.",
  [813709740093696] = "Bem-vindo ao Corner Cafe, {{Sr.|Sra.}}, precisa de alguma coisa?",
  [813709740093184] = "A carta do Louco que você convocou aparece na vertical. Você é o fim e também o começo... Desculpe, não consigo ver mais.",
  [813709740092928] = "A carta Eremita que você convocou aparece na vertical. A verdadeira resposta muitas vezes vem de dentro... Desculpe, não consigo ver mais.",
  [813709740092672] = "A carta da Lua que você convocou aparece ao contrário. Seu passado está coberto pela névoa... Desculpe, não consigo ver mais.",
  [813709740092416] = "Por favor, estenda sua mão e deixe sua intuição guiá-lo na escolha dessa carta.",
  [813709740092160] = "<P_Yellow> (Embaralha as cartas e as entrega para você) </> Qual segredo você deseja explorar?",
  [813709740091648] = "Alma perdida, por favor, pare e ouça os sussurros do destino. A cada amanhecer ganharei a oportunidade de revelar-lhes os mistérios.",
  [813709740091392] = "Você gostaria de um pouco de alecrim, manjericão ou cominho? Você sabe, eles são a alma da comida deliciosa.",
  [813709740091136] = "Talvez você devesse inventar um nome melhor.",
  [813709740090880] = "É só assar o peixe salgado na torta!",
  [813709740090624] = "Tudo bem, mas ainda sugiro que você compre um peixe salgado. Afinal, tem um significado muito mágico; O Imperador Roselle sempre disse: 'Um peixe salgado pode virar!'",
  [813709740090368] = "Vendo aqui todos os tipos de iguarias de peixe salgado. Quer experimentar minha recém-desenvolvida torta de peixe salgado?",
  [813709740090112] = "É tudo pão recém-assado esta manhã. Você gostaria de um pouco?",
  [813709740089856] = "As folhas verdes são um presente da Terra! Veja, suas cores são tão brilhantes que parecem brilhar. Esta é a verdadeira frescura do ‘farm to table’!",
  [813709740089600] = "Esses vegetais foram todos cultivados por mim; eles têm um gosto ótimo. Você gostaria de um pouco?",
  [813709740089344] = "Deixe-me pensar, Kalia tem um lote de presunto que tem um gosto muito bom; você pode tentar. Dizem que é importado do exterior.",
  [813709740088832] = "O pão de Shelia é muito bom, mas o da barraca de peixe salgado de Hoffman não é muito bom.",
  [813709740088576] = "Tem mais alguma coisa deliciosa na Iron Cross Street?",
  [813709740088320] = "Você gostaria de uma tigela de ensopado? Meu ensopado é o melhor da Rua Cruz de Ferro!",
  [813709740088064] = "Transportando peixes para o cais... já tentei o meu melhor...",
  [813709740087808] = "Acordo cedo... para ir ao cais...",
  [813709740087552] = "Estamos muito familiarizados com a Iron Cross Street e podemos ajudá-lo a encontrar pessoas ou entregar cartas. Você precisa disso?",
  [813709740087296] = "{{Sr.|Sra.}}, você pode comprar um vaso de flores? Eu... preciso economizar dinheiro para o tratamento médico do meu irmão.",
  [813709740087040] = "Sim, você passará por aquele mar de flores ao pegar o trem para Backlund.",
  [813709740086784] = "Um mar de flores?",
  [813709740086528] = "Estas flores foram todas desenterradas perto de uma aldeia a sudeste de Tingen, onde existe um vasto mar de flores.",
  [813709740086272] = "De onde vieram essas flores?",
  [813709740086016] = "{{Sr.|Sra.}}, comprando flores?",
  [813709740085760] = "Vocês também não gostam desses órfãos?",
  [813709740085504] = "Você precisa de ajuda com sua bagagem? Estou muito familiarizado com esta área.",
  [813709740085248] = "The Tingen Morning Post, 1 centavo por exemplar.",
  [813709740084992] = "Qual jornal você quer? Todos custam 1 centavo.",
  [813709740084736] = "Não, ele disse que queria ser um açougueiro culto e foi para casa escrever 'Cuidados fisiológicos pós-parto para porcas domésticas'!",
  [813709740084480] = "Ele decidiu não ser açougueiro e voltar a estudar acadêmicos? Naquela época, o Jornal Honesto publicou a notícia de que seu pai desistiu do ensino superior para ser açougueiro; ficamos todos muito surpresos...",
  [813709740084224] = "Senhora, você sabe, meu pai se formou no Departamento de Literatura da Universidade de Tingen; ele tem um sonho literário!",
  [813709740083968] = "Obrigado! Onde está seu pai, Sr. Butcher? Por que você é o único vigiando a barraca? Você nem é tão alto quanto o balcão!",
  [813709740083712] = "Carne de porco preta fresca! Dona Jenny, guardei as costelas mais completas para você!",
  [813709740083456] = "Gostaria de uma leitura de Tarot? As cartas ao meu alcance podem adivinhar seu destino desconhecido.",
  [813709740083200] = "Ouvi dizer que a loja de departamentos Harold tem novidades novamente.",
  [813709740082944] = "Eu odeio pessoas que fumam!",
  [813709740082688] = "O tabaco é a arma do homem na sua mesa. Ouvi dizer que a Backlund Cigar Shop está indo bem; talvez eu deva abrir um também?",
  [813709740080896] = "Que o Steam proteja você!",
  [813709740080640] = "Louvado seja a Meia Noite, louvado seja a Deusa da Meia Noite!",
  [813709740079872] = "Que a Noite te proteja!",
  [813709740078336] = "Que a Terra proteja você!",
  [813709740076800] = "Que a bênção do tolo esteja com você!",
  [813709740076288] = "Sangue... o cheiro da morte... <P_Heart> (Abaixa a cabeça, sem ousar olhar nos seus olhos.) </>",
  [813709740076032] = "Customizar roupas aqui é mais barato do que ir àquelas lojas de roupas; Eu só ganho um pouco pelo trabalho.",
  [813709740075776] = "Posso fazer estilos comuns de roupas. Apenas me diga os requisitos gerais do estilo; Não sou muito bom com roupas de alta qualidade.",
  [813709740075520] = "Você veio ao lugar certo. Muitos dos vizinhos da Rua Cruz de Ferro mandam fazer roupas por mim; minhas habilidades de alfaiataria são excelentes!",
  [813709740075008] = "Bem-vindo à minha alfaiataria. Você precisa de roupas sob medida?",
  [813709740074752] = "Eu sabia que você diria aquelas coisas inúteis...",
  [813709740074496] = "A misericórdia fraca só leva à perda do espírito de luta. O Senhor das Tempestades nos ensina que é preciso lutar na tempestade como um petrel, e não esperar por esmolas!",
  [813709740074240] = "A sua Igreja do Rio e do Mar distribui alimentos? A Catedral de Santa Selena distribuía pão antes.",
  [813709740073984] = "Ele é o Rei que governa o céu, o Imperador que domina o mar, o grande Deus das Tempestades!",
  [813709740073728] = "A escritura 'Livro das Tempestades' nos diz para não defender a luta ou pregar a guerra, mas devemos tratar os inimigos com a crueldade de uma tempestade!",
  [813709740073472] = "...Seu espírito se transformou no Eterno Sol Ardente, o Senhor das Tempestades e o Deus do Conhecimento e da Sabedoria; a humanidade nasceu de Sua sabedoria.",
  [813709740073216] = "O Criador acordou do caos, rompeu a escuridão, criou o primeiro raio de luz e então fundiu-se completamente no universo, tornando-se todas as coisas...",
  [1139165181860096] = "Eu entendo.",
  [813709740072704] = "A Tempestade está acima; você já ouviu falar da revelação da Tempestade?",
  [813709740072448] = "Arcebispo Snake de Backlund, conhecido como o \"Cantor de Deus\", diz-se que uma canção de \"Heart of the Storm\" é capaz de fazer ressoar a água do mar de todo o porto de Backlund! E vocês não conseguem nem encontrar a chave, suspiro!",
  [813709740072192] = "Ouça, o coro do Senhor das Tempestades não é brincadeira de criança! Em alto mar, cantar é a arma dos marinheiros.",
  [813709740071936] = "A apresentação do coral é muito importante para você?",
  [813709740071680] = "A apresentação na igreja é na semana que vem e você ainda está cantando tão mal!",
  [813709740071424] = "Obrigado pelo seu reconhecimento. Essas opiniões são apenas algumas ideias que ouvi com frequência em minha cidade natal.",
  [813709740071168] = "Você está interessado em ingressar no nosso Departamento de História da Hoy University? Acho que você tem ideias muito originais.",
  [813709740070912] = "Como disse, a história é em grande parte causada por conflitos entre uma minoria de pessoas que procuram mudanças, enquanto a maioria das pessoas apenas aplaude e torce pelos vencedores, considerando-se os condutores da história.",
  [813709740070656] = "De fato. Somente as pessoas de alto escalão decidem a direção da história, e o fazem para seus próprios propósitos; as pessoas comuns são simplesmente forçadas a seguir o fluxo.",
  [813709740070400] = "No entanto, a única lição que os humanos aprendem com a história é que os humanos não aprendem lições com a história.",
  [813709740070144] = "O passado tornou-se história e a história é, sem dúvida, grande. Queremos extrair dele alimento, fornecer avisos e evitar que as tragédias se repitam.",
  [813709740069888] = "Eu faço. Quem não estaria interessado em tudo o que aconteceu no passado?",
  [813709740069632] = "Você gosta de história?",
  [813709740069376] = "Isso parece muito bom.",
  [813709740069120] = "Graduar-se aqui permite que você vá diretamente para qualquer universidade em Loen como membro do corpo docente. Esta é a prova do nosso valor.",
  [813709740068864] = "No mínimo, em termos de literatura e história, esmagamos completamente a Universidade de Tingen. Não há dúvida sobre isso.",
  [813709740068608] = "Se você me perguntar qual universidade em Tingen é melhor, é claro que pensarei que é a nossa Universidade Hoy.",
  [813709740068352] = "De jeito nenhum, qual universidade em Tingen você acha que é melhor!",
  [813709740068096] = "Você é estudante aqui?",
  [813709740067840] = "Bem-vindo ao Restaurante Coastline para provar os sabores do oceano austral.",
  [813709740067584] = "Obrigado.",
  [813709740067328] = "Como pessoa comum, também farei o possível para cooperar com o seu trabalho.",
  [813709740067072] = "Você não está aqui há muito tempo, então talvez não saiba dessas coisas, mas entenderá mais tarde. Isto não é segredo; O capitão Dunn é um bom homem e Klein também é um muito bom Vigia Noturno .",
  [813709740066816] = "É aquele onde seu quartel-general foi atacado! O capitão Dunn e os outros impediram a descida de um deus maligno e protegeram a nós, pobres cordeiros.",
  [813709740066560] = "Qual incidente?",
  [813709740066304] = "Depende de todos vocês. Há cada vez mais Beyonder incidentes ultimamente, fazendo com que nós, idosos, nos sintamos apavorados, especialmente depois desse incidente.",
  [813709740066048] = "Você é muito gentil; Ainda preciso aprender mais experiência com meus superiores.",
  [813709740065792] = "Ahem, você deve ser o novo policial! Você é tão jovem; jovem e promissor!",
  [813709740065536] = "Você está doente? Deixe-me prescrever algumas ervas tradicionais.",
  [813709740065280] = "Não existe panacéia, mas existem prescrições para sintomas específicos.",
  [813709740065024] = "Afinal, o negócio do tabaco é prejudicial. Então, você precisa de um mordomo excelente e decente?",
  [813709740064768] = "Se você tiver um voto, por favor, vote em Sir Derval; ele certamente não irá decepcionar você.",
  [813709740064512] = "Ele certamente parece um excelente industrial.",
  [813709740064256] = "Ele também não usou a riqueza que ganhou para se divertir; ele construiu estradas e pontes, fez doações para a construção de bibliotecas, estabeleceu fundações de caridade e forneceu regularmente financiamento para asilos.",
  [813709740064000] = "Ele aprendeu com o imperador Roselle a revitalizar o país através da indústria, criando siderúrgicas, fábricas de porcelana e fábricas têxteis em Tingen, proporcionando um grande número de empregos.",
  [813709740063744] = "Sir Dervish é natural de Tingen. Não creio que alguém ame Tingen mais do que ele.",
  [813709740063488] = "Você pode me contar mais sobre isso?",
  [813709740063232] = "O velho já está nessa idade; não seria melhor ser membro da Câmara dos Lordes em Backlund? Por que ele deveria concorrer à prefeitura de Tingen?",
  [813709740062976] = "Louvado seja o Imperador!",
  [813709740062720] = "Meu ídolo é o Imperador Roselle. Ele foi um homem de ação que mudou todo o Intis com sua própria força.",
  [813709740062464] = "Isso parece muito bom.",
  [813709740062208] = "Por favor, me dê seu voto. Quero me tornar prefeito e realizar uma série de reformas para mudar o declínio de Tingen.",
  [813709740061952] = "O meu fundo de caridade por si só não pode ajudá-los; só aumentando o rendimento poderemos impulsionar o desenvolvimento económico.",
  [813709740061696] = "Aumentar adequadamente o emprego, esforçar-se por estabilizar os preços e estimular ativamente o consumo. Tenho muitas fábricas e conheço muito bem as verdadeiras demandas atuais dos trabalhadores.",
  [813709740061440] = "Se for eleito, que medidas tomará para mudar o status quo?",
  [813709740061184] = "Estou me preparando para participar das eleições para prefeito de Tingen. Tingen é terrível demais agora.",
  [813709740060928] = "Afinal, nosso futuro depende de bibliotecas, leitura e devaneios.",
  [813709740060672] = "Tenho me esforçado para aumentar o orçamento para livros e também estou entrando em contato com algumas pessoas de classe alta dispostas a doar livros. Espero que um dia haja inúmeros livros para ler aqui.",
  [813709740060416] = "Embora nosso acervo não se compare à biblioteca doada por Sir Dervish, nem tenha tantos livros raros quanto a biblioteca universitária, esta é a única biblioteca da cidade aberta a todos.",
  [813709740060160] = "Bem, se você tiver alguma consulta sobre assuntos familiares, pode vir até mim.",
  [813709740059904] = "Os jovens de hoje em dia não gostam de casar; Acho que isso é um problema muito sério!",
  [813709740059648] = "Obrigado, mas não tenho nenhuma necessidade nesse sentido por enquanto.",
  [813709740059392] = "Posso ajudar famílias recém-criadas a planejar as responsabilidades e obrigações que precisam assumir umas com as outras, como organizar as despesas domésticas e como equilibrar receitas e despesas...",
  [813709740059136] = "Louvado seja a Tempestade! Se você tiver alguma consulta sobre assuntos familiares, pode vir até mim.",
  [813709740058880] = "Tingen... Tingen é apenas uma cidade universitária, sem esperança e sem amor.",
  [813709740058624] = "Com amor!",
  [813709740058368] = "É simplesmente melhor que Tingen em todos os sentidos! Afinal, é a capital de Loen, uma terra próspera e rica de esperança! Diga-me, como posso ficar com minha namoradinha?",
  [813709740058112] = "Simplesmente?",
  [813709740057856] = "O que há de tão bom em Backlund? Além de ser grande, é simplesmente... simplesmente...",
  [813709740057600] = "Minha filha Selena, uma linda senhora, minha queridinha, recentemente tem feito barulho por viajar para Backlund, sem se importar nem um pouco com os sentimentos desse velho pai.",
  [813709740057088] = "Há algo em que eu possa ajudá-lo? Bem, não posso te ajudar em nada agora.",
  [813709740056832] = "Eu tenho alguns remédios mágicos aqui.",
  [813709740056576] = "Ouvi dizer que a siderúrgica está contratando?",
  [813709740056320] = "Nós, pessoas comuns, não temos habilidades ou conhecimentos, então só podemos vender nossa força e nos tornarmos trabalhadores.",
  [813709740056064] = "Para idosos como nós, poder viver com segurança e tomar algumas garrafas de vinho é considerado sorte, não é mesmo?",
  [813709740055808] = "Aqueles senhores sentados em carruagens? A vida deles é muito mais fácil!",
  [813709740055552] = "{{Sr.|Sra.}}, para onde você precisa de uma passagem de barco?",
  [813709740055296] = "Ser capaz de movimentar carga nas docas de Tingen agora já é muito bom para mim.",
  [813709740055040] = "Meu conselho para você é ser cauteloso em tudo e se proteger bem.",
  [813709740054784] = "Já estamos em um mundo louco. Até mesmo potências como Dunn e Daly retornaram ao abraço da Deusa.",
  [813709740054528] = "Beyonders também são mais fáceis de avançar agora, mas existe o risco de perder o controle. Riscos e oportunidades coexistem.",
  [813709740054272] = "Há cada vez mais incidentes envolvendo deuses malignos e as pessoas comuns estão sendo afetadas de forma mais ampla.",
  [813709740054016] = "Qual é a situação? É o mesmo de sempre; tudo fora do mundo das pessoas comuns é uma bagunça.",
  [813709740053760] = "Acabei de chegar em Tingen. Você pode revelar a situação aqui para mim?",
  [813709740053504] = "Você pode encontrar muitas coisas que deseja aqui: notícias, itens, recompensas. Você terá que descobrir o resto sozinho.",
  [813709740053248] = "O Evil Dragon Bar é um dos bares mais animados de Tingen. Os trabalhadores do distrito portuário e do distrito fabril adoram vir aqui, e também é um ponto de encontro para nós, Punidores Mandatados.",
  [813709740052992] = "Tempestades acima, Tingen está se tornando cada vez menos pacífica.",
  [813709740052736] = "Sim, vá à catedral para rezar com frequência!",
  [813709740052480] = "Viva uma vida normal, fique longe de coisas estranhas e vá à catedral para orar com frequência.",
  [813709740052224] = "Hoje em dia, em Tingen, há cada vez mais coisas estranhas. Eu realmente não sei como nós, cidadãos comuns, vamos sobreviver.",
  [813709740051968] = "Sinto que minha sorte não tem sido muito boa ultimamente. Devo ir ao Clube Adivinhação para uma leitura?",
  [813709740051712] = "Sim, é isso - legal. Não tão complicado e lindo como antes. Simplicidade e adequação são as necessidades comuns das pessoas agora, e é exatamente nisso que sou bom.",
  [813709740051456] = "Mais legal.",
  [813709740050176] = "Venha trocar de roupa; as pessoas confiam nas roupas!",
  [813709740049920] = "Isto é verdade, claro, mas para a classe trabalhadora, gastar 2 centavos por uma bebida é um dos poucos passatempos que podem pagar.",
  [813709740049664] = "Isso faz sentido, mas existem muitas maneiras de aliviar o estresse; não precisa ser bebida.",
  [813709740049408] = "Liberar o estresse ajuda a manter a estabilidade mental. Você sabe como a estabilidade mental é importante nesta era caótica.",
  [813709740049152] = "Não defendo o consumo de álcool, mas depois de um dia cansativo, vir aqui tomar uma bebida para relaxar ainda é muito necessário.",
  [813709740048896] = "Relaxe, não é grande coisa. Contanto que você beba, todos os seus problemas desaparecerão.",
  [813709740048640] = "Parece que você é uma pessoa sensata.",
  [813709740048384] = "É preciso aumentar o emprego!",
  [813709740048128] = "Não se surpreenda; o financiamento municipal mensal simplesmente não é suficiente para que as pessoas lá dentro comam até se fartar.",
  [813709740047872] = "Para manter o funcionamento do asilo, há um trabalho interminável para fazer aqui, e a comida é apenas suficiente para garantir que você não morra de fome.",
  [813709740047616] = "Por que?",
  [813709740047360] = "Além disso, o financiamento anual para o asilo é limitado. Deixando de lado alguns idosos, como funcionários, realmente não queremos que pessoas comuns venham aqui.",
  [813709740047104] = "O edifício foi construído com financiamento municipal; representa a cara do governo, mas as pessoas que vivem lá dentro não!",
  [813709740046848] = "O edifício do asilo é luminoso e bonito, mas não pode ajudar mais pessoas necessitadas?",
  [813709740046592] = "O asilo tem uma cota. Se você quiser vir, inscreva-se primeiro. Existem mais de 200 pessoas à sua frente.",
  [813709740046336] = "Por que ainda há fila?",
  [813709740046080] = "Embora as condições aqui sejam difíceis, pelo menos pode fornecer um abrigo para os sem-abrigo.",
  [813709740045824] = "O asilo não é um bom lugar.",
  [813709740045568] = "Obrigado pelo lembrete.",
  [813709740045312] = "Jovem, lembre-se de que o dinheiro que não está em suas mãos nunca será seu. Você deve defender sua renda legal.",
  [813709740045056] = "Seu pensamento é muito pragmático.",
  [813709740044800] = "É por isso que nunca deixo as pessoas atrasarem o aluguel. Talvez você saia bem de casa pela manhã e à noite esteja deitado no cemitério.",
  [813709740044544] = "O destino é realmente imprevisível.",
  [813709740044288] = "O irmão mais novo morreu no cumprimento do dever pouco depois de se formar e trabalhar em uma empresa de segurança. Ele era um jovem muito inteligente e eles nunca deixavam de pagar o aluguel.",
  [813709740044032] = "Uma pena o quê?",
  [813709740043776] = "Seu irmão mais velho é um escriturário astuto, apoiando seu irmão mais novo a se formar sozinho no Departamento de História da Hoy University, e sua irmã mais nova também ingressou na Backlund Technical University. É considerado uma coisa incrível na nossa Rua Cruz de Ferro, mas infelizmente!",
  [813709740043520] = "Você pode me contar mais sobre eles?",
  [813709740043264] = "Mas tínhamos uma família aqui que se transformou em fênix douradas – sim, a família Moretti, os três irmãos.",
  [813709740043008] = "Os inquilinos são, obviamente, pessoas comuns de Tingen, e não os residentes ricos da Rua Cruz de Ferro.",
  [813709740042752] = "Como estão os inquilinos aqui?",
  [813709740042496] = "<P_Heart> (Que condições adversas, que tipo de pessoas estão alugando esse tipo de lugar?) </>",
  [813709740042240] = "Dados os preços atualmente extremamente instáveis, é claro que é assinado mensalmente. E se a moeda se desvalorizar novamente? Devo arcar com a perda de um contrato de três meses?",
  [813709740041984] = "Assinado mensalmente?",
  [813709740041728] = "Meu contrato é assinado mensalmente e pago semanalmente, embora o pagamento mensal também seja adequado. A água é paga por pessoa e o gás é pago diretamente à companhia de gás com base no uso.",
  [813709740041472] = "Em termos de localização e orientação/iluminação é realmente bom. Como é pago o aluguel, a água e o gás?",
  [813709740041216] = "Jovem, abra os olhos e olhe. Esta localização, esta orientação e iluminação, temos até casas de banho públicas. Você consegue encontrar um apartamento melhor do que este aqui perto?",
  [813709740040960] = "Quais são as vantagens do seu lugar?",
  [1143492898225408] = "Observe um pouco mais",
  [813709740040448] = "Parece estranho, mas parece muito razoável.",
  [813709740040192] = "Eles são colhidos quando crescem e crescem novamente após serem colhidos.",
  [813709740039936] = "Por que você diz isso?",
  [813709740039680] = "Chamamos os residentes comuns que investem no mercado de ações de “alho-poró”.",
  [813709740039424] = "Sempre senti que o mercado de ações é uma aposta pública do governo. No mínimo, o mercado de ações de Loen é assim. Se você tem dinheiro, definitivamente não especule com ações.",
  [813709740039168] = "O mercado de ações? O mercado de ações é de fato um barômetro econômico de um país. Como diz o ditado, investir exige cautela e há riscos na entrada no mercado.",
  [813709740038912] = "Sim! Durante uma recessão, o mercado de ações também despencou e a renda do meu marido diminuiu drasticamente. Agora só podemos contratar servidores temporários.",
  [813709740038656] = "Isto é o que muitas vezes é chamado de recessão económica, certo!",
  [813709740038400] = "Eu realmente não consigo entender os preços atuais. Por que é que o dinheiro está cada vez mais difícil de ganhar, mas vale cada vez menos?",
  [813709740038144] = "Isso tem algum impacto em você?",
  [813709740037888] = "Desde que a nova moeda foi emitida, os preços recentes têm sido terríveis.",
  [813709740037632] = "Você não parece muito feliz.",
  [813709740037376] = "Quando você acha que Loen voltará a ser como era antes?",
  [813709740037120] = "Parece que você é uma empregada qualificada. Acredito que um empregador virá procurá-lo em breve.",
  [813709740036864] = "{{Sr.|Sra.}}, sou muito hábil em lavar roupa, cozinhar e limpar, e posso ler e escrever normalmente.",
  [813709740036608] = "Desculpe, não preciso de um no momento!",
  [813709740036352] = "Você está procurando um servo? Sou uma empregada muito profissional.",
  [813709740036096] = "Obrigado pela ajuda.",
  [813709740035840] = "Tosse, tosse, hum... você pode me dizer se precisar cooperar com alguma coisa.",
  [813709740035328] = "...Você é o cara novo, subordinado de Frye?",
  [813709740035072] = "...Senhor. Mountbatten, ainda não disse nada.",
  [813709740034816] = "E você, o que está olhando? Você tem uma opinião sobre minha voz?",
  [813709740034560] = "Droga, ele acha que os moradores desta rua são todos ovelhas? Eles não serão obedientes sem levar uma surra!",
  [813709740034304] = "Você também está aqui para reclamar da minha violenta aplicação da lei?",
  [813709740034048] = "As coisas que tenho aqui são todas fornecidas pelo município. Todos eles vêm do mesmo fornecedor.",
  [813709740033792] = "Compre duas batatas e ganhe uma de graça - pessoal, o que vocês estão esperando, só por hoje!",
  [813709740033536] = "O espinafre está tão fresco que está dançando! 1 centavo por pacote? É simplesmente o romance do mundo vegetal!",
  [813709740033280] = "{{Sr.|Sra.}} Quer comprar alguma coisa? Nossos produtos são os mais baratos e acessíveis. Alguns vendedores de vegetais afirmam que seus vegetais são da parte superior do rio Hoy, sem saber de qual terreno industrial abandonado eles realmente vieram.",
  [813709740033024] = "Quer um pouco de peixe Tussock? Foi capturado e enviado na parte superior do rio Hoy esta manhã. A carne é macia e tem poucos ossos. Custa apenas 7 centavos – sua melhor escolha!",
  [813709740032768] = "Diante de seus olhos está o mais puro verde! Da parte superior da bacia do rio Hoy – zero interferência industrial, longe de chaminés e fábricas!",
  [813709740032512] = "A forma mais clássica de comê-lo; até mesmo as empregadas dos cavalheiros do bairro rico costumam patrocinar! {{Sr.|Sra.}} Quer um pedaço?",
  [813709740032256] = "Bife fresco do Walker Ranch, a carne é firme e suculenta. Grelhar no carvão ou estufar lentamente pode fixar o sabor!",
  [813709740031744] = "Então você pode dar uma olhada no apartamento na Wendell Street. É muito adequado para uma elite como você. Fica no lado norte da Howls Street, também no rico Distrito Norte.",
  [813709740031488] = "Isso parece um pouco além das minhas necessidades reais.",
  [813709740031232] = "Se for uma villa, há uma villa de luxo para alugar na Howls Street. É uma casa que pertence a um grande magnata e agora eles se estabeleceram em Backlund.",
  [813709740030976] = "Uma vila.",
  [813709740030720] = "Você está procurando um apartamento ou uma villa?",
  [813709740030464] = "Algo mais?",
  [813709740030208] = "Deixe-me pensar sobre isso.",
  [813709740029952] = "Se você trabalha perto do Distrito Leste, também há algumas opções na Stephen Street para você escolher.",
  [813709740029696] = "A casa da Sra. Shaud na Rua Daffodil, 1, está para alugar. Em comparação com outras moradias, é muito rentável.",
  [813709740029440] = "Para moradias geminadas, depende de quanto espaço você precisa e do seu orçamento.",
  [813709740029184] = "E quanto às moradias?",
  [813709740028928] = "Parece bom.",
  [813709740028672] = "O transporte aqui é muito conveniente. Uma curta caminhada levará você até a Catedral de Santa Selena. Há também uma parada de bonde e é muito conveniente ir a outras igrejas e à estação de trem.",
  [813709740028416] = "Então recomendo as residências no trecho norte da Rua Daffodil. Fica perto do Distrito Norte e da área Golden Indus, e os preços das moradias também são razoáveis.",
  [813709740028160] = "Quero encontrar algo em um local melhor.",
  [813709740027904] = "Uh, de fato, se você for mais ao sul da Lower Street, verá as favelas e o distrito fabril.",
  [813709740027648] = "Além do proprietário exigente, deveria haver outros fatores inconvenientes, certo?",
  [813709740027392] = "Fica na Lower Iron Cross Street, mas a localização é boa, perto da Daffodil Street e da Golden Indus Avenue, e a vida é conveniente.",
  [813709740027136] = "Apartamento Frankie?",
  [813709740026880] = "A habitação mais barata em Tingen fica no Distrito Oeste. Existem alguns apartamentos perto da Iron Cross Street. Se você puder aceitar um proprietário exigente, talvez possa dar uma olhada no Frankie Apartment.",
  [813709740026624] = "{{Sr.|Sra.}}, você está procurando algo mais barato, algo em uma localização melhor ou talvez uma bela casa?",
  [813709740026368] = "Você pode me apresentar alguns?",
  [813709740026112] = "Quer alugar um lugar?",
  [813709740025856] = "Bem-vindo ao Restaurante Silver Crown.",
  [813709740025600] = "Somos o melhor restaurante da Rua Daffodil.",
  [813709740025344] = "Se procura servos, vir à nossa Associação dos Empregados Domésticos é a escolha certa.",
  [813709740025088] = "Venha até mim para beber; se você tiver negócios, encontre meu chefe .",
  [813709740024832] = "De fato!",
  [813709740024576] = "Blackthorn é um esquadrão mercenário formal. Você costuma sair para realizar algumas missões não oficiais. Hmm, você pode ganhar algum dinheiro extra e ajudar as pessoas a resolver dificuldades; é uma situação em que todos ganham.",
  [813709740024320] = "Este é o centro de atividades dos esquadrões mercenários de Tingen. Se precisar, posso apresentar outros esquadrões mercenários para você.",
  [813709740024064] = "Empresa de segurança é apenas um termo mais moderno; chama-se acompanhar os tempos. Os mercenários são uma tradição no nosso Continente Norte que continua até hoje.",
  [813709740023808] = "Por que uma empresa de segurança precisa usar um esquadrão mercenário como disfarce?",
  [813709740023552] = "Isso... também não tenho muita certeza.",
  [813709740023296] = "Você sabe, aquele garoto é um Red Glove agora, e um diácono de alto escalão.",
  [813709740023040] = "Não vejo nada de especial em você, mas o próprio Leonard levou você para Blackthorn.",
  [813709740022784] = "Sou eu.",
  [813709740022528] = "Você deve ser o recém-chegado de quem Bright me falou!",
  [813709740022272] = "Não mencione nenhum esquadrão mercenário, venha tomar uma bebida!",
  [813709740022016] = "Com certeza vou ler.",
  [813709740021760] = "Exatamente como foi retratado em “Storm Manor”! Eu realmente admiro a Sra. Sissi – confiante, preguiçosa e espirituosa.",
  [813709740021504] = "Um romancista policial de quem gosto muito disse uma vez que o culpado geralmente está escondido no lugar mais discreto!",
  [813709740021248] = "Isso é um elogio? Meu professor disse uma vez que só existe uma verdade e, se algo existiu, deve ter deixado rastros. Sempre segui seus ensinamentos.",
  [813709740020992] = "Tsk tsk, parece incrível que você possa realmente resolver um caso assim.",
  [813709740020736] = "Por exemplo, um fazendeiro morreu repentinamente e o assassino foi um pato.",
  [813709740020480] = "Casos bizarros?",
  [813709740020224] = "Porque, tosse, resolvi alguns casos particularmente bizarros. Claro, isso se deve principalmente à minha alta taxa de conclusão de comissões.",
  [813709740019968] = "Por que as pessoas chamam você de um grande detetive?",
  [813709740019712] = "A mais popular é Janice. Em relação às questões emocionais... bom, você sabe, ela é muito habilidosa nessa área, seja para homem ou para mulher.",
  [813709740019456] = "Isso é muito prático!",
  [813709740019200] = "Corey é muito bom em encontrar coisas. Podem ser itens diários ou vários animais, como ajudar pessoas a encontrar gatos ou cachorros.",
  [813709740018944] = "Tingen sabe tudo.",
  [813709740018688] = "Temos vários detetives aqui, e cada um tem diferentes áreas de especialização. Por exemplo, moro em Tingen desde criança e conheço muito bem a história, as ruas e os moradores de Tingen.",
  [813709740018432] = "O que quer que você queira saber, desde que seja em Tingen, posso ajudá-lo a investigar com clareza.",
  [813709740018176] = "Esta é a Agência de Detetives Henry! Há algo que eu possa fazer por você?",
  [813709740017920] = "Para onde você precisa de uma passagem de trem?",
  [813709740017664] = "OK!",
  [813709740017408] = "Eu recomendo fortemente que você leia esta série de romances.",
  [813709740017152] = "Acredito que isso deve ter realmente acontecido. Tal obra não poderia ter sido imaginada do nada; tudo é muito real.",
  [813709740016896] = "É um romance brilhante sobre as aventuras do Sr. Gehrman, envolvendo muitos segredos do mundo Beyonder.",
  [813709740016640] = "\"O Grande Aventureiro\"?",
  [813709740016384] = "Claro que é \"O Grande Aventureiro\"! Eu realmente espero poder escrever um best-seller assim também!",
  [813709740016128] = "<P_Heart> (Parece muito tímido, vamos mudar de assunto) </> Você tem algum livro para recomendar?",
  [813709740015872] = "Ah... apenas um recém-chegado, ainda não escrevi nada que valha a pena mostrar.",
  [813709740015616] = "Ouvi dizer que você é escritor?",
  [813709740015360] = "Frye é nosso capitão. Se você tiver alguma coisa, pode ir procurá-lo.",
  [813709740015104] = "Que a Deusa proteja você e eu.",
  [813709740014848] = "Eu entendo.",
  [813709740014592] = "Você sabe, há cada vez mais Beyonder incidentes ultimamente. Tenha cuidado com tudo.",
  [813709740014336] = "Você precisa solicitar reembolso? Cole seus recibos cuidadosamente atrás do formulário de solicitação de reembolso.",
  [813709740014080] = "Esta é a Blackthorn Security Company. Há algo que eu possa fazer por você?",
  [813709740013824] = "Há cada vez mais incidentes para lidar.",
  [813709740013568] = "Tosse, tosse, tosse, você é o novo funcionário da Blackthorn?",
  [813709740013312] = "Embora não estejamos mais juntos, estamos saudáveis ​​e felizes, vivendo a vida que queríamos.",
  [813709740013056] = "Haha, mais tarde ela foi para Backlund em busca de seus sonhos, e só nos correspondemos ocasionalmente.",
  [813709740012800] = "Você deve ter vivido muito feliz.",
  [813709740012544] = "Minha namorada achou minha comida deliciosa, então sugeriu que eu abrisse um restaurante e preparasse alguns pratos do dia a dia.",
  [813709740012288] = "Quarenta anos. Eu tinha apenas vinte anos quando abri esta loja. Essa foi realmente uma época maravilhosa.",
  [813709740012032] = "Parece que você está neste setor há muito tempo.",
  [813709740011776] = "Costumava ser chamado de Restaurante Will's. O tempo realmente voa; agora se tornou o Restaurante Old Will's.",
  [813709740011520] = "Somos um restaurante de longa data em Tingen; o sabor e o preço são impecáveis.",
  [813709740011264] = "A noite traz paz às pessoas.",
  [813709740010752] = "Engrenagens giratórias, vapor sibilante – tudo é tão perfeito.",
  [813709740010240] = "Eh... isso é algo para os Deuses fazerem. A importância do asilo consiste mais em evitar que estes pacientes causem novos perigos ocultos à sociedade. Tratá-los é algo que só os Deuses podem realizar.",
  [813709740009984] = "Você não é responsável por tratá-los?",
  [813709740009728] = "Quem ainda consegue se controlar e não prejudicar os outros não precisa vir aqui, como aquele Ademis, o maluco do bairro fabril.",
  [813709740009472] = "Os loucos?",
  [813709740009216] = "A maioria das pessoas com problemas mentais está acostumada a ir à Igreja em busca de padres para resolvê-los. Outros que eles não conseguem resolver chegam até nós. Claro, alguns são simplesmente loucos e não precisam vir até nós.",
  [813709740008960] = "Qual é a causa raiz dos problemas mentais? Além da genética, do estresse e da personalidade, a principal fonte é a corrupção do mal.",
  [813709740008704] = "O que isso tem a ver com a Igreja?",
  [813709740008448] = "É claro que o mundo está se tornando cada vez mais caótico. Se isto continuar, Tingen precisará de um segundo hospital psiquiátrico. Que a Deusa nos proteja... A Igreja deve fortalecer o seu poder para proteger a nós, pobres cordeiros.",
  [813709740008192] = "Por que há cada vez mais pacientes!",
  [813709740007936] = "É um incômodo, tem cada vez mais pacientes vindo aqui agora!",
  [813709740007680] = "Obrigado, eu entendo.",
  [813709740007424] = "Se você for ao Adivinhação Clube, pode avisar a dona Angélica na recepção que eu te apresentei. Ela e eu somos amigos.",
  [813709740007168] = "Claro, para romance, fortuna, estado de saúde, ou mesmo se você perder seu gato ou cachorro, você pode encontrar um adivinho para uma leitura.",
  [1143563228338432] = "Esta é a loja de departamentos mais sofisticada de toda Tingen; mesmo quando está fechado, muita gente fica de olho!",
  [813709740006656] = "Se tivermos problemas, estamos acostumados a ir ao Clube Adivinhação. Você sabe, ir para um adivinhação quando está em apuros é um hábito do povo de Tingen.",
  [813709740006400] = "Hahaha, de jeito nenhum. Você realmente é uma pessoa entusiasmada.",
  [813709740006144] = "Você encontrou algum problema?",
  [813709740005888] = "Eu entendo, estar sozinho também é uma habilidade.",
  [813709740005632] = "Esta é a norma. Teremos diferentes pessoas nos acompanhando em diferentes etapas.",
  [813709740005376] = "Sim, especialmente depois que meus bons amigos começaram suas próprias vidas. Para ser mais preciso, depois de se formar na escola, Melissa foi para Backlund e Elizabeth está na Universidade de Tingen...",
  [813709740005120] = "Na verdade, é muito adequado, especialmente quando você está sozinho.",
  [848824050422784] = "Meu?",
  [1130504917095936] = "Depois de uma viagem de trem a vapor de quatro horas, \nDaly chegou à estação ferroviária de Tingen.",
  [1130504917093888] = "Após o término da competição, o bar ainda estava muito animado.",
  [813709740004096] = "Acontece que... muitas pessoas nunca mais voltaram, permanecendo na frente de Midseashire, permanecendo nas montanhas de Minminsk.",
  [813709740003584] = "Malditos Feynapotters, eles lançaram um ataque furtivo em Backlund há quatro anos, causando a guerra. Louvado seja a Deusa, ainda vencemos.",
  [1169958218498561] = "Alguns dias depois...",
  [813709740003072] = "O tempo voa tão rápido. Num piscar de olhos, é 1358. Parece que a guerra acabou de terminar.",
  [813709740002816] = "O tempo está muito bom hoje. Você está aqui para relaxar também?",
  [813709740002560] = "Uma xícara de café todos os dias faz você se sentir revigorado!",
  [813709740002304] = "Você gostaria de um pouco de café? Recomendo uma xícara de café Fermer do Vale da Paz, no Continente Sul.",
  [813709740002048] = "Bem-vindo à loja de departamentos Harold. Tivemos algumas novidades recentemente. Você gostaria de dar uma olhada?",
  [813709740001792] = "Posso perguntar o que você precisa?",
  [813709740001536] = "Bem-vindo ao Restaurante Bonaparte!",
  [813709740001280] = "Oferecemos a cozinha Intis mais autêntica de toda Tingen.",
  [813709740001024] = "De nada. Você me lembrou um bom amigo e uma linda lembrança.",
  [813709740000768] = "Obrigado por me dizer isso.",
  [813709740000512] = "Ele era tão gentil e caloroso. Se quiser vê-lo, pode ir ao Cemitério Rafael, onde crescem as flores adormecidas. É aí que ele descansa.",
  [813709740000256] = "Suponho que sim, ele me ajudou, talvez...",
  [813709740000000] = "A propósito, você tem negócios com ele?",
  [813709739999744] = "Minhas condolências.",
  [813709739999488] = "Ele era muito jovem, tinha apenas 22 anos, acabara de se formar na Universidade de Tingen e tinha um futuro brilhante. A vida é imprevisível; valorize o presente. Desculpe, fiquei um pouco emocionado.",
  [813709739999232] = "Eu vi sua lápide no Cemitério Raphael com sua foto. Março de 1327 - setembro de 1349, melhor irmão; o melhor irmão mais novo; o melhor colega.",
  [813709739998976] = "Como você sabe que ele voltou para o abraço da Deusa?",
  [813709739998720] = "Klein? Ele é o Vidente mais talentoso que já conheci, mas... é uma pena que ele tenha retornado aos braços da Deusa!",
  [813709739998464] = "Você conhece o Sr. Moretti? A senhorita Angélica disse que você era muito próximo dele.",
  [813709739998208] = "Você gostaria de ter sua fortuna recente adivinhada?",
  [813709739997952] = "Ele faleceu há algum tempo. Mesmo sendo um mestre adivinhação muito poderoso, ele não conseguia prever seu próprio destino.",
  [813709739997696] = "Uma vez?",
  [813709739997440] = "Ele era um velho amigo do nosso clube e já serviu como nosso adivinhação mentor.",
  [813709739997184] = "Haines Vicente.",
  [813709739996928] = "Sim, ele e o Sr. Moretti ingressaram no clube na mesma época, e agora ele se tornou um vidente conhecido em Tingen. Eles estão bem próximos.",
  [813709739996672] = "Sr. Seaglass?",
  [813709739996416] = "Sim, o Sr. Moretti era uma pessoa que fazia as pessoas se sentirem muito gentis. Ele ajudou muitas pessoas que vieram aqui em busca de ajuda. Se você estiver interessado, pode conversar com o Sr. Seaglass.",
  [813709739996160] = "Por alguma razão, sinto que ele é muito gentil.",
  [813709739995904] = "Ele era um Vidente muito promissor, mas infelizmente não o vejo há vários anos.",
  [813709739995392] = "(Klein!) Esses acinzentados não estão mais aqui, certo?",
  [813709739995136] = "Sra. Riana é nossa mestre residente adivinhação, especializada em Tarot adivinhação , sonho adivinhação e astrologia. Ela cobra 1 sol por sessão.",
  [813709739994880] = "Edward Stiff é um vidente muito talentoso, especializado em cartas de tarô adivinhação e pôquer adivinhação. Ele cobra 3 centavos por sessão.",
  [813709739994624] = "Sr. Grassis é nosso Vidente mais acessível, especializado em Tarot adivinhação . Ele cobra 2 centavos por sessão.",
  [813709739994368] = "Você pode ver a lista aqui. Contém as apresentações e preços dos adivinhos. Posso apresentá-los a você.",
  [813709739994112] = "Eu quero um adivinhação !",
  [813709739993856] = "Muito bem, você pode ingressar no clube a qualquer momento.",
  [813709739993600] = "Não parece ruim, vou pensar sobre isso!",
  [813709739993344] = "Mais importante ainda, nossos membros são livres para ajudar outras pessoas com adivinhação no clube e definir seus próprios preços. Cobramos apenas uma porcentagem muito baixa como taxa. Você pode dar uma olhada nas apresentações e preços de outros membros.",
  [813709739993088] = "Todos os meses convidamos pelo menos um adivinho famoso para dar uma palestra e responder perguntas difíceis.",
  [813709739992832] = "Você também pode adquirir almoço, jantar, bebidas alcoólicas e alguns adivinhação livros e materiais didáticos a preço de custo.",
  [813709739992576] = "Principalmente porque a moeda Loen se desvalorizou significativamente! Os membros podem usar gratuitamente a sala de conferências do clube e várias adivinhação salas e ferramentas, desfrutar gratuitamente do café e do chá e ler os jornais e revistas que assinamos gratuitamente.",
  [813709739992320] = "Isso é inesperadamente caro!",
  [813709739992064] = "Ao contrário dos clubes políticos ou comerciais que exigem recomendações de membros formais, você só precisa preencher informações detalhadas e pagar a taxa anual de adesão. São 150 libras pela primeira vez e 50 libras todos os anos depois disso.",
  [813709739991808] = "Como faço para ingressar no clube?",
  [813709739991552] = "Essa é uma boa escolha.",
  [813709739991296] = "Que tal tomar primeiro uma xícara de chá preto Sibe ou café Southwell! Pense enquanto você bebe.",
  [813709739991040] = "Deixe-me pensar!",
  [813709739990784] = "Bem-vindo ao Clube Adivinhação. Você gostaria de um adivinhação ou deseja se juntar ao nosso clube?",
  [813709739990272] = "Ainda precisamos da proteção dos “figurões” para operar neste negócio.",
  [813709739990016] = "Parece que você sabe bastante!",
  [813709739989760] = "Você realmente conhece esse lugar!",
  [813709739989504] = "Barra do Dragão Maligno.",
  [813709739989248] = "Uh... convidado, se você tiver outras necessidades, pode tentar a sorte no cais. Ouvi dizer que há um mercado negro lá.",
  [813709739988992] = "No mercado?",
  [813709739988736] = "Você veio aqui depois de ler o jornal? Venha e dê uma olhada; Tenho o estoque mais completo de Tingen!",
  [813709739988480] = "O que é isso, procurar uma arma útil?",
  [813709739988224] = "Adeus.",
  [813709739987712] = "Ele se empolgou assistindo ao jogo e quis tentar, e o resultado... como vocês podem ver.",
  [813709739987456] = "Você não está tentando me enganar, está?",
  [813709739987200] = "Ela é verdadeiramente nosso modelo. Eu sempre irei apoiá-la.",
  [813709739986944] = "Vendo Linda ganhar o campeonato, estou muito animado. Talvez eu não consiga dormir esta noite. Por que não ficar e encontrar um pouco mais de diversão?",
  [813709739986688] = "Esta noite é verdadeiramente inesquecível...",
  [813709739986432] = "Ela é muito poderosa e muito forte. Eu perdi e aceito isso de todo o coração.",
  [813709739986176] = "Não tenho mais rosto para mostrar no Evil Dragon Bar. Talvez eu vá trabalhar em alguma doca mais tarde.",
  [813709739985920] = "Você está aqui para zombar de mim também?",
  [813709739984640] = "Há muito a ganhar! Se você vencer o campeonato, você se tornará uma figura conhecida nesta área, chegará às manchetes dos jornais e ganhará uma riqueza infinita!",
  [813709739984384] = "Isso é uma pena.",
  [813709739984128] = "Você está interessado em participar do próximo Campeonato Dragão?",
  [813709739983616] = "Olá, posso perguntar se você é Sophia?",
  [813709739983360] = "Eu só estou aqui para ajudar, não sei...",
  [813709739982848] = "Partidas? Vá perguntar na mercearia ao lado.",
  [813709739982592] = "{{Sr.|Sra.}}, você precisa de queijo de cabra? Garanto que este é o melhor queijo de cabra de Tingen!",
  [813709739982336] = "Partidas? Não. Carne fresca, quer comprar dois pedaços?",
  [813709739981824] = "Gentil {{Sr.|Sra.}}, você encontrou as correspondências para Jenny?",
  [813709739981568] = "{{Sr.|Sra.}}, uma caixa de fósforos?",
  [813709739981312] = "Olá, há algo que você precisa?",
  [813709739981056] = "Como eu saberia? Não é meu mensageiro... Porém, parece estar desenvolvendo algum tipo de poção. O que está na mesa é a fórmula da poção que ouvi. Talvez se você fizer a poção, ela aparecerá.",
  [813709739980800] = "Espírito do Mar? O que é aquilo? Ah... aquela coisinha. Eu já vi isso.",
  [813709739980544] = "Olá, você tem alguma dúvida sobre a sala de poções?",
  [813709739980288] = "Venha e mostre suas habilidades de dança!",
  [813709739980032] = "Em nosso mundo, não existe uma frase como “mate-os”. Essa é uma frase que só os covardes diriam, porque quando meus companheiros e eu tivermos esse pensamento em mente, já teremos tirado a vida da outra parte. Tudo já acabou.",
  [813709739979776] = "Esse cheiro é o cheiro de uma mentira!",
  [813709739979520] = "Não me faça repetir a mesma coisa duas vezes. Repetir a mesma coisa é um ato inútil. Eu odeio mais esse comportamento inútil. Inútil, inútil.",
  [813709739979264] = "Estranho, todos os lugares nas fotos parecem ter mudado...",
  [813709739971072] = "Quer jogar uma partida? Escolha um cachorro. Se conseguir capturar 10 ratos mais rápido, você receberá uma bela recompensa.",
  [813709739970816] = "Pistas indicam que esta pessoa é provavelmente a culpada do crime {{Crime}} cometido por {{Time}} em {{Place}}. Vá falar com ele.",
  [813709739970560] = "Uma pessoa gentil pode me ajudar a pegar os ratos?",
  [813709739970304] = "Resposta errada! Então, é um missão ou uma punição?",
  [813709739970048] = "Correto! Se você quiser saber alguma coisa no futuro, pode vir e me perguntar.",
  [813709739969792] = "Aha, então posso perguntar quem é o fundador do Clube do Tarô ?",
  [813709739969536] = "Tudo bem, que pena.",
  [813709739969280] = "Membro do Clube do Tarô , me responda uma pergunta. Se você mentir ou não puder responder, aceitará um missão arranjo ou será punido. De acordo com o princípio da reciprocidade, você pode me fazer uma pergunta depois.",
  [813709739969024] = "Quem pode me salvar? Não posso simplesmente pedir ajuda ao presidente sobre um assunto tão trivial... Não conheço mais ninguém. Suspiro, eu não deveria ter tentado convocar um mensageiro tão cedo. Ahh...",
  [813709739968768] = "Estranho, todos os lugares nas fotos parecem ter mudado...",
  [813709739967744] = "Entregue os itens.",
  [813709739966720] = "Você quer que eu mande você para a pista inferior?",
  [813709739966464] = "Você quer que eu mande você para a faixa do meio?",
  [813709739966208] = "Você quer que eu mande você para a pista superior?",
  [813709739965952] = "Você pode me dar os recursos que coletou e eu lhe ajudarei.",
  [813709739965696] = "Não se esqueça de vir e cultivar com frequência.",
  [813709739965440] = "O cultivo também é uma vantagem muito boa.",
  [813709739965184] = "Quer voltar para o clube?",
  [813709739964928] = "Claro!",
  [813709739964672] = "O tempo está bom hoje.",
  [813709739964416] = "Volte na próxima vez.",
  [813709739964160] = "Você verá quando der uma olhada.",
  [813709739963904] = "Tudo que vendo aqui é coisa boa.",
  [813709739963648] = "Você não entenderia.",
  [813709739963392] = "Equipamento é uma arte.",
  [1130298758796800] = "Desastre? Que desastre?",
  [1130298758661632] = "Jenny desapareceu...",
  [1130298758663680] = "Você suspeita que fui eu?",
  [813709739962368] = "As lacunas na história precisam de pessoas corajosas para serem exploradas.",
  [813709739962112] = "Então da próxima vez.",
  [813709739961856] = "Ei, aqui para melhorar novamente hoje?",
  [813709739961600] = "Tudo bem.",
  [813709739961344] = "Há um cordeirinho perdido aqui.",
  [813709739961088] = "Claro, sem problemas, respeitado {{Sr.|Sra.}}.",
  [813709739960832] = "Para onde devemos partir, {{Sr.|Sra.}}?",
  [813709739960576] = "Que queridinha.",
  [813709739960320] = "Você gostaria de fazer um city tour hoje também?",
  [813709739960064] = "Você deveria me chamar de honorável Lorde Arrodes!",
  [813709739959808] = "Impressionante, impressionante.",
  [813709739959552] = "Então, pegue aquela arma imbuída de Beyonder poder e ative as Beyonder habilidades concedidas ao seu corpo!",
  [813709739959296] = "Beba esta garrafa de poção de recuperação primeiro; o mais importante agora é clarear a mente e restaurar a saúde.",
  [813709739958784] = "Você tem uma língua doce.",
  [813709739958528] = "Estou feliz em ver você!",
  [813709739958272] = "Susie desapareceu em um piscar de olhos. É realmente preocupante.",
  [813709739958016] = "Que bom ver você, venha conferir os itens na loja do clube!",
  [813709739957760] = "Acabou... finalmente tudo acabou.",
  [813709739957504] = "Minha senhora, esta rosa combina com a sua beleza. Você gostaria de levar para casa?",
  [813709739957248] = "Já te disse, a pessoa que você procura não está aqui! Vá embora, vá embora!",
  [620129121479424] = "Compre jornal",
  [813709739956992] = "Linda senhora, posso escrever um poema para você?",
  [813709739956736] = "Saí de Tingen, mas não esperava me perder em Backlund.",
  [813709739956480] = "Você viu Frank? Ele desapareceu assim que o navio atracou. É realmente preocupante.",
  [813709739956224] = "O clima em Backlund é sempre sombrio, nebuloso e chuvoso; Estou muito feliz em conhecê-lo com um tempo tão bom. Bem, desejo-lhe felicidade também.",
  [813709739955968] = "Acho que você não veio me procurar apenas para um simples bate-papo.",
  [813709739955712] = "O que é? Parece que você quer falar sobre outra coisa.",
  [813709739955456] = "Parece que você veio na hora certa.",
  [813709739955200] = "A aura está prestes a se dissipar. Seu leal e humilde Arrodes espera para servi-lo novamente. (boneco acenando)",
  [813709739954944] = "Certamente é você; ninguém é mais bonito que você.",
  [813709739954688] = "Quem é a pessoa mais bonita do mundo?",
  [813709739954432] = "Sim, grande existência acima do Mundo Espiritual.",
  [813709739954176] = "Oh, respeitado Mestre! Quais são seus pedidos?",
  [813709739953920] = "Meu querido Mestre! Seu leal e humilde servo Arrodes está ao seu serviço.",
  [813709739953664] = "Se precisar de alguma coisa, pode me encontrar no Bar Bravehearts.",
  [813709739953408] = "Aconteceu alguma coisa?",
  [813709739953152] = "Estou atrasado para o trabalho hoje; o capataz vai descontar meu salário novamente.",
  [813709739952896] = "Tudo bem, por favor espere um momento!",
  [813709739952640] = "Você gostaria de chá preto ou café?",
  [519177257724417] = "Eu me pergunto como está a Srta. Audrey ultimamente.",
  [519177257724161] = "Tenho visto o gerente cada vez menos nos últimos anos. Talvez ele se sinta à vontade em confiar o banco ao jovem Mestre Hibbert.",
  [519177257723905] = "O gerente é um homem generoso; não leve isso a sério.",
  [519177257701889] = "Espere, o que você colocou?",
  [519177257630721] = "Claro, quando vou para algum lugar longe, mal consigo... não tenho escolha...",
  [519177257526529] = "Eu olhei, atrás do moinho de vento, tem algo ainda mais assustador...",
  [519177257506817] = "Não... você não pode tirar isso...",
  [519177257506305] = "Você já tomou sua decisão, certo?",
  [519177257487873] = "Pierre, voltarei para ver você quando tiver tempo. Quando nossa loja de chapéus abrir, você vem comprar um chapéu para Leah!",
  [519177257487105] = "Quando você vai embora?",
  [519177257486337] = "Tosse, por que esta caldeira está tão sufocante hoje!",
  [519109612076544] = "Obrigado!",
  [519109612036352] = "Siga-os e veja.",
  [519109611985152] = "Adeus, Sra. Skana.",
  [519109611921408] = "Isso é... algum tipo de quebra-cabeça desconhecido?",
  [519109611921152] = "Parece diferente desta vez?",
  [519109611896576] = "Um perfume maravilhoso, não é?",
  [519109611867904] = "Sr.Frye?",
  [519109611830528] = "É tão doloroso, apresse-se, deixe Yodora ser livre.",
  [519109611830272] = "Sinto muito, Arnold, gosto da sua canção de ninar, mas sou odiado por este mundo... Eu também odeio este mundo.",
  [519109611829760] = "Ah, eu entendo... eu falhei. Fui abandonado por Ele. Vou ser comido pela flauta de osso.",
  [519109611813376] = "Espere!",
  [519109611809280] = "......Boa criança, descanse em paz.",
  [519109611809024] = "Dói... quero ir para casa... quero ir para casa...",
  [519109611808768] = "Papai... Mamãe... salve-me... não serei mais obstinado...",
  [519109611808512] = "Serei obediente... vou me esforçar... serei o melhor filho...",
  [519109611803392] = "Ele escapou. Como Arnold poderia conhecer uma pessoa tão perigosa?",
  [519109611800064] = "Minha memória está piorando ultimamente?",
  [519109611799808] = "Lembro que os pais adotivos de Arnold mencionaram que ele parecia gostar particularmente de um certo tipo de pão.",
  [519109611795200] = "O salão está quase pronto; você poderia se dar ao trabalho de limpar o escritório do capitão?",
  [519109611794176] = "Blackthorn, o esquadrão Tingen Vigia Noturno disfarçado de empresa de segurança.",
  [519041160715264] = "Ei, você notou aquele esquisito lá em cima?",
  [519041160596992] = "Fique à vontade para dar uma olhada.",
}
